/* Leçons et annexes : générées par outils/construire_site.py depuis manuel/ et annexes/ */
window.AMF_COURS={"lessons":[{"id":"01","n":1,"title":"Cadre institutionnel et réglementaire (France, Europe, international)","html":"\n<blockquote class=\"note\">\n<p><strong>Poids à l'examen : 14 questions sur 120, toutes en catégorie C.</strong>\nRépartition : §1.1 (2) · §1.2.1 (2) · §1.2.2 (1) · §1.3 (3) · §1.5.1 (2) · §1.5.2 (2) · §1.8 (2).\nLe thème pèse lourd (12 % de l'examen) mais il est très « par cœur ». Les mêmes 5 ou 6 réflexes rapportent la majorité des points.</p>\n</blockquote>\n<hr/>\n<h2 id=\"1-1-le-cadre-de-tutelle-français\">1.1 Le cadre de tutelle français</h2>\n<h3 id=\"qui-fait-les-règles\">Qui fait les règles ?</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Niveau</th>\n<th>Qui</th>\n<th>Ce qu'il fait</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Loi</td>\n<td><strong>Parlement</strong></td>\n<td>Vote les lois, codifiées dans le <strong>Code monétaire et financier (CMF)</strong> : articles <strong>L.</strong> (législatifs), <strong>R.</strong> et <strong>D.</strong> (décrets).</td>\n</tr>\n<tr>\n<td>Pouvoir réglementaire</td>\n<td><strong>Ministre chargé de l'économie</strong></td>\n<td>Prend les arrêtés. Il <strong>homologue le Règlement général de l'AMF (RG AMF)</strong>, reconnaît la qualité de <strong>marché réglementé sur proposition de l'AMF</strong> et fixe le <strong>taux d'intérêt légal</strong> par arrêté.</td>\n</tr>\n<tr>\n<td>Administration</td>\n<td><strong>Direction générale du Trésor</strong></td>\n<td>Prépare les textes et représente la France à Bruxelles. Elle suit le <strong>label « Relance »</strong>. Avec le <strong>gouverneur de la Banque de France</strong>, elle peut <strong>saisir l'ACPR pour ouvrir une résolution</strong> bancaire.</td>\n</tr>\n<tr>\n<td>Supervision</td>\n<td><strong>AMF</strong> et <strong>ACPR</strong> (+ leur <strong>pôle commun</strong>)</td>\n<td>Appliquent et contrôlent les règles (détail ci-dessous).</td>\n</tr>\n<tr>\n<td>Consultation</td>\n<td><strong>CCLRF</strong>, <strong>CCSF</strong></td>\n<td>Donnent des avis, ne décident rien.</td>\n</tr>\n<tr>\n<td>Stabilité d'ensemble</td>\n<td><strong>HCSF</strong></td>\n<td>Surveillance macroprudentielle.</td>\n</tr>\n</tbody>\n</table></div>\n<h3 id=\"amf-ou-acpr-le-tableau-qui-rapporte-le-plus-de-points\">AMF ou ACPR : le tableau qui rapporte le plus de points</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th></th>\n<th><strong>AMF</strong> — Autorité des marchés financiers</th>\n<th><strong>ACPR</strong> — Autorité de contrôle prudentiel et de résolution</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Création</td>\n<td>2003 (loi de sécurité financière : fusion COB + CMF + CDGF)</td>\n<td>2010 (ACP), devenue ACPR en 2013 (loi de séparation bancaire)</td>\n</tr>\n<tr>\n<td>Statut</td>\n<td><strong>Autorité publique indépendante</strong>, dotée de la personnalité morale</td>\n<td>Autorité administrative indépendante <strong>adossée à la Banque de France</strong> (présidée par le gouverneur)</td>\n</tr>\n<tr>\n<td>Missions (CMF)</td>\n<td><strong>Protéger l'épargne investie</strong> dans les instruments financiers, <strong>informer les investisseurs</strong>, veiller au <strong>bon fonctionnement des marchés</strong> (« sécurité des marchés »)</td>\n<td><strong>Stabilité du système financier</strong> et <strong>protection des clients</strong> des banques et des assureurs</td>\n</tr>\n<tr>\n<td>Agrée</td>\n<td><strong>Les SGP (seule)</strong>, les <strong>OPC</strong> (OPCVM, FIA, <strong>OPCI</strong>…), les associations de CIF ; approuve les prospectus et le DEU</td>\n<td><strong>Établissements de crédit, entreprises d'investissement</strong>, assureurs, établissements de paiement et de monnaie électronique</td>\n</tr>\n<tr>\n<td>Contrôle</td>\n<td>Règles de bonne conduite des PSI, SGP, <strong>CIF</strong>, marchés, émetteurs, PSAN/PSCA</td>\n<td>Solidité financière (prudentiel), <strong>résolution des banques défaillantes</strong>, pratiques commerciales banque/assurance</td>\n</tr>\n<tr>\n<td>Sanctionne</td>\n<td><strong>Toute personne</strong>, physique ou morale, professionnelle ou non, qui porte atteinte au bon fonctionnement du marché ou à la protection des investisseurs</td>\n<td><strong>Uniquement</strong> les établissements placés sous son contrôle</td>\n</tr>\n</tbody>\n</table></div>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« L'AMF Garde les Marchés et les Gérants ; l'ACPR Agrée les Comptoirs (banques) et les Assureurs, et les Répare (résolution). »</strong></p>\n</aside>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>SGP → AMF, toujours et seule.</strong> EC ou EI → ACPR, plus l'<strong>approbation du programme d'activité par l'AMF</strong> pour leurs services d'investissement (« l'ACPR signe, l'AMF valide le programme »).</p>\n</aside>\n<p><strong>Organes de l'AMF</strong> (CMF L.621-2) : un <strong>Collège</strong>, une <strong>Commission des sanctions</strong> et des <strong>commissions consultatives</strong>.</p>\n<ul>\n<li><strong>Collège</strong> : 16 membres, dont un <strong>magistrat de la Cour des comptes</strong>. Le président de l'AMF est nommé par décret pour 5 ans non renouvelables. Le Collège adopte le RG AMF, délivre les agréments, <strong>ouvre les procédures</strong> de sanction, peut <strong>ordonner qu'il soit mis fin à un manquement</strong> (injonction) et propose la <strong>composition administrative</strong> (somme versée au <strong>Trésor public</strong>).</li>\n<li><strong>Commission des sanctions</strong> (12 membres, distincte du Collège) : <strong>prononce</strong> les sanctions (avertissement, blâme, interdiction d'exercer, sanction pécuniaire).</li>\n</ul>\n<aside class=\"callout c-warn\"><span class=\"callout-label\">Piège</span>\n<p>La Commission des sanctions <strong>prononce</strong> les sanctions : elle n'est pas « seulement consultative » et ne « transmet pas au procureur ». L'emprisonnement relève du <strong>juge pénal</strong>, jamais de l'AMF.</p>\n</aside>\n<aside class=\"callout c-warn\"><span class=\"callout-label\">Piège</span>\n<p>« Adossée à la Banque de France » est la réponse attendue pour l'ACPR, même si un choix « administrative indépendante » apparaît (voir l'annexe A, <a class=\"qref\" href=\"#\" data-q=\"23\">Q23</a>). Pour l'AMF, la bonne formule est « <strong>autorité publique indépendante</strong> ».</p>\n</aside>\n<h3 id=\"les-instances-consultatives-et-le-hcsf\">Les instances consultatives et le HCSF</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Instance</th>\n<th>Rôle</th>\n<th>Moyen de retenir</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>CCLRF</strong> — Comité consultatif de la <strong>législation</strong> et de la <strong>réglementation</strong> financières</td>\n<td><strong>Avis sur les projets de textes</strong> (lois, décrets, règlements européens) en banque, assurance et finance. Fonctions <strong>non rémunérées</strong>.</td>\n<td><span class=\"tag t-mnemo\">mnémo</span> le <strong>L</strong> de CCLRF = <strong>L</strong>oi : il relit les textes.</td>\n</tr>\n<tr>\n<td><strong>CCSF</strong> — Comité consultatif du <strong>secteur financier</strong></td>\n<td>Étudie les <strong>relations entre les établissements financiers et leurs clients</strong> et propose des <strong>avis et recommandations</strong>. Ce n'est <strong>ni un médiateur, ni un législateur, ni un contrôleur</strong>.</td>\n<td><span class=\"tag t-mnemo\">mnémo</span> le <strong>S</strong> de CCSF = <strong>S</strong>ervice au client.</td>\n</tr>\n<tr>\n<td><strong>HCSF</strong> — Haut conseil de stabilité financière (2013)</td>\n<td>Surveille <strong>l'ensemble du système financier</strong> (pas seulement les banques ou les assureurs), prévient le <strong>risque systémique</strong>, prend des mesures <strong>macroprudentielles</strong>. <strong>8 membres</strong>, présidé par le <strong>ministre de l'économie</strong> ; y siègent le <strong>président de l'ACPR</strong> (gouverneur de la Banque de France) et le président de l'AMF.</td>\n<td><span class=\"tag t-mnemo\">mnémo</span> <strong>H</strong>aut conseil = vue <strong>H</strong>élicoptère de tout le système.</td>\n</tr>\n</tbody>\n</table></div>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p>Exemple concret de mesure du HCSF : depuis 2022, les normes de crédit immobilier sont contraignantes (taux d'effort maximal de 35 %, durée maximale de 25 ans).</p>\n</aside>\n<h3 id=\"les-associations-professionnelles\">Les associations professionnelles</h3>\n<ul>\n<li>Tout <strong>établissement de crédit</strong> et toute <strong>entreprise d'investissement</strong> doit adhérer à un organisme professionnel (ou à un organe central) <strong>affilié à l'AFECEI</strong> (Association française des établissements de crédit et des entreprises d'investissement).</li>\n<li>Les <strong>associations de CIF sont agréées par l'AMF</strong>. Chaque CIF adhère à <strong>une et une seule</strong> association, qui exerce le <strong>premier niveau de contrôle</strong>. Toute <strong>modification du code de bonne conduite</strong> d'une association doit être <strong>approuvée au préalable par l'AMF</strong>.</li>\n</ul>\n<div class=\"ids\" data-sub=\"1.1\"></div>\n<hr/>\n<h2 id=\"1-2-1-le-cadre-européen\">1.2.1 Le cadre européen</h2>\n<h3 id=\"comment-leurope-fait-ses-textes\">Comment l'Europe fait ses textes</h3>\n<ul>\n<li>La <strong>Commission</strong> propose (monopole de l'initiative). Le <strong>Parlement européen</strong> et le <strong>Conseil de l'UE</strong> votent ensemble (codécision). Le <strong>trilogue</strong> est la négociation informelle entre ces trois institutions.</li>\n<li>Le <strong>processus Lamfalussy</strong> compte trois niveaux :\n<ul>\n<li><strong>Niveau 1</strong> : le texte-cadre (directive ou règlement) ;</li>\n<li><strong>Niveau 2</strong> : les mesures d'exécution (actes délégués, normes techniques préparées par les autorités européennes) ;</li>\n<li><strong>Niveau 3</strong> : les orientations et questions-réponses des autorités, pour une application convergente.</li>\n</ul>\n</li>\n<li>Une <strong>directive</strong> doit être <strong>transposée</strong> en droit national. Un <strong>règlement</strong> s'applique <strong>directement</strong>.</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« La Commission Propose, le Parlement et le Conseil Disposent »</strong> (P-P-C). À la question « qui vote les lois européennes ? », la base attend <strong>le Parlement européen</strong>.</p>\n</aside>\n<h3 id=\"le-système-européen-de-surveillance-financière-sesf-2011\">Le Système européen de surveillance financière (SESF, 2011)</h3>\n<p>C'est un <strong>réseau</strong> composé de trois <strong>autorités européennes de surveillance (AES)</strong>, du <strong>Comité européen du risque systémique</strong> et des <strong>autorités nationales</strong>.</p>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Autorité</th>\n<th>Domaine</th>\n<th>Siège</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>ESMA / AEMF</strong> — Autorité européenne des marchés financiers</td>\n<td><strong>Marchés</strong> et valeurs mobilières : protection des investisseurs, stabilité, cohérence de la régulation. Conseille la Commission et rédige les normes techniques. <strong>Supervise directement les agences de notation et les référentiels centraux.</strong> <strong>L'AMF y siège</strong> (pas l'ACPR, pas la Banque de France).</td>\n<td>Paris</td>\n</tr>\n<tr>\n<td><strong>EBA / ABE</strong> — Autorité bancaire européenne</td>\n<td><strong>Banques</strong> : stabilité et efficacité du système bancaire</td>\n<td>Paris</td>\n</tr>\n<tr>\n<td><strong>EIOPA / AEAPP</strong> — Autorité européenne des assurances et des pensions professionnelles</td>\n<td><strong>Assurance</strong> et retraites professionnelles</td>\n<td>Francfort</td>\n</tr>\n<tr>\n<td><strong>CERS / ESRB</strong> — Comité européen du risque systémique</td>\n<td>Surveillance <strong>macroprudentielle</strong> de l'UE</td>\n<td>Francfort (présidé par le président de la BCE)</td>\n</tr>\n</tbody>\n</table></div>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>E-B-A = Établissements Bancaires ; E-I-O-PA = Insurance + Occupational PEnsions ; E-S-MA = Securities &amp; MArkets.</strong> « Banque et assurance » = EBA + EIOPA. « Marchés » = ESMA.</p>\n</aside>\n<aside class=\"callout c-warn\"><span class=\"callout-label\">Piège</span>\n<p>La BCE et la Fédération bancaire européenne <strong>ne font pas partie</strong> du SESF. Le CERS est l'autorité <strong>macroprudentielle</strong> de l'UE, pas le FSB ni l'EBA.</p>\n</aside>\n<h3 id=\"lunion-bancaire-décidée-en-juin-2012\">L'Union bancaire (décidée en juin 2012)</h3>\n<ul>\n<li><strong>Objectif</strong> : <strong>anticiper les crises bancaires et mieux en traiter les conséquences</strong>.</li>\n<li><strong>Périmètre</strong> : les <strong>États de la zone euro</strong> et les États de l'UE qui ont choisi une <strong>« coopération rapprochée »</strong>.</li>\n<li><strong>Trois piliers</strong> :\n<ol>\n<li><strong>MSU</strong> — Mécanisme de surveillance unique (2014) : la <strong>BCE et les autorités nationales</strong> (pas l'EBA, pas l'ESMA). <strong>La BCE décide si une banque est « significative »</strong> et la supervise alors directement.</li>\n<li><strong>MRU</strong> — Mécanisme de résolution unique : Conseil de résolution unique et Fonds de résolution unique.</li>\n<li><strong>SGD</strong> — Systèmes de garantie des dépôts harmonisés (100 000 € par déposant et par banque). Les <strong>contributions des banques</strong> dépendent de leur <strong>profil de risque</strong> et du <strong>montant des dépôts garantis</strong>.</li>\n</ol>\n</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« Surveiller – Résoudre – Garantir »</strong> = MSU – MRU – SGD.</p>\n</aside>\n<h3 id=\"le-marché-unique-et-le-passeport-européen\">Le marché unique et le passeport européen</h3>\n<ul>\n<li>Le marché unique vise la <strong>libre circulation des capitaux</strong>. L'harmonisation des règles sert la <strong>protection des épargnants</strong> et le <strong>bon fonctionnement des marchés</strong>.</li>\n<li>Le <strong>passeport européen</strong> repose sur la <strong>reconnaissance mutuelle des agréments</strong>. Un établissement agréé dans son <strong>pays d'origine</strong> peut exercer dans <strong>tout l'UE/EEE</strong> (pas « toute l'Europe »), en <strong>libre prestation de services</strong> ou en <strong>libre établissement</strong> (succursale).\n<ul>\n<li>Le passeport ne vaut <strong>que pour les services agréés dans le pays d'origine</strong>.</li>\n<li>Un établissement de crédit français le demande <strong>auprès de l'ACPR</strong>.</li>\n<li>Pour commercialiser un fonds dans un autre pays, c'est <strong>la société de gestion</strong> qui obtient le passeport.</li>\n</ul>\n</li>\n<li>Pour les <strong>pays tiers</strong>, la <strong>procédure d'équivalence</strong> remplace le passeport. MiFID 2 a aussi <strong>renforcé l'échange d'informations entre autorités nationales</strong>.</li>\n<li>La directive <strong>Solvabilité II</strong> concerne <strong>l'assurance</strong>.</li>\n</ul>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p><strong>Le Royaume-Uni est un pays tiers depuis le 1er janvier 2021</strong> : plus de passeport, seulement des équivalences.</p>\n</aside>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p>L'UE s'est dotée en 2024 d'une <strong>quatrième autorité</strong>, l'<strong>AMLA</strong> (lutte contre le blanchiment, à Francfort), traitée au thème 3.</p>\n</aside>\n<div class=\"ids\" data-sub=\"1.2.1\"></div>\n<hr/>\n<h2 id=\"1-2-2-le-cadre-international\">1.2.2 Le cadre international</h2>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Organisme</th>\n<th>Mission</th>\n<th>Moyen de retenir</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>FMI</strong> (accords de <strong>Bretton Woods</strong>, 1944)</td>\n<td><strong>Stabilité financière</strong> et monétaire, <strong>faciliter le commerce international</strong> ; publie chaque année le <strong>rapport sur la stabilité financière dans le monde</strong> (GFSR)</td>\n<td><span class=\"tag t-mnemo\">mnémo</span> <strong>B</strong>retton <strong>W</strong>oods = <strong>B</strong>anque mondiale + FMI</td>\n</tr>\n<tr>\n<td><strong>Comité de Bâle</strong> (1974, au sein de la <strong>BRI</strong>)</td>\n<td><strong>Contrôle prudentiel bancaire</strong> : solidité du système mondial, coopération entre superviseurs. Ses accords (Bâle I, II, III) sont transposés en Europe par la <strong>CRD et le CRR</strong></td>\n<td><span class=\"tag t-mnemo\">mnémo</span> <strong>Bâle = Banques</strong></td>\n</tr>\n<tr>\n<td><strong>OICV / IOSCO</strong> (1983)</td>\n<td>Établit des <strong>standards internationaux</strong> pour les <strong>marchés de valeurs mobilières</strong>. <strong>Aucun pouvoir de sanction ni de contrôle</strong></td>\n<td><span class=\"tag t-mnemo\">mnémo</span> <strong>IOSCO = Securities</strong> (le S de valeurs mobilières)</td>\n</tr>\n<tr>\n<td><strong>FSB / Conseil de stabilité financière</strong> (G20 de Londres, 2009)</td>\n<td><strong>Surveiller le système financier mondial</strong>, identifier ses <strong>vulnérabilités</strong>, recommander des mesures ; liste des banques systémiques mondiales (avec coussins de fonds propres et TLAC)</td>\n<td><span class=\"tag t-mnemo\">mnémo</span> <strong>FSB = Financial Stability = vue d'ensemble mondiale</strong></td>\n</tr>\n<tr>\n<td><strong>GAFI / FATF</strong></td>\n<td>Lutte contre le blanchiment (thème 3)</td>\n<td>—</td>\n</tr>\n</tbody>\n</table></div>\n<ul>\n<li>L'AMF <strong>peut signer des accords de coopération avec ses homologues du monde entier</strong>, pas seulement dans l'UE ou la zone euro.</li>\n</ul>\n<aside class=\"callout c-warn\"><span class=\"callout-label\">Piège</span>\n<p>Le Comité de Bâle <strong>ne fait pas</strong> de politique monétaire, ne surveille pas les marchés de la zone euro et ne lutte pas contre la criminalité financière. Les standards de lutte anti-blanchiment relèvent du <strong>GAFI</strong>, pas du FSB.</p>\n</aside>\n<div class=\"ids\" data-sub=\"1.2.2\"></div>\n<hr/>\n<h2 id=\"1-3-les-acteurs-de-lintermédiation-et-de-la-distribution\">1.3 Les acteurs de l'intermédiation et de la distribution</h2>\n<h3 id=\"la-famille-des-psi-prestataires-de-services-dinvestissement\">La famille des PSI (prestataires de services d'investissement)</h3>\n<p>Un <strong>PSI</strong> est l'un des trois statuts suivants, agréé pour fournir des services d'investissement. L'agrément est obligatoire <strong>quelle que soit sa taille</strong>, sauf pour une entreprise qui ne sert <strong>que son propre groupe</strong>.</p>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Statut</th>\n<th>Définition</th>\n<th>Agrément</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Établissement de crédit (EC)</strong></td>\n<td>Banque. Avec l'agrément pour les services d'investissement, <strong>il est un PSI</strong>. Un même établissement peut cumuler les deux statuts.</td>\n<td><strong>ACPR</strong> + programme d'activité approuvé par l'<strong>AMF</strong></td>\n</tr>\n<tr>\n<td><strong>Entreprise d'investissement (EI)</strong></td>\n<td><strong>Personne morale autre qu'une SGP ou un EC</strong>, agréée pour fournir des services d'investissement <strong>à titre habituel</strong></td>\n<td><strong>ACPR</strong> + programme d'activité approuvé par l'<strong>AMF</strong></td>\n</tr>\n<tr>\n<td><strong>Société de gestion de portefeuille (SGP)</strong></td>\n<td>Gestion pour compte de tiers à titre principal (mandats, OPC)</td>\n<td><strong>AMF uniquement</strong></td>\n</tr>\n</tbody>\n</table></div>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« EI = Ni SGP Ni Banque »</strong> (une entreprise d'investissement est « autre que » les deux).</p>\n</aside>\n<aside class=\"callout c-warn\"><span class=\"callout-label\">Piège</span>\n<p>« Pour exercer la gestion de portefeuille, le PSI revêt le statut de… » → <strong>SGP</strong>. « Dans quel statut un <strong>établissement de crédit</strong> peut-il gérer des portefeuilles ? » → <strong>PSI</strong>. Lis bien qui est le sujet de la question.</p>\n</aside>\n<h3 id=\"les-intermédiaires-immatriculés-à-lorias\">Les intermédiaires immatriculés à l'ORIAS</h3>\n<p>L'<strong>ORIAS</strong> est l'<strong>Organisme pour le registre unique des intermédiaires en assurance, banque et finance</strong>.</p>\n<ul>\n<li>L'inscription est <strong>renouvelée chaque année</strong> et peut être radiée.</li>\n<li>L'ORIAS <strong>ne contrôle pas</strong> les règles de non-cumul des statuts : il les rappelle lors de l'inscription et les mentionne publiquement.</li>\n<li>Doivent s'y inscrire : les <strong>intermédiaires en assurance</strong> (dont l'<strong>agent général d'assurance</strong>, généralement une <strong>personne physique</strong>), les <strong>IOBSP</strong>, les <strong>CIF</strong>, les <strong>agents liés</strong> de PSI et les <strong>IFP</strong>.</li>\n<li><strong>N'ont pas à s'y inscrire</strong> : un chargé de clientèle salarié, un trader salarié, un marchand de biens.</li>\n</ul>\n<p><strong>IOBSP</strong> (intermédiaire en opérations de banque et en services de paiement) : il <strong>présente, propose ou aide à conclure</strong> des opérations de banque ou des services de paiement, <strong>contre rémunération</strong> et <strong>sans se porter ducroire</strong> (sans garantir la bonne fin).</p>\n<h3 id=\"le-cif-conseiller-en-investissements-financiers-le-statut-le\">Le CIF (conseiller en investissements financiers) : le statut le plus interrogé</h3>\n<ul>\n<li><strong>Activités</strong> :\n<ul>\n<li>conseil en investissement, conseil sur la fourniture de services d'investissement, <strong>conseil sur les biens divers</strong> (activité normale, pas seulement accessoire) ;</li>\n<li><strong>réception-transmission d'ordres (RTO) sur des parts ou actions d'OPC</strong>, mais <strong>pas</strong> de gestion sous mandat ni de gestion d'OPC ;</li>\n<li><strong>démarchage</strong> en vue de proposer son conseil.</li>\n</ul>\n</li>\n</ul>\n<aside class=\"callout c-warn\"><span class=\"callout-label\">Piège</span>\n<p><strong>Confirmé au BTS Banque 2026</strong> : à la question « Outre le conseil, quelles activités un CIF peut-il pratiquer ? », la bonne réponse peut être la <strong>RTO sur OPC</strong> (question EF26-07) et non le démarchage (question 96 de la base). Lis les trois propositions avant de répondre par réflexe.</p>\n</aside>\n<ul>\n<li><strong>Conditions</strong> :\n<ul>\n<li>conditions d'<strong>âge et d'honorabilité</strong> ;</li>\n<li><strong>compétence professionnelle adaptée</strong> (formation ou diplôme) ;</li>\n<li><strong>assurance de responsabilité civile professionnelle</strong> ;</li>\n<li>moyens techniques et procédures adaptés ;</li>\n<li><strong>immatriculation à l'ORIAS</strong> ;</li>\n<li><strong>adhésion à une et une seule association agréée par l'AMF</strong>.</li>\n</ul>\n</li>\n<li><strong>Pas d'agrément de l'AMF</strong>, pas de diplôme de niveau master obligatoire, pas de budget minimum.</li>\n<li><strong>Avant tout conseil</strong> : il fait signer une <strong>lettre de mission</strong>, qui précise notamment <strong>sa rémunération</strong>. Il indique si son conseil est <strong>indépendant ou non</strong>.</li>\n<li><strong>Jamais</strong> il ne reçoit de fonds ou d'instruments financiers de ses clients, à l'exception de ses honoraires.</li>\n<li><strong>Contrôle</strong> : 1er niveau par <strong>son association</strong>, puis <strong>l'AMF</strong>, qui contrôle et sanctionne.</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>CIF = « Une Lettre, Une Association, Un registre, Zéro fonds »</strong> :</p>\n<ul>\n<li><strong>Lettre</strong> de mission avant tout conseil ;</li>\n<li><strong>une seule</strong> association agréée AMF ;</li>\n<li><strong>ORIAS</strong> ;</li>\n<li><strong>jamais</strong> de fonds des clients.</li>\n</ul>\n</aside>\n<h3 id=\"les-autres-acteurs-à-connaître\">Les autres acteurs à connaître</h3>\n<ul>\n<li><strong>Entreprises d'assurance</strong> : elles <strong>peuvent proposer des instruments financiers</strong> (unités de compte). Le contrat d'assurance-vie relève du <strong>Code des assurances</strong> (thème 7.6).</li>\n<li><strong>CGPI</strong> (« conseiller en gestion de patrimoine indépendant ») : <strong>aucune existence légale</strong>. Le titre ne donne aucun droit.</li>\n<li><strong>Intermédiaire en biens divers</strong> : il commercialise un bien en mettant en avant son <strong>rendement financier probable</strong> (thème 7.9).</li>\n<li><strong>Plateformes de négociation</strong> : elles sont supervisées par l'AMF et l'ACPR. MiFID 2 fixe un <strong>cadre harmonisé</strong> pour les entreprises de pays tiers.</li>\n</ul>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p><strong>Financement participatif</strong> : depuis le <strong>10 novembre 2023</strong>, le règlement européen <strong>ECSP</strong> a supprimé le statut de <strong>CIP</strong> (conseiller en investissements participatifs). Les plateformes sont devenues des <strong>PSFP</strong> (prestataires de services de financement participatif), <strong>agréés par l'AMF</strong> et dotés d'un passeport européen. Les questions 101 et 115 de la base reposent encore sur le statut de CIP (voir l'annexe A).</p>\n</aside>\n<div class=\"ids\" data-sub=\"1.3\"></div>\n<hr/>\n<h2 id=\"1-5-1-politique-économique-et-monétaire-indicateurs-risque-s\">1.5.1 Politique économique et monétaire, indicateurs, risque systémique</h2>\n<h3 id=\"la-bce-et-leurosystème\">La BCE et l'Eurosystème</h3>\n<ul>\n<li>La <strong>zone euro</strong> regroupe les <strong>pays de l'UE ayant adopté l'euro</strong>.</li>\n<li>L'<strong>Eurosystème</strong> réunit la <strong>BCE et les banques centrales nationales de la zone euro</strong>. Il <strong>définit et conduit</strong> la politique monétaire unique ; ce n'est <strong>pas la BCE seule</strong>.</li>\n<li>Le <strong>SEBC</strong> (Système européen de banques centrales) réunit la BCE et les banques centrales des <strong>27 États de l'UE</strong>. Les traités lui confient l'orientation de la politique monétaire.</li>\n<li>Le <strong>Conseil des gouverneurs</strong> de la BCE fixe la politique monétaire <strong>en toute indépendance</strong> : ni les ministres, ni l'Ecofin n'interviennent.</li>\n<li>La BCE a la <strong>personnalité juridique</strong>.</li>\n<li><strong>Billets</strong> : la BCE autorise leur émission, et <strong>la BCE et les banques centrales nationales</strong> de la zone euro les émettent.</li>\n<li><strong>Objectif principal : la stabilité des prix.</strong> La BCE ne vise ni le chômage, ni la surveillance des marchés, ni l'agrément des banques.</li>\n<li><strong>Pour la France</strong>, la politique monétaire est décidée par la <strong>BCE</strong>, pas par la Banque de France.</li>\n</ul>\n<p><strong>Les trois taux directeurs</strong> (la BCE les fixe, mais <strong>ne fixe pas le taux de change</strong> de l'euro) :</p>\n<ol>\n<li><strong>Taux des opérations principales de refinancement (REFI)</strong> : le taux auquel les banques <strong>empruntent à la BCE</strong>, via des opérations d'<em>open market</em> à <strong>7 jours</strong> ;</li>\n<li><strong>Taux de la facilité de dépôt</strong> : la rémunération des dépôts des banques ;</li>\n<li><strong>Taux de la facilité de prêt marginal</strong> : le plafond du corridor.</li>\n</ol>\n<p>Les prêts de la banque centrale sont <strong>toujours garantis par des actifs</strong> (collatéral). En crise, la BCE <strong>se substitue au marché interbancaire</strong> pour apporter davantage de liquidité.</p>\n<aside class=\"callout c-warn\"><span class=\"callout-label\">Piège</span>\n<p>L'<strong>EONIA</strong>, l'<strong>EURIBOR</strong> et l'<strong>€STR</strong> ne sont <strong>pas</strong> des taux directeurs : ce sont des taux de marché.</p>\n</aside>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p><strong>Cible d'inflation</strong> : depuis juillet 2021, la BCE vise <strong>2 % à moyen terme, de façon symétrique</strong>. L'ancienne formule de la base (« inférieure à, mais proche de 2 % », <a class=\"qref\" href=\"#\" data-q=\"150\">Q150</a>) est dépassée, mais c'est la seule réponse qui cite 2 %.</p>\n</aside>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p>Depuis septembre 2024, c'est le <strong>taux de la facilité de dépôt</strong> qui pilote en pratique la politique monétaire. Il est fixé à <strong>2 % depuis juin 2025</strong> (à vérifier à la date de ton examen).</p>\n</aside>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p>La zone euro compte <strong>21 pays depuis l'entrée de la Bulgarie le 1er janvier 2026</strong> (la Croatie l'avait rejointe en 2023).</p>\n</aside>\n<h3 id=\"les-politiques-budgétaire-et-fiscale\">Les politiques budgétaire et fiscale</h3>\n<ul>\n<li>La <strong>politique fiscale relève de chaque État</strong>, qui peut en déléguer une partie au niveau local.</li>\n<li>Les politiques économiques nationales doivent respecter les <strong>grandes orientations adoptées par le Conseil de l'UE</strong>. Si un État menace le fonctionnement de l'Union économique et monétaire, la <strong>Commission peut lui adresser un avertissement</strong>. Elle ne peut ni l'exclure, ni lui imposer une politique sous astreinte.</li>\n</ul>\n<h3 id=\"les-indicateurs-à-savoir-définir\">Les indicateurs à savoir définir</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Indicateur</th>\n<th>Définition à retenir</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>PIB</strong></td>\n<td><strong>Somme des valeurs ajoutées</strong> créées par les unités productrices <strong>résidentes</strong> sur le territoire (la nationalité ne compte pas). C'est le résultat final de l'activité de production.</td>\n</tr>\n<tr>\n<td><strong>Croissance</strong></td>\n<td><strong>Variation du PIB en volume (réel)</strong> d'une année sur l'autre.</td>\n</tr>\n<tr>\n<td><strong>PIB par habitant</strong></td>\n<td>Sert à comparer les niveaux de vie entre pays.</td>\n</tr>\n<tr>\n<td><strong>PIB mondial</strong></td>\n<td>Somme des PIB nationaux <strong>convertis en dollars</strong>.</td>\n</tr>\n<tr>\n<td><strong>Inflation</strong></td>\n<td><strong>Hausse générale et durable des prix</strong> = <strong>perte du pouvoir d'achat de la monnaie</strong>. Mesurée par l'<strong>IPC</strong> (indice des prix à la consommation, INSEE). Elle <strong>érode l'épargne liquide</strong>.</td>\n</tr>\n<tr>\n<td><strong>Désinflation / déflation / stagflation</strong></td>\n<td><strong>Ralentissement</strong> de l'inflation / <strong>baisse</strong> générale des prix / <strong>forte inflation + croissance faible</strong>.</td>\n</tr>\n<tr>\n<td><strong>Taux d'intérêt légal</strong></td>\n<td>Fixé par <strong>arrêté du ministre de l'économie</strong>.</td>\n</tr>\n</tbody>\n</table></div>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>STAG-flation</strong> = l'économie <strong>stagne</strong> pendant que les prix <strong>flambent</strong>.</p>\n</aside>\n<h3 id=\"le-rôle-des-marchés-financiers\">Le rôle des marchés financiers</h3>\n<ul>\n<li>Ils <strong>mettent en relation directe</strong> les agents qui ont <strong>besoin de capitaux</strong> et ceux qui ont une <strong>capacité de financement</strong> : c'est le <strong>financement de l'économie</strong> (désintermédiation).</li>\n<li>Le marché peut être un lieu <strong>physique ou virtuel</strong>.</li>\n<li>Les <strong>fluctuations</strong> des cours dépendent de <strong>nombreux paramètres</strong> : résultats des entreprises, croissance, chômage, taux d'intérêt. Un cours monte en général quand les résultats dépassent les <strong>prévisions</strong>.</li>\n<li><strong>Volatilité</strong> = <strong>ampleur des variations</strong> de prix, donc mesure de <strong>risque</strong> (pas de performance).</li>\n<li><strong>Marché liquide</strong> = on peut traiter facilement une quantité raisonnable <strong>sans trop décaler les cours</strong> ; la liquidité est liée au <strong>volume de transactions</strong>.</li>\n<li><strong>Fluctuations intraday</strong> : les variations entre l'ouverture et la clôture d'une même séance.</li>\n<li>Les instruments les plus <strong>sensibles aux variations des taux d'intérêt</strong> sont les <strong>obligations</strong>.</li>\n</ul>\n<h3 id=\"micro-prudentiel-macro-prudentiel-et-risque-systémique\">Micro-prudentiel, macro-prudentiel et risque systémique</h3>\n<ul>\n<li><strong>Risque systémique</strong> : risque de <strong>perturbation du système financier</strong> pouvant avoir de <strong>graves répercussions sur l'économie réelle</strong>.\n<ul>\n<li>Il peut venir des <strong>intermédiaires, des marchés et des infrastructures</strong>.</li>\n<li>L'importance systémique d'un établissement s'apprécie au niveau <strong>international, national et local</strong>.</li>\n<li>Exemple typique : la défaillance massive des emprunteurs d'un <strong>gros</strong> établissement.</li>\n<li>Un établissement est « systémique » quand <strong>sa faillite troublerait gravement le système et l'économie</strong>, pas parce qu'il est coté ou présent dans plusieurs pays.</li>\n</ul>\n</li>\n<li><strong>Micro-prudentiel</strong> : règles prudentielles imposées à <strong>chaque établissement</strong> (ACPR, BCE).</li>\n<li><strong>Macro-prudentiel</strong> : surveillance <strong>du système dans son ensemble</strong>, par le <strong>CERS</strong> (UE) et le <strong>HCSF</strong> (France). Les <strong>coussins de fonds propres</strong> et la <strong>TLAC</strong> imposés aux grandes banques visent le <strong>risque systémique</strong>.</li>\n</ul>\n<div class=\"ids\" data-sub=\"1.5.1\"></div>\n<hr/>\n<h2 id=\"1-5-2-marchés-internationaux-de-capitaux-indicateurs-pays-ém\">1.5.2 Marchés internationaux de capitaux, indicateurs, pays émergents</h2>\n<ul>\n<li><strong>Taux de change</strong> : parité d'une monnaie contre une autre. Le régime peut être <strong>fixe</strong> ou <strong>flottant</strong> ; l'<strong>EUR/USD flotte selon l'offre et la demande</strong>. Le <strong>marché des changes est un marché de gré à gré, non réglementé</strong>.</li>\n<li><strong>Réserves de change</strong> : les <strong>devises étrangères détenues par les banques centrales</strong>.</li>\n<li><strong>Balance commerciale</strong> = exportations − importations de biens. La <strong>balance des paiements</strong> est un document de <strong>comptabilité nationale</strong> harmonisé (pas un document privé IFRS).</li>\n<li><strong>Fed funds target</strong> : le <strong>taux directeur de la Réserve fédérale américaine</strong>.</li>\n<li><strong>Indice de l'université du Michigan</strong> : il mesure la <strong>confiance des consommateurs</strong>.</li>\n<li><strong>Taux courts</strong> : les taux du <strong>marché monétaire</strong> (du jour le jour à 3 mois…).</li>\n<li><strong>€STR</strong> : le taux au jour le jour <strong>non garanti</strong> des banques, publié par la <strong>BCE</strong>. Il a remplacé l'EONIA.</li>\n<li><strong>RDB</strong> (revenu disponible brut) : le revenu des ménages <strong>après prélèvements sociaux et fiscaux</strong>. <strong>Taux d'épargne</strong> = épargne / RDB.</li>\n<li><strong>MSCI</strong> : grand <strong>fournisseur de données et d'indices</strong>, dont le <strong>MSCI Emerging Markets</strong>, un indice actions des pays émergents.</li>\n<li><strong>OCDE</strong> : Organisation de coopération et de développement économiques.</li>\n</ul>\n<p><strong>Les risques à reconnaître</strong></p>\n<ul>\n<li>Un investisseur en euros qui achète des actions brésiliennes en real supporte <strong>deux risques : change + action</strong>.</li>\n<li><strong>Liquidité</strong> : ne pas pouvoir vendre, ou seulement avec une forte décote.</li>\n<li><strong>Crédit</strong> : l'emprunteur ne rembourse pas.</li>\n<li><strong>Opérationnel</strong> : panne informatique, erreur de sens d'ordre. <strong>Une variation du dollar n'est pas un risque opérationnel</strong> : c'est un risque de marché (change).</li>\n</ul>\n<p><strong>Les pays émergents</strong></p>\n<ul>\n<li>Exemples : Brésil, Colombie, Égypte, Vietnam. Les <strong>BRICS</strong> sont le <strong>Brésil, la Russie, l'Inde, la Chine et l'Afrique du Sud</strong>.</li>\n<li>Leurs marchés sont <strong>plus risqués</strong>, <strong>moins liquides</strong> et <strong>plus volatils</strong> que ceux des pays développés. Le <strong>risque de défaut d'un État</strong> y dépend de sa <strong>solvabilité ET de sa liquidité</strong>.</li>\n<li>Ils améliorent la <strong>diversification</strong> grâce à une <strong>corrélation plus faible</strong> avec les pays développés. Mais la diversification géographique <strong>n'est pas toujours suffisante</strong>, car les mêmes classes d'actifs sont souvent corrélées d'un pays à l'autre.</li>\n<li>Pour cibler un fort potentiel de développement, on regarde d'abord le <strong>taux de croissance du PIB</strong>.</li>\n</ul>\n<p><strong>Repères historiques</strong></p>\n<ul>\n<li>La <strong>crise des subprimes</strong> est née de la <strong>hausse des taux de la Fed</strong>, qui a alourdi les charges des emprunteurs à taux variable.</li>\n<li>Le <strong>LIBOR</strong> et l'<strong>EURIBOR</strong> ont été réformés <strong>après des manipulations frauduleuses</strong>.</li>\n</ul>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p>Le <strong>LIBOR a disparu</strong> (2021-2023). L'<strong>EURIBOR a été réformé</strong> et existe toujours (administré par l'<strong>EMMI</strong>). L'<strong>EONIA a disparu le 3 janvier 2022</strong> au profit de l'<strong>€STR</strong>. Le détail des indices de référence est au §7.4.</p>\n</aside>\n<div class=\"ids\" data-sub=\"1.5.2\"></div>\n<hr/>\n<h2 id=\"1-8-cadre-juridique-des-instruments-financiers-et-des-servic\">1.8 Cadre juridique des instruments financiers et des services d'investissement</h2>\n<h3 id=\"instruments-financiers-cmf-l-211-1\">Instruments financiers (CMF L.211-1)</h3>\n<ul>\n<li>Ce sont les <strong>titres financiers</strong> (actions, obligations, TCN, parts et actions d'OPC) et les <strong>contrats financiers</strong> (= <strong>dérivés</strong> : options, futures, swaps, CFD…).</li>\n<li>Ce <strong>ne sont pas</strong> des instruments financiers : les effets de commerce, les bons de caisse, les livrets ni les fiducies.</li>\n</ul>\n<h3 id=\"les-10-services-dinvestissement-cmf-l-321-1\">Les 10 services d'investissement (CMF L.321-1)</h3>\n<ol>\n<li>Réception et transmission d'ordres pour le compte de tiers (<strong>RTO</strong>) ;</li>\n<li><strong>Exécution</strong> d'ordres pour le compte de tiers ;</li>\n<li><strong>Négociation pour compte propre</strong> ;</li>\n<li><strong>Gestion de portefeuille</strong> pour le compte de tiers ;</li>\n<li><strong>Conseil</strong> en investissement ;</li>\n<li><strong>Prise ferme</strong> ;</li>\n<li><strong>Placement garanti</strong> ;</li>\n<li><strong>Placement non garanti</strong> ;</li>\n<li>Exploitation d'un <strong>MTF</strong> (système multilatéral de négociation) ;</li>\n<li>Exploitation d'un <strong>OTF</strong> (système organisé de négociation).</li>\n</ol>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« RÉ-EX-NÉ-GÉ-CO, 3 P et 2 systèmes »</strong> : RTO – EXécution – NÉgociation – GEstion – COnseil + Prise ferme, Placement garanti, Placement non garanti + MTF et OTF.</p>\n</aside>\n<aside class=\"callout c-warn\"><span class=\"callout-label\">Piège</span>\n<p><strong>Ne sont pas</strong> des services d'investissement : la tenue d'un livret A, la vente d'un livret ou d'une assurance-vie, l'émission de bons de caisse, le conseil juridique, le conseil en opérations de banque ou en biens divers, la diffusion de moyens de paiement, le prêt de titres.</p>\n</aside>\n<p><strong>Services connexes</strong> (CMF L.321-2) : conservation et administration d'instruments financiers, octroi de crédit pour réaliser une transaction, conseil aux entreprises (structure du capital, fusions), change lié, <strong>recherche en investissements et analyse financière</strong>, services liés à la prise ferme.</p>\n<p><strong>Le conseil en investissement</strong> consiste à fournir des <strong>recommandations personnalisées</strong> sur une ou plusieurs <strong>transactions portant sur des instruments financiers</strong>, <strong>soit à la demande du client, soit à l'initiative du prestataire</strong>. Ce n'est pas une analyse générale, ni une recommandation générale de répartition du patrimoine, ni une explication du fonctionnement des marchés.</p>\n<h3 id=\"agréments-récapitulatif\">Agréments : récapitulatif</h3>\n<ul>\n<li><strong>AMF</strong> : SGP (avec un <strong>programme d'activité pour chaque service</strong>, des <strong>fonds propres réglementés</strong> par le CMF et le RG AMF et renforcés depuis AIFM), OPC dont les <strong>OPCI</strong> (une SCI ou une SCA n'a pas d'agrément AMF).</li>\n<li><strong>ACPR</strong> : EC et EI, plus approbation du programme d'activité par l'AMF.</li>\n<li><strong>Pas d'agrément</strong> pour l'entreprise qui ne sert que les sociétés de <strong>son propre groupe</strong>.</li>\n<li>Les <strong>MTF (SMN)</strong> peuvent organiser la négociation de titres <strong>qu'ils admettent eux-mêmes</strong> ET de titres admis sur un marché réglementé.</li>\n</ul>\n<h3 id=\"sanctions-et-responsabilités-ne-pas-mélanger\">Sanctions et responsabilités : ne pas mélanger</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Qui</th>\n<th>Exemples</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Administrative</strong></td>\n<td>AMF (Commission des sanctions), ACPR</td>\n<td>Avertissement, blâme, <strong>interdiction d'exercer</strong>, <strong>sanction pécuniaire</strong>. Pour un PSI : sanctions <strong>disciplinaires ET pécuniaires</strong>.</td>\n</tr>\n<tr>\n<td><strong>Pénale</strong></td>\n<td>Tribunal correctionnel</td>\n<td><strong>Emprisonnement</strong>, amendes (délit d'initié…)</td>\n</tr>\n<tr>\n<td><strong>Civile</strong></td>\n<td>Juge civil</td>\n<td><strong>Réparer le dommage</strong> causé à la victime (dommages et intérêts), en matière de devoir d'information, de conseil ou de mise en garde</td>\n</tr>\n</tbody>\n</table></div>\n<ul>\n<li><strong>Composition administrative</strong> : la personne s'engage à <strong>verser au Trésor public</strong> une somme, ce qui évite la procédure de sanction.</li>\n<li><strong>Injonction</strong> : le <strong>Collège</strong> de l'AMF peut <strong>ordonner qu'il soit mis fin</strong> à un manquement.</li>\n</ul>\n<div class=\"ids\" data-sub=\"1.8\"></div>\n<hr/>\n<h2 class=\"flash\" id=\"fiche-flash-du-thème-1-à-relire-la-veille\"> Fiche flash du thème 1 (à relire la veille)</h2>\n<ol>\n<li><strong>AMF</strong> : autorité publique indépendante, missions fixées par le <strong>CMF</strong>, agrée les <strong>SGP (seule)</strong> et les OPC. Organes : <strong>Collège (16) + Commission des sanctions + commissions consultatives</strong>. Elle sanctionne <strong>tout le monde</strong>.</li>\n<li><strong>ACPR</strong> : <strong>adossée à la Banque de France</strong>, agrée les <strong>EC et EI</strong> (programme d'activité approuvé par l'AMF), s'occupe de la <strong>résolution</strong> et sanctionne <strong>seulement ses assujettis</strong>.</li>\n<li><strong>CCLRF</strong> = avis sur les <strong>textes</strong> (non rémunéré) · <strong>CCSF</strong> = <strong>relations avec les clients</strong> · <strong>HCSF</strong> = <strong>tout le système</strong>, risque systémique (8 membres, présidé par le ministre).</li>\n<li><strong>Ministre de l'économie</strong> = pouvoir réglementaire, homologue le RG AMF, fixe le taux légal, reconnaît les marchés réglementés.</li>\n<li><strong>SESF</strong> = <strong>ESMA</strong> (marchés, Paris, l'AMF y siège), <strong>EBA</strong> (banques, Paris), <strong>EIOPA</strong> (assurance, Francfort) + <strong>CERS</strong> (macroprudentiel).</li>\n<li><strong>Union bancaire</strong> : zone euro + coopération rapprochée ; <strong>MSU (BCE + autorités nationales ; la BCE désigne les banques significatives) – MRU – SGD (100 000 €)</strong>.</li>\n<li><strong>Passeport</strong> : agrément du pays d'origine, valable dans l'UE, <strong>seulement pour les services agréés</strong> ; pour un fonds, c'est la <strong>SGP</strong> qui l'obtient.</li>\n<li><strong>Bâle</strong> = banques · <strong>IOSCO</strong> = standards des marchés de titres (pas de sanction) · <strong>FSB</strong> = vulnérabilités du système mondial · <strong>FMI</strong> = Bretton Woods, rapport sur la stabilité financière.</li>\n<li><strong>CIF</strong> : <strong>1 seule association agréée AMF, ORIAS, lettre de mission, jamais de fonds</strong>, conseil possible sur les <strong>biens divers</strong>, RTO sur OPC, <strong>pas d'agrément AMF</strong>.</li>\n<li><strong>EI</strong> = personne morale <strong>autre que SGP et EC</strong> · <strong>PSI</strong> = EC + EI + SGP · <strong>CGPI</strong> = aucun statut légal.</li>\n<li><strong>Eurosystème</strong> (BCE + BCN de la zone euro) définit la politique monétaire ; objectif = <strong>stabilité des prix (2 % symétrique)</strong> ; taux <strong>REFI</strong> = taux auquel les banques empruntent à la BCE (7 jours, prêts <strong>garantis</strong>).</li>\n<li><strong>PIB</strong> = somme des <strong>valeurs ajoutées</strong> des <strong>résidents</strong> ; <strong>croissance</strong> = variation du PIB réel ; <strong>inflation</strong> = hausse générale et durable des prix = baisse du pouvoir d'achat (IPC).</li>\n<li><strong>10 services d'investissement</strong> (RÉ-EX-NÉ-GÉ-CO + 3P + MTF/OTF) ; la recherche et l'analyse financière sont des services <strong>connexes</strong>.</li>\n<li>Sanction <strong>administrative</strong> (AMF) ≠ <strong>pénale</strong> (prison, juge) ≠ <strong>civile</strong> (réparation du dommage).</li>\n</ol>\n","toc":[{"id":"1-1-le-cadre-de-tutelle-français","t":"1.1 Le cadre de tutelle français"},{"id":"1-2-1-le-cadre-européen","t":"1.2.1 Le cadre européen"},{"id":"1-2-2-le-cadre-international","t":"1.2.2 Le cadre international"},{"id":"1-3-les-acteurs-de-lintermédiation-et-de-la-distribution","t":"1.3 Les acteurs de l'intermédiation et de la distribution"},{"id":"1-5-1-politique-économique-et-monétaire-indicateurs-risque-s","t":"1.5.1 Politique économique et monétaire, indicateurs, risque systémique"},{"id":"1-5-2-marchés-internationaux-de-capitaux-indicateurs-pays-ém","t":"1.5.2 Marchés internationaux de capitaux, indicateurs, pays émergents"},{"id":"1-8-cadre-juridique-des-instruments-financiers-et-des-servic","t":"1.8 Cadre juridique des instruments financiers et des services d'investissement"},{"id":"fiche-flash-du-thème-1-à-relire-la-veille","t":"Fiche flash du thème 1 (à relire la veille)"}]},{"id":"02","n":2,"title":"Déontologie, conformité et organisation déontologique des établissements","html":"\n<blockquote class=\"note\">\n<p><strong>Poids à l'examen : 6 questions sur 120, toutes en catégorie A</strong> (les 80 % se jouent aussi ici).\nRépartition : §2.1 (2) · §2.2 (2) · §2.3 (2).\nThème court et très régulier : les mêmes formules reviennent mot pour mot. Apprends-les telles quelles.</p>\n</blockquote>\n<hr/>\n<h2 id=\"2-1-fondements-des-règles-de-bonne-conduite-et-fonction-conf\">2.1 Fondements des règles de bonne conduite et fonction conformité</h2>\n<h3 id=\"la-phrase-à-connaître-par-cœur\">La phrase à connaître par cœur</h3>\n<blockquote class=\"note\">\n<p>Le PSI doit agir <strong>d'une manière honnête, loyale et professionnelle</strong>, qui <strong>serve au mieux l'intérêt des clients</strong> et <strong>favorise l'intégrité du marché</strong> (CMF L.533-11, RG AMF 314-3).</p>\n</blockquote>\n<p><span class=\"tag t-mnemo\">mnémo</span> <strong>« H-L-P »</strong> = <strong>H</strong>onnête, <strong>L</strong>oyale, <strong>P</strong>rofessionnelle. Méfie-toi des variantes piégées : « protectrice », « louable ».\n<span class=\"tag t-mnemo\">mnémo</span> Le PSI sert <strong>deux maîtres en même temps</strong> : <strong>le client ET le marché</strong>. Une réponse qui sacrifie l'un des deux (« sans avoir à préserver l'intégrité du marché », « la primauté du client est laissée à sa discrétion ») est fausse.</p>\n<p><strong>Les 5 principes que garantit la fonction conformité</strong> (grille AMF) :</p>\n<ol>\n<li><strong>Préserver l'intégrité des marchés</strong> ;</li>\n<li><strong>Assurer la primauté des intérêts des clients</strong> (= agir de manière honnête, loyale et professionnelle avec eux) ;</li>\n<li><strong>Fournir aux clients des informations claires, exactes et non trompeuses</strong>, pour <strong>toutes</strong> les communications, pas seulement les publicités ;</li>\n<li><strong>Connaître son client</strong> ;</li>\n<li><strong>Agir de manière honnête, loyale et professionnelle</strong>.</li>\n</ol>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« Marché – Primauté – Info CEN – KYC – HLP »</strong> (CEN = Claire, Exacte, Non trompeuse).</p>\n</aside>\n<aside class=\"callout c-warn\"><span class=\"callout-label\">Piège</span>\n<p>« Informations <strong>précises sur les performances futures</strong> » et « proposer en priorité les produits <strong>les plus rémunérateurs</strong> » sont faux. On ne promet jamais une performance future.</p>\n</aside>\n<ul>\n<li>La <strong>déontologie</strong> est l'<strong>ensemble des devoirs et des règles qu'impose aux professionnels l'exercice de leur métier</strong>, et non les valeurs personnelles de chaque salarié.</li>\n<li>Les <strong>règles de conflits d'intérêts</strong> des PSI sont dans le <strong>Code monétaire et financier</strong> (et le RG AMF).</li>\n<li>Les <strong>codes de bonne conduite</strong> sont élaborés par les <strong>associations professionnelles</strong>.</li>\n</ul>\n<h3 id=\"la-fonction-conformité\">La fonction conformité</h3>\n<ul>\n<li>Elle est <strong>obligatoire dans tous les cas</strong>, même si le PSI ne sert que des clients professionnels.</li>\n<li>Elle est <strong>permanente, indépendante et autonome</strong>, <strong>rattachée directement à la direction</strong>, avec des <strong>moyens humains et matériels suffisants</strong>.</li>\n<li>Son <strong>champ</strong> : <strong>tous les secteurs d'activité</strong> du PSI.</li>\n<li>Son <strong>rôle</strong> : <strong>contrôler et évaluer</strong> les procédures et l'<strong>efficacité des mesures</strong> destinées à éviter tout manquement aux obligations professionnelles. Elle <strong>ne sanctionne pas</strong>, ne traite pas les ordres et ne valide pas le RG AMF.</li>\n<li>Le PSI établit des <strong>procédures pour détecter le risque de manquement</strong> de ses dirigeants, salariés et personnes agissant pour son compte.</li>\n<li>Les personnes de la conformité <strong>ne sont pas impliquées dans les activités qu'elles contrôlent</strong>.</li>\n</ul>\n<h3 id=\"rcsi-ou-rcci\">RCSI ou RCCI ?</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th></th>\n<th><strong>RCSI</strong></th>\n<th><strong>RCCI</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Nom complet</td>\n<td>Responsable de la conformité pour les <strong>services d'investissement</strong></td>\n<td>Responsable de la conformité et du <strong>contrôle interne</strong></td>\n</tr>\n<tr>\n<td>Où ?</td>\n<td><strong>PSI autres que les SGP</strong> (banques, entreprises d'investissement)</td>\n<td><strong>Sociétés de gestion de portefeuille</strong></td>\n</tr>\n<tr>\n<td>Carte professionnelle</td>\n<td><strong>Délivrée par l'AMF</strong>, après un <strong>examen organisé par l'AMF</strong></td>\n<td><strong>Délivrée par l'AMF</strong>, après un <strong>examen organisé par l'AMF</strong></td>\n</tr>\n</tbody>\n</table></div>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>RCC<em>I</em> = gestIon</strong> (SGP) ; <strong>RC<em>S</em>I = Services d'investissement</strong> (les autres PSI).</p>\n<ul>\n<li>Un PSI peut avoir <strong>plusieurs RCSI</strong> si l'AMF juge leur nombre adapté à sa taille, à ses activités et à ses risques. Il n'y a pas de limite fixe.</li>\n<li>En <strong>SGP</strong>, le contrôle interne compte <strong>deux niveaux</strong> : le <strong>contrôle permanent</strong>, qui intègre la conformité, et le <strong>contrôle périodique</strong>. Le RCCI couvre <strong>la conformité, le contrôle permanent et le contrôle périodique</strong>.</li>\n<li>Le <strong>dirigeant</strong> d'une petite SGP <strong>peut être RCCI</strong>, mais il doit alors aussi être responsable du <strong>contrôle périodique et du contrôle permanent hors conformité</strong>.</li>\n</ul>\n</aside>\n<p><strong>Fonctions « réglementées »</strong> : le <strong>responsable de la conformité</strong> (RCSI ou RCCI) est l'exemple type. Les cartes de RCSI et de RCCI sont délivrées par l'<strong>AMF</strong>. D'autres fonctions de marché exigent une carte professionnelle <strong>délivrée par le PSI</strong> : <strong>analyste financier</strong>, négociateur, compensateur. Le back-office, le middle-office, le contrôle des risques et le service juridique n'en demandent pas.</p>\n<aside class=\"callout c-warn\"><span class=\"callout-label\">Piège</span>\n<p>« Quelle fonction nécessite une carte professionnelle <strong>chez un PSI</strong> ? » → <strong>analyste financier</strong> (<a class=\"qref\" href=\"#\" data-q=\"245\">Q245</a>). « <strong>Dans une SGP</strong>, laquelle nécessite une carte <strong>délivrée par l'AMF</strong> ? » → <strong>RCCI</strong>, et non le gérant (<a class=\"qref\" href=\"#\" data-q=\"264\">Q264</a>).</p>\n</aside>\n<div class=\"ids\" data-sub=\"2.1\"></div>\n<hr/>\n<h2 id=\"2-2-déclinaisons-opérationnelles-conflits-dintérêts-transact\">2.2 Déclinaisons opérationnelles : conflits d'intérêts, transactions personnelles, informations privilégiées, alertes</h2>\n<h3 id=\"les-conflits-dintérêts\">Les conflits d'intérêts</h3>\n<ul>\n<li>Le PSI prend <strong>toute mesure raisonnable</strong> pour <strong>détecter</strong> les conflits entre lui-même (ses dirigeants, salariés) et ses clients, et entre ses clients.\n<ul>\n<li>Exemple type : pousser les conseillers à vendre le <strong>produit le plus commissionné</strong> plutôt que le plus adapté.</li>\n</ul>\n</li>\n<li>Les mesures doivent être <strong>raisonnables et appropriées</strong>, jamais « radicales ». Le PSI <strong>n'a pas à refuser systématiquement</strong> l'opération ni à demander l'accord de l'AMF.</li>\n<li>La <strong>politique de gestion des conflits</strong> est <strong>fixée par le PSI lui-même</strong>. Pour un CIF ou une entité <strong>appartenant à un groupe</strong>, elle tient compte des <strong>activités des autres membres du groupe</strong>.</li>\n<li>Le PSI tient un <strong>registre</strong>, mis à jour <strong>régulièrement</strong>, des services exposés à un conflit présentant un risque pour les clients. La <strong>politique</strong> de gestion des conflits d'un CIF est <strong>révisée au moins une fois par an</strong>.</li>\n<li>Il peut organiser une <strong>surveillance séparée</strong> des personnes impliquées dans des activités conflictuelles.</li>\n<li>Les activités <strong>structurellement en conflit</strong> sont la <strong>négociation pour compte propre</strong> et l'<strong>exécution d'ordres pour compte de tiers</strong>.</li>\n<li>Une <strong>SGP qui gère des FIA</strong> doit identifier <strong>tous les conflits d'intérêts, existants et potentiels</strong>, susceptibles d'influencer leur gestion, et pas seulement ceux avec ses collaborateurs ou le dépositaire. Le sujet du BTS Banque 2026 range cette question ici, au §2.2.</li>\n<li><strong>Si les mesures ne suffisent pas</strong>, le PSI <strong>informe clairement le client</strong> avant d'agir, en dernier recours. Il n'informe ni l'ACPR, ni le commissaire aux comptes, ni le dépositaire.</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« Détecter → Prévenir → Gérer → et seulement si ça ne suffit pas : Informer le client »</strong>.</p>\n</aside>\n<h3 id=\"les-barrières-à-linformation-murailles-de-chine\">Les barrières à l'information (« murailles de Chine »)</h3>\n<ul>\n<li><strong>Définition</strong> : l'ensemble des <strong>procédures qui empêchent la circulation indue d'informations privilégiées</strong> entre les entités d'un PSI et qui préviennent les conflits d'intérêts <strong>au détriment des clients</strong>.</li>\n<li>Le PSI <strong>identifie</strong> les entités susceptibles de détenir des informations privilégiées et les <strong>sépare</strong> des autres.</li>\n<li><strong>Modalités</strong> : séparation <strong>physique, juridique, hiérarchique ou logique</strong>, ou <strong>gestion des flux d'information</strong>.</li>\n<li>Le <strong>« franchissement de la muraille »</strong> est l'<strong>autorisation</strong> donnée à une personne d'une entité d'<strong>apporter son concours à une autre entité</strong>, alors que l'une d'elles détient une information privilégiée (procédure encadrée par la conformité).</li>\n<li>Elles <strong>n'interdisent pas</strong> d'avoir à la fois des clients émetteurs et des clients investisseurs.</li>\n</ul>\n<h3 id=\"les-trois-listes\">Les trois listes</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Liste</th>\n<th>Contenu</th>\n<th>Moyen de retenir</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Liste de surveillance</strong> (<em>watch list</em>, confidentielle, <strong>conservée 5 ans</strong>)</td>\n<td>Émetteurs et instruments sur lesquels le PSI <strong>détient une information privilégiée</strong></td>\n<td><span class=\"tag t-mnemo\">mnémo</span> on <strong>surveille</strong>, on ne bloque pas</td>\n</tr>\n<tr>\n<td><strong>Liste d'interdiction</strong> (<em>restricted list</em>)</td>\n<td>Émetteurs et instruments sur lesquels le PSI <strong>doit restreindre son activité</strong> (conseil, recherche, compte propre…)</td>\n<td><span class=\"tag t-mnemo\">mnémo</span> on <strong>interdit</strong> certaines activités</td>\n</tr>\n<tr>\n<td><strong>Liste d'initiés</strong> (règlement MAR)</td>\n<td>Personnes ayant accès à une information privilégiée pour une opération donnée ; <strong>mise à jour régulièrement</strong> et sans délai, pas une fois par an</td>\n<td><span class=\"tag t-mnemo\">mnémo</span> elle <strong>vit</strong> avec l'opération</td>\n</tr>\n</tbody>\n</table></div>\n<h3 id=\"les-transactions-personnelles\">Les transactions personnelles</h3>\n<ul>\n<li><strong>Définition</strong> : une opération réalisée par une <strong>personne concernée</strong> (salarié, dirigeant…) <strong>en dehors du cadre de ses fonctions</strong>, <strong>pour son propre compte OU pour une personne avec laquelle elle a des liens familiaux ou étroits</strong> (« dans les deux cas »).\n<ul>\n<li>Exemple : un gérant qui souscrit, <strong>pour son compte</strong>, des parts du fonds <strong>qu'il gère</strong>.</li>\n<li>Contre-exemples : une opération pour compte propre du PSI, ou un ordre exécuté dans un mandat.</li>\n</ul>\n</li>\n<li>Les règles s'appliquent aux personnes concernées <strong>exposées à des conflits OU ayant accès à des informations privilégiées ou confidentielles</strong>.</li>\n<li>Obligation : <strong>informer sans délai l'employeur</strong> de toute transaction personnelle. Il n'y a ni durée de détention minimale imposée, ni obligation d'ouvrir le compte dans sa propre banque.</li>\n<li>Le PSI <strong>interdit</strong> les transactions personnelles <strong>incompatibles avec ses obligations professionnelles</strong> (abus de marché, information confidentielle, conflit). Il impose aux personnes concernées des mesures de <strong>restriction, d'interdiction et d'abstention</strong>.</li>\n</ul>\n<h3 id=\"les-lanceurs-dalerte-et-le-devoir-dalerte\">Les lanceurs d'alerte et le devoir d'alerte</h3>\n<ul>\n<li>Le collaborateur qui signale <strong>de bonne foi</strong> un manquement exerce sa <strong>faculté d'alerte éthique</strong>. Il est <strong>protégé</strong> : aucune mesure discriminatoire en matière de licenciement, de rémunération ou de formation (loi <strong>Sapin 2</strong>).</li>\n<li>L'<strong>AMF traite les alertes en toute confidentialité</strong>. Elle n'indemnise pas les lanceurs d'alerte et ne communique jamais leur nom.</li>\n</ul>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p><strong>Loi Waserman (2022)</strong> : le lanceur d'alerte <strong>choisit librement</strong> de signaler <strong>en interne ou directement à l'autorité compétente</strong> (AMF, ACPR…). Il n'est plus obligé de passer d'abord par sa hiérarchie. La protection s'étend aux personnes qui l'aident (« facilitateurs »).</p>\n</aside>\n<h3 id=\"lenregistrement-des-communications\">L'enregistrement des communications</h3>\n<p>Depuis MiFID 2, les <strong>conversations téléphoniques et communications électroniques</strong> liées à des ordres ou à des transactions sont <strong>enregistrées</strong>. Le client en est <strong>informé</strong>. Les enregistrements sont <strong>conservés 5 ans</strong>, et jusqu'à 7 ans si l'autorité le demande.</p>\n<div class=\"ids\" data-sub=\"2.2\"></div>\n<hr/>\n<h2 id=\"2-3-traitement-des-réclamations-et-médiation\">2.3 Traitement des réclamations et médiation</h2>\n<h3 id=\"la-réclamation-au-sein-du-psi\">La réclamation au sein du PSI</h3>\n<ul>\n<li><strong>Définition</strong> : une <strong>déclaration actant le mécontentement</strong> d'un client envers le professionnel, <strong>quel qu'en soit le canal</strong>, y compris un <strong>simple appel téléphonique</strong>.</li>\n<li>Ce <strong>n'est pas</strong> une réclamation : une <strong>demande d'information, de clarification ou de documents</strong>.</li>\n<li>Le PSI met en place une <strong>procédure efficace et transparente</strong>, pour le <strong>traitement raisonnable et rapide</strong> des réclamations :\n<ul>\n<li>elle concerne <strong>tous les clients, professionnels comme non professionnels</strong> ;</li>\n<li>elle est <strong>toujours gratuite</strong> ;</li>\n<li>il y a <strong>enregistrement de la réclamation ET des mesures prises</strong> ;</li>\n<li>le service est <strong>séparé des équipes opérationnelles mises en cause</strong> ;</li>\n<li>les réclamations servent à <strong>identifier les dysfonctionnements</strong> et à lancer des <strong>actions correctives</strong> ;</li>\n<li>pour les porteurs <strong>à l'étranger</strong>, la SGP prévoit des modalités adaptées, sans restreindre leurs droits.</li>\n</ul>\n</li>\n</ul>\n<p><strong>Les délais, à savoir sans hésiter :</strong></p>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Étape</th>\n<th>Délai</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Accusé de réception</strong></td>\n<td><strong>10 jours ouvrables</strong> maximum</td>\n</tr>\n<tr>\n<td><strong>Réponse</strong> au client</td>\n<td><strong>2 mois</strong> maximum à compter de la réception</td>\n</tr>\n<tr>\n<td>Saisine du médiateur si pas de réponse</td>\n<td>Au bout de <strong>2 mois</strong></td>\n</tr>\n</tbody>\n</table></div>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« 10 jours pour dire \"bien reçu\", 2 mois pour répondre. »</strong></p>\n</aside>\n<h3 id=\"la-médiation\">La médiation</h3>\n<ul>\n<li>La médiation est un mode de <strong>règlement amiable</strong> des conflits, pas judiciaire. L'avis du médiateur <strong>peut être accepté ou refusé par les parties</strong> : il ne s'impose pas et ne met pas fin au litige d'office.</li>\n<li><strong>Médiation de la consommation</strong> :\n<ul>\n<li>elle concerne les litiges entre le professionnel et un <strong>particulier n'agissant pas pour ses besoins professionnels</strong> ;</li>\n<li>elle est <strong>gratuite</strong> pour le consommateur ;</li>\n<li>le médiateur rend un avis <strong>en droit et en équité</strong> ;</li>\n<li>elle est <strong>impossible si une action en justice est engagée</strong>.</li>\n</ul>\n</li>\n<li><strong>Médiation bancaire</strong> : pour un litige avec une <strong>banque</strong> (crédit, compte courant…). Le client n'est pas obligé d'aller en justice ni chez le médiateur de l'AMF.</li>\n</ul>\n<h3 id=\"le-médiateur-de-lamf\">Le médiateur de l'AMF</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Point</th>\n<th>Ce qu'il faut savoir</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Nomination</td>\n<td>Par le <strong>président de l'AMF, après avis du Collège</strong> (pour 3 ans)</td>\n</tr>\n<tr>\n<td>Qui peut le saisir ?</td>\n<td><strong>Tout épargnant</strong>, personne <strong>physique ou morale</strong>, client <strong>professionnel ou non</strong>, <strong>quel que soit le montant</strong></td>\n</tr>\n<tr>\n<td>Quand ?</td>\n<td><strong>Après une première réclamation écrite</strong> au professionnel, restée insatisfaisante ou <strong>sans réponse au bout de 2 mois</strong>, et <strong>sans procédure judiciaire</strong> en cours</td>\n</tr>\n<tr>\n<td>Compétence</td>\n<td>Matière <strong>financière</strong> : gestion de portefeuille, RTO, ordres de bourse, OPC, <strong>épargne salariale</strong>…</td>\n</tr>\n<tr>\n<td>Hors compétence</td>\n<td><strong>Crédits bancaires</strong>, comptes courants, <strong>assurance-vie</strong>, PEL (médiateurs bancaire ou de l'assurance)</td>\n</tr>\n<tr>\n<td>Coût</td>\n<td><strong>Gratuit</strong>, même si l'avis est défavorable à l'épargnant</td>\n</tr>\n</tbody>\n</table></div>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« Le médiateur de l'AMF ne parle que de BOURSE et d'ÉPARGNE financière : ni crédit, ni assurance-vie, ni PEL. »</strong></p>\n</aside>\n<aside class=\"callout c-warn\"><span class=\"callout-label\">Piège</span>\n<p>Pas de seuil de 1 000 €, pas de réservation aux personnes physiques, pas de délai d'un mois.</p>\n</aside>\n<div class=\"ids\" data-sub=\"2.3\"></div>\n<hr/>\n<h2 class=\"flash\" id=\"fiche-flash-du-thème-2\"> Fiche flash du thème 2</h2>\n<ol>\n<li>PSI = <strong>honnête, loyal, professionnel</strong> → <strong>intérêt du client ET intégrité du marché</strong>.</li>\n<li>Information <strong>claire, exacte, non trompeuse</strong>, pour <strong>toutes</strong> les communications.</li>\n<li>Conformité <strong>obligatoire, indépendante, rattachée à la direction</strong>, sur <strong>toutes</strong> les activités ; elle <strong>contrôle et évalue</strong>, elle <strong>ne sanctionne pas</strong>.</li>\n<li><strong>RCSI</strong> (PSI hors SGP) et <strong>RCCI</strong> (SGP) : <strong>carte professionnelle de l'AMF</strong> après <strong>examen AMF</strong>. En SGP : contrôle <strong>permanent</strong> (avec la conformité) + <strong>périodique</strong>.</li>\n<li>Conflits : mesures <strong>raisonnables et appropriées</strong> ; politique <strong>fixée par le PSI</strong> ; en dernier recours, <strong>informer le client</strong>.</li>\n<li><strong>Murailles de Chine</strong> = barrières contre la <strong>circulation des informations privilégiées</strong> (séparation physique, juridique, hiérarchique, logique).</li>\n<li><strong>Surveillance</strong> = le PSI détient l'information ; <strong>interdiction</strong> = il restreint ses activités ; <strong>initiés</strong> = liste tenue à jour.</li>\n<li><strong>Transaction personnelle</strong> = hors fonctions, pour <strong>soi ou un proche</strong> → <strong>déclaration sans délai</strong> à l'employeur.</li>\n<li><strong>Lanceur d'alerte</strong> de bonne foi = <strong>protégé</strong> ; l'AMF traite les alertes <strong>confidentiellement</strong>.</li>\n<li>Réclamation : <strong>AR sous 10 jours ouvrables, réponse sous 2 mois</strong>, <strong>gratuite</strong>, <strong>tous clients</strong>, enregistrée avec les mesures prises.</li>\n<li><strong>Médiateur AMF</strong> : nommé par le président après avis du Collège, <strong>gratuit</strong>, <strong>tout épargnant</strong> sans seuil, <strong>après une réclamation écrite</strong>, <strong>pas si procès</strong> ; <strong>pas de crédit ni d'assurance-vie</strong>.</li>\n</ol>\n","toc":[{"id":"2-1-fondements-des-règles-de-bonne-conduite-et-fonction-conf","t":"2.1 Fondements des règles de bonne conduite et fonction conformité"},{"id":"2-2-déclinaisons-opérationnelles-conflits-dintérêts-transact","t":"2.2 Déclinaisons opérationnelles : conflits d'intérêts, transactions personnelles, informations privilégiées, alertes"},{"id":"2-3-traitement-des-réclamations-et-médiation","t":"2.3 Traitement des réclamations et médiation"},{"id":"fiche-flash-du-thème-2","t":"Fiche flash du thème 2"}]},{"id":"03","n":3,"title":"Sécurité financière : blanchiment, terrorisme, corruption, embargos","html":"\n<blockquote class=\"note\">\n<p><strong>Poids à l'examen : 3 questions sur 120, catégorie A.</strong>\nLa base compte près de 90 questions sur ce thème, et ce sont toujours les mêmes chiffres et les mêmes acteurs. Six nombres et quatre sigles suffisent presque.</p>\n</blockquote>\n<hr/>\n<h2 id=\"3-1-le-blanchiment-définition-étapes-délit\">3.1 Le blanchiment : définition, étapes, délit</h2>\n<h3 id=\"définition-code-pénal-art-324-1\">Définition (Code pénal art. 324-1)</h3>\n<p>Blanchir, c'est :</p>\n<ul>\n<li><strong>faciliter la justification mensongère de l'origine</strong> des biens ou revenus de l'auteur d'un <strong>crime ou d'un délit</strong> (n'importe lequel, pas seulement un crime) ;</li>\n<li>ou <strong>apporter son concours à une opération de placement, de dissimulation ou de conversion</strong> du produit direct ou indirect d'un crime ou d'un délit.</li>\n</ul>\n<p>C'est la <strong>conversion ou le transfert de biens</strong> d'origine illicite <strong>pour en déguiser l'origine</strong>. Ce <strong>n'est pas</strong> :</p>\n<ul>\n<li>l'optimisation fiscale ;</li>\n<li>le rapatriement de fonds ;</li>\n<li>« donner une apparence illicite à des fonds licites ».</li>\n<li>Le <strong>financement du terrorisme</strong> est une infraction <strong>distincte</strong>, même si les mêmes outils le combattent.</li>\n</ul>\n<h3 id=\"les-3-étapes\">Les 3 étapes</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Termes de la base (grille AMF)</th>\n<th>Termes anglo-saxons</th>\n<th>Image</th>\n<th>Exemple</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>1. Placement</strong></td>\n<td><em>Placement</em></td>\n<td>prélavage</td>\n<td>Introduire les espèces dans le circuit bancaire (dépôts fractionnés)</td>\n</tr>\n<tr>\n<td><strong>2. Dissimulation</strong></td>\n<td><em>Layering</em> = <strong>empilement</strong></td>\n<td>lavage</td>\n<td>Multiplier les opérations pour brouiller la piste (virements en cascade, sociétés écrans)</td>\n</tr>\n<tr>\n<td><strong>3. Conversion</strong></td>\n<td><em>Integration</em> = <strong>intégration</strong></td>\n<td>essorage</td>\n<td>Réinjecter les fonds dans l'économie légale (immobilier, entreprises)</td>\n</tr>\n</tbody>\n</table></div>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« P-D-C : Place, Dissimule, Convertit »</strong> ou, en version anglaise, <strong>« P-E-I : Placement, Empilement, Intégration »</strong>. La <strong>phase initiale</strong> est toujours le <strong>placement</strong>.</p>\n</aside>\n<aside class=\"callout c-warn\"><span class=\"callout-label\">Piège</span>\n<p>« Prélavage, lavage, essorage » est l'image, pas la réponse attendue. Face à « placement, dissimulation et <strong>restitution</strong> », choisis « placement, dissimulation, <strong>conversion</strong> ».</p>\n</aside>\n<h3 id=\"les-peines-code-pénal\">Les peines (Code pénal)</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Délit</th>\n<th>Peine maximale</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Blanchiment simple</strong></td>\n<td><strong>5 ans</strong> d'emprisonnement et <strong>375 000 €</strong> d'amende</td>\n</tr>\n<tr>\n<td><strong>Blanchiment aggravé</strong> (habituel, <strong>en bande organisée</strong>, ou <strong>en utilisant les facilités de sa profession</strong>)</td>\n<td><strong>10 ans</strong> et <strong>750 000 €</strong></td>\n</tr>\n</tbody>\n</table></div>\n<p>Le blanchiment est un <strong>délit</strong>, ni une contravention, ni une simple infraction administrative.</p>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« 5 – 375 / 10 – 750 »</strong> : l'aggravé double tout. Un <strong>collaborateur de banque</strong> qui utilise ses fonctions est dans le cas <strong>aggravé</strong>.</p>\n</aside>\n<aside class=\"callout c-warn\"><span class=\"callout-label\">Piège</span>\n<p>Le montant blanchi ou le caractère international <strong>ne rendent pas</strong> le délit aggravé ; seuls l'habitude, la bande organisée et l'usage de la profession le font.</p>\n</aside>\n<hr/>\n<h2 id=\"3-2-les-acteurs-institutionnels\">3.2 Les acteurs institutionnels</h2>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Acteur</th>\n<th>Ce qu'il est</th>\n<th>Ce qu'il fait</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>GAFI</strong> (Groupe d'action financière, créé en 1989 par le G7)</td>\n<td><strong>Organisme intergouvernemental</strong> regroupant un <strong>nombre limité de pays</strong>. Il ne dépend ni de l'ONU, ni de l'OCDE, ni du FMI.</td>\n<td><strong>Conçoit les normes</strong> (ses 40 recommandations) et <strong>impulse la stratégie</strong> mondiale de lutte contre le blanchiment et le financement du terrorisme ; fait de la <strong>coopération internationale</strong> un objectif central. Pour les crypto-actifs liés au terrorisme, il recommande le <strong>gel sans délai</strong> des avoirs.</td>\n</tr>\n<tr>\n<td><strong>TRACFIN</strong> (Traitement du renseignement et action contre les circuits financiers clandestins)</td>\n<td><strong>Cellule de renseignement financier française</strong> : un <strong>service à compétence nationale rattaché au ministère de l'Économie et des Finances</strong></td>\n<td><strong>Reçoit et analyse les déclarations de soupçon</strong> (blanchiment ET terrorisme : <strong>destinataire exclusif</strong>), <strong>enquête</strong>, y compris sur des fraudes comme les <strong>faux ordres de virement</strong>, puis <strong>saisit le procureur de la République</strong>. Il <strong>ne sanctionne pas</strong> et ne contrôle pas les dispositifs.</td>\n</tr>\n<tr>\n<td><strong>ACPR</strong></td>\n<td>Superviseur des banques et des assureurs</td>\n<td><strong>Contrôle et sanctionne</strong> leur dispositif anti-blanchiment, y compris le manquement à déclarer à TRACFIN</td>\n</tr>\n<tr>\n<td><strong>AMF</strong></td>\n<td>Superviseur des SGP, CIF, PSCA/PSAN…</td>\n<td><strong>Contrôle</strong> le dispositif anti-blanchiment des <strong>sociétés de gestion</strong> (et des CIF)</td>\n</tr>\n<tr>\n<td><strong>EBA</strong></td>\n<td>Autorité bancaire européenne</td>\n<td>Orientations anti-blanchiment au niveau européen (ce rôle passe progressivement à l'AMLA)</td>\n</tr>\n</tbody>\n</table></div>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« GAFI fait les normes, TRACFIN reçoit les soupçons, ACPR et AMF contrôlent et sanctionnent. »</strong></p>\n</aside>\n<aside class=\"callout c-warn\"><span class=\"callout-label\">Piège</span>\n<p>Les déclarations de soupçon vont <strong>toujours à TRACFIN</strong>, jamais à l'AMF, au GAFI, à la DGFiP ni directement au procureur.</p>\n</aside>\n<aside class=\"callout c-warn\"><span class=\"callout-label\">Piège</span>\n<p>Pour les <strong>abus de marché</strong>, la déclaration va à l'<strong>AMF</strong> (thème 4). Ne confonds pas les deux.</p>\n</aside>\n<p>Le cadre juridique français de la lutte anti-blanchiment (LCB-FT) est aux <strong>articles L.561-1 et suivants du Code monétaire et financier</strong>.</p>\n<hr/>\n<h2 id=\"3-3-lobligation-de-vigilance-connaître-son-client\">3.3 L'obligation de vigilance : connaître son client</h2>\n<h3 id=\"lapproche-par-les-risques\">L'approche par les risques</h3>\n<p>Le professionnel <strong>évalue le risque de chaque client et de chaque opération</strong> et adapte son niveau de vigilance (<strong>proportionnalité</strong>). Elle n'est ni standardisée pour tous, ni facultative, ni un « examen renforcé de toute opération au-delà de 150 000 € ». Les <strong>sociétés de gestion</strong> doivent elles aussi mener cette approche et ne peuvent pas s'en remettre au dispositif de leur dépositaire.</p>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Niveau</th>\n<th>Quand ?</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Simplifiée</strong></td>\n<td><strong>Uniquement</strong> pour les produits, services ou clients <strong>à faible risque</strong>, et <strong>jamais en cas de soupçon</strong></td>\n</tr>\n<tr>\n<td><strong>Standard</strong></td>\n<td>Cas général. Même pour une petite opération provenant d'une banque, le professionnel <strong>reste soumis à la vigilance standard</strong> et à la déclaration de soupçon éventuelle.</td>\n</tr>\n<tr>\n<td><strong>Complémentaire / renforcée</strong></td>\n<td><strong>PPE</strong> (personne politiquement exposée) ; client <strong>non présent physiquement</strong> (au moins une mesure complémentaire) ; pays à risque ; opération complexe ou inhabituelle</td>\n</tr>\n</tbody>\n</table></div>\n<h3 id=\"lidentification-kyc\">L'identification (KYC)</h3>\n<ul>\n<li><strong>Quand ?</strong> <strong>Avant l'entrée en relation</strong>, puis <strong>tout au long de la relation</strong>, et pas seulement à l'ouverture. Les renseignements peuvent être vérifiés <strong>au plus tard avant la première opération</strong>.</li>\n<li><strong>Comment ?</strong> Sur la base d'un <strong>document officiel probant</strong>, vérifié par le professionnel ; les seules déclarations orales ne suffisent pas, et il n'y a pas de casier judiciaire à demander.\n<ul>\n<li><strong>À distance</strong> : copie d'un <strong>document officiel en cours de validité</strong> et <strong>signature électronique certifiée</strong> par un prestataire qualifié. La 5e directive a <strong>allégé</strong> l'exigence d'un justificatif supplémentaire quand l'identification numérique atteint le niveau « substantiel ».</li>\n</ul>\n</li>\n<li><strong>Qui ?</strong> Le <strong>client</strong>, les <strong>personnes agissant pour son compte</strong> et le <strong>bénéficiaire effectif</strong>.\n<ul>\n<li>Pour une <strong>personne morale</strong> : identifier les <strong>personnes physiques qui la contrôlent</strong>.</li>\n</ul>\n</li>\n<li><strong>Bénéficiaire effectif</strong> : la ou les <strong>personnes physiques</strong> qui <strong>contrôlent en dernier lieu</strong> le client (en pratique plus de <strong>25 %</strong> du capital ou des droits de vote, ou contrôle par d'autres moyens), ou pour qui l'opération est réalisée.\n<ul>\n<li>Ce n'est <strong>jamais une personne morale</strong>, ni forcément le représentant légal.</li>\n<li>La <strong>5e directive</strong> a imposé un système d'identification du bénéficiaire effectif en dernier ressort.</li>\n</ul>\n</li>\n<li><strong>KYC</strong> (<em>Know Your Customer</em>) : la <strong>connaissance approfondie</strong> du client.</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« Pas d'identité, pas de relation »</strong> : si le professionnel ne peut pas identifier le client ou connaître l'objet de la relation, il <strong>n'exécute aucune opération</strong> et <strong>n'entame pas</strong> la relation. Si elle existe déjà, <strong>il y met fin</strong>. Il ne peut pas « exécuter puis réclamer les justificatifs ».</p>\n</aside>\n<h3 id=\"les-ppe-personnes-politiquement-exposées\">Les PPE (personnes politiquement exposées)</h3>\n<ul>\n<li><strong>Qui ?</strong> Les personnes qui exercent ou ont exercé (depuis <strong>moins d'un an</strong>) une <strong>fonction publique importante</strong> : chef d'État, ministre, parlementaire, <strong>membre d'une cour suprême ou de la Cour des comptes</strong>, dirigeant de banque centrale, ambassadeur… ainsi que leur <strong>famille</strong> et leurs <strong>proches associés</strong>.</li>\n<li><strong>Ne sont pas PPE</strong> en tant que tels : un élu local, un juge d'instruction, un patron du CAC 40.</li>\n<li><strong>Mesures</strong> : <strong>vigilance complémentaire / renforcée</strong>. Ce n'est ni un allègement, ni un signalement automatique à l'AMF. La qualité de PPE peut <strong>s'étendre au bénéficiaire effectif</strong>.</li>\n<li><strong>But</strong> : la <strong>lutte contre le blanchiment</strong> et la corruption, pas une protection politique.</li>\n</ul>\n<h3 id=\"la-conservation-des-documents\">La conservation des documents</h3>\n<p><strong>5 ans à compter de la clôture du compte ou de la fin de la relation</strong> (pas 1, 3 ou 10 ans).</p>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« 5 ans »</strong> partout en sécurité financière : conservation des documents, et aussi des listes d'initiés (thème 4).</p>\n</aside>\n<h3 id=\"les-seuils-à-connaître\">Les seuils à connaître</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Seuil</th>\n<th>Règle</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>10 000 € par mois calendaire</strong></td>\n<td>Les <strong>dépôts ou retraits d'espèces</strong> cumulés sur un compte au-delà de ce seuil font l'objet d'une <strong>communication systématique d'informations (COSI) à TRACFIN</strong></td>\n</tr>\n<tr>\n<td><strong>Peine &gt; 1 an</strong></td>\n<td>Champ de la <strong>déclaration de soupçon</strong> : sommes pouvant provenir d'une infraction punie d'une peine de prison <strong>supérieure à un an</strong>, ou liées au <strong>terrorisme</strong>. <strong>La fraude fiscale</strong> est concernée.</td>\n</tr>\n</tbody>\n</table></div>\n<hr/>\n<h2 id=\"3-4-la-déclaration-de-soupçon-à-tracfin\">3.4 La déclaration de soupçon à TRACFIN</h2>\n<ul>\n<li>C'est une <strong>obligation</strong> : le PSI qui soupçonne <strong>DOIT</strong> déclarer, ce n'est pas une simple faculté.</li>\n<li><strong>Quand ?</strong> <strong>Avant l'exécution</strong> de l'opération. Si l'opération a déjà été exécutée, on <strong>informe TRACFIN sans délai</strong>.</li>\n<li><strong>Confidentialité absolue</strong> : <strong>divulguer</strong> la déclaration au client concerné est <strong>sanctionné pénalement</strong>, y compris pour une PPE. Les entités d'un <strong>même groupe peuvent s'informer</strong> entre elles. La déclaration n'est ni validée par l'AMF, ni partagée avec les parties à l'opération.</li>\n<li><strong>Protection du déclarant</strong> : celui qui déclare <strong>de bonne foi</strong> ne peut être poursuivi pour <strong>violation du secret professionnel</strong>.</li>\n<li><strong>Organisation</strong> : le responsable du dispositif anti-blanchiment est un dirigeant ou un salarié, <strong>jamais un expert externe</strong>. Une SGP qui <strong>sous-traite</strong> des tâches de vigilance <strong>reste responsable</strong> de ses obligations.</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« Soupçon = DOIT déclarer, AVANT, en SECRET, à TRACFIN ; et de bonne foi = protégé. »</strong></p>\n</aside>\n<h3 id=\"les-activités-à-risque\">Les activités à risque</h3>\n<ul>\n<li>La base retient le <strong>financement participatif</strong> comme activité au risque le plus élevé, devant le crédit et l'assurance-vie.</li>\n<li>Le <em><strong>de-risking</strong></em> consiste à <strong>exclure les clients à risque</strong> plutôt qu'à gérer leur risque.</li>\n<li>Les <strong>PSAN enregistrés à l'AMF</strong> appliquent <strong>l'intégralité</strong> des obligations anti-blanchiment et de gel des avoirs. La <strong>5e directive</strong> a soumis à la LCB-FT les <strong>services liés aux crypto-actifs</strong>.</li>\n</ul>\n<hr/>\n<h2 id=\"3-5-la-corruption-loi-sapin-2-et-afa\">3.5 La corruption : loi Sapin 2 et AFA</h2>\n<ul>\n<li>La <strong>loi Sapin 2</strong> (9 décembre 2016) impose un <strong>programme anti-corruption</strong> aux sociétés qui emploient <strong>au moins 500 salariés</strong> ET réalisent un <strong>chiffre d'affaires supérieur à 100 millions d'euros</strong>.</li>\n<li>Ce programme comprend une <strong>cartographie des risques</strong> : identifier l'<strong>exposition de la société aux sollicitations externes aux fins de corruption</strong>. Ce n'est ni une cartographie des risques pays, ni une analyse du risque de non-paiement.</li>\n<li>L'<strong>AFA</strong> (Agence française anticorruption) est placée <strong>auprès des ministres de la Justice et du Budget</strong>, et non de l'AMF ou de l'ACPR. Elle contrôle ces programmes.</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« Sapin 500 / 100 »</strong> : 500 salariés, 100 M€ de chiffre d'affaires.</p>\n</aside>\n<hr/>\n<h2 id=\"3-6-échange-dinformations-fiscales-fatca-embargos-et-gel-des\">3.6 Échange d'informations fiscales, FATCA, embargos et gel des avoirs</h2>\n<ul>\n<li><strong>FATCA</strong> (<em>Foreign Account Tax Compliance Act</em>) : <strong>loi américaine</strong> contre l'<strong>évasion fiscale des contribuables américains</strong> via leurs comptes à l'étranger. À l'entrée en relation, le client remplit une <strong>auto-certification fiscale</strong>.</li>\n<li><strong>EAI</strong> (échange automatique d'informations, norme <strong>OCDE</strong>, « CRS ») : les États signataires échangent <strong>systématiquement</strong> les informations sur les <strong>comptes financiers</strong> ouverts chez eux, et pas toutes les données personnelles.</li>\n<li><strong>Gel des avoirs et embargos</strong> :\n<ul>\n<li>les mesures nationales de gel s'imposent à <strong>toute personne physique ou morale</strong> ; face à un client visé, l'établissement <strong>suspend immédiatement toutes les opérations au débit et au crédit</strong> de son compte, sans attendre d'autorisation ;</li>\n<li>les PSAN appliquent l'intégralité du dispositif ;</li>\n<li>d'après la base, les <strong>courtiers d'assurance</strong> ne sont pas visés par les mesures de gel.</li>\n</ul>\n</li>\n</ul>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p><strong>DAC8</strong> : depuis le <strong>1er janvier 2026</strong>, l'échange automatique d'informations s'étend aux <strong>crypto-actifs</strong>.</p>\n</aside>\n<hr/>\n<div class=\"ids\" data-sub=\"3\"></div>\n<hr/>\n<h2 id=\"les-grandes-évolutions-depuis-la-base-2021-2026\"><span class=\"tag t-new\">nouveau</span> Les grandes évolutions depuis la base (2021-2026)</h2>\n<ul>\n<li><strong>Paquet européen anti-blanchiment (2024)</strong> :\n<ul>\n<li>un <strong>règlement unique</strong> (AMLR), d'application directe à partir de <strong>juillet 2027</strong> ;</li>\n<li>une <strong>6e directive</strong> ;</li>\n<li>une nouvelle autorité européenne, l'<strong>AMLA</strong>, installée à <strong>Francfort</strong>. Elle supervisera directement certaines entités financières à haut risque à partir de <strong>2028</strong>.</li>\n<li><strong>Confirmé au BTS Banque 2026</strong> : le sujet l'appelle <strong>ALBC</strong> (Autorité de lutte contre le blanchiment de capitaux et le financement du terrorisme). Elle <strong>harmonise les procédures de contrôle interne et de vigilance</strong> au sein de l'UE ; elle ne s'occupe ni des normes prudentielles de Bâle ni des politiques budgétaires (question EF26-23).</li>\n<li>L'AMLR prévoit un <strong>plafond européen de paiement en espèces de 10 000 €</strong> (la France applique déjà <strong>1 000 €</strong> pour un résident).</li>\n</ul>\n</li>\n<li><strong>Crypto-actifs</strong> : MiCA remplace progressivement le régime PSAN par celui des <strong>PSCA</strong>. La <strong>« travel rule »</strong> (identification de l'émetteur et du bénéficiaire de chaque transfert de crypto-actifs) s'applique depuis le <strong>30 décembre 2024</strong>.</li>\n<li><strong>Registre des bénéficiaires effectifs</strong> : depuis un arrêt de la Cour de justice de l'UE (novembre 2022), il n'est plus librement ouvert au public. L'accès est réservé aux personnes justifiant d'un <strong>intérêt légitime</strong>.</li>\n<li><strong>Sanctions internationales</strong> : depuis 2022, les mesures de gel visant la Russie ont fortement renforcé la vigilance sur les embargos.</li>\n</ul>\n<hr/>\n<h2 class=\"flash\" id=\"fiche-flash-du-thème-3\"> Fiche flash du thème 3</h2>\n<ol>\n<li>Blanchiment = <strong>placement → dissimulation (empilement) → conversion (intégration)</strong>, à partir d'un <strong>crime ou d'un délit</strong>.</li>\n<li>Peines : <strong>5 ans / 375 000 €</strong> ; aggravé (habitude, <strong>bande organisée</strong>, <strong>profession</strong>) <strong>10 ans / 750 000 €</strong>. C'est un <strong>délit</strong>.</li>\n<li><strong>GAFI</strong> = normes, intergouvernemental · <strong>TRACFIN</strong> = reçoit et analyse les soupçons (service de Bercy), saisit le procureur · <strong>ACPR / AMF</strong> contrôlent et sanctionnent.</li>\n<li><strong>Approche par les risques</strong> ; vigilance simplifiée <strong>seulement si faible risque et jamais en cas de soupçon</strong> ; renforcée pour les <strong>PPE</strong> et les clients <strong>à distance</strong>.</li>\n<li>Identifier <strong>avant</strong> la relation et <strong>tout au long</strong> ; client + mandataires + <strong>bénéficiaire effectif</strong> (personne <strong>physique</strong>, plus de 25 %).</li>\n<li>Impossible d'identifier → <strong>aucune opération, aucune relation</strong>, rupture si elle existe.</li>\n<li>Conservation : <strong>5 ans après la fin de la relation</strong>.</li>\n<li>Espèces : <strong>10 000 € par mois</strong> → information systématique à TRACFIN ; soupçon si peine <strong>&gt; 1 an</strong>.</li>\n<li>Déclaration de soupçon : <strong>obligatoire, avant l'opération, confidentielle</strong> (sa divulgation est un délit) ; déclarant de bonne foi <strong>protégé</strong>.</li>\n<li><strong>Sapin 2</strong> : plus de <strong>500 salariés ET 100 M€</strong> → cartographie des risques ; <strong>AFA</strong> auprès de la Justice et du Budget.</li>\n<li><strong>FATCA</strong> = loi US, <strong>auto-certification</strong> ; <strong>EAI</strong> = norme <strong>OCDE</strong> sur les <strong>comptes financiers</strong>.</li>\n</ol>\n","toc":[{"id":"3-1-le-blanchiment-définition-étapes-délit","t":"3.1 Le blanchiment : définition, étapes, délit"},{"id":"3-2-les-acteurs-institutionnels","t":"3.2 Les acteurs institutionnels"},{"id":"3-3-lobligation-de-vigilance-connaître-son-client","t":"3.3 L'obligation de vigilance : connaître son client"},{"id":"3-4-la-déclaration-de-soupçon-à-tracfin","t":"3.4 La déclaration de soupçon à TRACFIN"},{"id":"3-5-la-corruption-loi-sapin-2-et-afa","t":"3.5 La corruption : loi Sapin 2 et AFA"},{"id":"3-6-échange-dinformations-fiscales-fatca-embargos-et-gel-des","t":"3.6 Échange d'informations fiscales, FATCA, embargos et gel des avoirs"},{"id":"les-grandes-évolutions-depuis-la-base-2021-2026","t":"🆕 Les grandes évolutions depuis la base (2021-2026)"},{"id":"fiche-flash-du-thème-3","t":"Fiche flash du thème 3"}]},{"id":"04","n":4,"title":"La réglementation « Abus de marché »","html":"\n<blockquote class=\"note\">\n<p><strong>Poids à l'examen : 2 questions sur 120, catégorie A.</strong>\nBase : environ 40 questions, très répétitives. Tout tient dans le règlement européen <strong>MAR</strong> (<em>Market Abuse Regulation</em>, n° 596/2014, applicable depuis 2016).</p>\n</blockquote>\n<hr/>\n<h2 id=\"4-1-le-cadre-le-règlement-mar\">4.1 Le cadre : le règlement MAR</h2>\n<ul>\n<li><strong>Objectif</strong> : assurer l'<strong>intégrité des marchés</strong> et la confiance des investisseurs, ni la liquidité, ni la volatilité.</li>\n<li><strong>Périmètre</strong> : les pays de l'<strong>Espace économique européen (EEE)</strong>, pas l'OCDE ni le G20. Il couvre les instruments négociés sur un marché réglementé, un MTF ou un OTF, ainsi que les instruments qui leur sont liés.</li>\n<li><strong>Les abus de marché</strong> sont les <strong>opérations d'initié</strong>, la <strong>divulgation illicite d'informations privilégiées</strong> et les <strong>manipulations de marché</strong> (dont la <strong>diffusion de fausses informations</strong>).</li>\n<li>Le blanchiment ou les « opérations douteuses » <strong>ne sont pas</strong> des abus de marché.</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« I-D-M » = Initié, Divulgation, Manipulation.</strong></p>\n</aside>\n<hr/>\n<h2 id=\"4-2-linformation-privilégiée-et-les-initiés\">4.2 L'information privilégiée et les initiés</h2>\n<h3 id=\"la-définition-en-4-critères\">La définition en 4 critères</h3>\n<p>Une information privilégiée est une information :</p>\n<ol>\n<li><strong>Précise</strong> ;</li>\n<li><strong>Non rendue publique</strong> ;</li>\n<li>Qui concerne, directement ou indirectement, un <strong>émetteur ou un instrument financier</strong> ;</li>\n<li>Qui, si elle était rendue publique, serait <strong>susceptible d'influencer sensiblement le cours</strong>.</li>\n</ol>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« P-N-E-S » = Précise, Non publique, sur un Émetteur, Sensible pour le cours.</strong></p>\n</aside>\n<aside class=\"callout c-warn\"><span class=\"callout-label\">Piège</span>\n<p>Une information <strong>publique</strong> n'est jamais privilégiée. Une information n'est pas privilégiée du seul fait que des dirigeants la détiennent.</p>\n</aside>\n<h3 id=\"qui-est-initié\">Qui est initié ?</h3>\n<p><strong>Toute personne</strong> qui détient une information privilégiée <strong>dans l'exercice de sa profession ou de ses fonctions</strong>, <strong>salariée ou non</strong> : ni uniquement les dirigeants, ni seulement le commissaire aux comptes. C'est aussi le cas de quiconque la détient en sachant, ou en devant savoir, qu'elle est privilégiée.</p>\n<h3 id=\"lobligation-dabstention\">L'obligation d'abstention</h3>\n<p>Le détenteur d'une information privilégiée <strong>s'abstient de toute opération, à l'achat comme à la vente</strong>, sur les instruments de l'émetteur, <strong>tant que l'information n'est pas publique</strong>. Prévenir sa direction ne suffit pas, et la vente n'est pas plus permise que l'achat.</p>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Comportement</th>\n<th>Qualification</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Acheter ou vendre grâce à une information confidentielle connue par sa profession</td>\n<td><strong>Délit / manquement d'initié</strong></td>\n</tr>\n<tr>\n<td>Agir sur une <strong>recommandation</strong> dont on <strong>sait ou devrait savoir</strong> qu'elle repose sur une information privilégiée</td>\n<td><strong>Opération d'initié</strong></td>\n</tr>\n<tr>\n<td><strong>Répandre</strong> une information privilégiée (même sur un réseau social professionnel)</td>\n<td><strong>Divulgation illicite</strong> d'information privilégiée</td>\n</tr>\n<tr>\n<td><strong>Tentative</strong> d'opération d'initié, même échouée</td>\n<td><strong>Sanctionnable</strong>, et doit être <strong>déclarée</strong></td>\n</tr>\n</tbody>\n</table></div>\n<p><strong>Exception</strong> : le <strong>sondage de marché</strong> (<em>market sounding</em>). Communiquer des informations à des investisseurs potentiels avant l'annonce d'une transaction <strong>n'est pas un abus</strong> s'il respecte des <strong>règles contraignantes</strong> (consignation, consentement à devenir initié…).</p>\n<h3 id=\"les-listes-dinitiés\">Les listes d'initiés</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Point</th>\n<th>Règle</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Contenu</td>\n<td><strong>Toutes les personnes</strong> ayant accès à des informations privilégiées : c'est une liste de <strong>personnes</strong>, pas d'émetteurs (ça, c'est la liste de surveillance, thème 2), et <strong>pas tous les collaborateurs</strong></td>\n</tr>\n<tr>\n<td>Objectif</td>\n<td><strong>Maîtriser les flux d'informations privilégiées</strong> et <strong>faciliter les enquêtes</strong> du régulateur</td>\n</tr>\n<tr>\n<td>Information</td>\n<td>La <strong>personne inscrite</strong> est <strong>informée</strong> de son inscription et de ses obligations</td>\n</tr>\n<tr>\n<td>Mise à jour</td>\n<td><strong>Sans délai</strong>, à chaque changement</td>\n</tr>\n<tr>\n<td>Conservation</td>\n<td><strong>Au moins 5 ans</strong> après son établissement ou sa mise à jour</td>\n</tr>\n</tbody>\n</table></div>\n<ul>\n<li>L'émetteur publie ses informations privilégiées et les conserve <strong>sur son site internet pendant au moins 5 ans</strong>.</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« 5 ans »</strong>, comme en lutte anti-blanchiment : liste d'initiés, informations sur le site de l'émetteur, documents clients.</p>\n</aside>\n<hr/>\n<h2 id=\"4-3-les-manipulations-de-marché\">4.3 Les manipulations de marché</h2>\n<ul>\n<li>Ce sont les <strong>ordres ou transactions qui donnent des indications fausses ou trompeuses</strong> sur l'offre, la demande ou le cours, ou qui fixent le cours à un niveau anormal ou artificiel.</li>\n<li>La <strong>diffusion de fausses informations</strong> ou de rumeurs, par tout moyen, est une manipulation.</li>\n<li>Un <strong>contrat de liquidité</strong> conclu avec un prestataire est une <strong>pratique de marché admise</strong>, pas une manipulation.</li>\n</ul>\n<h3 id=\"les-pratiques-interdites-à-connaître-par-leur-nom\">Les pratiques interdites à connaître par leur nom</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Pratique</th>\n<th>Définition</th>\n<th>Moyen de retenir</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Front running</strong></td>\n<td>Un intermédiaire <strong>exploite abusivement les ordres de ses clients en attente</strong> pour passer <strong>avant eux</strong> ses propres ordres</td>\n<td><span class=\"tag t-mnemo\">mnémo</span> <strong>front</strong> = passer <strong>devant</strong> le client</td>\n</tr>\n<tr>\n<td><strong>Late trading</strong></td>\n<td>Un ordre de souscription ou de rachat d'OPC <strong>transmis et accepté après l'heure limite</strong> de centralisation (<em>cut-off</em>) mais exécuté sur une valeur liquidative déjà connue</td>\n<td><span class=\"tag t-mnemo\">mnémo</span> <strong>late</strong> = <strong>en retard</strong> sur l'heure limite</td>\n</tr>\n<tr>\n<td><strong>Market timing</strong></td>\n<td><strong>Arbitrage</strong> qui exploite l'<strong>écart entre la valeur liquidative (comptable) d'un fonds et la valeur de marché</strong> de ses actifs. Il nuit à l'<strong>égalité de traitement des porteurs</strong>.</td>\n<td><span class=\"tag t-mnemo\">mnémo</span> <strong>timing</strong> = jouer sur le <strong>décalage</strong> de la VL</td>\n</tr>\n</tbody>\n</table></div>\n<ul>\n<li><strong>Late trading et market timing sont interdits</strong> et jugés <strong>répréhensibles</strong> par l'AMF, quel que soit le fonds.</li>\n<li><strong>Prévention du late trading</strong> : la SGP <strong>fixe l'heure limite de réception des ordres</strong> chez le <strong>centralisateur</strong>, qui <strong>contrôle le respect de cette heure limite</strong> (ni l'AMF, ni l'ACPR).</li>\n<li>Une analyse de marché pour acheter « au bon moment » n'est <strong>pas</strong> du market timing.</li>\n</ul>\n<hr/>\n<h2 id=\"4-4-la-détection-la-déclaration-et-les-sanctions\">4.4 La détection, la déclaration et les sanctions</h2>\n<h3 id=\"la-déclaration-dopération-suspecte-stor\">La déclaration d'opération suspecte (STOR)</h3>\n<ul>\n<li>Elle se fait <strong>auprès de l'AMF</strong>, pas à la Banque de France, à TRACFIN ni au GAFI.</li>\n<li>Elle est <strong>obligatoire et sans retard</strong>, <strong>dès qu'il existe des raisons de soupçonner</strong> un délit d'initié ou une manipulation, <strong>tentatives comprises</strong>. Il n'y a pas de délai de 45 jours ou de 3 mois, et pas d'attente d'une procédure judiciaire.</li>\n<li>Aucun seuil de patrimoine ni critère de nationalité n'intervient, et on <strong>n'avertit pas</strong> le client.</li>\n<li>Exemple de signal suspect : <strong>plusieurs transactions inhabituelles</strong> pour le client sur un titre <strong>juste avant une annonce</strong>.</li>\n<li>Un salarié qui <strong>alerte l'AMF de bonne foi</strong> n'encourt <strong>aucune sanction</strong> (statut de lanceur d'alerte).</li>\n</ul>\n<h3 id=\"les-sanctions\">Les sanctions</h3>\n<ul>\n<li><strong>Administratives</strong> (Commission des sanctions de l'AMF) : jusqu'à <strong>100 millions d'euros ou 10 fois le profit réalisé</strong>.</li>\n<li><strong>Pénales</strong> (délit d'initié, manipulation, divulgation) : jusqu'à <strong>5 ans d'emprisonnement et 100 millions d'euros d'amende</strong> (ou 10 fois le profit).</li>\n<li>Les deux voies ne se cumulent pas pour les mêmes faits : l'AMF et le Parquet national financier se concertent pour choisir la voie.</li>\n</ul>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p><strong>Listing Act (2024)</strong> :</p>\n<ul>\n<li>les <strong>dirigeants</strong> déclarent leurs transactions au-delà de <strong>20 000 € par an</strong>, au lieu de 5 000 € ;</li>\n<li>depuis <strong>juin 2026</strong>, les <strong>étapes intermédiaires</strong> d'un processus long (une fusion en négociation, par exemple) n'ont plus à être publiées : seul l'événement final l'est.</li>\n</ul>\n<p>La définition de l'information privilégiée et les obligations d'abstention restent inchangées.</p>\n</aside>\n<div class=\"ids\" data-sub=\"4\"></div>\n<hr/>\n<h2 class=\"flash\" id=\"fiche-flash-du-thème-4\"> Fiche flash du thème 4</h2>\n<ol>\n<li>MAR → <strong>intégrité des marchés</strong>, champ <strong>EEE</strong>. Trois abus : <strong>initié, divulgation illicite, manipulation</strong> (dont fausses informations).</li>\n<li>Information privilégiée = <strong>précise, non publique, sur un émetteur, susceptible d'influencer sensiblement le cours</strong>.</li>\n<li>Initié = <strong>toute personne</strong> qui la détient par ses fonctions → <strong>abstention totale (achat ET vente)</strong> jusqu'à sa publication.</li>\n<li><strong>Tentative</strong> = sanctionnable et à déclarer ; agir sur une <strong>recommandation</strong> fondée sur une information privilégiée = initié.</li>\n<li><strong>Liste d'initiés</strong> = des <strong>personnes</strong>, la personne inscrite est <strong>informée</strong>, mise à jour sans délai, <strong>conservée 5 ans</strong>.</li>\n<li><strong>Sondage de marché</strong> encadré = <strong>pas</strong> un abus.</li>\n<li><strong>Front running</strong> (passer devant l'ordre du client) · <strong>late trading</strong> (ordre après l'heure limite → contrôlé par le <strong>centralisateur</strong>) · <strong>market timing</strong> (arbitrage sur l'écart de VL) → <strong>interdits</strong>.</li>\n<li>Soupçon d'abus → <strong>déclaration à l'AMF, obligatoire, sans retard</strong>.</li>\n<li>Sanctions AMF : <strong>100 M€ ou 10 fois le profit</strong> ; pénal : <strong>5 ans</strong>.</li>\n</ol>\n","toc":[{"id":"4-1-le-cadre-le-règlement-mar","t":"4.1 Le cadre : le règlement MAR"},{"id":"4-2-linformation-privilégiée-et-les-initiés","t":"4.2 L'information privilégiée et les initiés"},{"id":"4-3-les-manipulations-de-marché","t":"4.3 Les manipulations de marché"},{"id":"4-4-la-détection-la-déclaration-et-les-sanctions","t":"4.4 La détection, la déclaration et les sanctions"},{"id":"fiche-flash-du-thème-4","t":"Fiche flash du thème 4"}]},{"id":"05","n":5,"title":"Commercialisation d'instruments financiers, démarchage, vente à distance et conseil","html":"\n<blockquote class=\"note\">\n<p><strong>Poids à l'examen : 6 questions sur 120.</strong></p>\n<ul>\n<li><strong>§5.1 : 4 questions en catégorie A</strong> (démarchage, vente à distance, conseil, publicité, gouvernance produits) ;</li>\n<li><strong>§5.2 : 2 questions en catégorie C</strong> (prospectus, DICI/DIC, frais).</li>\n</ul>\n<p>Le §5.1 est un gros réservoir de points A : les délais (<strong>14 jours, 48 heures, 30 jours</strong>) et la définition du démarchage tombent à coup sûr.</p>\n</blockquote>\n<hr/>\n<h2 id=\"5-1-le-démarchage-bancaire-et-financier-cmf-l-341-1-et-suiva\">5.1 Le démarchage bancaire et financier (CMF L.341-1 et suivants)</h2>\n<h3 id=\"quest-ce-que-le-démarchage\">Qu'est-ce que le démarchage ?</h3>\n<p><strong>Deux situations</strong> constituent un acte de démarchage :</p>\n<ol>\n<li><strong>Toute prise de contact non sollicitée</strong>, <strong>par quelque moyen que ce soit</strong> (téléphone, courrier, e-mail, <strong>mailing personnalisé avec coupon-réponse</strong>), avec une personne <strong>physique ou morale</strong>, pour obtenir son accord sur une opération bancaire ou financière ;</li>\n<li><strong>Le fait de se rendre physiquement</strong> au <strong>domicile</strong> des personnes, sur leur <strong>lieu de travail</strong> ou dans des lieux non destinés à la commercialisation, <strong>quelle que soit la personne à l'initiative</strong> de la démarche, même à la demande du client.</li>\n</ol>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th><span class=\"tag t-ok\">juste</span> C'est du démarchage</th>\n<th><span class=\"tag t-err\">erreur</span> Ce n'est pas du démarchage</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Appel téléphonique non sollicité (prospect, représentant légal d'une petite entreprise)</td>\n<td>Sollicitation <strong>dans les locaux du PSI</strong> (au guichet, dans la file d'attente, en agence), même non demandée</td>\n</tr>\n<tr>\n<td>Courrier ou e-mail non sollicité proposant une opération</td>\n<td><strong>Campagne publicitaire générale</strong> (presse, mailing centralisé de présentation d'une gamme)</td>\n</tr>\n<tr>\n<td>Mailing ciblé avec coupon-réponse pour souscrire</td>\n<td>Lettre proposant un <strong>rendez-vous</strong> pour faire le point avec son conseiller</td>\n</tr>\n<tr>\n<td>Visite au domicile du client, <strong>même à sa demande</strong> (pour un mandat de gestion, par exemple)</td>\n<td>Rencontre <strong>dans les bureaux d'une personne morale, à sa demande</strong></td>\n</tr>\n<tr>\n<td>Contact avec une personne morale dont le chiffre d'affaires est <strong>inférieur à 5 M€</strong></td>\n<td>Envoi d'une documentation <strong>demandée</strong> par le client</td>\n</tr>\n<tr>\n<td></td>\n<td>Proposition à un client d'une <strong>opération habituelle</strong> pour lui (nature, risque, montant)</td>\n</tr>\n<tr>\n<td></td>\n<td>Contact avec des <strong>investisseurs qualifiés</strong> ou de grandes personnes morales</td>\n</tr>\n</tbody>\n</table></div>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« Démarcher = SORTIR de l'agence ou ENTRER chez le client sans y être invité. »</strong> Une visite au domicile reste du démarchage même si le client l'a demandée.</p>\n</aside>\n<aside class=\"callout c-warn\"><span class=\"callout-label\">Piège</span>\n<p><strong>L'opération habituelle d'un client connu</strong> échappe aux règles du démarchage, contrairement à une opération <strong>inhabituelle</strong> pour lui.</p>\n</aside>\n<h3 id=\"qui-peut-démarcher\">Qui peut démarcher ?</h3>\n<ul>\n<li><strong>Uniquement les établissements limitativement énumérés par la loi</strong> : <strong>établissements de crédit, entreprises d'investissement, entreprises d'assurance</strong>, SGP, CIF… ainsi que les <strong>personnes physiques qu'ils mandatent</strong>.</li>\n<li><strong>Le démarcheur personne physique</strong> :\n<ul>\n<li>est <strong>majeur</strong> ;</li>\n<li>a le <strong>baccalauréat ou 2 ans d'expérience</strong> ;</li>\n<li>remplit des conditions d'honorabilité ;</li>\n<li>est couvert par une <strong>assurance de responsabilité civile professionnelle</strong>.</li>\n<li>Il <strong>n'a pas besoin d'un agrément de l'AMF</strong>.</li>\n</ul>\n</li>\n<li><strong>Le mandat</strong> est <strong>nominatif</strong>. Il précise la <strong>nature des produits et services</strong> et les <strong>conditions</strong> dans lesquelles le démarchage peut s'exercer. Le démarcheur ne propose <strong>que les produits pour lesquels il a mandat</strong>, et non tous types de produits.</li>\n<li><strong>La carte de démarchage</strong> :\n<ul>\n<li>elle est <strong>délivrée par l'établissement pour le compte duquel il agit</strong>, ni par l'AMF, ni par la Banque de France, ni par le ministère ;</li>\n<li>elle comporte notamment le <strong>nom du démarcheur</strong> ;</li>\n<li>elle est <strong>valable 3 ans</strong> pour un salarié ;</li>\n<li>le démarcheur en est <strong>en possession</strong> et la <strong>présente</strong> à la personne démarchée, systématiquement et sur sa demande.</li>\n</ul>\n</li>\n<li><strong>Sanctions</strong> : selon la nature du démarcheur, l'<strong>AMF ou l'ACPR</strong>. Exercer sans carte est puni de <strong>6 mois d'emprisonnement et 7 500 €</strong> d'amende pour une personne physique.</li>\n</ul>\n<h3 id=\"quels-produits\">Quels produits ?</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Interdits au démarchage</th>\n<th>Autorisés</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Produits dont le <strong>risque maximum n'est pas connu</strong> au moment de la souscription, ou dont la perte peut dépasser l'apport initial</td>\n<td><strong>Parts et actions d'OPCVM</strong> (y compris une SICAV étrangère autorisée en France)</td>\n</tr>\n<tr>\n<td>Ventes d'<strong>options d'achat</strong></td>\n<td>Instruments <strong>admis sur un marché réglementé</strong> ou un marché étranger reconnu</td>\n</tr>\n<tr>\n<td><strong>Actions non cotées</strong>, parts d'<strong>organismes de titrisation</strong></td>\n<td>Obligations convertibles, actions de pays émergents (si elles sont cotées)</td>\n</tr>\n<tr>\n<td><strong>Bons de caisse</strong></td>\n<td></td>\n</tr>\n</tbody>\n</table></div>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« Risque inconnu = démarchage interdit »</strong>, même avec une mise en garde écrite.</p>\n</aside>\n<aside class=\"callout c-warn\"><span class=\"callout-label\">Piège</span>\n<p><strong>Produits d'assurance et de protection sociale</strong> : ils relèvent de leur <strong>propre régime</strong> (Code des assurances), hors du démarchage bancaire et financier (<a class=\"qref\" href=\"#\" data-q=\"634\">Q634</a>). La <a class=\"qref\" href=\"#\" data-q=\"600\">Q600</a> dit pourtant que les règles s'appliquent « à tous les produits d'épargne (… assurance-vie …) » : apprends les deux formulations telles quelles.</p>\n</aside>\n<h3 id=\"les-obligations-du-démarcheur\">Les obligations du démarcheur</h3>\n<ul>\n<li><strong>Avant toute offre</strong>, il s'informe sur la <strong>situation financière</strong>, l'<strong>expérience</strong> et les <strong>objectifs</strong> de placement du démarché. S'informer « uniquement de sa situation financière » ne suffit pas.</li>\n<li>Il <strong>informe de manière claire et compréhensible</strong>, sur <strong>papier ou autre support durable</strong>, ce dernier <strong>avec l'accord du client</strong>.</li>\n<li>Les règles du démarchage <strong>s'ajoutent</strong> à toutes les autres (la réglementation du produit, la vente à distance) : elles ne dispensent de rien.</li>\n</ul>\n<h3 id=\"les-délais-le-tableau-à-connaître-par-cœur\">Les délais : le tableau à connaître par cœur</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Situation</th>\n<th>Délai</th>\n<th>Détail</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Rétractation</strong> après démarchage (service d'investissement : <strong>gestion de portefeuille, conseil</strong>, compte de dépôt…)</td>\n<td><strong>14 jours calendaires révolus</strong></td>\n<td><strong>Sans motif ni pénalité</strong>. Le client paie seulement le prix du service <strong>effectivement fourni</strong> (<em>prorata temporis</em>).</td>\n</tr>\n<tr>\n<td>Restitution des sommes et biens reçus après rétractation</td>\n<td><strong>30 jours maximum</strong></td>\n<td></td>\n</tr>\n<tr>\n<td><strong>Transaction sur instruments financiers, RTO ou exécution d'ordres</strong> après démarchage</td>\n<td><strong>Délai de réflexion de 48 heures</strong>, <strong>pas de rétractation</strong></td>\n<td>Le client ne peut pas se rétracter d'un achat de titres, dont le prix varie</td>\n</tr>\n<tr>\n<td><strong>Vente à distance</strong> de services financiers</td>\n<td><strong>14 jours</strong> (30 jours pour l'assurance-vie)</td>\n<td>La <strong>charge de la preuve</strong> de l'information appartient au <strong>vendeur</strong></td>\n</tr>\n</tbody>\n</table></div>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« 14 pour se rétracter, 48 heures pour réfléchir à un ordre, 30 pour rendre l'argent. »</strong></p>\n</aside>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« On ne se rétracte pas d'un ordre de bourse »</strong> : RTO et exécution n'ont <strong>pas</strong> de délai de rétractation, seulement 48 heures de réflexion.</p>\n</aside>\n<h3 id=\"le-démarchage-téléphonique-bloctel\">Le démarchage téléphonique (Bloctel)</h3>\n<p>Démarcher par téléphone un consommateur inscrit sur la <strong>liste d'opposition</strong> est <strong>interdit</strong>, <strong>sauf</strong> dans le cadre de l'<strong>exécution d'un contrat en cours</strong> et en rapport avec son objet. Les <strong>jours, horaires et fréquence</strong> des appels sont <strong>fixés par décret</strong> et non librement : depuis 2023, du <strong>lundi au vendredi, 10 h-13 h et 14 h-20 h</strong>, et <strong>4 appels au plus par période de 30 jours</strong>.</p>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p><strong>À vérifier</strong> : une loi de 2025 a prévu de passer au <strong>consentement préalable (opt-in)</strong> pour le démarchage téléphonique des consommateurs, à partir d'<strong>août 2026</strong>. La base repose sur le système Bloctel (opposition, <em>opt-out</em>).</p>\n</aside>\n<hr/>\n<h2 id=\"5-1-suite-conseil-communications-promotionnelles-et-gouverna\">5.1 (suite) Conseil, communications promotionnelles et gouvernance des produits</h2>\n<h3 id=\"le-conseil\">Le conseil</h3>\n<ul>\n<li>Une <strong>recommandation personnalisée</strong> porte sur l'achat, la vente, la souscription, l'échange, le remboursement, la <strong>détention</strong> ou la prise ferme d'un <strong>instrument financier particulier</strong>, ou sur l'exercice d'un droit qu'il confère.\n<ul>\n<li>Un article de journaliste diffusé au public n'est pas une recommandation personnalisée.</li>\n</ul>\n</li>\n<li>Le conseiller propose des produits <strong>adaptés au profil de chaque client</strong>. Il n'impose ni des produits « sans risque » à tous, ni les mêmes produits à tous.</li>\n<li>Le conseil <strong>peut être fourni par un système automatisé</strong> (robo-conseiller), par téléphone, sans rencontre physique.</li>\n</ul>\n<h3 id=\"les-communications-et-la-publicité\">Les communications et la publicité</h3>\n<ul>\n<li>Toute information adressée aux clients, y compris potentiels, est <strong>exacte, claire et non trompeuse</strong> : les <strong>trois</strong> adjectifs, pas seulement « claire et non trompeuse ». Les communications <strong>promotionnelles</strong> sont <strong>autorisées</strong>, y compris pour les SGP, mais <strong>clairement identifiables</strong> comme telles.</li>\n<li><strong>Performances</strong> : si elles sont présentées, elles précisent <strong>l'impact des frais</strong>. Elles ne doivent pas être le <strong>thème central</strong> du document, et les performances passées ne sont pas « un élément clé à fournir ».</li>\n<li>Il n'existe pas de maquette imposée pour la publicité.</li>\n<li>Les <strong>communications précontractuelles</strong> permettent au client d'apprécier la <strong>nature des services ou instruments</strong> et les <strong>risques</strong>, <strong>avant</strong> la signature.</li>\n</ul>\n<h3 id=\"la-gouvernance-des-produits-mif-2\">La gouvernance des produits (MIF 2)</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Acteur</th>\n<th>Obligations</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Producteur</strong> (concepteur)</td>\n<td><strong>Définit le marché cible</strong>, y compris un <strong>marché cible négatif</strong> (les clients à qui il ne faut <strong>pas</strong> proposer le produit), et une <strong>stratégie de distribution compatible</strong> (il <strong>définit les canaux de distribution</strong>). Le marché cible décrit les <strong>besoins, profils et objectifs</strong> des clients, pas seulement leur catégorie : il est obligatoire même pour un produit destiné à tous. Il peut inclure l'<strong>âge</strong> parmi d'autres critères.</td>\n</tr>\n<tr>\n<td><strong>Distributeur</strong></td>\n<td><strong>Obtient du producteur</strong> les informations utiles, puis <strong>affine le marché cible</strong> selon la réalité <strong>de sa clientèle</strong>. Il ne propose le produit <strong>qu'aux clients concernés</strong>, ni à tous, ni en attendant qu'ils se manifestent.</td>\n</tr>\n<tr>\n<td>Producteur <strong>et</strong> distributeur à la fois</td>\n<td><strong>Une seule évaluation</strong> du marché cible</td>\n</tr>\n</tbody>\n</table></div>\n<ul>\n<li>Un distributeur soumis à MIF 2 peut vendre le produit d'un producteur <strong>qui n'y est pas soumis</strong> (une société étrangère, par exemple).</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« Le producteur dessine la cible et choisit les canaux, le distributeur l'ajuste à ses clients. »</strong></p>\n</aside>\n<h3 id=\"les-pouvoirs-dintervention-sur-les-produits\">Les pouvoirs d'intervention sur les produits</h3>\n<ul>\n<li>L'<strong>ESMA</strong> peut <strong>interdire ou restreindre temporairement</strong>, dans toute l'UE, la commercialisation auprès des <strong>clients de détail</strong> de produits spéculatifs (<strong>CFD, options binaires, forex</strong>), y compris émis hors UE.</li>\n<li>Les <strong>autorités nationales</strong> (l'AMF en France) disposent des mêmes pouvoirs, à titre permanent (thème 6.9).</li>\n</ul>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p><strong>MIF 2 « quick fix » (2021)</strong> : l'information est désormais fournie <strong>par voie électronique par défaut</strong>.</p>\n</aside>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p>Depuis <strong>2022</strong>, le marché cible intègre aussi les <strong>préférences de durabilité</strong> (ESG) des clients.</p>\n</aside>\n<div class=\"ids\" data-sub=\"5.1\"></div>\n<hr/>\n<h2 id=\"5-2-prospectus-et-documents-dinformation-dici-dic-priips-fra\">5.2 Prospectus et documents d'information (DICI, DIC PRIIPs), frais</h2>\n<h3 id=\"le-prospectus-dun-opc\">Le prospectus d'un OPC</h3>\n<ul>\n<li>C'est un document <strong>informationnel</strong>, ni promotionnel, ni contractuel.</li>\n<li>Il précise les <strong>catégories d'actifs</strong> autorisées et indique si les opérations sur <strong>contrats financiers</strong> (dérivés) sont faites <strong>à titre de couverture ou d'exposition</strong> (spéculation).</li>\n<li>Il est <strong>remis sur simple demande</strong> au client non professionnel.</li>\n</ul>\n<h3 id=\"le-dici-document-dinformation-clé-pour-linvestisseur-des-opc\">Le DICI (document d'information clé pour l'investisseur) des OPCVM</h3>\n<ul>\n<li><strong>Nature</strong> : un document <strong>précontractuel</strong>, <strong>obligatoirement remis avant la souscription</strong> (ni après, ni sur demande). Il a remplacé le <strong>prospectus simplifié</strong>.</li>\n<li><strong>Champ</strong> : <strong>les OPCVM</strong>, pour tous les fonds <strong>commercialisés dans l'UE</strong>. Il est <strong>visé par l'AMF</strong> (agrément).</li>\n<li><strong>Contenu</strong> (2 pages, langage non technique, <strong>cohérent avec le prospectus</strong>) :\n<ul>\n<li>un <strong>indicateur synthétique de risque et de rendement</strong>, <strong>obligatoire</strong>, sur une <strong>échelle de 1 à 7</strong> (1 = risque et rendement potentiel les plus faibles) ;</li>\n<li>les <strong>frais</strong> : frais <strong>d'entrée et de sortie</strong> (en <strong>%</strong>) et <strong>frais courants</strong> ;</li>\n<li>les <strong>performances passées, nettes de frais</strong> ;</li>\n<li>une déclaration sur la <strong>politique de rémunération</strong>.</li>\n</ul>\n</li>\n<li><strong>Langue</strong> : le <strong>français en principe</strong>, avec des exceptions.</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« DICI = 2 pages, 1 à 7, AVANT. »</strong></p>\n</aside>\n<h3 id=\"le-dic-priips-document-dinformations-clés-ou-kid\">Le DIC PRIIPs (document d'informations clés, ou KID)</h3>\n<ul>\n<li><strong>Le règlement PRIIPs</strong> (2018) vise à <strong>faciliter la compréhension et la comparaison</strong> des produits d'investissement « packagés » pour les <strong>clients non professionnels</strong>, grâce à un <strong>document standardisé</strong>. Il n'interdit aucun produit.</li>\n<li><strong>Produits concernés</strong> : les <strong>assurances-vie en unités de compte</strong>, les <strong>FIA</strong>, les <strong>EMTN structurés</strong>, les <strong>obligations à formule</strong>… mais <strong>pas</strong> une action ou une obligation classique, un PEL ou une assurance habitation.</li>\n<li><strong>Le DIC n'est pas un document publicitaire.</strong> Il contient un <strong>indicateur de risque de 1 à 7</strong> et <strong>4 scénarios de performance</strong> : <strong>tensions, défavorable, intermédiaire, favorable</strong>.</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« PRIIPs = Packagés ; 4 scénarios : Tension, Défavorable, Intermédiaire, Favorable (T-D-I-F) ».</strong></p>\n</aside>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p><strong>Depuis le 1er janvier 2023, le DICI des OPCVM est remplacé par le DIC PRIIPs</strong> pour les clients non professionnels. Les questions « DICI » de la base gardent les mêmes réponses (remise avant souscription, échelle de 1 à 7, frais en %), mais le document s'appelle désormais <strong>DIC</strong>.\n<strong>Confirmé au BTS Banque 2026</strong> : la question sur l'affichage du risque est posée avec le <strong>DIC</strong>, et la réponse reste l'<strong>échelle de 1 à 7</strong> (question 692, mise à jour dans la base).</p>\n</aside>\n<h3 id=\"les-frais-ce-quil-faut-savoir-répondre\">Les frais : ce qu'il faut savoir répondre</h3>\n<ul>\n<li>Les frais sont communiqués <strong>avant</strong> l'opération, <strong>en euros ET en pourcentage</strong>.</li>\n<li>Pour un service de gestion, ils sont communiqués <strong>régulièrement, au moins une fois par an</strong>.</li>\n<li><strong>Frais prélevés sur la valeur liquidative</strong> : les frais de gestion (dont <strong>gestion financière</strong>), les frais courants, les frais de transaction.</li>\n<li><strong>Frais payés directement par l'investisseur</strong>, hors valeur liquidative : les <strong>frais de souscription et de rachat</strong>.</li>\n<li>La SGP doit fournir aux clients non professionnels l'information sur les <strong>frais et commissions</strong>.</li>\n</ul>\n<div class=\"ids\" data-sub=\"5.2\"></div>\n<hr/>\n<h2 class=\"flash\" id=\"fiche-flash-du-thème-5\"> Fiche flash du thème 5</h2>\n<ol>\n<li>Démarchage = <strong>contact non sollicité par tout moyen</strong> OU <strong>visite au domicile ou au travail quelle que soit l'initiative</strong>.</li>\n<li><strong>Pas de démarchage</strong> : en agence, publicité générale, <strong>opération habituelle</strong> d'un client, investisseurs qualifiés, personne morale <strong>&gt; 5 M€</strong> ou reçue à sa demande.</li>\n<li>Démarcheurs : établissements <strong>limitativement énumérés</strong> (EC, EI, assureurs…) + personnes mandatées : <strong>majeures, bac ou 2 ans d'expérience, RC pro, carte délivrée par le mandant (3 ans)</strong>.</li>\n<li><strong>Interdit</strong> si le <strong>risque maximum n'est pas connu</strong> ; non coté et titrisation interdits ; <strong>OPCVM autorisés</strong>.</li>\n<li><strong>14 jours</strong> de rétractation (sans motif ni pénalité, prorata du service fourni), <strong>30 jours</strong> pour restituer, <strong>48 heures</strong> de réflexion pour les <strong>ordres et la RTO</strong> (pas de rétractation).</li>\n<li>Information <strong>exacte, claire, non trompeuse</strong> ; publicité <strong>identifiable</strong> ; performances <strong>avec l'impact des frais</strong>.</li>\n<li>MIF 2 : le <strong>producteur</strong> définit le <strong>marché cible</strong> (et le <strong>cible négatif</strong>) et les <strong>canaux</strong> ; le <strong>distributeur</strong> l'affine ; producteur et distributeur à la fois = <strong>une seule évaluation</strong>.</li>\n<li><strong>ESMA</strong> : interdiction temporaire européenne (CFD, options binaires).</li>\n<li><strong>DICI</strong> : remis <strong>avant</strong>, visé par l'AMF, échelle <strong>1 à 7</strong>, frais en %, performances nettes → remplacé par le <strong>DIC PRIIPs</strong> depuis 2023.</li>\n<li><strong>PRIIPs</strong> : UC, FIA, EMTN, obligations à formule ; <strong>4 scénarios</strong> ; <strong>pas</strong> un document publicitaire.</li>\n<li>Frais : <strong>en € et en %</strong>, <strong>au moins une fois par an</strong> ; souscription et rachat <strong>hors VL</strong>, frais de gestion <strong>dans la VL</strong>.</li>\n</ol>\n","toc":[{"id":"5-1-le-démarchage-bancaire-et-financier-cmf-l-341-1-et-suiva","t":"5.1 Le démarchage bancaire et financier (CMF L.341-1 et suivants)"},{"id":"5-1-suite-conseil-communications-promotionnelles-et-gouverna","t":"5.1 (suite) Conseil, communications promotionnelles et gouvernance des produits"},{"id":"5-2-prospectus-et-documents-dinformation-dici-dic-priips-fra","t":"5.2 Prospectus et documents d'information (DICI, DIC PRIIPs), frais"},{"id":"fiche-flash-du-thème-5","t":"Fiche flash du thème 5"}]},{"id":"06","n":6,"title":"Relations avec les clients","html":"\n<blockquote class=\"note\">\n<p><strong>Poids à l'examen : 25 questions sur 120. C'est le thème le plus lourd avec le thème 8.</strong></p>\n<ul>\n<li><strong>16 questions en catégorie A</strong> (les plus importantes pour le seuil A) : §6.1.1 (5), §6.2 (5), §6.3 (3), §6.4 (3).</li>\n<li><strong>9 questions en catégorie C</strong> : §6.1.2 (2), §6.5 (2), §6.6 (1), §6.7 (1), §6.8 (2), §6.9 (1).</li>\n</ul>\n<p>Ce thème porte <strong>à lui seul près de la moitié de la catégorie A</strong>. Il mérite une attention maximale.</p>\n</blockquote>\n<hr/>\n<h2 id=\"6-1-1-connaître-évaluer-et-catégoriser-le-client-mif-2\">6.1.1 Connaître, évaluer et catégoriser le client (MIF 2)</h2>\n<h3 id=\"les-3-catégories-et-aucune-autre\">Les 3 catégories, et aucune autre</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Catégorie</th>\n<th>Qui ?</th>\n<th>Protection</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Client non professionnel</strong> (de détail)</td>\n<td><strong>Tous ceux qui ne sont ni professionnels ni contreparties éligibles</strong> : les <strong>personnes physiques par nature</strong>, les petites entreprises, les professions libérales…</td>\n<td><strong>La plus élevée</strong></td>\n</tr>\n<tr>\n<td><strong>Client professionnel</strong></td>\n<td>Celui qui possède <strong>l'expérience, les connaissances et la compétence</strong> pour <strong>prendre ses propres décisions</strong> et <strong>évaluer correctement les risques</strong></td>\n<td>Intermédiaire</td>\n</tr>\n<tr>\n<td><strong>Contrepartie éligible</strong></td>\n<td>Les <strong>investisseurs institutionnels</strong> : établissements de crédit, entreprises d'investissement, assureurs, OPC et SGP, États, banques centrales…</td>\n<td><strong>La plus faible</strong></td>\n</tr>\n</tbody>\n</table></div>\n<aside class=\"callout c-warn\"><span class=\"callout-label\">Piège</span>\n<p>Il n'y a <strong>que 3 catégories</strong>. Les « prospects », les « contreparties non éligibles » ou les « contreparties personnes morales » <strong>n'en sont pas</strong>.</p>\n</aside>\n<aside class=\"callout c-warn\"><span class=\"callout-label\">Piège</span>\n<p>Être commerçant, profession libérale, notaire, avocat ou salarié de banque <strong>ne rend pas</strong> professionnel.</p>\n</aside>\n<p><strong>Professionnels par nature</strong> (CMF D.533-11) :</p>\n<ul>\n<li><strong>EC, EI</strong>, autres établissements financiers agréés, <strong>assureurs</strong>, <strong>OPC et SGP</strong>, fonds de retraite, <strong>unions de mutuelles</strong>, <strong>sociétés de capital-risque</strong>, États, banques centrales, institutions internationales ;</li>\n<li><strong>les grandes entreprises</strong> qui remplissent <strong>2 des 3 critères</strong> suivants :\n<ul>\n<li><strong>total de bilan ≥ 20 M€</strong> ;</li>\n<li><strong>chiffre d'affaires net ≥ 40 M€</strong> ;</li>\n<li><strong>capitaux propres ≥ 2 M€</strong>.</li>\n</ul>\n</li>\n</ul>\n<p>Pour une entreprise <strong>contrepartie éligible</strong>, la base retient : bilan <strong>≥ 20 M€</strong> et chiffre d'affaires <strong>≥ 40 M€</strong>.</p>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« 20 – 40 – 2 »</strong> : bilan 20, chiffre d'affaires 40, capitaux propres 2 (en millions d'euros), <strong>2 critères sur 3</strong>.</p>\n</aside>\n<h3 id=\"le-classement-et-ses-changements\">Le classement et ses changements</h3>\n<ul>\n<li>Le <strong>PSI classe lui-même</strong> ses clients, à l'<strong>entrée en relation</strong>, selon des <strong>politiques et procédures écrites</strong>. Ce n'est pas le client qui choisit, ni l'AMF.</li>\n<li>Il <strong>informe obligatoirement chaque client de sa catégorie</strong>, dans tous les cas, parce qu'elle détermine <strong>son niveau de protection</strong>. L'AMF n'est pas informée.</li>\n<li><strong>Objectif</strong> de la catégorisation : <strong>déterminer le niveau de protection</strong>, et non la fiscalité ou l'affectation à un conseiller.</li>\n<li><strong>Changements de catégorie</strong> : <strong>tout client</strong> (non pro, pro, contrepartie éligible) peut <strong>demander</strong> à changer. Le changement peut venir du client ou du PSI.\n<ul>\n<li><strong>Pro → non pro</strong> (davantage de protection) : sur <strong>demande du client ET acceptation du PSI</strong>, qui n'y est pas obligé. C'est possible <strong>pour une transaction ou un service déterminé</strong>.</li>\n<li><strong>Contrepartie éligible → catégorie plus protectrice</strong> : sur sa demande.</li>\n<li><strong>Non pro → pro</strong> (moins de protection) : sur <strong>demande du client</strong>, puis <strong>évaluation par le PSI</strong> de sa compétence, de son expérience et de ses connaissances, selon une procédure du CMF. Il faut en pratique <strong>2 critères sur 3</strong> :\n<ul>\n<li><strong>portefeuille &gt; 500 000 €</strong> ;</li>\n<li><strong>au moins 10 transactions significatives par trimestre</strong> sur les 4 trimestres précédents ;</li>\n<li><strong>au moins 1 an d'expérience professionnelle</strong> dans le secteur financier.</li>\n</ul>\n</li>\n<li>Une simple demande, même par lettre recommandée, ne suffit jamais pour devenir professionnel. Un <strong>non professionnel ne peut jamais devenir contrepartie éligible</strong>.</li>\n</ul>\n</li>\n<li>Si un pro ou une contrepartie éligible <strong>ne remplit plus les conditions</strong>, le PSI <strong>prend les mesures appropriées</strong> : il ne rompt pas la relation et ne prévient pas l'AMF.</li>\n<li>Un même client peut appartenir à <strong>plusieurs catégories selon les services</strong>.</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« Descendre est facile, monter se mérite »</strong> : vers plus de protection, une demande acceptée suffit ; vers moins de protection, il faut une demande <strong>et</strong> une évaluation.</p>\n</aside>\n<h3 id=\"la-connaissance-du-client\">La connaissance du client</h3>\n<ul>\n<li><strong>Pour un client non professionnel</strong>, on recueille ses <strong>connaissances et son expérience</strong>. Avant un conseil ou une gestion, on ajoute sa <strong>situation financière</strong> (dont sa <strong>capacité à subir des pertes</strong>) et ses <strong>objectifs</strong> (dont sa <strong>tolérance au risque</strong>). La tolérance au risque et la capacité à subir des pertes sont des <strong>ajouts de MIF 2</strong>.\n<ul>\n<li>On ne lui demande ni les coordonnées de son employeur, ni le FICP, ni un CV, ni son casier judiciaire.</li>\n</ul>\n</li>\n<li><strong>Fiabilité des informations</strong> :\n<ul>\n<li>le PSI <strong>peut se fonder sur les déclarations du client, sauf si elles sont manifestement erronées</strong> ;</li>\n<li>il met en place des dispositifs pour <strong>déceler les incohérences</strong> et <strong>attirer l'attention du client</strong> ;</li>\n<li>il <strong>ne se fie pas indûment à l'auto-évaluation</strong> ;</li>\n<li>il ne remplit <strong>jamais</strong> le questionnaire à la place du client, mais il peut lui proposer une <strong>liste d'objectifs</strong>.</li>\n</ul>\n</li>\n<li>Le questionnaire peut être <strong>automatisé</strong>, à condition de vérifier autant que possible les réponses par des éléments objectifs. Les diligences sont <strong>traçables et contrôlables par l'AMF</strong>.</li>\n<li>La <strong>charge de la preuve</strong> de cette évaluation <strong>pèse sur le PSI</strong>.</li>\n<li>Si la situation du client change, on <strong>actualise</strong> les informations.</li>\n<li><strong>Identification</strong> : pour une <strong>personne morale</strong>, un <strong>extrait de registre officiel de moins de 3 mois</strong> (Kbis). Si la personne physique est <strong>absente</strong>, on demande une <strong>pièce justificative supplémentaire</strong>.</li>\n</ul>\n<div class=\"ids\" data-sub=\"6.1.1\"></div>\n<hr/>\n<h2 id=\"6-1-2-confidentialité-secret-professionnel-données-personnel\">6.1.2 Confidentialité, secret professionnel, données personnelles, enregistrements</h2>\n<h3 id=\"le-secret-professionnel-bancaire\">Le secret professionnel (bancaire)</h3>\n<ul>\n<li>Sa violation est un <strong>délit pénal</strong> : <strong>1 an d'emprisonnement et 15 000 € d'amende</strong> (Code pénal 226-13).\n<ul>\n<li>Exemple : un banquier qui révèle à la presse des informations sur un client.</li>\n</ul>\n</li>\n<li><strong>Exception</strong> : la communication est permise <strong>avec l'accord du client</strong> ou dans des <strong>circonstances prévues par la loi</strong>. Le secret n'est donc pas absolu.</li>\n</ul>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Le secret N'EST PAS opposable à</th>\n<th>Le secret EST opposable à</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>ACPR</strong>, <strong>AMF</strong>, <strong>Banque de France</strong></td>\n<td>Un tiers en litige avec le client</td>\n</tr>\n<tr>\n<td><strong>Autorité judiciaire agissant dans une procédure pénale</strong></td>\n<td>L'employeur, la famille du client (même les parents d'un jeune majeur)</td>\n</tr>\n<tr>\n<td><strong>Administration fiscale et des douanes</strong></td>\n<td><strong>Une association professionnelle (AFTI…)</strong></td>\n</tr>\n<tr>\n<td><strong>Commission de surendettement</strong> (Banque de France)</td>\n<td>La presse</td>\n</tr>\n<tr>\n<td><strong>Commissions d'enquête parlementaires</strong></td>\n<td>Les commissaires aux comptes (selon la base)</td>\n</tr>\n<tr>\n<td><strong>Agences de notation</strong>, pour la notation des produits financiers</td>\n<td></td>\n</tr>\n</tbody>\n</table></div>\n<ul>\n<li>Le <strong>commissaire aux comptes d'une SGP</strong> ne peut <strong>jamais</strong> opposer le secret professionnel à l'AMF.</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« Les gendarmes (ACPR, AMF, BdF), les juges au pénal, le fisc et les douanes, le surendettement et le Parlement passent ; les curieux restent dehors. »</strong></p>\n</aside>\n<h3 id=\"le-rgpd-et-la-cnil\">Le RGPD et la CNIL</h3>\n<ul>\n<li>Le <strong>RGPD</strong> (règlement général sur la protection des données, 2016/679) protège les données des <strong>personnes physiques</strong>.</li>\n<li>La <strong>CNIL</strong> <strong>contrôle</strong> les traitements et peut <strong>sanctionner financièrement dès le premier manquement</strong>. Elle ne prononce pas de sanctions pénales.</li>\n<li><strong>Les droits du client</strong> :\n<ul>\n<li><strong>accès</strong> à ses données <strong>à tout moment</strong>, sur simple demande ;</li>\n<li>savoir si des données le concernant figurent dans un fichier ;</li>\n<li><strong>rectification</strong>.</li>\n<li>En revanche, <strong>pas d'accès aux données d'un tiers</strong>, même de sa famille. Pour une personne <strong>décédée</strong>, il faut être <strong>héritier</strong>.</li>\n</ul>\n</li>\n<li><strong>Les obligations du responsable de traitement</strong> :\n<ul>\n<li><strong>cartographier</strong> (tenir un registre) des traitements ;</li>\n<li>collecter des données <strong>adéquates, pertinentes et limitées</strong> à la finalité ;</li>\n<li>en cas de <strong>violation de données</strong>, <strong>notifier la CNIL au plus tard 72 heures</strong> après en avoir eu connaissance.</li>\n</ul>\n</li>\n<li>Le <strong>consentement</strong> est valable s'il est <strong>libre, spécifique, éclairé et univoque</strong>.</li>\n<li>Les <strong>données sensibles</strong> (origine, opinions, religion, syndicat…) sont <strong>interdites sauf exceptions</strong> limitativement prévues.</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p>Consentement <strong>« L-S-E-U »</strong> (Libre, Spécifique, Éclairé, Univoque) ; violation → <strong>72 heures</strong>.</p>\n</aside>\n<h3 id=\"la-conservation-et-lenregistrement\">La conservation et l'enregistrement</h3>\n<ul>\n<li><strong>Durée de conservation : 5 ans</strong>, partout :\n<ul>\n<li>les <strong>documents de connaissance du client</strong> pendant toute la relation <strong>+ 5 ans</strong> après sa fin ;</li>\n<li>les <strong>données sur les opérations et transactions</strong> pendant 5 ans ;</li>\n<li>les <strong>enregistrements</strong> de tout service et de toute transaction pendant 5 ans.</li>\n</ul>\n</li>\n<li><strong>L'enregistrement des conversations</strong> :\n<ul>\n<li>il couvre les conversations <strong>téléphoniques ET les communications électroniques</strong> relatives aux transactions <strong>conclues ou destinées à l'être</strong>, même si la transaction n'a finalement pas lieu ;</li>\n<li>il n'est pas nécessaire pour un simple point sur le compte ;</li>\n<li>le client en est <strong>informé à l'avance</strong> ;</li>\n<li><strong>but</strong> : faciliter le <strong>contrôle de la régularité et de la conformité</strong> des opérations ;</li>\n<li>l'écoute est réservée au <strong>responsable de la conformité</strong> ou à son délégué.</li>\n</ul>\n</li>\n<li>Une communication électronique adressée à un client non professionnel est un <strong>support durable</strong>.</li>\n</ul>\n<div class=\"ids\" data-sub=\"6.1.2\"></div>\n<hr/>\n<h2 id=\"6-2-linformation-à-donner-aux-clients\">6.2 L'information à donner aux clients</h2>\n<h3 id=\"les-règles-générales\">Les règles générales</h3>\n<ul>\n<li>L'information est <strong>claire, exacte et non trompeuse</strong> pour <strong>tous les clients et toutes les communications</strong>, publicité comprise. Les <strong>communications promotionnelles</strong> doivent être <strong>clairement identifiables</strong>.</li>\n<li>Elle doit être <strong>compréhensible par un investisseur moyen</strong> et présenter <strong>autant les avantages que les risques</strong>.</li>\n<li>Les <strong>avertissements sur les risques</strong> sont écrits dans une <strong>police au moins égale</strong> à celle du texte principal, jamais en note de bas de page.</li>\n<li>La <strong>description de la nature et des risques</strong> des instruments varie <strong>selon la catégorie du client</strong>.</li>\n<li>Les <strong>comparaisons</strong> avec d'autres instruments sont <strong>autorisées</strong> si elles sont pertinentes et équilibrées.</li>\n<li><strong>Fiscalité</strong> : on précise qu'elle <strong>dépend de la situation individuelle du client et peut évoluer</strong>.</li>\n</ul>\n<h3 id=\"les-performances\">Les performances</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Règle</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Passées</strong></td>\n<td><strong>Les 5 dernières années au minimum</strong> (ou depuis la création si le produit est plus récent ; davantage si la durée de placement recommandée dépasse 5 ans), par <strong>périodes complètes de 12 mois</strong>. On mentionne l'<strong>effet des frais</strong>. Elles ne sont <strong>jamais le thème central</strong> et ne prédisent pas l'avenir.</td>\n</tr>\n<tr>\n<td><strong>Simulées</strong> (passées)</td>\n<td>On précise qu'il s'agit de <strong>simulations</strong> et que <strong>les performances passées ne préjugent pas des performances futures</strong></td>\n</tr>\n<tr>\n<td><strong>Futures</strong></td>\n<td>Elles reposent sur des <strong>hypothèses raisonnables fondées sur des éléments objectifs</strong></td>\n</tr>\n</tbody>\n</table></div>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« 5 ans, 12 mois pleins, frais inclus, jamais au centre. »</strong></p>\n</aside>\n<h3 id=\"ce-que-le-client-non-professionnel-reçoit-avant-le-service\">Ce que le client non professionnel reçoit avant le service</h3>\n<ul>\n<li>Les informations sur le <strong>PSI</strong> : son <strong>agrément et le nom de l'autorité</strong> qui l'a délivré, la <strong>nature, la fréquence et les dates des comptes rendus</strong>, une <strong>brève description des mesures de protection</strong> de ses avoirs.</li>\n<li>Une <strong>description générale de la nature et des risques des instruments</strong>, adaptée à sa catégorie.</li>\n<li><strong>Les coûts et frais</strong>, <strong>détaillés</strong>, taxes comprises.\n<ul>\n<li>L'<strong>information sur la tarification</strong> est due à <strong>tous les clients</strong>, avant le service.</li>\n<li><strong>Si le prix n'est pas déterminé</strong>, on donne sa <strong>base de calcul</strong>.</li>\n<li>L'indication des <strong>coûts totaux</strong> est <strong>imposée</strong> par la réglementation.</li>\n</ul>\n</li>\n<li>La <strong>politique d'exécution</strong>, <strong>communiquée avant le service</strong> ; le client doit y <strong>consentir</strong>.</li>\n<li><strong>Pour le conseil</strong> :\n<ul>\n<li>on précise <strong>avant le service</strong> si le conseil est <strong>indépendant ou non</strong> ;</li>\n<li>on indique si l'<strong>adéquation sera réévaluée périodiquement</strong>.</li>\n</ul>\n</li>\n<li><strong>Conflits d'intérêts</strong> : le client est <strong>informé si les mesures ne suffisent pas</strong> à éviter le risque d'atteinte à ses intérêts. La politique dépend de la <strong>nature de l'activité</strong>. La <strong>SGP</strong> doit avoir une <strong>politique écrite</strong>, et celle d'un CIF est adaptée à sa taille.</li>\n</ul>\n<h3 id=\"les-instruments-complexes\">Les instruments complexes</h3>\n<p>Exemples : les <strong>fonds à formule</strong> et les <strong>FIA à formule</strong>. Une action, une obligation à taux fixe ou un OPCVM actions ne sont pas complexes.</p>\n<h3 id=\"les-rémunérations-reçues-de-tiers-inducements\">Les rémunérations reçues de tiers (« inducements »)</h3>\n<ul>\n<li><strong>Conseil indépendant</strong> :\n<ul>\n<li>le conseiller ne peut <strong>pas conserver</strong> de rétrocessions : il <strong>les reverse au client</strong> ;</li>\n<li>il est <strong>rémunéré uniquement par le client</strong> (honoraires) ;</li>\n<li>il dispose d'un <strong>éventail suffisamment large et diversifié</strong> d'instruments.</li>\n</ul>\n</li>\n<li><strong>Conseil non indépendant</strong> : il <strong>peut conserver</strong> les rétrocessions <strong>si le client en est informé</strong> et si elles <strong>améliorent la qualité du service</strong>.</li>\n<li>L'information sur les commissions reçues porte sur leur <strong>existence, leur nature et leur montant</strong>. Elle est <strong>complète, exacte et compréhensible</strong> ; une <strong>information générique est insuffisante</strong>. Une <strong>forme résumée</strong> est possible si le PSI s'engage à donner le détail sur demande.</li>\n<li>Une <strong>information individualisée sur le montant réel</strong> des avantages reçus est envoyée <strong>au moins une fois par an</strong>.</li>\n<li><strong>Les avantages non monétaires mineurs</strong> (une invitation à une <strong>conférence de formation</strong> sur un produit, par exemple, mais ni un spectacle ni une voiture) peuvent être conservés <strong>sous conditions</strong>. Ils sont <strong>divulgués au client avant</strong> le service.</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« Indépendant = Ne garde rien ; Non indépendant = Informe et améliore. »</strong></p>\n</aside>\n<h3 id=\"les-comptes-rendus-et-lavis-dopéré\">Les comptes rendus et l'avis d'opéré</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Règle</th>\n<th>Détail</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Quand ?</td>\n<td><strong>Sans délai</strong>, <strong>après chaque exécution</strong>. Pour un <strong>non professionnel</strong> : un <strong>avis au plus tard le premier jour ouvrable</strong> suivant l'exécution (idem pour la SGP qui exécute une souscription ou un rachat d'OPCVM)</td>\n</tr>\n<tr>\n<td>Contenu</td>\n<td><strong>Jour et heure</strong> d'exécution, <strong>lieu d'exécution</strong>, prix, <strong>montant total des commissions et frais</strong>. La plus-value ou le prix moyen d'acquisition n'y figurent pas.</td>\n</tr>\n<tr>\n<td>Ordre exécuté par tranches</td>\n<td><strong>Prix de chaque tranche OU prix moyen</strong></td>\n</tr>\n<tr>\n<td>Conservation</td>\n<td>L'avis d'opéré <strong>est enregistré</strong> : il prouve que le PSI a respecté son obligation d'information</td>\n</tr>\n<tr>\n<td>Coûts « ex post »</td>\n<td><strong>Récapitulatif annuel</strong> des coûts et frais (gestion, conseil)</td>\n</tr>\n<tr>\n<td>Porteurs d'OPCVM</td>\n<td>Ils reçoivent <strong>toute l'information nécessaire sur la gestion</strong> ; l'état d'exécution d'un ordre leur est donné <strong>sur demande</strong></td>\n</tr>\n</tbody>\n</table></div>\n<ul>\n<li><strong>Prix total</strong> = prix de l'instrument + <strong>coûts liés à l'exécution</strong>.</li>\n<li>Les frais d'un OPC figurent <strong>globalement en % dans le DICI/DIC</strong> et <strong>en détail dans le prospectus</strong>.</li>\n</ul>\n<div class=\"ids\" data-sub=\"6.2\"></div>\n<hr/>\n<h2 id=\"6-3-agir-au-mieux-des-intérêts-du-client-adéquation-et-carac\">6.3 Agir au mieux des intérêts du client : adéquation et caractère approprié</h2>\n<h3 id=\"le-principe\">Le principe</h3>\n<p>Agir au mieux des intérêts du client (MIF 1, renforcée par MIF 2) est une <strong>obligation de moyens</strong>, pas de résultat ni de performance.</p>\n<h3 id=\"les-deux-tests\">Les deux tests</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th></th>\n<th><strong>Test d'adéquation</strong> (<em>suitability</em>)</th>\n<th><strong>Test du caractère approprié</strong> (<em>appropriateness</em>)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Pour quels services ?</td>\n<td><strong>Conseil en investissement</strong> et <strong>gestion de portefeuille</strong></td>\n<td><strong>Les autres services</strong> : RTO, exécution d'ordres…</td>\n</tr>\n<tr>\n<td>Qu'évalue-t-on ?</td>\n<td><strong>Connaissances et expérience</strong> + <strong>situation financière</strong> (dont la <strong>capacité à subir des pertes</strong>) + <strong>objectifs</strong> (dont la <strong>tolérance au risque</strong> et l'horizon)</td>\n<td><strong>Connaissances et expérience</strong> seulement</td>\n</tr>\n<tr>\n<td>Si le client ne répond pas</td>\n<td>Le PSI <strong>s'abstient</strong> de fournir le service. Une décharge, une simple mise en garde ou une délégation ne suffisent pas.</td>\n<td>Le PSI <strong>met en garde</strong> le client, puis peut exécuter</td>\n</tr>\n<tr>\n<td>Exemption</td>\n<td>Aucune</td>\n<td>L'<strong>exécution simple</strong> : instruments <strong>non complexes</strong>, à l'<strong>initiative du client</strong>, après l'avoir informé de l'absence de test</td>\n</tr>\n</tbody>\n</table></div>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« ADÉQUATION = CONSEIL et GESTION (je décide pour toi ou je te recommande : je dois TOUT savoir). APPROPRIÉ = le reste (tu décides seul : je vérifie juste que tu comprends). »</strong></p>\n</aside>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>Le test d'adéquation compte 4 volets : Connaissances, Expérience, Situation financière, Objectifs.</strong></p>\n</aside>\n<p><strong>Points précis tirés de la base</strong></p>\n<ul>\n<li>Pour un <strong>client professionnel par nature</strong>, on vérifie seulement que le produit répond à ses <strong>objectifs</strong> (tolérance au risque comprise). Ses connaissances et sa capacité financière sont <strong>présumées</strong>.</li>\n<li>L'adéquation relève de la <strong>responsabilité du PSI</strong>, pas du client ni de l'AMF. Son but est de permettre au PSI d'<strong>agir au mieux des intérêts du client</strong>, ce qu'on explique au client de <strong>manière claire et simple</strong>.</li>\n<li>Un client expérimenté <strong>n'est pas réputé connaître</strong> le caractère adéquat d'un produit.</li>\n<li>L'<strong>étendue des informations</strong> à recueillir <strong>varie selon la complexité du produit</strong>. Le <strong>questionnaire</strong> doit être <strong>compréhensible</strong> et permettre d'<strong>évaluer l'adéquation</strong>.</li>\n<li>Les informations sont recueillies <strong>toujours avant</strong> une gestion de portefeuille, <strong>quelle que soit la catégorie</strong> du client.</li>\n<li><strong>Offre groupée</strong> : le test porte sur <strong>l'ensemble de l'offre</strong>.</li>\n<li><strong>Produit illiquide</strong> : on tient compte de la <strong>durée pendant laquelle le client accepte de conserver</strong> le placement.</li>\n<li>La recommandation est présentée comme <strong>adaptée au client</strong> et <strong>fondée sur l'examen de sa situation propre</strong>. On remet une <strong>déclaration d'adéquation</strong> au client non professionnel.</li>\n<li>Sans test d'adéquation possible, le PSI ne peut rendre <strong>aucun service d'investissement</strong> de conseil ou de gestion (la base cite le <strong>crédit immobilier</strong> comme seul service possible).</li>\n</ul>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p><strong>Depuis le 2 août 2022</strong>, le test d'adéquation inclut les <strong>préférences du client en matière de durabilité</strong> (ESG). Voir le thème 8.7.</p>\n</aside>\n<h3 id=\"lencadrement-des-rémunérations\">L'encadrement des rémunérations</h3>\n<ul>\n<li>Il couvre les <strong>rémunérations monétaires, les commissions et les avantages non monétaires</strong>.</li>\n<li>La <strong>lettre de mission du CIF</strong> précise la nature et les modalités de la prestation et les <strong>modalités de rémunération</strong>. Elle mentionne que le client a pris connaissance du <strong>document d'entrée en relation</strong>.</li>\n</ul>\n<h3 id=\"les-compétences-des-vendeurs\">Les compétences des vendeurs</h3>\n<ul>\n<li>Le PSI vérifie que les personnes qui informent ou conseillent les clients ont les <strong>connaissances minimales</strong> : c'est l'<strong>examen AMF</strong> ou une vérification interne.</li>\n<li><strong>Délai : 6 mois</strong> à compter de la <strong>prise de fonction</strong>. Pendant ce délai, le collaborateur travaille sous la <strong>supervision</strong> d'une personne qualifiée.</li>\n<li><strong>Exception</strong> : pour une personne <strong>en alternance</strong>, le PSI <strong>peut ne pas</strong> procéder à la vérification.</li>\n<li>Les connaissances et compétences font l'objet d'une <strong>évaluation annuelle</strong>.</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« 6 mois pour être certifié. »</strong></p>\n</aside>\n<div class=\"ids\" data-sub=\"6.3\"></div>\n<hr/>\n<h2 id=\"6-4-meilleure-exécution-best-execution-et-meilleure-sélectio\">6.4 Meilleure exécution (<em>best execution</em>) et meilleure sélection (<em>best selection</em>)</h2>\n<h3 id=\"laquelle-sapplique\">Laquelle s'applique ?</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Service fourni</th>\n<th>Obligation</th>\n<th>Moyen de retenir</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Exécution d'ordres</strong> pour compte de tiers</td>\n<td><strong>Meilleure exécution</strong> : le PSI choisit le <strong>lieu</strong> d'exécution</td>\n<td><span class=\"tag t-mnemo\">mnémo</span> j'<strong>exécute</strong> → je choisis le <strong>lieu</strong></td>\n</tr>\n<tr>\n<td><strong>RTO</strong>, <strong>gestion de portefeuille</strong>, <strong>gestion d'OPC</strong> (le PSI transmet ses ordres à un intermédiaire)</td>\n<td><strong>Meilleure sélection</strong> : le PSI <strong>sélectionne les intermédiaires</strong>, <strong>par classe d'instruments</strong>, et s'assure qu'<strong>ils respectent la meilleure exécution</strong></td>\n<td><span class=\"tag t-mnemo\">mnémo</span> je <strong>transmets</strong> → je choisis l'<strong>intermédiaire</strong></td>\n</tr>\n</tbody>\n</table></div>\n<h3 id=\"la-politique-dexécution\">La politique d'exécution</h3>\n<ul>\n<li><strong>Objectif</strong> : obtenir <strong>le meilleur résultat possible</strong> pour <strong>tous les clients</strong>, sur <strong>tous les instruments</strong> (pas seulement les actions ou les dérivés).</li>\n<li><strong>Critères</strong> : le <strong>prix</strong>, le <strong>coût</strong>, la <strong>rapidité</strong>, la <strong>probabilité d'exécution et de règlement</strong>, la taille, la nature de l'ordre.</li>\n<li><strong>Pour un non professionnel</strong>, le meilleur résultat se mesure au <strong>coût total</strong> : <strong>prix de l'instrument + tous les coûts liés à l'exécution</strong>, et non au prix seul ni à la rapidité.</li>\n<li><strong>Contenu</strong> :\n<ul>\n<li>les <strong>lieux d'exécution</strong>. <strong>Un seul lieu</strong> est admis s'il donne le meilleur résultat dans la plupart des cas. Un <strong>internalisateur systématique</strong> peut être un lieu d'exécution, pas une chambre de compensation ni un dépositaire central.</li>\n<li>Ce sont des informations <strong>générales et standardisées</strong>, pas individualisées.</li>\n<li>Pour un non professionnel : <strong>l'importance relative des facteurs</strong> et <strong>la liste des lieux auxquels le PSI fait le plus confiance</strong>.</li>\n</ul>\n</li>\n<li><strong>Consentement préalable du client</strong> à la politique (ni confidentielle, ni approuvée « après chaque opération »).</li>\n<li><strong>Exécution hors plateforme de négociation</strong> (hors marché réglementé, MTF ou OTF, chez un <strong>internalisateur systématique</strong> par exemple) : <strong>consentement préalable exprès</strong> du client, <strong>général ou transaction par transaction</strong>.</li>\n<li><strong>Révision au moins une fois par an</strong>, et à chaque modification substantielle.</li>\n<li>En cas de <strong>litige</strong>, le PSI doit <strong>démontrer</strong> qu'il a exécuté conformément à sa politique.</li>\n<li><strong>Exécution équitable et rapide</strong> : les <strong>ordres comparables</strong> sont exécutés selon leur <strong>ordre d'arrivée</strong>, sans favoriser le compte propre. L'<strong>affectation</strong> des exécutions entre les OPCVM gérés est <strong>définitive</strong>.</li>\n</ul>\n<h3 id=\"les-instructions-spécifiques-du-client\">Les instructions spécifiques du client</h3>\n<p>Si le client donne une <strong>instruction spécifique</strong> (lieu, moment…), le PSI <strong>doit la suivre</strong>. Il est alors <strong>dégagé de la meilleure exécution</strong> pour les éléments couverts par l'instruction. Un ordre « sans indication de cours » n'est pas une instruction spécifique.</p>\n<h3 id=\"la-meilleure-sélection\">La meilleure sélection</h3>\n<ul>\n<li>Une <strong>politique de sélection des intermédiaires par type d'instruments</strong>, <strong>réexaminée au moins une fois par an</strong>.</li>\n<li>Pour une SGP, cette politique figure dans le <strong>rapport de gestion</strong>.</li>\n</ul>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p>MIF 2 obligeait à publier chaque année les <strong>5 principaux lieux d'exécution</strong> par classe d'instruments (<a class=\"qref\" href=\"#\" data-q=\"1188\">Q1188</a>). La <strong>révision de MIF 2 (2024) a supprimé cette obligation</strong>. Si la question tombe, la réponse attendue reste celle de la base.</p>\n</aside>\n<div class=\"ids\" data-sub=\"6.4\"></div>\n<hr/>\n<h2 id=\"6-5-charges-et-commissions\">6.5 Charges et commissions</h2>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Frais</th>\n<th>Définition</th>\n<th>Qui les fixe ou les perçoit</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Droits de garde</strong></td>\n<td>Prix de la <strong>conservation des titres</strong> (compte-titres, PEA) et des opérations administratives liées. Ils <strong>varient selon les titres et le nombre de lignes</strong>.</td>\n<td>Le <strong>teneur de compte-conservateur</strong> (le PSI). Ils sont fixés par la <strong>convention de compte</strong> ou la brochure tarifaire, et <strong>négociables</strong>.</td>\n</tr>\n<tr>\n<td><strong>Frais de courtage</strong> (de transaction)</td>\n<td>Frais d'<strong>exécution des ordres de bourse</strong></td>\n<td><strong>Libres</strong>, fixés par le <strong>PSI</strong> (règles de publicité des tarifs bancaires). Ce n'est ni l'AMF, ni l'entreprise de marché, ni un décret.</td>\n</tr>\n<tr>\n<td><strong>Frais de tenue de compte</strong></td>\n<td>Peuvent comporter un <strong>minimum annuel par compte</strong>. En <strong>épargne salariale</strong>, ils sont <strong>à la charge de l'employeur</strong>.</td>\n<td>La banque</td>\n</tr>\n<tr>\n<td><strong>Commission de souscription</strong></td>\n<td>Le <strong>droit d'entrée</strong></td>\n<td>Payée <strong>directement</strong> par l'investisseur, hors valeur liquidative</td>\n</tr>\n<tr>\n<td><strong>Commission de rachat</strong></td>\n<td>Le <strong>droit de sortie</strong></td>\n<td>Payée <strong>directement</strong> par l'investisseur, hors valeur liquidative</td>\n</tr>\n<tr>\n<td><strong>Frais de gestion</strong></td>\n<td>Ils rémunèrent la gestion financière et figurent dans le <strong>prospectus</strong></td>\n<td>Prélevés <strong>sur la valeur liquidative</strong></td>\n</tr>\n<tr>\n<td><strong>Commission de surperformance</strong></td>\n<td><strong>Part variable</strong> de la commission de gestion, liée à la <strong>surperformance</strong> par rapport à l'objectif ou à un <strong>indicateur de référence</strong>. Elle n'est possible que si elle est <strong>expressément prévue dans le DICI/DIC et le prospectus</strong> et <strong>cohérente avec l'objectif de gestion</strong>.</td>\n<td>Elle rémunère la <strong>SGP</strong></td>\n</tr>\n<tr>\n<td><strong>Commission de mouvement</strong></td>\n<td>Prélevée sur les transactions d'un compte géré sous mandat</td>\n<td>Peut être <strong>partagée entre la SGP et le dépositaire</strong></td>\n</tr>\n</tbody>\n</table></div>\n<ul>\n<li>Un <strong>mandat de gestion</strong> peut être rémunéré par une <strong>commission de gestion et une commission de surperformance</strong>.</li>\n<li>Dans un FIA, les <strong>frais d'intermédiation</strong> pour la RTO sont des <strong>frais de transaction</strong>.</li>\n<li>Sous MIF 2, le <strong>coût de la recherche</strong> est <strong>facturé séparément</strong> des commissions d'exécution (<em>unbundling</em>).</li>\n<li>Un ordre peut être <strong>annulé tant qu'il n'est pas exécuté</strong>.</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« Entrée = souscription, Sortie = rachat, Garde = conservation, Courtage = exécution. »</strong></p>\n</aside>\n<div class=\"ids\" data-sub=\"6.5\"></div>\n<hr/>\n<h2 id=\"6-6-contrat-capacité-procuration-comptes-à-plusieurs-titulai\">6.6 Contrat, capacité, procuration, comptes à plusieurs titulaires, démembrement</h2>\n<h3 id=\"les-comptes-à-plusieurs-titulaires\">Les comptes à plusieurs titulaires</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Compte</th>\n<th>Fonctionnement</th>\n<th>Moyen de retenir</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Joint</strong></td>\n<td><strong>Chaque titulaire agit seul</strong>, sur sa seule signature (solidarité active). Les titulaires <strong>ne sont pas forcément parents</strong> et leur nombre n'est pas limité.</td>\n<td><span class=\"tag t-mnemo\">mnémo</span> <strong>Joint = Je peux seul</strong></td>\n</tr>\n<tr>\n<td><strong>Indivis</strong></td>\n<td><strong>Toutes les opérations exigent la signature de tous</strong> les cotitulaires</td>\n<td><span class=\"tag t-mnemo\">mnémo</span> <strong>Indivis = Indispensable d'être tous d'accord</strong></td>\n</tr>\n</tbody>\n</table></div>\n<p>Un compte-titres peut être <strong>individuel, joint ou indivis</strong>.</p>\n<h3 id=\"le-démembrement\">Le démembrement</h3>\n<ul>\n<li>Un compte-titres peut être détenu en <strong>usufruit et nue-propriété</strong>.</li>\n<li><strong>L'usufruitier perçoit les revenus</strong> (dividendes, coupons). Le nu-propriétaire détient le capital.</li>\n<li><strong>Sans convention</strong>, certains actes exigent l'<strong>accord des deux</strong>.</li>\n</ul>\n<h3 id=\"la-capacité-et-la-représentation\">La capacité et la représentation</h3>\n<ul>\n<li>La <strong>capacité civile</strong> concerne les <strong>majeurs et les mineurs</strong>.</li>\n<li>Un <strong>mineur émancipé</strong> peut ouvrir seul un compte.</li>\n<li><strong>Les régimes de protection des majeurs</strong> :\n<ul>\n<li><strong>sauvegarde de justice</strong> : protection légère ;</li>\n<li><strong>curatelle</strong> : la personne est <strong>assistée</strong> pour les actes importants, ses actes peuvent être annulés s'ils lui nuisent ;</li>\n<li><strong>tutelle</strong> : la personne est <strong>représentée</strong>.</li>\n</ul>\n</li>\n<li>Le <strong>mandat</strong> (procuration) <strong>exige l'acceptation du mandataire</strong>. Il prend la forme d'un <strong>acte sous seing privé, voire notarié</strong> (le notaire n'est pas obligatoire).</li>\n<li>Le <strong>mandat de gestion</strong> précise les <strong>modalités de sa dénonciation</strong>.</li>\n</ul>\n<div class=\"ids\" data-sub=\"6.6\"></div>\n<hr/>\n<h2 id=\"6-7-insolvabilité-du-particulier-et-de-lentreprise\">6.7 Insolvabilité du particulier et de l'entreprise</h2>\n<h3 id=\"le-particulier-le-surendettement\">Le particulier : le surendettement</h3>\n<ul>\n<li>La procédure concerne les <strong>dettes non professionnelles des personnes physiques</strong>. Le <strong>secrétariat des commissions</strong> est assuré par la <strong>Banque de France</strong>.</li>\n<li>Situation <strong>irrémédiablement compromise</strong> → la <strong>commission</strong> décide un <strong>rétablissement personnel</strong> = <strong>effacement des dettes non professionnelles</strong>.</li>\n<li>Le <strong>FICP</strong> (fichier national des incidents de remboursement des crédits aux particuliers) est <strong>géré par la Banque de France</strong>.\n<ul>\n<li>Il recense les <strong>incidents caractérisés</strong> et les <strong>plans de surendettement</strong>.</li>\n<li>Une inscription au FICP <strong>doit alerter</strong> le PSI sur la situation de son client. Elle n'interdit pas juridiquement tout crédit.</li>\n</ul>\n</li>\n<li>Le <strong>droit au compte</strong> bénéficie aux personnes <strong>physiques et morales</strong>.</li>\n</ul>\n<h3 id=\"lentreprise-les-procédures-collectives\">L'entreprise : les procédures collectives</h3>\n<ul>\n<li><strong>Cessation des paiements</strong> : <strong>impossibilité de faire face au passif exigible avec l'actif disponible</strong>. Ce n'est ni avoir fait des pertes, ni un premier découvert. L'entreprise doit la déclarer <strong>dans les 45 jours</strong>.</li>\n<li><strong>Redressement judiciaire</strong> : <strong>poursuite de l'activité, maintien de l'emploi, apurement du passif</strong>.</li>\n<li><strong>Liquidation judiciaire</strong> : cessation des paiements <strong>ET</strong> redressement <strong>manifestement impossible</strong> (les deux conditions).</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>Cessation des paiements = « Dispo &lt; Exigible »</strong> ; déclaration <strong>sous 45 jours</strong>.</p>\n</aside>\n<div class=\"ids\" data-sub=\"6.7\"></div>\n<hr/>\n<h2 id=\"6-8-protection-des-clients-et-de-leurs-avoirs\">6.8 Protection des clients et de leurs avoirs</h2>\n<h3 id=\"le-fgdr-fonds-de-garantie-des-dépôts-et-de-résolution\">Le FGDR (Fonds de garantie des dépôts et de résolution)</h3>\n<ul>\n<li>C'est une <strong>personne morale de droit privé</strong>, financée par les <strong>banques adhérentes</strong>. Il <strong>gère l'ensemble des mécanismes</strong> : dépôts, titres, cautions. C'est le système français d'indemnisation des investisseurs.</li>\n<li>Il <strong>intervient à la demande de l'ACPR</strong>, pas des clients ni de l'AMF.</li>\n</ul>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Garantie</th>\n<th>Plafond</th>\n<th>Calcul</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Dépôts</strong> (comptes courants, livrets, espèces du PEA…)</td>\n<td><strong>100 000 €</strong></td>\n<td><strong>Par déposant et par établissement</strong> (pas par foyer, pas tous établissements confondus)</td>\n</tr>\n<tr>\n<td><strong>Titres</strong> (indisponibles)</td>\n<td><strong>70 000 €</strong></td>\n<td><strong>Par investisseur et par établissement</strong>, <strong>pour l'ensemble de ses comptes-titres</strong> dans cet établissement</td>\n</tr>\n<tr>\n<td>Délai d'indemnisation des dépôts</td>\n<td><strong>7 jours ouvrables</strong></td>\n<td></td>\n</tr>\n</tbody>\n</table></div>\n<ul>\n<li>Le <strong>contenu d'un coffre-fort n'est pas couvert</strong>.</li>\n<li>Les systèmes de garantie des dépôts s'<strong>harmonisent progressivement au niveau européen</strong>.</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« 100 pour l'argent, 70 pour les titres, 7 jours pour payer. »</strong></p>\n</aside>\n<h3 id=\"la-protection-des-avoirs-par-le-psi\">La protection des avoirs par le PSI</h3>\n<ul>\n<li><strong>Ségrégation</strong> : les instruments des clients sont <strong>séparés</strong> de ceux du PSI par des <strong>registres et comptes distincts</strong>.</li>\n<li>Le PSI met en place des <strong>protections contre les risques opérationnels de perte et de fraude</strong>.</li>\n<li>Il <strong>n'utilise les titres de ses clients</strong> (prêts, cessions temporaires) <strong>qu'avec leur consentement exprès préalable</strong>.</li>\n</ul>\n<h3 id=\"le-droit-de-la-consommation-et-de-la-concurrence\">Le droit de la consommation et de la concurrence</h3>\n<ul>\n<li>La <strong>DGCCRF</strong> constate les infractions au droit de la consommation.</li>\n<li>Les règles sur les <strong>pratiques commerciales trompeuses</strong> protègent <strong>les clients</strong>.</li>\n<li>Les <strong>ententes</strong> et autres pratiques anticoncurrentielles exposent à des <strong>amendes et de l'emprisonnement</strong>.</li>\n<li>Pour les <strong>personnes âgées vulnérables</strong>, les mesures de vigilance peuvent prévoir un <strong>examen systématique des opérations au-delà d'un âge de référence</strong> fixé en interne. Il n'y a ni interdiction totale, ni juge des tutelles.</li>\n</ul>\n<div class=\"ids\" data-sub=\"6.8\"></div>\n<hr/>\n<h2 id=\"6-9-mesures-renforcées-sur-les-produits-spéculatifs-à-haut-r\">6.9 Mesures renforcées sur les produits spéculatifs à haut risque</h2>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Produit</th>\n<th>Règle</th>\n<th>Depuis</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Options binaires</strong></td>\n<td><strong>Commercialisation, distribution et vente interdites aux clients non professionnels</strong>, en France ou <strong>depuis la France</strong>, <strong>par tous les établissements</strong> (les clients professionnels restent possibles). Interdiction aussi au niveau européen (ESMA).</td>\n<td>ESMA 2018, <strong>décision AMF du 2 juillet 2019</strong></td>\n</tr>\n<tr>\n<td><strong>CFD</strong> (<em>contracts for difference</em>)</td>\n<td><strong>Commercialisation restreinte</strong>, pas interdite, auprès des non professionnels : <strong>plafonds d'effet de levier</strong> selon le sous-jacent, protection contre le solde négatif, avertissements</td>\n<td><strong>1er août 2018</strong> (ESMA), <strong>décision AMF du 1er août 2019</strong></td>\n</tr>\n<tr>\n<td><strong>Publicité électronique</strong> (loi <strong>Sapin 2</strong>)</td>\n<td><strong>Interdite</strong> vers les <strong>clients non professionnels</strong> pour certains contrats financiers très spéculatifs : <strong>options binaires, CFD, contrats sur devises (forex)</strong>, et contrats dont le <strong>risque maximal n'est pas connu</strong> à la souscription</td>\n<td>2016</td>\n</tr>\n</tbody>\n</table></div>\n<ul>\n<li><strong>Exception</strong> : la publicité reste possible pour les <strong>CFD bénéficiant d'une protection intrinsèque du capital</strong>.</li>\n<li>Le <strong>démarchage</strong> des CFD est <strong>interdit</strong>.</li>\n<li>Sanctions de la publicité illicite : l'<strong>AMF</strong> et la <strong>DGCCRF</strong>.</li>\n<li>Le <strong>levier d'un CFD accroît les pertes</strong> potentielles.</li>\n<li>L'AMF publie des <strong>listes noires</strong> des sites et acteurs non autorisés.</li>\n<li><strong>Pouvoir d'intervention</strong> (règlement MiFIR art. 42) : l'AMF peut <strong>interdire ou restreindre</strong> la commercialisation d'un instrument qui pose de graves problèmes de protection des investisseurs. L'<strong>ESMA</strong> dispose d'un pouvoir temporaire au niveau européen.</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« Options binaires = INTERDITES (aux particuliers) ; CFD = BRIDÉS (levier plafonné). »</strong></p>\n</aside>\n<div class=\"ids\" data-sub=\"6.9\"></div>\n<hr/>\n<h2 class=\"flash\" id=\"fiche-flash-du-thème-6\"> Fiche flash du thème 6</h2>\n<ol>\n<li><strong>3 catégories seulement</strong> : non pro (protection maximale, toutes les personnes physiques par nature), pro (sait décider et évaluer les risques), contrepartie éligible (institutionnels).</li>\n<li>Pro par nature : établissements financiers, OPC et SGP, mutuelles, capital-risque + grandes entreprises <strong>2 critères sur 3 (bilan 20 M€, CA 40 M€, capitaux propres 2 M€)</strong>.</li>\n<li>Catégorie <strong>fixée par le PSI à l'entrée en relation, toujours communiquée au client</strong>. Pro → non pro : demande + accord du PSI. Non pro → pro : demande + <strong>évaluation</strong> (2 critères sur 3 : 500 000 €, 10 opérations par trimestre, 1 an d'expérience).</li>\n<li>Connaissance client (MIF 2) : <strong>connaissances, expérience, situation financière (capacité à subir des pertes), objectifs (tolérance au risque)</strong> ; pas d'auto-évaluation aveugle ; <strong>charge de la preuve sur le PSI</strong>.</li>\n<li>Secret : <strong>1 an / 15 000 €</strong> ; non opposable à ACPR, AMF, BdF, juge pénal, fisc, douanes, surendettement, commissions parlementaires.</li>\n<li>RGPD : accès à tout moment, rectification ; <strong>violation → CNIL sous 72 h</strong> ; consentement libre, spécifique, éclairé, univoque.</li>\n<li><strong>5 ans</strong> de conservation ; enregistrement <strong>téléphone + électronique</strong> des transactions conclues ou envisagées, <strong>client prévenu</strong>.</li>\n<li>Information : <strong>claire, exacte, non trompeuse</strong> ; performances sur <strong>5 ans, 12 mois pleins, frais inclus</strong> ; risques <strong>dans la même police</strong>.</li>\n<li>Conseil <strong>indépendant</strong> = rétrocessions <strong>reversées au client</strong> + large gamme ; non indépendant = <strong>information</strong> du client.</li>\n<li>Avis d'opéré : <strong>sans délai</strong>, au plus tard <strong>le premier jour ouvrable</strong> (non pro) ; <strong>jour, heure, lieu</strong>, frais ; tranches = <strong>prix de chaque tranche ou prix moyen</strong>.</li>\n<li><strong>Adéquation</strong> (conseil, gestion) → si le client ne répond pas, <strong>pas de service</strong>. <strong>Caractère approprié</strong> (RTO, exécution) → mise en garde ; <strong>exécution simple</strong> = non complexe + initiative du client.</li>\n<li>Vendeurs : connaissances minimales vérifiées <strong>sous 6 mois</strong> (sauf alternance).</li>\n<li><strong>Meilleure exécution</strong> = celui qui <strong>exécute</strong> (coût total pour le non pro) ; <strong>meilleure sélection</strong> = celui qui <strong>transmet</strong> (intermédiaires revus <strong>chaque année</strong>). <strong>Instruction spécifique</strong> = on la suit, sans meilleure exécution. Hors plateforme = <strong>consentement exprès préalable</strong>. Politique <strong>révisée chaque année</strong> et <strong>approuvée par le client</strong>.</li>\n<li>Frais : garde = conservation (convention) ; courtage libre ; surperformance <strong>seulement si prévue au DICI et au prospectus</strong>.</li>\n<li><strong>Joint = chacun seul</strong> ; <strong>indivis = tous ensemble</strong> ; usufruitier = revenus.</li>\n<li>Surendettement : rétablissement personnel = <strong>effacement</strong> ; FICP = <strong>Banque de France</strong> ; cessation des paiements = <strong>actif disponible &lt; passif exigible</strong>, déclaration <strong>sous 45 jours</strong>.</li>\n<li>FGDR (droit privé, à la demande de l'ACPR) : <strong>100 000 € dépôts / 70 000 € titres</strong>, par client et par établissement, <strong>7 jours ouvrables</strong>.</li>\n<li>Options binaires <strong>interdites</strong> aux non pro ; CFD <strong>restreints</strong> (levier) ; publicité électronique <strong>interdite</strong> (Sapin 2) ; démarchage de CFD interdit.</li>\n</ol>\n","toc":[{"id":"6-1-1-connaître-évaluer-et-catégoriser-le-client-mif-2","t":"6.1.1 Connaître, évaluer et catégoriser le client (MIF 2)"},{"id":"6-1-2-confidentialité-secret-professionnel-données-personnel","t":"6.1.2 Confidentialité, secret professionnel, données personnelles, enregistrements"},{"id":"6-2-linformation-à-donner-aux-clients","t":"6.2 L'information à donner aux clients"},{"id":"6-3-agir-au-mieux-des-intérêts-du-client-adéquation-et-carac","t":"6.3 Agir au mieux des intérêts du client : adéquation et caractère approprié"},{"id":"6-4-meilleure-exécution-best-execution-et-meilleure-sélectio","t":"6.4 Meilleure exécution (best execution) et meilleure sélection (best selection)"},{"id":"6-5-charges-et-commissions","t":"6.5 Charges et commissions"},{"id":"6-6-contrat-capacité-procuration-comptes-à-plusieurs-titulai","t":"6.6 Contrat, capacité, procuration, comptes à plusieurs titulaires, démembrement"},{"id":"6-7-insolvabilité-du-particulier-et-de-lentreprise","t":"6.7 Insolvabilité du particulier et de l'entreprise"},{"id":"6-8-protection-des-clients-et-de-leurs-avoirs","t":"6.8 Protection des clients et de leurs avoirs"},{"id":"6-9-mesures-renforcées-sur-les-produits-spéculatifs-à-haut-r","t":"6.9 Mesures renforcées sur les produits spéculatifs à haut risque"},{"id":"fiche-flash-du-thème-6","t":"Fiche flash du thème 6"}]},{"id":"07","n":7,"title":"Instruments financiers, crypto-actifs et leurs risques","html":"\n<blockquote class=\"note\">\n<p><strong>Poids à l'examen : 21 questions sur 120, toutes en catégorie C.</strong>\nRépartition : §7.1 (3) · §7.2 (3) · §7.3 (3) · §7.4 (2) · §7.5 (1) · §7.6 (2) · §7.7 (1) · §7.8 (2) · §7.9 (2) · §7.10 (2).</p>\n<p>C'est le thème « technique » par excellence : peu de pièges juridiques, beaucoup de <strong>définitions</strong> et quelques <strong>calculs simples</strong>. Les exemples chiffrés ci-dessous ont été vérifiés.</p>\n</blockquote>\n<hr/>\n<h2 id=\"7-1-le-couple-risquerendement-et-les-familles-de-risques\">7.1 Le couple risque/rendement et les familles de risques</h2>\n<h3 id=\"le-principe\">Le principe</h3>\n<p><strong>Le rendement attendu est lié au risque</strong> : plus on espère gagner, plus on accepte de perdre. Les actions sont <strong>plus risquées</strong> (et en moyenne plus rémunératrices) que les emprunts d'État. <strong>Volatilité élevée</strong> = <strong>possibilités de gain ET de perte plus importantes</strong>, c'est-à-dire un écart de performances possibles plus grand.</p>\n<h3 id=\"les-risques-à-savoir-nommer\">Les risques à savoir nommer</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Risque</th>\n<th>Définition à retenir</th>\n<th>Exemple type de la base</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>De marché</strong> (de cours, de volatilité)</td>\n<td>Perte due à une <strong>variation défavorable des prix</strong> des instruments</td>\n<td>Baisse de la valeur de marché d'une action ; vendre une obligation <strong>avant l'échéance</strong></td>\n</tr>\n<tr>\n<td><strong>De crédit</strong> = <strong>de défaut</strong> = risque émetteur</td>\n<td>Le débiteur <strong>ne rembourse pas</strong> le capital ou les intérêts</td>\n<td><strong>Le risque principal d'une obligation conservée jusqu'à l'échéance</strong></td>\n</tr>\n<tr>\n<td><strong>De contrepartie</strong></td>\n<td>L'<strong>autre partie</strong> à la transaction fait défaut, notamment au <strong>règlement-livraison</strong></td>\n<td>L'acheteur ne paie pas, le vendeur ne livre pas</td>\n</tr>\n<tr>\n<td><strong>De liquidité</strong> (de revente)</td>\n<td><strong>Ne pas pouvoir vendre</strong>, ou seulement <strong>avec une forte décote</strong> ou pas au moment voulu</td>\n<td>Trouver difficilement une contrepartie</td>\n</tr>\n<tr>\n<td><strong>De change</strong></td>\n<td>Variation <strong>défavorable</strong> (à la hausse comme à la baisse) du cours d'une <strong>devise autre que la sienne</strong></td>\n<td>Un exportateur payé en dollars ; une émission d'obligations en francs suisses</td>\n</tr>\n<tr>\n<td><strong>De taux</strong></td>\n<td>Variation des taux d'intérêt. Il touche <strong>surtout les obligations à taux fixe</strong> : si les taux montent, leur prix baisse.</td>\n<td>Les obligations sont les plus exposées</td>\n</tr>\n<tr>\n<td><strong>Opérationnel</strong></td>\n<td>Pertes dues à des <strong>processus, personnes, systèmes défaillants ou à des événements extérieurs</strong></td>\n<td><strong>Panne informatique</strong>, erreur de saisie, <strong>dysfonctionnement du marché</strong>, fraude, cybercriminalité</td>\n</tr>\n<tr>\n<td><strong>D'effet de levier</strong></td>\n<td>L'<strong>exposition au marché est supérieure au capital investi</strong></td>\n<td>CFD, options, achat à crédit</td>\n</tr>\n<tr>\n<td><strong>De durabilité</strong> (SFDR)</td>\n<td>Un <strong>événement environnemental, social ou de gouvernance</strong> qui pourrait avoir une <strong>incidence négative importante sur la valeur</strong> de l'investissement</td>\n<td>Thème 8.7</td>\n</tr>\n</tbody>\n</table></div>\n<p><strong>Cas combinés à connaître</strong> :</p>\n<ul>\n<li><strong>Obligation en dollars gardée jusqu'à l'échéance</strong> : risque de <strong>change + crédit</strong>.</li>\n<li><strong>Obligation revendue avant l'échéance</strong> : risques de <strong>liquidité + marché + crédit</strong>.</li>\n<li><strong>Action</strong> : le risque majeur est la <strong>perte en capital</strong>.</li>\n</ul>\n<p><strong>La volatilité</strong></p>\n<ul>\n<li>Elle se mesure par l'<strong>écart-type des variations de cours</strong> : c'est une <strong>mesure statistique du risque</strong>.</li>\n<li>On distingue la <strong>volatilité historique</strong> et la <strong>volatilité implicite</strong>.</li>\n<li>Elle est la <strong>plus forte sur les actions</strong>, la plus faible sur le monétaire.</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« Garder une obligation jusqu'au bout = risque de DÉFAUT ; la vendre avant = risque de MARCHÉ (et de liquidité). »</strong></p>\n</aside>\n<aside class=\"callout c-warn\"><span class=\"callout-label\">Piège</span>\n<p>Une <strong>forte hausse du dollar</strong> est un risque de <strong>change</strong> (de marché), jamais un risque opérationnel.\n<strong>Placements atypiques</strong> (vin, métaux, manuscrits, diamants) : <strong>rendement potentiel élevé, risque élevé</strong>, liquidité faible.</p>\n</aside>\n<h3 id=\"instruments-financiers-la-classification\">Instruments financiers : la classification</h3>\n<ul>\n<li><strong>Instruments financiers</strong> = <strong>titres financiers</strong> (actions, obligations, <strong>TCN</strong>, <strong>parts et actions d'OPC</strong>) + <strong>contrats financiers</strong> (<strong>dérivés</strong> : options, <strong>contrats à terme</strong>, swaps, <strong>CFD</strong>).</li>\n<li><strong>Tous les titres financiers sont des instruments financiers</strong>, mais l'inverse est faux : un <strong>CFD n'est pas un titre financier</strong>.</li>\n<li>Une assurance-vie n'est pas un contrat financier au sens du CMF.</li>\n</ul>\n<div class=\"ids\" data-sub=\"7.1\"></div>\n<hr/>\n<h2 id=\"7-2-les-actions\">7.2 Les actions</h2>\n<h3 id=\"nature-et-droits\">Nature et droits</h3>\n<ul>\n<li>Une action est un <strong>titre de propriété</strong> (<strong>titre de capital</strong>) : une <strong>part du capital social</strong>. Une obligation, à l'inverse, est un <strong>titre de créance</strong>.</li>\n<li>L'actionnaire n'est <strong>engagé qu'à hauteur de son apport</strong> : sa responsabilité n'est pas illimitée.</li>\n<li>En cas de <strong>liquidation</strong>, l'actionnaire est servi <strong>en dernier, après tous les créanciers</strong> (État compris) : il ne récupère que l'éventuel <strong>boni de liquidation</strong> (question EF26-60, BTS Banque 2026).</li>\n<li><strong>L'action ordinaire</strong> donne :\n<ul>\n<li>un <strong>droit de vote</strong> aux assemblées générales, qui <strong>nomment et révoquent les administrateurs</strong> ;</li>\n<li>un <strong>droit au dividende</strong>, et au boni de liquidation.</li>\n</ul>\n</li>\n<li><strong>Le dividende</strong> :\n<ul>\n<li>c'est une <strong>part du bénéfice distribuée</strong> : un <strong>revenu variable</strong>, jamais garanti ;</li>\n<li>il est versé <strong>en espèces ou en actions</strong>. L'<strong>option</strong> du paiement en actions est <strong>exercée par chaque actionnaire</strong> ;</li>\n<li>les bénéfices non distribués deviennent des <strong>réserves</strong> ;</li>\n<li>au <strong>détachement du dividende</strong>, le cours <strong>baisse mécaniquement du montant du dividende</strong>.</li>\n</ul>\n</li>\n<li>Les actions sont <strong>négociables dès l'immatriculation de la société au RCS</strong>. Elles sont le plus souvent <strong>au porteur</strong>.</li>\n<li>Seules les actions de <strong>sociétés anonymes</strong> (SA, SCA) peuvent être cotées, pas celles d'une SARL ni les parts de SCI.</li>\n</ul>\n<h3 id=\"les-actions-de-préférence\">Les actions de préférence</h3>\n<ul>\n<li>Elles <strong>dérogent au principe de proportionnalité</strong>.</li>\n<li>Elles peuvent porter des <strong>droits particuliers de toute nature</strong> : un <strong>avantage pécuniaire</strong> (dividende majoré), plus ou moins de droits de vote…</li>\n<li>Elles sont émises <strong>en quantité limitée</strong>. <strong>Sans droit de vote</strong>, elles ne peuvent dépasser <strong>la moitié du capital</strong>, et <strong>le quart</strong> dans une société cotée.</li>\n<li>Le <strong>droit de vote double</strong> permet de voter <strong>deux fois plus</strong>. La base le rattache aux actions de préférence (voir l'annexe A).</li>\n</ul>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p><strong>Loi Attractivité (2024)</strong> : les sociétés qui s'introduisent en bourse peuvent émettre des <strong>actions de préférence à droits de vote multiples</strong>.</p>\n</aside>\n<h3 id=\"valorisation-et-ratios\">Valorisation et ratios</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Ratio</th>\n<th>Formule</th>\n<th>Lecture</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Capitalisation boursière</strong></td>\n<td><strong>Nombre d'actions × cours de bourse</strong></td>\n<td>La <strong>valeur de marché</strong> de la société</td>\n</tr>\n<tr>\n<td><strong>BNPA</strong></td>\n<td><strong>Bénéfice net / nombre d'actions</strong></td>\n<td>Bénéfice par action</td>\n</tr>\n<tr>\n<td><strong>PER</strong> (<em>Price Earning Ratio</em>)</td>\n<td><strong>Cours / BNPA</strong></td>\n<td>Un indicateur <strong>boursier</strong> de <strong>cherté</strong>. <strong>Un PER faible = action bon marché.</strong> Il <strong>augmente quand le cours monte</strong>.</td>\n</tr>\n<tr>\n<td><strong>Rendement</strong> de l'action</td>\n<td><strong>Dividende / cours</strong></td>\n<td>Exprimé en %</td>\n</tr>\n<tr>\n<td><strong>Rendement bénéficiaire</strong> (<em>earning yield</em>)</td>\n<td><strong>BNPA / cours</strong> = 1 / PER</td>\n<td>Le revenu potentiel rapporté au prix</td>\n</tr>\n<tr>\n<td><strong>Bêta</strong></td>\n<td>Sensibilité au marché</td>\n<td><strong>β &gt; 1 : l'action amplifie</strong> les variations du marché</td>\n</tr>\n</tbody>\n</table></div>\n<p><strong>Exemple</strong> : 10 millions d'actions cotées 50 €, un bénéfice par action de 4 € et un dividende de 2 € donnent :</p>\n<ul>\n<li>une <strong>capitalisation de 500 M€</strong> ;</li>\n<li>un <strong>PER de 50 / 4 = 12,5</strong> ;</li>\n<li>un <strong>rendement de 2 / 50 = 4 %</strong> ;</li>\n<li>un <strong>rendement bénéficiaire de 4 / 50 = 8 %</strong>.</li>\n</ul>\n<p><strong>Méthodes d'évaluation</strong> :</p>\n<ul>\n<li>celles qui conviennent : <strong>PER et multiples comparables</strong>, <strong>actualisation des flux futurs</strong>, <strong>actif net réévalué</strong>, actif net comptable par action ;</li>\n<li>celles qui ne conviennent pas : le nombre de salariés, la « parité des taux d'intérêt ».</li>\n<li>Si la <strong>valeur fondamentale est supérieure au cours</strong>, on anticipe une <strong>hausse</strong>.</li>\n<li>Pour connaître le prix d'achat immédiat, on regarde les <strong>prix des vendeurs dans le carnet d'ordres</strong>, plutôt que le dernier cours.</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« PER = Prix / Earnings (le bénéfice) »</strong> : on paie combien d'années de bénéfices ?</p>\n</aside>\n<div class=\"ids\" data-sub=\"7.2\"></div>\n<hr/>\n<h2 id=\"7-3-les-obligations\">7.3 Les obligations</h2>\n<h3 id=\"le-vocabulaire\">Le vocabulaire</h3>\n<ul>\n<li><strong>Obligation</strong> : <strong>titre de créance</strong>. L'investisseur est <strong>créancier</strong> de l'émetteur.</li>\n<li><strong>Nominal</strong> (valeur faciale) : la base de calcul du coupon.</li>\n<li><strong>Coupon</strong> : l'<strong>intérêt</strong> perçu, égal à <strong>taux facial (nominal) × valeur nominale</strong>.</li>\n<li><strong>Prix d'émission au pair</strong> = <strong>100 % du nominal</strong>.\n<ul>\n<li><strong>Prime d'émission</strong> = <strong>nominal − prix d'émission</strong>.</li>\n<li><strong>Prime de remboursement</strong> = <strong>prix de remboursement − nominal</strong>.</li>\n<li>Les primes sont possibles à l'émission comme au remboursement, et la valeur de remboursement est fixée dans le <strong>contrat d'émission</strong>.</li>\n</ul>\n</li>\n<li><strong>In fine</strong> : <strong>tout le capital est remboursé en une seule fois à l'échéance</strong>, et les <strong>intérêts sont payés à chaque période</strong>. L'<strong>amortissement</strong> porte sur le <strong>principal</strong>.</li>\n<li><strong>Cotation en % du nominal</strong>, ce qui permet de <strong>comparer</strong> les obligations entre elles.</li>\n<li><strong>Coupon couru</strong> : la part d'intérêt acquise <strong>depuis le dernier coupon</strong>, calculée avec le <strong>taux nominal</strong>.</li>\n<li><strong>Prix à payer</strong> = <strong>(cours coté + coupon couru) en % × nominal</strong>.</li>\n</ul>\n<p><strong>Exemple</strong> : nominal 1 000 €, cours 98,50 %, coupon de 4 % par an, 73 jours écoulés depuis le dernier coupon.</p>\n<ul>\n<li>Coupon couru = 4 % × 73/365 = <strong>0,80 %</strong>.</li>\n<li>Prix = (98,50 % + 0,80 %) × 1 000 € = <strong>993 €</strong>.</li>\n</ul>\n<p><strong>Exemple de durée restante</strong> : une obligation de 15 ans émise il y a 6 ans, achetée aujourd'hui, sera remboursée <strong>dans 9 ans</strong> et sert toujours son coupon d'origine.</p>\n<h3 id=\"le-taux-de-rendement-actuariel\">Le taux de rendement actuariel</h3>\n<ul>\n<li>C'est le <strong>taux d'actualisation qui égalise le prix de marché et la valeur actuelle des flux futurs</strong> : le rendement réel si l'on garde l'obligation jusqu'au bout et qu'on réinvestit les coupons au même taux.</li>\n<li>Il sert à <strong>calculer le prix</strong>, à la place du taux nominal ou de l'Euribor.</li>\n<li>L'<strong>actualisation</strong> consiste à calculer la <strong>valeur présente de flux futurs</strong>.</li>\n</ul>\n<h3 id=\"la-relation-tauxprix-la-règle\">La relation taux/prix : LA règle</h3>\n<p><strong>Quand les taux montent, le prix des obligations à taux fixe baisse. Quand les taux baissent, il monte</strong>, selon leur <strong>sensibilité</strong>.</p>\n<ul>\n<li>La <strong>sensibilité</strong> est la <strong>variation en % du prix</strong> pour <strong>1 % (100 points de base) de variation des taux</strong>. Elle dépend surtout de la <strong>durée de vie résiduelle</strong>.</li>\n<li>Exemple : une sensibilité de 6 et des taux en hausse de 0,5 % donnent un prix en <strong>baisse de 3 %</strong>.</li>\n<li>La valeur d'une obligation dépend du <strong>taux de référence ET de ses caractéristiques propres</strong>.</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« Taux et prix font la balançoire »</strong> : l'un monte, l'autre descend.</p>\n</aside>\n<h3 id=\"les-types-dobligations\">Les types d'obligations</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Type</th>\n<th>À retenir</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>À taux fixe</strong></td>\n<td><strong>Taux nominal fixe</strong>, coupon constant ; exposée au <strong>risque de taux</strong></td>\n</tr>\n<tr>\n<td><strong>À taux variable ou révisable</strong></td>\n<td>Le <strong>coupon varie</strong> avec les taux, ce qui la protège du risque de taux sur le prix</td>\n</tr>\n<tr>\n<td><strong>Zéro coupon</strong></td>\n<td><strong>Aucun coupon intermédiaire</strong> : les intérêts <strong>capitalisés</strong> sont versés <strong>à l'échéance</strong>, en une fois. Le rendement est <strong>connu dès l'achat</strong> si on la garde jusqu'au bout. Indexée sur un indice actions, sa <strong>prime de remboursement dépend de l'indice</strong>.</td>\n</tr>\n<tr>\n<td><strong>Indexée</strong></td>\n<td>Le coupon et le remboursement suivent un <strong>indice de prix</strong>. L'<strong>OATi</strong> est indexée sur l'<strong>inflation française (IPC hors tabac)</strong>.</td>\n</tr>\n<tr>\n<td><strong>Démembrée</strong> (<em>strips</em>)</td>\n<td>Le <strong>principal et les coupons se négocient séparément</strong>. Les <strong>droits de vote</strong> en assemblée d'obligataires vont <strong>en principe au nu-propriétaire</strong>.</td>\n</tr>\n<tr>\n<td><strong>À haut rendement</strong> (<em>high yield</em>)</td>\n<td>Émetteurs à <strong>risque de défaut élevé</strong></td>\n</tr>\n<tr>\n<td><strong>OAT</strong> (obligations <strong>assimilables du Trésor</strong>)</td>\n<td>Émises par l'<strong>État</strong>, <strong>par adjudication</strong>, avec un <strong>coupon annuel</strong>. La dette de l'État est gérée par l'<strong>Agence France Trésor</strong>.</td>\n</tr>\n</tbody>\n</table></div>\n<ul>\n<li>On peut <strong>vendre une obligation avant l'échéance</strong>, avec un risque de perte en capital.</li>\n<li>Les obligations nouvelles se souscrivent sur le <strong>marché primaire</strong>, pendant la période de souscription.</li>\n<li>Un <strong>GIE</strong> peut émettre des obligations, <strong>sous conditions</strong>.</li>\n</ul>\n<div class=\"ids\" data-sub=\"7.3\"></div>\n<hr/>\n<h2 id=\"7-4-le-marché-monétaire-les-tcn-et-les-indices-de-référence\">7.4 Le marché monétaire, les TCN et les indices de référence</h2>\n<h3 id=\"le-marché-monétaire\">Le marché monétaire</h3>\n<p>Il compte <strong>deux compartiments</strong> :</p>\n<ul>\n<li>le <strong>marché interbancaire</strong>, où une banque peut être prêteuse ou emprunteuse et aussi émettrice ;</li>\n<li>le <strong>marché des titres de créances négociables (TCN)</strong>.</li>\n</ul>\n<h3 id=\"les-tcn-titres-de-créances-négociables\">Les TCN (titres de créances négociables)</h3>\n<ul>\n<li>Ce sont des <strong>titres financiers</strong> émis <strong>au gré de l'émetteur</strong> sur le <strong>marché monétaire</strong>. Ils permettent aux émetteurs, y compris les entreprises non financières, de <strong>se financer à court ou moyen terme</strong>.</li>\n<li>Le <strong>nominal minimum</strong> est de <strong>150 000 €</strong>. Les particuliers y accèdent <strong>via des OPC</strong> (fonds monétaires).</li>\n<li>Leur <strong>rémunération est libre</strong>, éventuellement indexée sur un taux de marché. Ils sont émis <strong>au pair, en dessous du pair ou avec une prime</strong>.</li>\n<li>Ils exigent une <strong>documentation financière déposée à la Banque de France</strong>, qui <strong>surveille ce marché</strong>.</li>\n<li>Leur risque de crédit et de marché est <strong>faible</strong> en raison de leur durée courte, <strong>mais il existe</strong>.</li>\n</ul>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>TCN</th>\n<th>Durée</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>NEU CP</strong> (titres négociables à court terme)</td>\n<td><strong>≤ 1 an</strong></td>\n</tr>\n<tr>\n<td><strong>NEU MTN</strong> (moyen terme)</td>\n<td><strong>&gt; 1 an</strong></td>\n</tr>\n<tr>\n<td><strong>BTF</strong> (bons du Trésor à taux fixe)</td>\n<td><strong>≤ 1 an</strong></td>\n</tr>\n</tbody>\n</table></div>\n<ul>\n<li>Les <strong>bons de caisse</strong> sont des titres <strong>nominatifs et non négociables</strong> : ce ne sont pas des TCN.</li>\n</ul>\n<h3 id=\"les-indices-de-référence\">Les indices de référence</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Indice</th>\n<th>Caractéristiques</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>EURIBOR</strong> (<em>Euro Interbank Offered Rate</em>)</td>\n<td>Taux moyen auquel des banques de l'UE <strong>se prêtent</strong> des fonds. <strong>Plusieurs échéances, d'1 semaine à 12 mois</strong>. <strong>Calculé chaque jour ouvré</strong>, <strong>base 360 jours</strong>. <strong>Administré par l'EMMI</strong> (European Money Markets Institute), ni la BCE ni Bloomberg. <strong>Méthode hybride</strong> (transactions réelles + estimations), <strong>réformée</strong> pour éviter les manipulations.</td>\n</tr>\n<tr>\n<td><strong>€STR</strong> (<em>euro short-term rate</em>)</td>\n<td><strong>Taux au jour le jour</strong> des <strong>emprunts non garantis</strong> des banques auprès de contreparties financières, <strong>calculé et publié par la BCE</strong> sur la base des <strong>transactions réelles de la veille</strong> (de plus d'1 M€). Il a <strong>remplacé l'EONIA</strong>, mais <strong>pas l'Euribor</strong>.</td>\n</tr>\n</tbody>\n</table></div>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« Euribor = plusieurs maturités (1 semaine-12 mois), EMMI ; €STR = 1 jour, BCE. »</strong></p>\n</aside>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p>L'<strong>EONIA a disparu le 3 janvier 2022</strong>. L'Euribor existe toujours.</p>\n</aside>\n<div class=\"ids\" data-sub=\"7.4\"></div>\n<hr/>\n<h2 id=\"7-5-les-titres-hybrides-ou-composés\">7.5 Les titres hybrides ou composés</h2>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Titre</th>\n<th>Ce qu'il permet</th>\n<th>À retenir</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Obligation convertible</strong></td>\n<td><strong>Convertir l'obligation en actions</strong>, au <strong>choix du porteur</strong> : c'est une possibilité, pas une obligation</td>\n<td><strong>Hybride</strong>, car il donne <strong>accès au capital</strong>. Son <strong>coupon est plus faible</strong> qu'une obligation classique (c'est l'<strong>avantage pour l'émetteur</strong>). Le <strong>prix de conversion est toujours supérieur au cours de l'action</strong> à l'émission.</td>\n</tr>\n<tr>\n<td><strong>Bon de souscription (BSA)</strong></td>\n<td><strong>Souscrire une action (ou une obligation) à un prix fixé à l'avance</strong>, pendant une <strong>période déterminée par l'émetteur</strong>, <strong>au choix du porteur</strong></td>\n<td><strong>Accès différé</strong> au capital. Attaché à une action (<strong>ABSA</strong>) ou à une obligation (<strong>OBSA</strong>), ou <strong>distribué gratuitement</strong>. Une OBSA permet donc d'acquérir des actions.</td>\n</tr>\n<tr>\n<td><strong>Titre subordonné</strong></td>\n<td>Une dette <strong>remboursée après les autres créanciers</strong></td>\n<td><strong>Plus risqué</strong> que l'obligation classique, donc <strong>mieux rémunéré</strong>. Il est <strong>assimilé à des fonds propres</strong> et <strong>renforce la structure financière</strong> de l'émetteur.</td>\n</tr>\n<tr>\n<td><strong>EMTN structuré</strong></td>\n<td>Titre de créance dont le rendement dépend d'une formule ou d'un sous-jacent</td>\n<td>Soumis à PRIIPs (DIC)</td>\n</tr>\n</tbody>\n</table></div>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>Convertible = « obligation + option de devenir actionnaire »</strong> : on paie cette option par un coupon plus faible.</p>\n</aside>\n<div class=\"ids\" data-sub=\"7.5\"></div>\n<hr/>\n<h2 id=\"7-6-les-autres-placements-épargne-réglementée-comptes-à-term\">7.6 Les autres placements : épargne réglementée, comptes à terme, assurance-vie, parts sociales, titrisation</h2>\n<h3 id=\"lépargne-réglementée-et-les-comptes-à-terme\">L'épargne réglementée et les comptes à terme</h3>\n<ul>\n<li><strong>Livret A</strong> : épargne <strong>réglementée par la loi</strong>. Son taux est <strong>fixé par le ministre de l'Économie</strong> selon une <strong>formule</strong> (taux courts et inflation).</li>\n<li><strong>LEP</strong> (livret d'épargne populaire) : réservé aux foyers <strong>sous un plafond de revenu fiscal</strong>.</li>\n<li><strong>Livret jeune</strong> :\n<ul>\n<li>intérêts calculés <strong>par quinzaine</strong> ;</li>\n<li>taux <strong>libre</strong>, mais <strong>au moins égal à celui du livret A</strong> ;</li>\n<li>plafond de <strong>1 600 €</strong>.</li>\n</ul>\n</li>\n<li><strong>CEL</strong> (compte épargne logement) : durée <strong>illimitée</strong>.</li>\n<li><strong>Compte à terme (CAT)</strong> :\n<ul>\n<li>placement bancaire de <strong>durée fixée à l'avance</strong> (<strong>1 mois minimum</strong>) ;</li>\n<li>les fonds sont <strong>bloqués</strong>, mais un <strong>déblocage anticipé</strong> est possible si le contrat le prévoit, avec pénalités ;</li>\n<li>taux <strong>fixe, progressif ou variable</strong>, <strong>librement fixé</strong> par la banque ;</li>\n<li>intérêts soumis à l'<strong>impôt sur le revenu et aux prélèvements sociaux</strong>.</li>\n</ul>\n</li>\n</ul>\n<h3 id=\"lassurance-vie-code-des-assurances\">L'assurance-vie (Code des assurances)</h3>\n<ul>\n<li><strong>Le contrat</strong> :\n<ul>\n<li>il peut être <strong>monosupport</strong> (fonds en euros) ou <strong>multisupport</strong> (unités de compte, ou euros + UC) ;</li>\n<li>il se <strong>dénoue en capital ou en rente</strong>, au choix ;</li>\n<li>il peut servir à <strong>préparer sa retraite</strong> : c'est une épargne de long terme.</li>\n</ul>\n</li>\n<li><strong>Fonds en euros</strong> : <strong>capital garanti par l'assureur</strong>. Il est investi <strong>majoritairement en obligations</strong> (d'État, d'entreprises) <strong>et en immobilier</strong>, donc peu risqué.</li>\n<li><strong>Unités de compte</strong> : <strong>risque financier pour le souscripteur</strong>, sans garantie du capital. Un contrat <strong>multisupport est plus risqué</strong> qu'un monosupport en euros.</li>\n<li><strong>Fiscalité</strong> : les gains sont <strong>toujours soumis aux prélèvements sociaux</strong> (thème 12).</li>\n<li><strong>Contrats non réclamés</strong> (loi <strong>Eckert</strong>) : <strong>10 ans après le décès</strong>, les sommes sont <strong>déposées à la Caisse des dépôts</strong>.</li>\n</ul>\n<h3 id=\"les-autres-instruments\">Les autres instruments</h3>\n<ul>\n<li><strong>Parts sociales</strong> des banques coopératives : elles <strong>donnent le droit de voter en assemblée générale</strong> (une personne, une voix). Elles sont <strong>rémunérées</strong> et <strong>non cotées</strong>.</li>\n<li><strong>Organismes de titrisation</strong> :\n<ul>\n<li>ils <strong>rachètent des créances</strong> et <strong>émettent des titres adossés</strong> à ces créances ;</li>\n<li>ils sont <strong>gérés par une société de gestion</strong> agréée, avec un programme d'activité spécifique ;</li>\n<li>ils ne sont démarchables <strong>qu'auprès d'investisseurs qualifiés</strong>.</li>\n</ul>\n</li>\n<li><strong>PERP</strong> : sortie anticipée possible notamment en cas d'<strong>invalidité</strong>.</li>\n</ul>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p>Le <strong>PERP</strong> (<a class=\"qref\" href=\"#\" data-q=\"1498\">Q1498</a>) <strong>n'est plus commercialisé depuis le 1er octobre 2020</strong> : il a été remplacé par le <strong>PER</strong> (loi PACTE).</p>\n</aside>\n<aside class=\"callout c-warn\"><span class=\"callout-label\">Piège</span>\n<p>Les 0,75 % de la <a class=\"qref\" href=\"#\" data-q=\"1507\">Q1507</a> correspondent à l'<strong>ancien taux du livret A</strong>. La règle actuelle : le taux du livret jeune est au moins égal à celui du livret A.</p>\n</aside>\n<div class=\"ids\" data-sub=\"7.6\"></div>\n<hr/>\n<h2 id=\"7-7-les-produits-dérivés\">7.7 Les produits dérivés</h2>\n<ul>\n<li>Un <strong>dérivé</strong> est un produit dont la <strong>valeur dépend d'un actif sous-jacent</strong> : actions, taux, change, crédit, matières premières, crypto-actifs. Il se négocie sur un marché organisé ou de gré à gré.</li>\n</ul>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Produit</th>\n<th>Engagement</th>\n<th>À retenir</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Future</strong> (contrat à terme ferme)</td>\n<td><strong>Achat ou vente à un prix fixé aujourd'hui</strong> pour un <strong>règlement-livraison futur</strong>. L'acheteur et le vendeur sont <strong>irrévocablement engagés</strong>.</td>\n<td>Sur un marché organisé, la <strong>chambre de compensation</strong> s'interpose. <strong>Appels de marge</strong> quotidiens, calculés sur le <strong>cours de compensation de fin de journée</strong>.</td>\n</tr>\n<tr>\n<td><strong>Option</strong> (conditionnelle)</td>\n<td>L'acheteur paie une <strong>prime</strong> et obtient <strong>le droit, pas l'obligation</strong>, d'acheter (<strong>call</strong>) ou de vendre (<strong>put</strong>) le sous-jacent à un <strong>prix d'exercice</strong> fixé, jusqu'à ou à une échéance</td>\n<td>Sa valeur dépend notamment du <strong>prix d'exercice</strong>, de l'<strong>échéance</strong> et de la <strong>volatilité anticipée</strong> du sous-jacent</td>\n</tr>\n<tr>\n<td><strong>Swap</strong></td>\n<td><strong>Échange de flux financiers</strong> selon un <strong>échéancier fixé à l'avance</strong></td>\n<td>Exemple : taux fixe contre taux variable</td>\n</tr>\n<tr>\n<td><strong>CFD</strong></td>\n<td><strong>Pari sur la hausse ou la baisse</strong> d'un sous-jacent <strong>sans jamais le détenir</strong></td>\n<td><strong>Hautement spéculatif</strong>, avec effet de levier (thème 6.9)</td>\n</tr>\n</tbody>\n</table></div>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« CALL = j'aCHETE ; PUT = je me déPUTe du titre (je vends). »</strong></p>\n</aside>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>Future = ferme ; option = optionnel pour l'acheteur, qui a payé une prime.</strong></p>\n</aside>\n<div class=\"ids\" data-sub=\"7.7\"></div>\n<hr/>\n<h2 id=\"7-8-les-opc-valorisation-souscription-rachat\">7.8 Les OPC : valorisation, souscription, rachat</h2>\n<h3 id=\"les-familles\">Les familles</h3>\n<ul>\n<li><strong>OPC</strong> = <strong>OPCVM + FIA</strong> (depuis 2014).\n<ul>\n<li>L'<strong>OPCVM</strong> est conforme à la <strong>directive UCITS</strong> et doit être agréé par l'<strong>AMF</strong> pour sa <strong>constitution, sa transformation et sa liquidation</strong>.</li>\n<li>Le <strong>FIA</strong> est un OPC (pas un OPCVM) et relève de la directive <strong>AIFM</strong>. Il <strong>peut prendre plus de risques</strong>, mais il a des règles. Il a <strong>toujours un dépositaire</strong>.</li>\n<li>Exemples de FIA : <strong>SCPI</strong>, <strong>OPCI</strong> (investi principalement en <strong>immobilier</strong>), FCPR, <strong>FCPE</strong>…</li>\n</ul>\n</li>\n<li><strong>SICAV</strong> = <strong>société anonyme</strong> : le porteur est <strong>actionnaire</strong>.</li>\n<li><strong>FCP</strong> = <strong>copropriété</strong> de valeurs mobilières : le porteur est <strong>copropriétaire</strong>.</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« SICAV = Société → ActionnAire ; FCP = Fonds Commun → CoPropriétaire. »</strong></p>\n</aside>\n<ul>\n<li>Un OPC est investi en <strong>instruments financiers</strong>, pas en œuvres d'art ou en matières premières agricoles en direct. Il apporte <strong>diversification des risques et évaluation permanente</strong>.</li>\n<li>Il peut être détenu par des <strong>personnes physiques, des personnes morales et des associations</strong>, et distribué par la <strong>SGP ou des distributeurs</strong> (banques, courtiers, CIF).</li>\n<li>Sa <strong>gestion financière</strong> est assurée par une <strong>SGP</strong>, qui exerce les droits de vote <strong>dans l'intérêt exclusif des porteurs</strong>.</li>\n<li>Les <strong>fonds de capital-investissement</strong> (FCPR, FCPI, FIP) sont <strong>ouverts à tous</strong>. Les fonds professionnels de capital-investissement <strong>n'ont pas besoin d'agrément préalable</strong> de l'AMF.</li>\n<li>Introduire des <strong>gates</strong> (plafonnement des rachats) exige l'<strong>agrément de l'AMF</strong> et une <strong>information des porteurs</strong>, à qui l'on propose de <strong>sortir sans frais</strong>.</li>\n</ul>\n<h3 id=\"la-valeur-liquidative-vl\">La valeur liquidative (VL)</h3>\n<ul>\n<li><strong>VL = actif net de l'OPC / nombre de parts</strong>. C'est le <strong>prix d'une part</strong> ; ce n'est ni le capital initial, ni un cours de bourse qui varie en continu.</li>\n<li>La <strong>VL d'origine est choisie par la SGP</strong>.</li>\n<li><strong>Qui la calcule ?</strong> La <strong>SGP</strong>, ou le <strong>valorisateur</strong> si la tâche est déléguée. La SGP la <strong>valide</strong> et la <strong>publie</strong>, et elle est <strong>communiquée à toute personne qui la demande</strong>.</li>\n<li><strong>Comment ?</strong> Les actifs sont valorisés <strong>à leur valeur de marché</strong>, selon les principes comptables de l'<strong>ANC</strong> (Autorité des normes comptables). Les <strong>frais de gestion sont provisionnés avant le calcul</strong>.</li>\n<li><strong>Fréquence</strong> : elle <strong>varie selon l'OPC</strong> et figure dans le <strong>prospectus et le DIC</strong>. Pour les <strong>OPC à vocation générale</strong>, elle est calculée <strong>au moins deux fois par mois</strong> (hors FCPR, FCPI, FIP et FCPE).</li>\n<li><strong>Les ordres</strong> :\n<ul>\n<li>ils sont exécutés sur une <strong>VL inconnue</strong> (le « cours inconnu ») : le prix de rachat d'un FCP n'est connu <strong>qu'après l'heure limite de centralisation</strong> ;</li>\n<li>ils sont <strong>irrévocables</strong> ;</li>\n<li>les souscriptions et rachats sont possibles <strong>à tout moment</strong>, selon la fréquence de VL.</li>\n</ul>\n</li>\n<li><strong>Les frais sont présentés TTC.</strong></li>\n</ul>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Opération</th>\n<th>Formule</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Souscription</strong></td>\n<td><strong>VL + commission de souscription</strong> (droits d'entrée)</td>\n</tr>\n<tr>\n<td><strong>Rachat</strong></td>\n<td><strong>VL − commission de rachat</strong></td>\n</tr>\n</tbody>\n</table></div>\n<p><strong>Exemple</strong> : un actif net de 10 M€ et 100 000 parts donnent une <strong>VL de 100 €</strong>.</p>\n<ul>\n<li>Avec <strong>2 %</strong> de droits d'entrée, on souscrit à <strong>102 €</strong>.</li>\n<li>Avec <strong>1 %</strong> de commission de rachat, on reçoit <strong>99 €</strong> par part.</li>\n</ul>\n<div class=\"ids\" data-sub=\"7.8\"></div>\n<hr/>\n<h2 id=\"7-9-les-biens-divers-régime-de-la-loi-sapin-2\">7.9 Les biens divers (régime de la loi Sapin 2)</h2>\n<ul>\n<li><strong>Définition</strong> : toute personne qui propose d'<strong>acquérir des droits sur des biens</strong> en <strong>mettant en avant un rendement financier</strong>, direct ou indirect, est un <strong>intermédiaire en biens divers</strong>. Le <strong>critère principal</strong> est le <strong>mode de commercialisation</strong>, pas la nature du bien.</li>\n<li><strong>Exemples</strong> : <strong>vin</strong>, <strong>rentes viagères</strong>, <strong>chevaux de course</strong>, diamants, panneaux solaires, terres rares, forêts… Un BSA ou une assurance-vie n'en sont pas.</li>\n<li><strong>Rendement potentiellement élevé mais risques importants</strong> : les actifs ne sont pas standardisés et il n'existe pas de marché encadré.</li>\n</ul>\n<p><strong>Le régime (Code monétaire et financier, contrôle de l'AMF)</strong></p>\n<ol>\n<li>Les <strong>intermédiaires</strong> sont <strong>enregistrés auprès de l'AMF</strong>.</li>\n<li><strong>Avant toute commercialisation</strong>, ils <strong>déposent à l'AMF</strong> le <strong>projet de document d'information</strong> (sur l'opération, l'initiateur et le gestionnaire), les <strong>contrats-types</strong> et les <strong>communications promotionnelles</strong>. Le <strong>contrôle est a priori pour tous</strong> les biens divers. L'AMF dispose de <strong>2 mois</strong> pour formuler ses observations et peut fixer un <strong>minimum de garanties</strong> pour toutes les opérations.</li>\n<li>Les <strong>informations utiles</strong> sont fournies <strong>avant toute communication promotionnelle ou démarchage</strong>. Les communications sont <strong>exactes, claires et non trompeuses</strong>.</li>\n<li><strong>Le gestionnaire</strong> établit <strong>chaque année</strong> un <strong>inventaire des biens, un bilan et un compte de résultat certifiés par un commissaire aux comptes</strong>. Il les adresse <strong>aux détenteurs et à l'AMF</strong>, l'inventaire <strong>dans les 3 mois</strong>.</li>\n<li>L'intermédiaire agit <strong>dans l'intérêt exclusif des investisseurs</strong>.</li>\n<li>Si l'opération ne respecte plus son document d'information, l'AMF peut <strong>ordonner la fin de tout démarchage</strong>.</li>\n<li><strong>Sanctions pénales</strong> : <strong>emprisonnement et amende</strong> (5 ans et 18 000 € selon la base) pour diffusion sans enregistrement préalable.</li>\n</ol>\n<ul>\n<li>Le CIF qui conseille un bien divers fait d'abord signer une <strong>lettre de mission</strong>.</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« Bien divers = on te vend du RENDEMENT sur une chose → passage obligé par l'AMF AVANT. »</strong></p>\n</aside>\n<div class=\"ids\" data-sub=\"7.9\"></div>\n<hr/>\n<h2 id=\"7-10-les-crypto-actifs\">7.10 Les crypto-actifs</h2>\n<h3 id=\"les-notions-de-base\">Les notions de base</h3>\n<ul>\n<li><strong>Crypto-actif</strong> : un <strong>actif numérique</strong>, stocké et échangé <strong>électroniquement</strong>, reposant sur la <strong>blockchain</strong> (registre décentralisé, sécurisé et transparent). Exemple : le <strong>Bitcoin</strong>, une monnaie virtuelle qui ne s'échange qu'en ligne.</li>\n<li>Il <strong>n'a pas cours légal</strong>, ni en France ni dans l'Union européenne : seul l'<strong>euro</strong> a cours légal en France. Personne n'est obligé de l'accepter, il n'existe ni cours officiel ni parité BCE, et ce <strong>n'est pas un instrument financier</strong>.</li>\n<li>Les transactions <strong>sous pseudonyme ou anonymes</strong> le rendent attractif pour la fraude.</li>\n<li>La <strong>faillite d'une plateforme n'est pas couverte par le FGDR</strong>.</li>\n<li><strong>Confirmé au BTS Banque 2026</strong> : l'examen dit désormais <strong>« crypto-actifs »</strong> et non plus « crypto-monnaies » (question 1649, mise à jour dans la base). Les réponses ne changent pas.</li>\n<li><strong>ICO</strong> (<em>Initial Coin Offering</em>, offre au public de jetons) : une <strong>levée de fonds</strong> pour <strong>financer un projet</strong>, par émission de <strong>jetons</strong> qui <strong>représentent des droits</strong> (d'usage d'un service, par exemple) échangés contre des crypto-monnaies. Les <strong>risques</strong> sont ceux des monnaies virtuelles et du projet financé. Il n'y a <strong>pas de cotation sur Euronext</strong> ni de remboursement garanti.</li>\n</ul>\n<h3 id=\"ce-que-dit-la-base-régime-pacte-de-2019\">Ce que dit la base (régime PACTE de 2019)</h3>\n<ul>\n<li>L'<strong>AMF supervise les PSAN</strong> (prestataires de services sur actifs numériques).\n<ul>\n<li><strong>Enregistrement obligatoire</strong> pour l'achat-vente contre monnaie légale et la <strong>conservation</strong> ; l'AMF vérifie notamment leur <strong>dispositif anti-blanchiment et de gel des avoirs</strong>.</li>\n<li><strong>Agrément optionnel</strong>.</li>\n</ul>\n</li>\n<li>Les PSAN sont soumis à <strong>toutes les obligations anti-blanchiment</strong> :\n<ul>\n<li><strong>identification avant toute transaction occasionnelle</strong> ;</li>\n<li><strong>gel des avoirs</strong> sur tous les actifs ;</li>\n<li><strong>politique de conflits d'intérêts</strong> couvrant aussi les services d'investissement s'ils sont PSI.</li>\n</ul>\n</li>\n<li>Le <strong>visa de l'AMF</strong> pour une ICO est <strong>optionnel</strong>, et seules les ICO <strong>visées</strong> peuvent être <strong>démarchées</strong>. Une offre est « au public » au-delà d'un <strong>seuil fixé par le RG AMF</strong>.</li>\n<li>L'<strong>AMF publie des listes noires</strong> de sites non autorisés.</li>\n<li>La <strong>monnaie électronique anonyme ne peut jamais</strong> servir à acheter des actifs numériques (<a class=\"qref\" href=\"#\" data-q=\"2578\">Q2578</a>, réponse absente de la base).</li>\n</ul>\n<h3 id=\"ce-qui-a-changé-le-règlement-européen-mica\"><span class=\"tag t-new\">nouveau</span> Ce qui a changé : le règlement européen MiCA</h3>\n<ul>\n<li><strong>MiCA</strong> (<em>Markets in Crypto-Assets</em>) s'applique depuis le <strong>30 juin 2024</strong> pour les <strong>stablecoins</strong> et depuis le <strong>30 décembre 2024</strong> pour le reste.</li>\n<li><strong>Les PSAN deviennent des PSCA</strong> (prestataires de services sur crypto-actifs, <em>CASP</em>). Ils doivent obtenir un <strong>agrément</strong>, délivré en France par l'<strong>AMF</strong>, avec <strong>passeport européen</strong>. La période transitoire française pour les PSAN existants a pris fin <strong>au plus tard le 1er juillet 2026</strong>.</li>\n<li>Le <strong>visa optionnel des ICO disparaît</strong> : toute offre au public de crypto-actifs exige un <strong>livre blanc</strong> (<em>white paper</em>), <strong>notifié</strong> à l'autorité, avec des règles de communication.</li>\n<li>La <strong>« travel rule »</strong> (identification de l'émetteur et du bénéficiaire de chaque transfert) s'applique depuis le <strong>30 décembre 2024</strong>.</li>\n<li>Les <strong>règles de compétence des équipes</strong> des PSCA ont été renforcées (orientations de l'ESMA appliquées par l'AMF en 2026), et le <strong>DAC8</strong> organise l'échange fiscal d'informations depuis 2026.</li>\n</ul>\n<aside class=\"callout c-warn\"><span class=\"callout-label\">Piège</span>\n<p><strong>Stratégie à l'examen</strong> : si la question reprend mot pour mot une question PSAN ou ICO de la base, donne la réponse de la base (visa <strong>optionnel</strong>, PSAN <strong>enregistré</strong> à l'AMF). Si elle parle de <strong>MiCA</strong>, de <strong>PSCA</strong> ou de <strong>livre blanc</strong>, raisonne avec le nouveau régime (<strong>agrément obligatoire</strong>, <strong>livre blanc notifié</strong>).</p>\n</aside>\n<div class=\"ids\" data-sub=\"7.10\"></div>\n<hr/>\n<h2 class=\"flash\" id=\"fiche-flash-du-thème-7\"> Fiche flash du thème 7</h2>\n<ol>\n<li><strong>Rendement lié au risque</strong> ; volatilité = <strong>écart-type</strong>, maximale sur les <strong>actions</strong>.</li>\n<li>Obligation <strong>gardée jusqu'à l'échéance → risque de crédit (défaut)</strong> ; <strong>vendue avant → risque de marché</strong> (+ liquidité) ; en devise étrangère → <strong>+ change</strong>.</li>\n<li><strong>Opérationnel</strong> = processus, personnes, systèmes, événements extérieurs (<strong>panne informatique</strong>). <strong>Contrepartie</strong> = défaut au <strong>règlement-livraison</strong>.</li>\n<li>Titres financiers (actions, obligations, TCN, OPC) ⊂ instruments financiers ⊃ contrats financiers (<strong>dérivés, CFD</strong>).</li>\n<li>Action = <strong>titre de capital</strong> ; responsabilité <strong>limitée à l'apport</strong> ; dividende <strong>variable</strong> ; cours <strong>en baisse du montant du dividende</strong> au détachement.</li>\n<li><strong>Capitalisation = nombre d'actions × cours</strong> ; <strong>PER = cours / BNPA</strong> (faible = bon marché) ; <strong>rendement = dividende / cours</strong> ; <strong>β &gt; 1</strong> amplifie.</li>\n<li>Actions de préférence : droits particuliers, <strong>sans vote : ≤ 1/2 du capital (≤ 1/4 si cotée)</strong>.</li>\n<li>Obligation = <strong>titre de créance</strong> ; cotée <strong>en % du nominal</strong> ; <strong>prix payé = cours + coupon couru</strong> ; <strong>taux en hausse → prix en baisse</strong> (sensibilité = variation en % pour 1 % de taux).</li>\n<li><strong>Zéro coupon</strong> : tout est payé à l'échéance, rendement connu ; <strong>taux variable</strong> : pas de risque de taux sur le prix ; <strong>OATi</strong> = inflation (IPC hors tabac) ; <strong>OAT</strong> = État, <strong>adjudication</strong>, <strong>Agence France Trésor</strong>.</li>\n<li><strong>TCN</strong> : marché <strong>monétaire</strong>, <strong>150 000 € minimum</strong>, surveillés par la <strong>Banque de France</strong> ; <strong>NEU CP ≤ 1 an</strong>, <strong>NEU MTN &gt; 1 an</strong>, <strong>BTF ≤ 1 an</strong>.</li>\n<li><strong>Euribor</strong> : 1 semaine à 12 mois, chaque jour ouvré, <strong>base 360</strong>, <strong>EMMI</strong> ; <strong>€STR</strong> : jour le jour, <strong>BCE</strong>, transactions réelles (a remplacé l'EONIA).</li>\n<li><strong>Convertible</strong> : conversion au choix du porteur, <strong>coupon plus faible</strong> ; <strong>BSA</strong> : souscrire plus tard à un prix fixé ; <strong>subordonné</strong> : remboursé <strong>après</strong> les autres, quasi fonds propres.</li>\n<li>Livret A : taux fixé par le <strong>ministre</strong> ; CAT : <strong>1 mois minimum</strong>, taux libre ; assurance-vie : <strong>euros = capital garanti</strong>, <strong>UC = risque</strong>, gains <strong>toujours soumis aux prélèvements sociaux</strong>, contrats non réclamés → <strong>CDC après 10 ans</strong>.</li>\n<li><strong>Future = ferme</strong> (chambre de compensation, appels de marge) ; <strong>option = droit</strong> (call = acheter, put = vendre ; prime ; valeur selon prix d'exercice, échéance, <strong>volatilité</strong>) ; <strong>swap = échange de flux</strong>.</li>\n<li><strong>OPC = OPCVM + FIA</strong> ; <strong>SICAV = actionnaire</strong>, <strong>FCP = copropriétaire</strong> ; <strong>VL = actif net / parts</strong>, à <strong>cours inconnu</strong>, <strong>au moins 2 fois par mois</strong> (vocation générale) ; souscription = <strong>VL + droits d'entrée</strong>, rachat = <strong>VL − commission de rachat</strong>.</li>\n<li><strong>Biens divers</strong> : rendement mis en avant → <strong>dépôt préalable à l'AMF</strong> (2 mois), comptes annuels <strong>certifiés</strong>, sanctions <strong>pénales</strong>.</li>\n<li><strong>Crypto</strong> : pas de cours légal, pas de FGDR ; base = <strong>visa ICO optionnel / PSAN</strong> ; aujourd'hui = <strong>MiCA : PSCA agréés, livre blanc</strong>.</li>\n</ol>\n","toc":[{"id":"7-1-le-couple-risquerendement-et-les-familles-de-risques","t":"7.1 Le couple risque/rendement et les familles de risques"},{"id":"7-2-les-actions","t":"7.2 Les actions"},{"id":"7-3-les-obligations","t":"7.3 Les obligations"},{"id":"7-4-le-marché-monétaire-les-tcn-et-les-indices-de-référence","t":"7.4 Le marché monétaire, les TCN et les indices de référence"},{"id":"7-5-les-titres-hybrides-ou-composés","t":"7.5 Les titres hybrides ou composés"},{"id":"7-6-les-autres-placements-épargne-réglementée-comptes-à-term","t":"7.6 Les autres placements : épargne réglementée, comptes à terme, assurance-vie, parts sociales, titrisation"},{"id":"7-7-les-produits-dérivés","t":"7.7 Les produits dérivés"},{"id":"7-8-les-opc-valorisation-souscription-rachat","t":"7.8 Les OPC : valorisation, souscription, rachat"},{"id":"7-9-les-biens-divers-régime-de-la-loi-sapin-2","t":"7.9 Les biens divers (régime de la loi Sapin 2)"},{"id":"7-10-les-crypto-actifs","t":"7.10 Les crypto-actifs"},{"id":"fiche-flash-du-thème-7","t":"Fiche flash du thème 7"}]},{"id":"08","n":8,"title":"Gestion collective, gestion pour compte de tiers et finance durable","html":"\n<blockquote class=\"note\">\n<p><strong>Poids à l'examen : 25 questions sur 120, toutes en catégorie C, dont 15 sur la seule finance durable (§8.7).</strong>\nRépartition : §8.1 (1) · §8.2.1 (1) · §8.2.2 (2) · §8.4 (2) · §8.5 (3) · §8.6 (1) · <strong>§8.7 (15)</strong>.</p>\n<p> <strong>Le §8.7 vaut à lui seul 12,5 % de l'examen.</strong> Ses questions sont très répétitives (labels, stratégies ISR, ESG). Si tu maîtrises les tableaux de la partie 8.7, tu sécurises une quinzaine de points.\nL'AMF propose aussi un <strong>examen « Finance durable » distinct</strong> (60 questions). Cette leçon prépare à la partie finance durable de l'examen général et en donne la base.</p>\n</blockquote>\n<hr/>\n<h2 id=\"8-1-les-acteurs-de-la-gestion-dactifs\">8.1 Les acteurs de la gestion d'actifs</h2>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Acteur</th>\n<th>Rôle</th>\n<th>Moyen de retenir</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>SGP</strong> (société de gestion de portefeuille)</td>\n<td><strong>Gère</strong> les OPC et les mandats. <strong>Agréée par l'AMF</strong> et <strong>membre d'une association professionnelle</strong> (AFG). Elle est soumise à une <strong>obligation de moyens</strong> et a un <strong>devoir d'information et de conseil</strong>. Elle a un <strong>responsable de la conformité</strong> (RCCI). Son <strong>middle-office suit les positions</strong> des portefeuilles.</td>\n<td><span class=\"tag t-mnemo\">mnémo</span> Le <strong>cerveau</strong></td>\n</tr>\n<tr>\n<td><strong>Dépositaire</strong></td>\n<td><strong>Conserve tous les actifs</strong> (titres et espèces), <strong>contrôle la régularité des décisions</strong> de la SGP et le <strong>respect des règles d'investissement</strong>, <strong>suit les flux de liquidités</strong> (depuis UCITS V).</td>\n<td><span class=\"tag t-mnemo\">mnémo</span> Le <strong>coffre-fort + le gendarme</strong></td>\n</tr>\n<tr>\n<td><strong>Valorisateur</strong></td>\n<td><strong>Calcule la valeur liquidative</strong>, si la SGP lui délègue cette tâche</td>\n<td><span class=\"tag t-mnemo\">mnémo</span> La <strong>calculatrice</strong></td>\n</tr>\n<tr>\n<td><strong>Commissaire aux comptes</strong></td>\n<td><strong>Certifie l'exactitude et la régularité des comptes</strong> de l'OPC. Il est choisi sur la liste de la Compagnie nationale des commissaires aux comptes, pas sur une liste de l'AMF.</td>\n<td><span class=\"tag t-mnemo\">mnémo</span> Le <strong>certificateur</strong></td>\n</tr>\n<tr>\n<td><strong>Prime broker</strong></td>\n<td>Offre aux <strong>hedge funds</strong> (FIA) des services d'<strong>intermédiation et de financement d'opérations avec effet de levier</strong>. Son intervention passe par un <strong>contrat écrit</strong> dont le <strong>dépositaire est informé</strong>.</td>\n<td><span class=\"tag t-mnemo\">mnémo</span> Le <strong>banquier des hedge funds</strong></td>\n</tr>\n<tr>\n<td><strong>Expert externe en évaluation</strong></td>\n<td><strong>Évalue les immeubles d'un OPCI</strong></td>\n<td><span class=\"tag t-mnemo\">mnémo</span> L'<strong>expert immobilier</strong></td>\n</tr>\n<tr>\n<td><strong>Distributeur</strong></td>\n<td>Commercialise les parts : réseaux bancaires, courtiers, CIF, ou la SGP elle-même</td>\n<td></td>\n</tr>\n</tbody>\n</table></div>\n<p><strong>Les règles à retenir sur le dépositaire</strong></p>\n<ul>\n<li>Peuvent être dépositaires : les <strong>établissements de crédit</strong>, les entreprises d'investissement, la <strong>Caisse des dépôts</strong>… mais <strong>jamais la SGP ni la SICAV</strong>.</li>\n<li><strong>Déléguer la garde</strong> des actifs à un tiers <strong>ne l'exonère pas</strong> de sa responsabilité.</li>\n<li>Les actifs conservés <strong>ne peuvent être réutilisés que pour le compte du fonds</strong>, et seulement sous conditions.</li>\n<li><strong>Indépendance</strong> : personne ne peut siéger à la fois dans l'organe de direction de la SGP et dans celui du dépositaire. Le dirigeant d'une SICAV ne peut pas diriger le dépositaire.</li>\n</ul>\n<div class=\"ids\" data-sub=\"8.1\"></div>\n<hr/>\n<h2 id=\"8-2-1-les-fondamentaux-mandat-de-gestion-opcvm-fia-ratios-so\">8.2.1 Les fondamentaux : mandat de gestion, OPCVM, FIA, ratios, souscriptions et rachats</h2>\n<h3 id=\"la-gestion-sous-mandat-gestion-individualisée-discrétionnair\">La gestion sous mandat (gestion individualisée, discrétionnaire)</h3>\n<ul>\n<li>Le <strong>mandat de gestion</strong> est une <strong>convention</strong> par laquelle le client <strong>donne pouvoir</strong> (procuration) à un gérant de gérer <strong>son</strong> portefeuille, selon ses <strong>objectifs, son expérience et sa situation</strong>. La gestion est <strong>individualisée et discrétionnaire</strong> : un portefeuille dédié à un client unique.</li>\n<li><strong>Contenu minimum</strong> :\n<ul>\n<li>les <strong>objectifs de gestion</strong> (mention <strong>obligatoire</strong>) ;</li>\n<li>les <strong>catégories d'instruments</strong> autorisées ;</li>\n<li>la <strong>répartition recherchée par classe d'actifs</strong>, avec ses <strong>planchers et plafonds</strong> ;</li>\n<li>les <strong>modalités d'information</strong> du mandant ;</li>\n<li>les <strong>méthodes de valorisation</strong> ;</li>\n<li>les <strong>modalités de résiliation</strong>.</li>\n<li>Il ne mentionne <strong>jamais de rendement promis</strong>.</li>\n</ul>\n</li>\n<li><strong>Obligations du gérant</strong> : <strong>loyauté</strong> et <strong>moyens</strong>, <strong>jamais de résultat</strong>. Il agit <strong>dans l'intérêt exclusif</strong> de ses mandants.</li>\n<li>Le mandat peut être <strong>résilié à tout moment par le mandant ou par le mandataire</strong>.</li>\n<li>Le gérant <strong>informe le client si la valeur totale du portefeuille baisse de 10 %</strong> depuis le dernier relevé (puis à chaque multiple de 10 %).</li>\n<li><strong>Commission de mouvement</strong> : ce sont les <strong>frais liés aux opérations d'achat ou de vente</strong> sur le portefeuille d'un OPC ou d'un mandat de gestion (frais de transaction). Ce ne sont ni des frais d'entrée, ni un forfait annuel de gestion (question EF26-79, BTS Banque 2026). Elle peut être partagée entre la SGP et le dépositaire (§6.5).</li>\n</ul>\n<h3 id=\"la-gestion-collective-opc\">La gestion collective (OPC)</h3>\n<ul>\n<li>Une <strong>souscription d'OPC vaut adhésion au contrat de gestion</strong> : il n'y a pas de mandat à signer.</li>\n<li>Les parts sont <strong>émises et rachetées à la demande des porteurs</strong>, <strong>à la valeur liquidative</strong>.</li>\n<li><strong>Obligation d'honorer les rachats</strong>. Elle peut être <strong>suspendue provisoirement</strong>, dans des <strong>circonstances exceptionnelles</strong> et <strong>si l'intérêt des porteurs le commande</strong>, selon les conditions des statuts. Sauf dans ce cas, le porteur est certain de récupérer ses fonds, car l'OPCVM garde des liquidités pour cela.</li>\n<li><strong>Ratios de répartition des risques</strong> :\n<ul>\n<li>ils sont respectés <strong>en permanence</strong>, pas seulement aux dates d'arrêté des comptes ;</li>\n<li><strong>règle de base</strong> : <strong>5 % maximum de l'actif par émetteur</strong>, porté à 10 % sous conditions (règle « 5/10/40 ») ;</li>\n<li>le <strong>ratio d'emprise</strong> empêche un OPCVM d'exercer une <strong>influence notable sur la gestion d'un émetteur</strong>.</li>\n</ul>\n</li>\n<li><strong>SICAV</strong> : constituée en <strong>SA ou en SAS</strong>.</li>\n<li><strong>FCP</strong> : <strong>sans personnalité juridique</strong>, dépendant de sa SGP. D'après la base, il n'a pas à publier de comptes.</li>\n<li>Le cadre est <strong>européen et français, strict</strong>, et la gestion est <strong>professionnelle et diversifiée</strong> (ce n'est pas une gestion individualisée).</li>\n<li><strong>Risque de contrepartie</strong> pour une SGP : la défaillance de la contrepartie à une opération ou à un contrat.</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« Mandat = MON portefeuille, mes règles ; OPC = NOTRE portefeuille, ses règles (ratios permanents). »</strong></p>\n</aside>\n<div class=\"ids\" data-sub=\"8.2.1\"></div>\n<hr/>\n<h2 id=\"8-2-2-mesurer-la-performance-et-le-risque\">8.2.2 Mesurer la performance et le risque</h2>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Notion</th>\n<th>Définition</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Performance absolue</strong></td>\n<td>Mesurée <strong>sans référence</strong> à un indice ou à un autre fonds</td>\n</tr>\n<tr>\n<td><strong>Performance relative</strong></td>\n<td><strong>Écart avec un indice de référence</strong> ou une autre référence</td>\n</tr>\n<tr>\n<td><strong>Performance annuelle</strong> (fonds de capitalisation)</td>\n<td><strong>Variation de la VL sur un an</strong>, en % de la VL de départ</td>\n</tr>\n<tr>\n<td><strong>Volatilité</strong></td>\n<td><strong>Amplitude des variations</strong> de la valeur. Plus elle est élevée, plus l'actif est <strong>risqué</strong>. Elle <strong>ne mesure pas tous les risques</strong> (pas la liquidité, par exemple).</td>\n</tr>\n<tr>\n<td><strong>Ratio de Sharpe</strong></td>\n<td><strong>Rentabilité excédentaire</strong> (au-delà du taux sans risque) <strong>par unité de risque</strong> (volatilité). Il sert à <strong>évaluer la performance d'un gérant</strong>.</td>\n</tr>\n<tr>\n<td><strong>Ratio d'information</strong></td>\n<td>Qualité de la surperformance face à l'indice, rapportée à la volatilité de l'écart. Il sert à juger une <strong>gestion benchmarkée</strong>.</td>\n</tr>\n<tr>\n<td><strong>Alpha</strong></td>\n<td>Indicateur de <strong>performance</strong> (la valeur ajoutée du gérant)</td>\n</tr>\n<tr>\n<td><strong>Actif sans risque</strong></td>\n<td>Revenus <strong>certains</strong>, <strong>écart-type nul</strong></td>\n</tr>\n<tr>\n<td><strong>Horizon de placement</strong></td>\n<td>La <strong>durée de détention envisagée</strong>. <strong>Moyen terme = 3 à 8 ans</strong>. <strong>Plus le risque est élevé, plus l'horizon recommandé est long.</strong></td>\n</tr>\n<tr>\n<td><strong>Attribution de performance</strong></td>\n<td>Expliquer la performance par les marchés, le <strong>solde étant attribué au talent du gérant</strong></td>\n</tr>\n<tr>\n<td><strong>Indice de référence (benchmark)</strong></td>\n<td>L'objectif à atteindre et l'étalon de comparaison. Une <strong>gestion benchmarkée</strong> (dite <strong>indicielle</strong> dans le sujet du BTS Banque 2026, question 1964) s'analyse <strong>par rapport à l'indice indiqué dans son DIC</strong>.</td>\n</tr>\n</tbody>\n</table></div>\n<p><strong>Exemple</strong> : un rendement de 7 %, un taux sans risque de 2 % et une volatilité de 10 % donnent un <strong>Sharpe de (7 − 2) / 10 = 0,5</strong>.</p>\n<ul>\n<li>Le <strong>CAC 40</strong> est <strong>pondéré par les capitalisations</strong> (flottantes).</li>\n<li>La <strong>performance d'une seule année ne suffit pas</strong> pour choisir un fonds.</li>\n<li>La SGP doit pouvoir <strong>mesurer à tout moment</strong> le risque global, le risque de chaque position et ses engagements.</li>\n</ul>\n<h3 id=\"le-règlement-benchmark-ue-20161011\">Le règlement « Benchmark » (UE 2016/1011)</h3>\n<ul>\n<li><strong>Objet</strong> : <strong>encadrer la fourniture et l'utilisation des indices de référence</strong> dans l'UE, afin d'<strong>éviter leur manipulation</strong>. Il n'impose pas de méthode de calcul et n'interdit aucun indice.</li>\n<li><strong>Définition</strong> : un indice utilisé pour <strong>déterminer un montant à verser</strong> au titre d'un instrument ou d'un contrat financier, ou <strong>le prix</strong> d'un instrument.</li>\n<li>Il distingue les indices <strong>d'importance critique</strong> et <strong>d'importance significative</strong> (et non significative).</li>\n<li>La méthodologie est <strong>transparente</strong>. L'administrateur <strong>peut externaliser</strong> des fonctions <strong>sans compromettre son contrôle</strong> ni la surveillance de l'autorité.</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« Absolue = seule ; relative = comparée. Sharpe = ce que le gérant gagne en plus, par unité de risque. »</strong></p>\n</aside>\n<div class=\"ids\" data-sub=\"8.2.2\"></div>\n<hr/>\n<h2 id=\"8-4-le-cadre-réglementaire-gestion-sous-mandat-directives-ai\">8.4 Le cadre réglementaire : gestion sous mandat, directives AIFM, UCITS et règlement MMF</h2>\n<h3 id=\"la-gestion-sous-mandat\">La gestion sous mandat</h3>\n<ul>\n<li>Le PSI <strong>gère les risques de chaque portefeuille individuel</strong> et dispose d'une <strong>procédure de liquidité</strong> qui lui permet de <strong>liquider les positions</strong> dans le respect du mandat.</li>\n<li>Le <strong>gestionnaire</strong> et le <strong>teneur de compte</strong> <strong>catégorisent chacun le client séparément</strong>.</li>\n</ul>\n<h3 id=\"les-textes\">Les textes</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Texte</th>\n<th>Ce qu'il faut retenir</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>UCITS IV</strong> (2009)</td>\n<td>A <strong>créé le DICI</strong> en remplacement du <strong>prospectus simplifié</strong>. Un OPCVM est agréé par l'<strong>autorité de son pays de constitution</strong>.</td>\n</tr>\n<tr>\n<td><strong>UCITS V</strong> (2014/91/UE)</td>\n<td><strong>Protection des actifs</strong> (responsabilité du dépositaire), <strong>suivi des liquidités par le dépositaire</strong>, transparence, <strong>politiques de rémunération compatibles avec une gestion saine des risques</strong></td>\n</tr>\n<tr>\n<td><strong>AIFM</strong> (2011/61/UE)</td>\n<td>Régule les <strong>gestionnaires de FIA</strong> (les SGP, des <strong>personnes morales</strong>) et les <strong>principales sources de risque</strong> de la gestion alternative. Il impose un <strong>dépositaire distinct</strong>. Il ouvre un <strong>passeport</strong> pour commercialiser les FIA <strong>auprès des clients professionnels de l'EEE</strong>. Il exige des <strong>simulations de crise de liquidité au moins une fois par an</strong> et l'identification de <strong>tous</strong> les conflits d'intérêts. Il s'applique <strong>intégralement au-delà de 500 M€</strong> d'actifs gérés (selon la base).</td>\n</tr>\n<tr>\n<td><strong>MMF</strong> (règlement 2017/1131, fonds monétaires)</td>\n<td><strong>Règles uniformes d'agrément et de fonctionnement</strong> des fonds monétaires. L'<strong>appellation « fonds monétaire » est réservée aux fonds agréés comme tels</strong>, y compris les <strong>fonds déjà existants</strong>. Il impose un <strong>examen annuel</strong> des méthodes d'évaluation de la qualité de crédit.</td>\n</tr>\n<tr>\n<td><strong>Pré-commercialisation</strong></td>\n<td><strong>Tester l'appétence des investisseurs</strong> pour un fonds avant de le lancer</td>\n</tr>\n</tbody>\n</table></div>\n<ul>\n<li>En France, les OPC sont <strong>agréés par l'AMF</strong>. La gestion collective est encadrée par le <strong>RG AMF</strong> et le CMF.</li>\n<li>La <strong>principale règle européenne</strong> pour les OPC est la <strong>répartition des risques</strong>.</li>\n<li>Un fonds qui n'est ni un OPCVM ni un FIA relève des <strong>« autres placements collectifs »</strong>.</li>\n<li>La <strong>direction effective</strong> d'une SGP est assurée par <strong>au moins deux personnes</strong> honorables et expérimentées.</li>\n<li><strong>MIF 2</strong> impose aux SGP de <strong>vérifier les connaissances et les compétences</strong> de leurs collaborateurs.</li>\n</ul>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p><strong>AIFM 2</strong> (directive 2024/927, à transposer avant avril 2026) : règles sur les <strong>fonds qui octroient des prêts</strong>, <strong>outils de gestion de la liquidité</strong> obligatoires (au moins deux pour les fonds ouverts, également pour les OPCVM) et encadrement renforcé de la délégation.</p>\n</aside>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p><strong>ELTIF 2.0</strong> (janvier 2024) : accès des particuliers facilité.</p>\n</aside>\n<div class=\"ids\" data-sub=\"8.4\"></div>\n<hr/>\n<h2 id=\"8-5-les-instruments-de-la-gestion-collective-la-typologie-de\">8.5 Les instruments de la gestion collective : la typologie des OPC</h2>\n<h3 id=\"les-deux-familles\">Les deux familles</h3>\n<p><strong>OPC = OPCVM + FIA.</strong> La distinction repose surtout sur les <strong>ratios d'investissement réglementaires</strong>.</p>\n<ul>\n<li><strong>OPCVM</strong> (directive UCITS) : investis <strong>essentiellement en valeurs mobilières et instruments du marché monétaire</strong>. Un OPCVM <strong>ne peut pas être transformé</strong> en un autre placement collectif.</li>\n<li><strong>FIA</strong> (directive AIFM) : ce <strong>ne sont pas des OPCVM</strong>. Ils <strong>peuvent</strong> être des OPC (comme les OPCI ou les fonds professionnels). Les <strong>fonds professionnels spécialisés</strong> ne sont pas forcément des OPC.</li>\n</ul>\n<h3 id=\"les-fonds-à-connaître\">Les fonds à connaître</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Fonds</th>\n<th>Règle à retenir</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Fonds monétaire</strong></td>\n<td><strong>Placement de court terme sécurisé</strong>, adapté au profil « <strong>sécurité</strong> ». Les fonds à <strong>valeur liquidative constante de dette publique</strong> sont des fonds monétaires.</td>\n</tr>\n<tr>\n<td><strong>Fonds « obligations »</strong></td>\n<td><strong>Sensible aux taux d'intérêt</strong></td>\n</tr>\n<tr>\n<td><strong>Fonds « actions »</strong></td>\n<td>Peut être exposé à des marchés étrangers (la Deutsche Börse, par exemple)</td>\n</tr>\n<tr>\n<td><strong>OPC à formule</strong></td>\n<td>Il offre une <strong>garantie ou protection du capital</strong> à une échéance donnée, selon une formule (instrument <strong>complexe</strong>)</td>\n</tr>\n<tr>\n<td><strong>Fonds de fonds</strong></td>\n<td>Investi <strong>en parts d'autres OPCVM</strong></td>\n</tr>\n<tr>\n<td><strong>Maître / nourricier</strong></td>\n<td>Le <strong>nourricier</strong> est investi <strong>en totalité et en permanence</strong> (au moins <strong>85 %</strong>) dans <strong>un seul OPCVM maître</strong>, avec des liquidités à titre accessoire. Le <strong>maître</strong> compte au moins un nourricier parmi ses porteurs.</td>\n</tr>\n<tr>\n<td><strong>ETF / tracker</strong> (indiciel coté)</td>\n<td><strong>Réplique à la hausse comme à la baisse un indice</strong>, il est <strong>coté en continu en bourse</strong> et peut distribuer des dividendes. <span class=\"tag t-warn\">piège</span> La base juge <strong>faux</strong> de dire que c'est « un instrument hybride fonds + action ».</td>\n</tr>\n<tr>\n<td><strong>FCPR</strong></td>\n<td><strong>Au moins 50 % en titres non cotés</strong>, <strong>ouvert à tous</strong></td>\n</tr>\n<tr>\n<td><strong>FCPI</strong> (innovation)</td>\n<td>FIA ouvert aux particuliers ; <strong>plus de 70 % en titres non cotés innovants</strong> ; fonds <strong>bloqués 7 à 10 ans</strong> (5 ans pour la réduction d'impôt)</td>\n</tr>\n<tr>\n<td><strong>FIP</strong> (proximité)</td>\n<td><strong>Au moins 70 % en PME</strong> d'une <strong>zone géographique</strong> définie</td>\n</tr>\n<tr>\n<td><strong>OPCI</strong> (FIA)</td>\n<td>Deux formes : <strong>FPI</strong> et <strong>SPPICAV</strong>. <strong>Au moins 60 % en immobilier</strong>.</td>\n</tr>\n<tr>\n<td><strong>SCPI</strong> (FIA)</td>\n<td>Objet <strong>exclusif</strong> : acquérir et gérer un <strong>patrimoine immobilier locatif</strong>. Offre au public après une <strong>note d'information visée par l'AMF</strong> et un bulletin de souscription.</td>\n</tr>\n<tr>\n<td><strong>ELTIF / FEILT</strong></td>\n<td><strong>Fonds fermé</strong>. Au moins <strong>70 %</strong> en actifs éligibles (<strong>non cotés</strong> ou capitalisation inférieure à 500 M€). Durée <strong>cohérente avec le cycle de vie des actifs</strong>. Les particuliers peuvent <strong>annuler</strong> leur souscription pendant <strong>2 semaines</strong> sans pénalité. <strong>Un OPCVM ne peut pas devenir un ELTIF.</strong> Il est agréé par l'<strong>AMF</strong> pour un fonds français.</td>\n</tr>\n<tr>\n<td><strong>Fonds professionnel à vocation générale</strong> (FIA, ex-ARIA)</td>\n<td><strong>Agrément de l'AMF</strong>. Ses statuts fixent le <strong>seuil de plafonnement des rachats</strong> (<em>gates</em>).</td>\n</tr>\n<tr>\n<td><strong>Fonds professionnel spécialisé</strong></td>\n<td>Simple <strong>déclaration</strong> à l'AMF</td>\n</tr>\n<tr>\n<td><strong>Fonds d'épargne salariale</strong></td>\n<td>Ouverts à <strong>tous les salariés</strong>. <strong>FCPE ou SICAVAS</strong> dans le <strong>PEE</strong> (avec participation et intéressement). Régulés par l'<strong>AMF</strong>. Les sommes d'un <strong>PERCO</strong> sont disponibles <strong>à la retraite</strong>.</td>\n</tr>\n<tr>\n<td><strong>Organisme de titrisation</strong></td>\n<td><strong>Exposé aux risques de créances acquises</strong>, <strong>non soumis aux ratios</strong> des OPC, comptes établis <strong>sous le contrôle du dépositaire</strong> ; peut faire une <strong>offre au public</strong> selon la base</td>\n</tr>\n<tr>\n<td><strong>Groupement forestier</strong></td>\n<td><strong>Société civile</strong> à parts sociales gérant des <strong>forêts</strong></td>\n</tr>\n<tr>\n<td><strong>Société d'épargne forestière (SEF)</strong></td>\n<td>Réduction d'impôt contre un <strong>engagement de 8 ans</strong>, <strong>liquidité réduite</strong></td>\n</tr>\n</tbody>\n</table></div>\n<ul>\n<li><strong>Catégories de parts</strong> : des <strong>valeurs liquidatives différentes</strong> selon les catégories d'investisseurs, prévues par le prospectus.</li>\n<li><strong>Capitalisation</strong> : les revenus sont <strong>réinvestis</strong>. <strong>Distribution</strong> : les revenus sont <strong>reversés</strong> aux porteurs.</li>\n<li><strong>Commercialisation transfrontière</strong> :\n<ul>\n<li>pour un <strong>OPCVM étranger</strong> en France, l'<strong>autorité du pays d'origine notifie l'AMF</strong> ;</li>\n<li>pour un <strong>FIA de l'UE</strong> commercialisé en France par une SGP française, on fait une <strong>notification préalable à l'AMF</strong>.</li>\n</ul>\n</li>\n<li><strong>Label « Relance »</strong> (2020) : il identifie les OPC qui investissent dans les <strong>fonds propres d'entreprises françaises</strong>, <strong>cotées ou non</strong>, <strong>surtout des PME et des ETI</strong>. Il s'adresse aux épargnants prêts à un <strong>placement non garanti de moyen ou long terme</strong>. Reporting <strong>semestriel</strong>, suivi par la <strong>DG Trésor</strong>.</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« FCPR 50, FCPI 70, FIP 70, OPCI 60, nourricier 85. »</strong></p>\n</aside>\n<div class=\"ids\" data-sub=\"8.5\"></div>\n<hr/>\n<h2 id=\"8-6-les-types-de-gestion\">8.6 Les types de gestion</h2>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Gestion</th>\n<th>Objectif</th>\n<th>Moyen de retenir</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Active</strong></td>\n<td><strong>Choisir chaque titre</strong> pour <strong>battre le marché</strong> ou l'indice</td>\n<td><span class=\"tag t-mnemo\">mnémo</span> « je <strong>bats</strong> l'indice »</td>\n</tr>\n<tr>\n<td><strong>Passive / indicielle</strong></td>\n<td><strong>Reproduire</strong> un indice (le CAC 40, l'Euribor 3 mois…), en détenant les titres dans les <strong>mêmes proportions</strong></td>\n<td><span class=\"tag t-mnemo\">mnémo</span> « je <strong>copie</strong> l'indice »</td>\n</tr>\n<tr>\n<td><strong>Alternative</strong> (hedge funds)</td>\n<td><strong>Performance absolue</strong>, <strong>positive quel que soit le marché</strong>, <strong>décorrélée</strong>, par des stratégies variées <strong>avec ou sans dérivés ni levier</strong>. Elle s'adresse à des investisseurs <strong>connaisseurs</strong>.</td>\n<td><span class=\"tag t-mnemo\">mnémo</span> « je gagne <strong>dans tous les cas</strong> »</td>\n</tr>\n<tr>\n<td><strong>Thématique</strong></td>\n<td>Un <strong>thème ou secteur</strong> (énergies alternatives, par exemple)</td>\n<td></td>\n</tr>\n<tr>\n<td><strong>Diversifiée</strong></td>\n<td><strong>Mélange</strong> actions, obligations, autres</td>\n<td></td>\n</tr>\n<tr>\n<td><strong>Multigestion</strong></td>\n<td>Investir dans <strong>plusieurs fonds de plusieurs SGP</strong></td>\n<td></td>\n</tr>\n<tr>\n<td><strong>Capital-investissement</strong></td>\n<td>Prendre des participations <strong>dans des sociétés non cotées</strong></td>\n<td></td>\n</tr>\n<tr>\n<td><strong>Style « value »</strong></td>\n<td>Valeurs <strong>sous-évaluées</strong> au regard de leurs fondamentaux</td>\n<td><span class=\"tag t-mnemo\">mnémo</span> value = <strong>bonne affaire</strong></td>\n</tr>\n<tr>\n<td><strong>Style « growth »</strong></td>\n<td>Valeurs <strong>de croissance</strong></td>\n<td><span class=\"tag t-mnemo\">mnémo</span> growth = <strong>croissance</strong></td>\n</tr>\n</tbody>\n</table></div>\n<ul>\n<li>Le profil « <strong>sécurité</strong> » correspond à un <strong>fonds monétaire</strong>.</li>\n</ul>\n<div class=\"ids\" data-sub=\"8.6\"></div>\n<hr/>\n<h2 id=\"8-7-finance-durable-isr-esg-finance-verte-et-solidaire-rse-n\">8.7 Finance durable : ISR, ESG, finance verte et solidaire, RSE, notation extra-financière (15 questions)</h2>\n<h3 id=\"le-vocabulaire-de-base\">Le vocabulaire de base</h3>\n<ul>\n<li><strong>ESG</strong> = critères <strong>Environnementaux, Sociaux et de Gouvernance</strong> : <strong>3 piliers</strong> de critères <strong>extra-financiers</strong>. Ils évaluent la <strong>prise en compte du développement durable et des enjeux de long terme</strong>, pas la rentabilité.</li>\n<li><strong>ISR</strong> (investissement socialement responsable) : une <strong>forme d'investissement durable</strong> qui <strong>ajoute</strong> (sans les remplacer) des <strong>critères ESG</strong> à l'analyse financière. Il <strong>concilie performance financière et impact social et environnemental</strong>.\n<ul>\n<li><strong>L'ISR est une façon d'investir ; l'ESG, ce sont les critères utilisés.</strong></li>\n<li>Un placement ISR <strong>reste soumis aux aléas du marché</strong> : pas de garantie de capital.</li>\n<li>Il peut porter sur des actions, des obligations, du monétaire, de l'<strong>immobilier</strong>, et sur <strong>tout ou partie</strong> du portefeuille.</li>\n<li>Il est vendu par les <strong>réseaux bancaires et financiers</strong>, avec un <strong>DIC</strong> comme tout fonds grand public. Il se développe <strong>dans le monde entier</strong>, pas seulement en France.</li>\n</ul>\n</li>\n<li><strong>Finance verte</strong> : les opérations financières qui <strong>favorisent la transition énergétique et la lutte contre le réchauffement climatique</strong>.</li>\n<li><strong>Finance solidaire</strong> : elle finance des <strong>activités d'utilité sociale</strong> (lutte contre l'exclusion, cohésion sociale, développement durable), par exemple des <strong>ateliers protégés employant des personnes handicapées</strong>. <strong>Elle est distincte de l'ISR</strong> : ni l'une n'inclut l'autre.</li>\n<li><strong>Greenwashing</strong> (écoblanchiment) : une <strong>publicité mensongère</strong> fondée sur de faux arguments écologiques. Exemple type du BTS Banque 2026 (question EF26-100) : une société de gestion illustre sa publicité de <strong>panneaux solaires et d'éoliennes</strong> alors que ses fonds n'investissent que dans l'<strong>extraction d'énergies fossiles</strong>. Communiquer clairement sur un projet pétrolier n'est pas du greenwashing.</li>\n<li>Les <strong>œuvres d'art</strong> ne relèvent pas de la finance durable.</li>\n</ul>\n<h3 id=\"classer-un-critère-dans-le-bon-pilier\">Classer un critère dans le bon pilier</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th><strong>E</strong>nvironnement</th>\n<th><strong>S</strong>ocial</th>\n<th><strong>G</strong>ouvernance</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Émissions de CO₂, <strong>recyclage des déchets</strong>, eau, biodiversité, énergie</td>\n<td><strong>Conditions de travail</strong>, formation, <strong>santé</strong>, <strong>non-discrimination</strong>, <strong>emploi des personnes handicapées</strong>, <strong>relations avec les sous-traitants</strong></td>\n<td><strong>Lutte contre la corruption</strong>, <strong>transparence de la rémunération des dirigeants</strong>, indépendance du conseil d'administration, droits des actionnaires</td>\n</tr>\n</tbody>\n</table></div>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>E = la planète ; S = les personnes (salariés, fournisseurs, clients, santé) ; G = le pouvoir et l'argent des dirigeants (corruption, rémunérations).</strong></p>\n</aside>\n<h3 id=\"les-stratégies-isr-le-tableau-à-connaître-par-cœur\">Les stratégies ISR : le tableau à connaître par cœur</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Approche</th>\n<th>Principe</th>\n<th>Indice pour la reconnaître</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Best-in-class</strong></td>\n<td>Retenir les <strong>meilleures entreprises de chaque secteur</strong>, <strong>sans exclure aucun secteur</strong>. L'allocation sectorielle reste <strong>alignée sur l'indice</strong>. On <strong>peut garder une entreprise d'un secteur polluant</strong>, si c'est la meilleure de son secteur.</td>\n<td>« <strong>au sein de leur secteur</strong> », « sans exclure de secteur »</td>\n</tr>\n<tr>\n<td><strong>Best-in-universe</strong></td>\n<td>Retenir les <strong>mieux notées tous secteurs confondus</strong>. Les <strong>secteurs vertueux sont surreprésentés</strong>, d'où un biais sectoriel assumé.</td>\n<td>« <strong>indépendamment du secteur</strong> »</td>\n</tr>\n<tr>\n<td><strong>Best effort</strong></td>\n<td>Privilégier les entreprises qui montrent <strong>les meilleurs progrès</strong> ou perspectives ESG dans le temps</td>\n<td>« <strong>amélioration</strong> », « progrès »</td>\n</tr>\n<tr>\n<td><strong>Exclusion sectorielle</strong></td>\n<td><strong>Exclure des secteurs</strong> jugés néfastes : armement, tabac, jeux, OGM, nucléaire, charbon…</td>\n<td>« <strong>exclut</strong> » + secteurs</td>\n</tr>\n<tr>\n<td><strong>Exclusion normative</strong></td>\n<td>Exclure les entreprises qui <strong>ne respectent pas les normes ou conventions internationales</strong> (droits humains, OIT…)</td>\n<td>« <strong>normes, conventions</strong> »</td>\n</tr>\n<tr>\n<td><strong>Thématique</strong></td>\n<td>Investir <strong>uniquement</strong> dans des secteurs liés au <strong>développement durable</strong> : renouvelables, eau, santé, climat</td>\n<td>« <strong>secteurs du développement durable</strong> »</td>\n</tr>\n<tr>\n<td><strong>Engagement actionnarial</strong></td>\n<td><strong>Dialoguer et voter activement en assemblée générale</strong> pour <strong>influencer les pratiques ESG</strong> des entreprises</td>\n<td>« <strong>assemblées générales</strong>, droits de vote »</td>\n</tr>\n<tr>\n<td><strong>Impact investing</strong></td>\n<td>Investir, souvent <strong>dans le non coté</strong>, dans des entreprises qui recherchent un <strong>impact social ou environnemental mesurable</strong></td>\n<td>« <strong>impact mesurable</strong> »</td>\n</tr>\n</tbody>\n</table></div>\n<ul>\n<li>Ces approches ne sont <strong>pas exclusives</strong> : elles se combinent, et il en existe d'autres.</li>\n<li>« Best execution », « best selection », « CORE » ou « Value added » <strong>ne sont pas</strong> des approches ISR.</li>\n<li><strong>Obligations des SGP qui pratiquent l'ISR</strong> :\n<ul>\n<li>elles <strong>expliquent toujours</strong> comment elles prennent en compte les critères ESG ;</li>\n<li>elles documentent leurs critères de sélection (<strong>code de transparence</strong>) ;</li>\n<li>elles organisent un <strong>contrôle et un suivi des risques</strong> ;</li>\n<li>si la note ESG d'une valeur <strong>se dégrade</strong>, elles suivent la <strong>politique d'investissement et de désinvestissement</strong> prévue ;</li>\n<li>leur approche ESG repose sur des <strong>critères objectifs</strong>.</li>\n</ul>\n</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« CLASS = dans sa CLASSE (son secteur) ; UNIVERSE = dans tout l'UNIVERS ; EFFORT = celui qui PROGRESSE. »</strong></p>\n</aside>\n<h3 id=\"les-labels-le-tableau-qui-rapporte-le-plus-de-points\">Les labels : le tableau qui rapporte le plus de points</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Label</th>\n<th>Créé par</th>\n<th>Ce qu'il garantit</th>\n<th>Détails à retenir</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Label ISR</strong> (2016)</td>\n<td><strong>Ministère de l'Économie et des Finances</strong></td>\n<td>Que le fonds <strong>intègre des critères ESG</strong> dans sa politique d'investissement et vise des objectifs financiers et extra-financiers</td>\n<td>Dossier déposé auprès d'un <strong>organisme de certification accrédité par le COFRAC</strong> (Afnor Certification, EY, Deloitte…), sous le contrôle du ministère ; ni l'AMF, ni les agences de notation. Attribué pour <strong>3 ans renouvelables</strong>. <strong>Rapport ESG au moins annuel</strong> aux investisseurs. Pour le conserver, il faut <strong>apporter des preuves</strong> de la qualité durable des investissements. Il s'applique aux fonds <strong>actions, obligations et monétaires</strong>.</td>\n</tr>\n<tr>\n<td><strong>Label Greenfin</strong> (ex-TEEC, 2015)</td>\n<td><strong>Ministère de la Transition écologique</strong> (label <strong>public français</strong>)</td>\n<td>Que le fonds <strong>finance la transition énergétique et écologique</strong> (les « <strong>éco-activités</strong> »)</td>\n<td><strong>Exclut le nucléaire et les énergies fossiles</strong>. <strong>Dérivés limités</strong> à une gestion efficace du portefeuille. Ouvert aux fonds <strong>français et étrangers</strong>.</td>\n</tr>\n<tr>\n<td><strong>Label Finansol</strong> (1997)</td>\n<td>Association Finansol (aujourd'hui <strong>FAIR</strong>)</td>\n<td>Il <strong>distingue les produits d'épargne solidaire</strong> des autres, selon des critères de <strong>solidarité, transparence et information</strong></td>\n<td>Il est attribué à <strong>un produit</strong>, pas à un établissement. <strong>Deux types de produits</strong> : <strong>investissement solidaire</strong> et <strong>partage</strong>. Un <strong>fonds de partage</strong> reverse <strong>au moins 25 % des revenus</strong> sous forme de dons. Il finance l'<strong>accès à l'emploi</strong>, au <strong>logement</strong>…</td>\n</tr>\n<tr>\n<td><strong>Label Relance</strong> (2020)</td>\n<td>DG Trésor</td>\n<td>Financement des <strong>entreprises françaises</strong> (fonds propres)</td>\n<td>Voir le §8.5</td>\n</tr>\n<tr>\n<td><strong>Label bas-carbone</strong></td>\n<td>Ministère de la Transition écologique</td>\n<td>Projets de <strong>réduction des émissions de gaz à effet de serre</strong> (objectifs climatiques de la France)</td>\n<td></td>\n</tr>\n</tbody>\n</table></div>\n<ul>\n<li><strong>Agrément ESUS</strong> (<strong>E</strong>ntreprise <strong>S</strong>olidaire d'<strong>U</strong>tilité <strong>S</strong>ociale) : réservé aux entreprises de l'<strong>économie sociale et solidaire</strong>, sous critères. Investir dans une entreprise ESUS ouvre droit à des <strong>avantages fiscaux</strong> (réduction d'impôt). Dans une entreprise de l'ESS, les <strong>bénéfices</strong> servent <strong>principalement au développement de l'activité</strong>.</li>\n<li><strong>Fonds solidaire d'un plan d'épargne salariale</strong> : entre <strong>5 et 10 %</strong> de l'actif en entreprises solidaires (« au plus 10 % » selon la base).</li>\n<li>Pour identifier un fonds ISR, la base cite <strong>le label ISR et le label Greenfin</strong>.</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« ISR = Finances (Bercy) ; GREENfin = Écologie (vert, sans nucléaire ni fossile) ; FINANSOL = SOLidarité (produit d'épargne). »</strong></p>\n</aside>\n<h3 id=\"les-obligations-vertes-green-bonds\">Les obligations vertes (<em>green bonds</em>)</h3>\n<ul>\n<li>Elles financent <strong>exclusivement des projets environnementaux</strong> (transition écologique, renouvelables).</li>\n<li>C'est <strong>l'émetteur qui les qualifie de vertes</strong>.</li>\n<li>Elles sont émises par des <strong>entités publiques ou des entreprises</strong>.</li>\n<li>Leur <strong>signe distinctif</strong> : un <strong>reporting détaillé</strong> de l'émetteur sur les projets financés. Pour les <strong>OAT vertes</strong>, l'État publie un <strong>rapport annuel</strong>.</li>\n<li>Leur risque et leur rendement ne dépendent <strong>pas</strong> de la performance écologique des projets.</li>\n</ul>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p><strong>Norme européenne d'obligation verte (EuGB)</strong>, applicable depuis le <strong>21 décembre 2024</strong> : label volontaire qui exige que l'<strong>essentiel des fonds (85 %)</strong> soit aligné sur la <strong>taxonomie</strong> et passe par un <strong>examinateur externe</strong> enregistré auprès de l'ESMA.\n<strong>Confirmé au BTS Banque 2026</strong> : un fonds investi en <strong>obligations vertes européennes</strong> finance des projets <strong>compatibles avec les objectifs du règlement Taxonomie</strong> (question 1922, mise à jour dans la base).</p>\n</aside>\n<h3 id=\"la-notation-extra-financière\">La notation extra-financière</h3>\n<ul>\n<li>Elle évalue la <strong>politique environnementale, sociale et de gouvernance</strong> d'un acteur. Elle n'évalue ni la solvabilité, ni la rentabilité, ni le cours. Elle peut intégrer la <strong>qualité des codes de conduite</strong>, la <strong>gestion des ressources humaines</strong> ou la <strong>contribution à la santé publique</strong>, et elle concerne <strong>tous types d'entreprises</strong>.</li>\n<li><strong>Ses sources</strong> : documents publics, <strong>questionnaires</strong>, entretiens avec la direction, les salariés, les syndicats, les ONG, les fournisseurs…</li>\n<li><strong>Notation déclarative</strong> (non sollicitée) : faite par l'agence <strong>sans accord de l'entreprise</strong>. Les agences sont alors <strong>rémunérées par les investisseurs</strong>.</li>\n<li><strong>Notation sollicitée</strong> : faite <strong>à la demande de l'émetteur</strong>, par exemple une entreprise qui veut connaître son positionnement RSE.</li>\n<li>Les <strong>méthodes diffèrent d'une agence à l'autre</strong>.</li>\n<li>Exemples : <strong>Trucost</strong> (impacts <strong>environnementaux</strong>) ; indices éthiques comme le <strong>DJSI World</strong> ou le <strong>Low Carbon 100 Europe</strong> d'Euronext (les 100 entreprises <strong>qui émettent le moins de CO₂</strong>).</li>\n<li>L'<strong>empreinte carbone</strong> du portefeuille mesure les <strong>émissions de gaz à effet de serre</strong> d'un portefeuille.</li>\n</ul>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p>Le règlement européen sur les <strong>notations ESG</strong> (applicable depuis le <strong>2 juillet 2026</strong>) soumet les agences à l'<strong>agrément et à la surveillance de l'ESMA</strong>. Il impose la <strong>transparence</strong> des méthodes, sans les uniformiser : elles restent différentes d'une agence à l'autre.</p>\n</aside>\n<h3 id=\"la-rse-responsabilité-sociale-ou-sociétale-des-entreprises\">La RSE (responsabilité sociale ou sociétale des entreprises)</h3>\n<ul>\n<li>C'est l'<strong>intégration volontaire</strong> par les entreprises de <strong>préoccupations sociales et environnementales</strong> dans leur activité, pour <strong>concilier performance économique et performance sociale</strong>.</li>\n<li><strong>Toutes les entreprises</strong> peuvent s'y engager, quelle que soit leur taille. L'impact à limiter couvre les <strong>sites de production, ceux des sous-traitants et toute la chaîne d'approvisionnement</strong>.</li>\n<li><strong>Norme internationale ISO 26000</strong> : gouvernance, conditions de travail, environnement…</li>\n<li><strong>Cadre français</strong> :\n<ul>\n<li>la loi <strong>NRE</strong> (2001) ;</li>\n<li>les lois <strong>Grenelle</strong> (2009-2010) ;</li>\n<li>la loi <strong>PACTE</strong> (22 mai 2019), qui a modifié l'article 1833 du Code civil : la société prend <strong>en considération les enjeux sociaux et environnementaux</strong> de son activité, et peut se doter d'une <strong>raison d'être</strong>.</li>\n</ul>\n</li>\n<li><strong>DPEF</strong> (déclaration de performance extra-financière, depuis <strong>2017</strong>) :\n<ul>\n<li>elle informe sur les <strong>conséquences sociales et environnementales</strong> de l'activité (climat, conditions de travail, lutte contre les discriminations…) ;</li>\n<li>elle concerne les <strong>sociétés cotées</strong> de plus de 500 salariés et de plus de 20 M€ de bilan ou 40 M€ de chiffre d'affaires, et les <strong>non cotées</strong> de plus de 500 salariés et de plus de 100 M€ de bilan ou de chiffre d'affaires ;</li>\n<li>elle est <strong>vérifiée par un organisme tiers indépendant</strong>.</li>\n</ul>\n</li>\n</ul>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p><strong>La CSRD remplace la DPEF</strong> par un <strong>rapport de durabilité</strong> (standards européens ESRS, vérification par un commissaire aux comptes ou un OTI). Les premiers rapports sont publiés en 2025 pour les plus grandes entreprises. Le <strong>paquet « Omnibus » (2025)</strong> a <strong>reporté</strong> les vagues suivantes et <strong>réduit le champ</strong> des entreprises concernées.</p>\n</aside>\n<h3 id=\"le-cadre-européen-sfdr-et-taxonomie\">Le cadre européen : SFDR et taxonomie</h3>\n<ul>\n<li><strong>Plan d'action pour la finance durable</strong> (2018) : donner à l'Europe un <strong>cadre financier pour une économie plus verte</strong>. Le <strong>Pacte vert</strong> (<em>Green Deal</em>, 2019) vise la <strong>neutralité carbone en 2050</strong>. Le <strong>protocole de Kyoto</strong> (1997) a posé les bases d'un <strong>marché du carbone</strong>.</li>\n<li><strong>Taxonomie</strong> : la <strong>liste des activités considérées comme durables</strong> sur le plan environnemental, qui sert de référentiel européen.</li>\n<li><strong>SFDR</strong> (règlement <em>Disclosure</em> 2019/2088, applicable depuis mars 2021) :\n<ul>\n<li><strong>Objet</strong> : <strong>renforcer les obligations de transparence</strong> en matière de durabilité dans les services financiers. Il ne définit pas les activités durables (c'est la taxonomie), ni les préférences de durabilité (c'est MIF 2).</li>\n<li><strong>Qui ?</strong> Les acteurs des marchés financiers et les conseillers, <strong>FIA compris</strong>.</li>\n<li><strong>Où ?</strong> Sur le <strong>site internet</strong> et dans les <strong>documents précontractuels</strong>, <strong>au niveau de l'entité ET du produit</strong>.</li>\n<li><strong>Quoi ?</strong>\n<ul>\n<li>la manière dont les <strong>risques en matière de durabilité</strong> sont intégrés dans les décisions d'investissement et dans les <strong>politiques de rémunération</strong> ;</li>\n<li>la prise en compte des <strong>principales incidences négatives</strong> ;</li>\n<li>les <strong>politiques générales</strong> de l'entité.</li>\n</ul>\n</li>\n<li>Un <strong>conseiller financier de moins de 3 personnes</strong> <strong>intègre</strong> quand même les risques de durabilité dans son conseil.</li>\n<li>Un produit qui met en avant des caractéristiques E/S <strong>explique en quoi il diffère d'un indice de marché large</strong>.</li>\n<li><strong>Classification</strong> :\n<ul>\n<li><strong>article 6</strong> : simple information sur les risques ;</li>\n<li><strong>article 8</strong> : produit qui <strong>promeut</strong> des caractéristiques E/S ;</li>\n<li><strong>article 9</strong> : produit qui a un <strong>objectif d'investissement durable</strong>.</li>\n</ul>\n</li>\n</ul>\n</li>\n<li><strong>Risque en matière de durabilité</strong> : un événement ESG qui pourrait avoir une <strong>incidence négative importante sur la valeur</strong> de l'investissement.</li>\n<li><strong>Contrôle</strong> : l'<strong>AMF</strong> veille à la <strong>qualité de l'information</strong> des SGP sur leur stratégie climat et leurs risques climatiques.</li>\n</ul>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p>Depuis le <strong>2 août 2022</strong>, le conseiller doit recueillir les <strong>préférences de durabilité</strong> du client (MIF 2).</p>\n</aside>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p>Depuis <strong>2024-2025</strong>, les <strong>noms de fonds</strong> utilisant des termes ESG ou « durable » doivent respecter les <strong>orientations de l'ESMA</strong> (au moins <strong>80 %</strong> d'investissements alignés et des exclusions minimales).</p>\n</aside>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p>Le <strong>label ISR a été réformé en 2024</strong> : <strong>exclusion des entreprises qui lancent de nouveaux projets d'énergies fossiles</strong>, <strong>sélectivité renforcée (30 %)</strong> et exigences sur les plans de transition climatique.</p>\n</aside>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p>Une <strong>révision de SFDR</strong> (création de catégories de produits) est en discussion depuis la proposition de la Commission fin 2025.</p>\n</aside>\n<div class=\"ids\" data-sub=\"8.7\"></div>\n<hr/>\n<h2 class=\"flash\" id=\"fiche-flash-du-thème-8\"> Fiche flash du thème 8</h2>\n<ol>\n<li><strong>SGP</strong> gère (agrément AMF, association, obligation de moyens) ; <strong>dépositaire</strong> = <strong>conservation + contrôle de régularité + suivi des liquidités</strong> (la délégation ne l'exonère pas) ; <strong>valorisateur</strong> = VL ; <strong>CAC</strong> = certifie les comptes ; <strong>prime broker</strong> = hedge funds.</li>\n<li><strong>Mandat</strong> = objectifs, catégories d'instruments, répartition avec planchers et plafonds, information, valorisation ; <strong>obligation de moyens et de loyauté</strong>, résiliable <strong>à tout moment par les deux parties</strong> ; alerte en cas de <strong>baisse de 10 %</strong>.</li>\n<li>OPC : ratios <strong>en permanence</strong>, <strong>5 % par émetteur</strong>, <strong>ratio d'emprise</strong> ; rachats suspendus <strong>seulement en cas exceptionnel et dans l'intérêt des porteurs</strong> ; SICAV = <strong>SA ou SAS</strong>.</li>\n<li>Performance <strong>absolue</strong> (seule) ou <strong>relative</strong> (indice) ; <strong>Sharpe</strong> = excès de rendement / volatilité ; <strong>moyen terme = 3 à 8 ans</strong> ; risque élevé = horizon <strong>long</strong> ; règlement <strong>Benchmark</strong> = contre la <strong>manipulation</strong> des indices.</li>\n<li><strong>UCITS IV</strong> = DICI ; <strong>UCITS V</strong> = dépositaire, liquidités, rémunérations ; <strong>AIFM</strong> = gestionnaires de FIA, dépositaire, passeport pour les professionnels, stress tests annuels ; <strong>MMF</strong> = appellation « monétaire » <strong>réservée</strong>.</li>\n<li><strong>FCPR ≥ 50 % non coté</strong>, <strong>FCPI &gt; 70 %</strong>, <strong>FIP ≥ 70 % PME régionales</strong>, <strong>OPCI ≥ 60 % immobilier</strong>, <strong>nourricier ≥ 85 % dans un seul maître</strong> ; <strong>SCPI</strong> = immobilier locatif, note visée par l'AMF ; <strong>ELTIF</strong> = fermé ; <strong>ETF</strong> = indice coté en continu.</li>\n<li><strong>Active</strong> = battre l'indice ; <strong>passive</strong> = le copier ; <strong>alternative</strong> = performance <strong>absolue</strong> ; <strong>value</strong> = sous-évaluées ; <strong>growth</strong> = croissance.</li>\n<li><strong>ESG</strong> = 3 piliers : <strong>E</strong> (CO₂, déchets), <strong>S</strong> (travail, santé, handicap, sous-traitants, discrimination), <strong>G</strong> (corruption, rémunération des dirigeants).</li>\n<li><strong>Best-in-class</strong> = les meilleurs <strong>de chaque secteur</strong> (sans exclusion) ; <strong>best-in-universe</strong> = les meilleurs <strong>tous secteurs</strong> ; <strong>best effort</strong> = les <strong>progrès</strong> ; <strong>exclusion</strong> sectorielle ou normative ; <strong>thématique</strong> ; <strong>engagement</strong> = vote en AG ; <strong>impact</strong> = mesurable.</li>\n<li><strong>Label ISR</strong> : <strong>ministère des Finances</strong>, organismes accrédités <strong>COFRAC</strong>, <strong>3 ans renouvelables</strong>, rapport ESG annuel. <strong>Greenfin</strong> : <strong>ministère de l'Écologie</strong>, <strong>sans nucléaire ni fossiles</strong>. <strong>Finansol</strong> : <strong>produits d'épargne solidaire</strong> (fonds de partage ≥ 25 % des revenus donnés).</li>\n<li><strong>Green bond</strong> = projets verts, <strong>qualifié par l'émetteur</strong>, <strong>reporting</strong> ; <strong>OAT verte</strong> = rapport annuel de l'État.</li>\n<li>Notation extra-financière : <strong>déclarative</strong> (sans l'accord de l'entreprise, payée par les investisseurs) / <strong>sollicitée</strong> (à la demande de l'émetteur) ; <strong>méthodes différentes</strong>.</li>\n<li>RSE : <strong>ISO 26000</strong>, loi <strong>PACTE</strong> (art. 1833 C. civ.) ; <strong>DPEF</strong> vérifiée par un <strong>OTI</strong>, remplacée par la <strong>CSRD</strong>.</li>\n<li><strong>SFDR</strong> = <strong>transparence</strong> (entité + produit, site + précontractuel, <strong>FIA compris</strong>) ; <strong>taxonomie</strong> = liste des activités durables ; <strong>Green Deal</strong> = neutralité carbone <strong>2050</strong>.</li>\n</ol>\n","toc":[{"id":"8-1-les-acteurs-de-la-gestion-dactifs","t":"8.1 Les acteurs de la gestion d'actifs"},{"id":"8-2-1-les-fondamentaux-mandat-de-gestion-opcvm-fia-ratios-so","t":"8.2.1 Les fondamentaux : mandat de gestion, OPCVM, FIA, ratios, souscriptions et rachats"},{"id":"8-2-2-mesurer-la-performance-et-le-risque","t":"8.2.2 Mesurer la performance et le risque"},{"id":"8-4-le-cadre-réglementaire-gestion-sous-mandat-directives-ai","t":"8.4 Le cadre réglementaire : gestion sous mandat, directives AIFM, UCITS et règlement MMF"},{"id":"8-5-les-instruments-de-la-gestion-collective-la-typologie-de","t":"8.5 Les instruments de la gestion collective : la typologie des OPC"},{"id":"8-6-les-types-de-gestion","t":"8.6 Les types de gestion"},{"id":"8-7-finance-durable-isr-esg-finance-verte-et-solidaire-rse-n","t":"8.7 Finance durable : ISR, ESG, finance verte et solidaire, RSE, notation extra-financière (15 questions)"},{"id":"fiche-flash-du-thème-8","t":"Fiche flash du thème 8"}]},{"id":"09","n":9,"title":"Fonctionnement et organisation des marchés","html":"\n<blockquote class=\"note\">\n<p><strong>Poids à l'examen : 7 questions sur 120.</strong></p>\n<ul>\n<li><strong>§9.2 : 2 questions en catégorie A</strong> (ordres et séance de bourse) ;</li>\n<li>§9.1 (2), §9.3 (1), §9.4 (1), §9.5 (1) en catégorie C.</li>\n</ul>\n<p>Les <strong>types d'ordres</strong> et la <strong>priorité prix puis temps</strong> sont des points A faciles à gagner.</p>\n</blockquote>\n<hr/>\n<h2 id=\"9-1-les-lieux-et-modes-dexécution\">9.1 Les lieux et modes d'exécution</h2>\n<h3 id=\"les-plateformes-de-négociation-mif-2\">Les plateformes de négociation (MIF 2)</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Lieu</th>\n<th>Définition</th>\n<th>Exemples / à retenir</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Marché réglementé (MR)</strong></td>\n<td>Système <strong>multilatéral</strong> géré par une <strong>entreprise de marché</strong>, avec des <strong>règles de fonctionnement et d'admission très précises</strong>. Le statut est accordé par le <strong>ministre de l'Économie, sur proposition de l'AMF</strong>.</td>\n<td><strong>Euronext Paris, compartiments A, B et C</strong>, classés selon la <strong>capitalisation boursière</strong> (A &gt; 1 Md€, B de 150 M€ à 1 Md€, C &lt; 150 M€)</td>\n</tr>\n<tr>\n<td><strong>SMN / MTF</strong> (système multilatéral de négociation)</td>\n<td>Fait <strong>se rencontrer de multiples intérêts acheteurs et vendeurs</strong>. On peut y négocier des actions <strong>déjà admises sur un MR de l'EEE</strong>, et des titres qu'il admet lui-même.</td>\n<td><strong>Euronext Growth</strong> (PME), <strong>Euronext Access</strong> (ex-marché libre, petites entreprises non admises sur un MR)</td>\n</tr>\n<tr>\n<td><strong>OTF</strong> (système organisé de négociation)</td>\n<td>Plateforme multilatérale <strong>réservée aux obligations, produits structurés, quotas d'émission et dérivés</strong>, <strong>jamais aux actions</strong></td>\n<td></td>\n</tr>\n<tr>\n<td><strong>Internalisateur systématique (IS)</strong></td>\n<td>Un <strong>PSI</strong> qui, de façon <strong>organisée, fréquente et systématique</strong>, <strong>exécute les ordres de ses clients face à son compte propre</strong>, <strong>en dehors</strong> d'un MR, d'un MTF ou d'un OTF</td>\n<td>Il se porte <strong>directement contrepartie</strong> du client</td>\n</tr>\n<tr>\n<td><strong>Gré à gré (OTC)</strong></td>\n<td>Transaction bilatérale, hors plateforme</td>\n<td><strong>Aucune protection contre le risque de contrepartie</strong> (pas de garantie de bonne fin). Le <strong>FOREX</strong> (marché des changes) en est l'exemple.</td>\n</tr>\n</tbody>\n</table></div>\n<p><strong>Les règles à retenir</strong></p>\n<ul>\n<li>L'<strong>entreprise de marché</strong> (Euronext, <strong>entreprise privée</strong>) est une <strong>société commerciale</strong>.\n<ul>\n<li>Elle <strong>organise les négociations</strong> (actions, obligations, dérivés).</li>\n<li>Elle fixe les <strong>règles de suspension</strong> des cotations en cas de forte variation des cours.</li>\n<li>Elle <strong>calcule les indices</strong> (le CAC 40).</li>\n</ul>\n</li>\n<li>MIF 2 <strong>interdit la négociation régulière des actions de gré à gré</strong> (obligation de négociation des actions sur une plateforme).</li>\n<li>Les <strong>dérivés soumis à l'obligation de compensation</strong> ne peuvent pas se négocier sur un <strong>IS</strong> : seulement sur un MR, un MTF ou un OTF.</li>\n<li>Un PSI peut <strong>grouper</strong> les ordres de ses clients, entre eux ou avec son compte propre, <strong>sous conditions</strong>.</li>\n<li><strong>Matières premières</strong> : un marché de <strong>couverture</strong> du risque de prix. Les entités non financières vérifient que leur négoce reste <strong>accessoire</strong> grâce à un <strong>ratio</strong>.</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« MR et MTF = multilatéraux ; OTF = pas d'actions ; IS = le PSI joue contre son client. »</strong></p>\n</aside>\n<aside class=\"callout c-warn\"><span class=\"callout-label\">Piège</span>\n<p>Euronext Growth est un <strong>MTF</strong>, pas un marché réglementé. Euronext Access et le Forex <strong>ne sont pas</strong> des marchés réglementés.</p>\n</aside>\n<h3 id=\"comptant-terme-et-srd\">Comptant, terme et SRD</h3>\n<ul>\n<li><strong>Marché au comptant</strong> : règlement et livraison immédiats (à J+2).</li>\n<li><strong>Marché à terme</strong> : la transaction est <strong>conclue aujourd'hui à un prix fixé</strong>, pour une exécution <strong>ultérieure</strong>.\n<ul>\n<li>Les dérivés <strong>listés</strong> sont <strong>standardisés</strong> (échéances, montants) et peuvent être négociés sur un <strong>MR</strong>.</li>\n<li>Les dérivés <strong>de gré à gré</strong> s'exécutent <strong>hors MR</strong>.</li>\n</ul>\n</li>\n<li><strong>SRD</strong> (service de règlement différé) :\n<ul>\n<li>il permet de <strong>négocier à terme</strong> : <strong>différer le paiement</strong> des titres achetés, ou la <strong>livraison</strong> des titres vendus, au <strong>dernier jour de bourse du mois</strong> ;</li>\n<li>c'est un service payant (commission) ;</li>\n<li>il est réservé à certaines valeurs du marché réglementé.</li>\n</ul>\n</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>SRD = « Je Règle à la fin du mois » (dernier jour de bourse).</strong></p>\n</aside>\n<div class=\"ids\" data-sub=\"9.1\"></div>\n<hr/>\n<h2 id=\"9-2-les-ordres-et-la-séance-de-bourse-à-paris-catégorie-a\">9.2 Les ordres et la séance de bourse à Paris (catégorie A)</h2>\n<h3 id=\"les-types-dordres\">Les types d'ordres</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Ordre</th>\n<th>Prix</th>\n<th>Ce qu'il faut savoir</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Au marché</strong></td>\n<td><strong>Aucune limite de prix</strong></td>\n<td><strong>Prioritaire sur tous les autres</strong>. Exécuté <strong>immédiatement</strong> aux <strong>meilleurs prix disponibles</strong> du carnet, en une ou plusieurs fois, dans la limite des quantités. On <strong>ne maîtrise pas le prix</strong>.</td>\n</tr>\n<tr>\n<td><strong>À cours limité</strong></td>\n<td><strong>Prix maximum à l'achat</strong>, <strong>prix minimum à la vente</strong></td>\n<td>Exécuté <strong>à la limite ou à un meilleur cours</strong>. Il <strong>garantit le prix</strong>, mais <strong>ni l'exécution, ni le moment, ni la quantité</strong>.</td>\n</tr>\n<tr>\n<td><strong>À la meilleure limite</strong></td>\n<td><strong>Aucune indication de prix</strong> à la saisie</td>\n<td>Il <strong>devient un ordre à cours limité au prix de la meilleure offre en face</strong> (meilleure demande pour une vente) <strong>au moment de son arrivée</strong></td>\n</tr>\n<tr>\n<td><strong>Indexé</strong> (<em>pegged</em>)</td>\n<td>Suit le marché</td>\n<td>Il <strong>suit en permanence la meilleure offre ou la meilleure demande</strong> du carnet</td>\n</tr>\n<tr>\n<td><strong>À seuil de déclenchement</strong> (<em>stop</em>)</td>\n<td>Un <strong>seuil</strong> déclenche l'ordre</td>\n<td>Une fois le seuil atteint, il devient un ordre au marché. Un stop <strong>de vente</strong> fixe un cours <strong>auquel et au-dessous duquel</strong> on vend, pour limiter les pertes.</td>\n</tr>\n<tr>\n<td><strong>À plage de déclenchement</strong> (<em>stop limit</em>)</td>\n<td>Un seuil <strong>et</strong> une limite</td>\n<td>Il devient un ordre à cours limité une fois le seuil atteint</td>\n</tr>\n<tr>\n<td><strong>Iceberg</strong></td>\n<td>Ordre à <strong>quantité cachée</strong></td>\n<td>Seule une partie de la quantité est affichée</td>\n</tr>\n</tbody>\n</table></div>\n<p><strong>Durée de validité</strong> : sans indication, un ordre est <strong>valable pour la journée</strong> (ordre « <strong>jour</strong> », retiré le soir s'il n'est pas exécuté). Il peut aussi être <strong>à date déterminée</strong> ou <strong>à révocation</strong>.</p>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« AU MARCHÉ = à tout prix, en premier ; LIMITÉ = mon prix ou mieux ; MEILLEURE LIMITE = le prix d'en face à l'arrivée ; STOP = je déclenche à partir d'un seuil. »</strong></p>\n</aside>\n<aside class=\"callout c-warn\"><span class=\"callout-label\">Piège</span>\n<p>Un acheteur fixe un <strong>maximum</strong> ; un vendeur fixe un <strong>minimum</strong>.</p>\n</aside>\n<h3 id=\"la-priorité-dexécution-dans-le-carnet\">La priorité d'exécution dans le carnet</h3>\n<p><strong>1. Le prix, puis 2. l'heure d'arrivée</strong> (priorité stricte de prix, puis de temps). La <strong>taille de l'ordre</strong> ne compte <strong>jamais</strong>.</p>\n<ul>\n<li>Les ordres <strong>comparables</strong> d'un PSI sont exécutés <strong>dans l'ordre de leur réception</strong>.</li>\n<li>Quand un ordre <strong>groupé</strong> est <strong>partiellement exécuté</strong>, la SGP <strong>répartit au prorata</strong>, selon sa <strong>politique d'allocation</strong>.</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« Prix d'abord, chrono ensuite. »</strong></p>\n</aside>\n<h3 id=\"la-séance-de-bourse-sur-euronext-paris-actions-en-continu\">La séance de bourse sur Euronext Paris (actions en continu)</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Heure</th>\n<th>Phase</th>\n<th>Ce qui se passe</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>7 h 15 – 9 h</strong></td>\n<td><strong>Préouverture</strong></td>\n<td>Les ordres <strong>s'accumulent</strong>, <strong>aucune transaction</strong>. Euronext diffuse <strong>au fil de l'eau un cours théorique d'ouverture</strong>. Les ordres peuvent être modifiés ou annulés.</td>\n</tr>\n<tr>\n<td><strong>9 h</strong></td>\n<td><strong>Fixing d'ouverture</strong></td>\n<td>Le cours est celui qui <strong>maximise le volume échangé</strong></td>\n</tr>\n<tr>\n<td><strong>9 h – 17 h 30</strong></td>\n<td><strong>Négociation en continu</strong></td>\n<td><strong>Chaque ordre est confronté immédiatement</strong> aux ordres de sens opposé</td>\n</tr>\n<tr>\n<td><strong>17 h 30 – 17 h 35</strong></td>\n<td><strong>Préclôture</strong></td>\n<td>Accumulation des ordres</td>\n</tr>\n<tr>\n<td><strong>17 h 35</strong></td>\n<td><strong>Fixing de clôture</strong></td>\n<td>Le <strong>cours de clôture</strong> est le <strong>cours de référence du jour</strong></td>\n</tr>\n<tr>\n<td><strong>17 h 35 – 17 h 40</strong></td>\n<td><strong>TAL</strong> (<em>trading at last</em>)</td>\n<td>Exécutions <strong>au cours de clôture</strong></td>\n</tr>\n</tbody>\n</table></div>\n<ul>\n<li><strong>Cotation au fixing</strong> (une ou deux fois par jour) : pour les <strong>valeurs peu liquides</strong> (Euronext Access, par exemple). Les ordres sont <strong>accumulés puis confrontés tous ensemble</strong>.</li>\n<li><strong>Cotation en continu</strong> : pour les valeurs liquides.</li>\n<li><strong>Réservation et suspension</strong> : si le cours franchit les <strong>limites de variation</strong>, la cotation est <strong>suspendue temporairement quelques minutes</strong>, pas jusqu'au lendemain. La <strong>suspension</strong> d'un titre sert à <strong>garantir la bonne diffusion d'une information</strong> à tous. Elle n'est ni définitive, ni décidée par l'AMF seule.</li>\n<li><strong>Marché dirigé par les prix</strong> (<em>quote driven</em>) : les prix viennent des <strong>fourchettes des teneurs de marché</strong>. <strong>Marché dirigé par les ordres</strong> : le cours naît de la <strong>confrontation des ordres dans le carnet</strong>.</li>\n<li>Le <strong>code ISIN</strong> est l'<strong>immatriculation internationale unique d'un instrument financier</strong>. Le LEI, lui, identifie les acteurs (§9.3).</li>\n<li>Les <strong>OAT pour les particuliers</strong> ont <strong>en permanence un cours</strong> représentatif.</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« 7 h 15 j'empile, 9 h je fixe, 9 h - 17 h 30 je traite, 17 h 35 je clôture, jusqu'à 17 h 40 je finis au dernier cours. »</strong></p>\n</aside>\n<div class=\"ids\" data-sub=\"9.2\"></div>\n<hr/>\n<h2 id=\"9-3-transparence-pré-négociation-et-post-négociation\">9.3 Transparence pré-négociation et post-négociation</h2>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th></th>\n<th><strong>Pré-négociation</strong> (avant la transaction)</th>\n<th><strong>Post-négociation</strong> (après)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>MR et MTF</strong> (actions)</td>\n<td>Publier les <strong>5 meilleures limites à l'achat et à la vente</strong>, avec les quantités. Exigences <strong>identiques</strong> pour un MR et un MTF.</td>\n<td>Publier <strong>en temps réel</strong> le <strong>prix, le volume et l'heure</strong> de chaque transaction</td>\n</tr>\n<tr>\n<td><strong>Marché dirigé par les prix</strong></td>\n<td><strong>Meilleurs prix à l'achat et à la vente de chaque teneur de marché</strong></td>\n<td></td>\n</tr>\n<tr>\n<td><strong>IS</strong></td>\n<td>Publication de prix <strong>pour les transactions jusqu'à la taille standard de marché</strong></td>\n<td></td>\n</tr>\n<tr>\n<td><strong>Gré à gré</strong> (actions cotées)</td>\n<td></td>\n<td>Publication via un <strong>dispositif de publication agréé (APA)</strong></td>\n</tr>\n</tbody>\n</table></div>\n<ul>\n<li>La transparence post-négociation s'applique <strong>à tous les modes d'exécution</strong>, et les règles MIF 2 sont <strong>harmonisées pour tous les instruments</strong>.</li>\n<li><strong>Non publié</strong> : le <strong>nom des PSI</strong> qui ont transmis les ordres.</li>\n<li>Les cours sont <strong>publiés par l'entreprise de marché</strong>. Elle peut <strong>différer la publication avec l'accord de l'AMF</strong>, et <strong>rend compte chaque jour à l'AMF</strong> des ordres et transactions.</li>\n<li>Les <strong>dark pools</strong> sont des plateformes pour <strong>ordres de grande taille, sans transparence pré-négociation</strong>.</li>\n<li>Le <strong>LEI</strong> (<em>Legal Entity Identifier</em>) est l'<strong>immatriculation mondiale unique des acteurs</strong> (personnes morales). Il <strong>facilite le contrôle des risques par les autorités</strong> et est <strong>attribué en France par l'INSEE</strong>.</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« ISIN = l'instrument ; LEI = l'entité (l'acteur). »</strong></p>\n</aside>\n<div class=\"ids\" data-sub=\"9.3\"></div>\n<hr/>\n<h2 id=\"9-4-les-participants-le-reporting-et-le-trading-algorithmiqu\">9.4 Les participants, le reporting et le trading algorithmique</h2>\n<h3 id=\"les-participants\">Les participants</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Participant</th>\n<th>Rôle</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Teneur de marché</strong> (<em>market maker</em>)</td>\n<td>Il <strong>assure la liquidité</strong> en <strong>affichant en permanence des prix d'achat et de vente</strong>. Il a un <strong>accès direct et continu</strong> à la négociation. Son activité exige un <strong>accord avec la plateforme</strong>.</td>\n</tr>\n<tr>\n<td><strong>Animateur de marché, apporteur de liquidité</strong></td>\n<td>Il <strong>transmet en continu des prix</strong> à l'achat et à la vente pour un titre et <strong>amortit la volatilité</strong></td>\n</tr>\n<tr>\n<td><strong>Contrat de liquidité</strong></td>\n<td>Conclu entre un PSI et <strong>toute société cotée</strong> (pratique de marché admise)</td>\n</tr>\n<tr>\n<td><strong>Membre négociateur</strong> (broker)</td>\n<td>Les intermédiaires <strong>non membres</strong> d'Euronext <strong>transmettent leurs ordres à un membre négociateur</strong></td>\n</tr>\n</tbody>\n</table></div>\n<h3 id=\"le-reporting-des-transactions-à-lamf\">Le reporting des transactions à l'AMF</h3>\n<p>Les <strong>PSI</strong> déclarent la <strong>liste de tous les ordres exécutés</strong>, <strong>avec l'identification des clients</strong>, <strong>au plus tard à la fin du jour ouvrable suivant</strong> (J+1).</p>\n<h3 id=\"le-trading-algorithmique-et-à-haute-fréquence\">Le trading algorithmique et à haute fréquence</h3>\n<ul>\n<li><strong>Trading algorithmique</strong> : un <strong>algorithme fixe automatiquement les paramètres des ordres</strong>, avec une intervention humaine limitée ou nulle. Il peut servir à placer des ordres <em>stop-loss</em>. Il <strong>n'est pas forcément à haute fréquence</strong>, et pas réservé aux MR.</li>\n<li><strong>Trading à haute fréquence</strong> : <strong>plus de 2 messages par seconde</strong> sur un même instrument et une même plateforme.</li>\n<li><strong>Obligations MIF 2</strong> :\n<ul>\n<li>les PSI <strong>notifient l'autorité</strong>, <strong>testent leurs algorithmes</strong> et <strong>marquent leurs ordres</strong> ;</li>\n<li>les MR <strong>identifient</strong> les ordres algorithmiques et les algorithmes utilisés.</li>\n</ul>\n</li>\n</ul>\n<div class=\"ids\" data-sub=\"9.4\"></div>\n<hr/>\n<h2 id=\"9-5-les-données-de-marché-et-les-agences-de-notation\">9.5 Les données de marché et les agences de notation</h2>\n<h3 id=\"les-diffuseurs-de-données\">Les diffuseurs de données</h3>\n<ul>\n<li>Ils <strong>centralisent l'information</strong> de tous les acteurs. Les données financières couvrent <strong>les instruments, les émetteurs et les marchés</strong>.</li>\n<li><strong>Euronext</strong> diffuse des données sur les titres cotés et <strong>calcule le CAC 40</strong>, le principal indice de Paris. Le <strong>Dow Jones</strong> compte <strong>30 valeurs</strong>.</li>\n<li><strong>Reuters</strong> et Bloomberg sont des agences d'<strong>information</strong> ; <strong>Moody's</strong>, S&amp;P et Fitch des agences de <strong>notation</strong>.</li>\n<li>L'<strong>INSEE</strong> calcule le <strong>PIB</strong>.</li>\n</ul>\n<h3 id=\"les-prestataires-de-services-de-communication-de-données-psc\">Les prestataires de services de communication de données (PSCD)</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Prestataire</th>\n<th>Rôle</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>APA</strong> (dispositif de publication agréé)</td>\n<td><strong>Publie les transactions</strong> réalisées par les entreprises d'investissement <strong>hors plateforme</strong>, <strong>dans les 15 minutes</strong>, de façon <strong>publique et gratuite</strong></td>\n</tr>\n<tr>\n<td><strong>CTP</strong> (système consolidé de publication)</td>\n<td><strong>Agrège</strong> toutes les transactions sur un instrument, toutes plateformes confondues. Les systèmes consolidés sont <strong>possibles et encadrés</strong>.</td>\n</tr>\n<tr>\n<td><strong>ARM</strong> (mécanisme de déclaration agréé)</td>\n<td><strong>Déclare les transactions au régulateur</strong> pour le compte des entreprises d'investissement</td>\n</tr>\n</tbody>\n</table></div>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p>Depuis <strong>2022</strong>, la plupart des PSCD sont <strong>agréés et supervisés par l'ESMA</strong>. La base (<a class=\"qref\" href=\"#\" data-q=\"2104\">Q2104</a>) répond encore « l'AMF ou l'ACPR selon leur statut ».</p>\n</aside>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p>La révision de MiFIR (2024) organise l'arrivée de <strong>« consolidated tapes » européennes</strong> sélectionnées par l'ESMA (obligations d'abord, puis actions) et <strong>interdit le paiement pour flux d'ordres (PFOF)</strong> au plus tard à mi-2026.</p>\n</aside>\n<h3 id=\"les-agences-de-notation-de-crédit\">Les agences de notation de crédit</h3>\n<ul>\n<li>La note mesure la <strong>perception du risque de crédit</strong> de l'emprunteur <strong>par l'agence</strong> : sa capacité à rembourser, <strong>à court et à long terme</strong>.</li>\n<li>Les agences <strong>publient leurs méthodes</strong> et les <strong>appliquent de façon stable</strong>.</li>\n<li>Elles sont <strong>enregistrées et supervisées par l'ESMA</strong>, ni par l'AMF, ni par la Commission. Elles ne dépendent pas du FMI.</li>\n</ul>\n<div class=\"ids\" data-sub=\"9.5\"></div>\n<hr/>\n<h2 class=\"flash\" id=\"fiche-flash-du-thème-9\"> Fiche flash du thème 9</h2>\n<ol>\n<li><strong>MR</strong> = statut accordé par le <strong>ministre sur proposition de l'AMF</strong> ; Euronext Paris <strong>A, B, C (capitalisation)</strong> ; <strong>Euronext Growth = MTF</strong> ; <strong>Euronext Access</strong> = petites valeurs hors MR.</li>\n<li><strong>OTF</strong> : pas d'actions ; <strong>IS</strong> : le PSI exécute face à son compte propre, hors plateforme ; <strong>OTC</strong> : pas de protection contre la contrepartie.</li>\n<li><strong>SRD</strong> : paiement ou livraison <strong>le dernier jour de bourse du mois</strong>.</li>\n<li><strong>Au marché</strong> = sans limite, <strong>prioritaire</strong> ; <strong>cours limité</strong> = maximum à l'achat, minimum à la vente, exécuté à la limite ou mieux ; <strong>meilleure limite</strong> = devient limité au meilleur prix en face ; <strong>stop</strong> = seuil de déclenchement ; <strong>iceberg</strong> = quantité cachée ; sans précision = <strong>ordre jour</strong>.</li>\n<li>Priorité : <strong>prix puis heure</strong> (jamais la taille).</li>\n<li>Séance : <strong>préouverture 7 h 15 (cours théorique) → fixing 9 h (volume maximal) → continu jusqu'à 17 h 30 → fixing 17 h 35 (cours de référence) → TAL jusqu'à 17 h 40</strong>.</li>\n<li>Fixing = valeurs <strong>peu liquides</strong> ; forte variation = <strong>suspension de quelques minutes</strong>.</li>\n<li>Pré-négociation MR et MTF : <strong>5 meilleures limites</strong> ; post-négociation : <strong>prix, volume, heure en temps réel</strong> ; nom des PSI <strong>non publié</strong>.</li>\n<li><strong>LEI</strong> = acteurs (INSEE) ; <strong>ISIN</strong> = instruments.</li>\n<li>Reporting des transactions : <strong>J+1 avec l'identité des clients</strong> ; <strong>HFT</strong> : plus de <strong>2 messages par seconde</strong>.</li>\n<li><strong>APA</strong> = publie l'OTC sous 15 min, gratuitement ; <strong>CTP</strong> = consolide ; <strong>ARM</strong> = déclare au régulateur.</li>\n<li>Agences de notation : <strong>risque de crédit</strong>, méthodes publiques, <strong>supervisées par l'ESMA</strong>.</li>\n</ol>\n","toc":[{"id":"9-1-les-lieux-et-modes-dexécution","t":"9.1 Les lieux et modes d'exécution"},{"id":"9-2-les-ordres-et-la-séance-de-bourse-à-paris-catégorie-a","t":"9.2 Les ordres et la séance de bourse à Paris (catégorie A)"},{"id":"9-3-transparence-pré-négociation-et-post-négociation","t":"9.3 Transparence pré-négociation et post-négociation"},{"id":"9-4-les-participants-le-reporting-et-le-trading-algorithmiqu","t":"9.4 Les participants, le reporting et le trading algorithmique"},{"id":"9-5-les-données-de-marché-et-les-agences-de-notation","t":"9.5 Les données de marché et les agences de notation"},{"id":"fiche-flash-du-thème-9","t":"Fiche flash du thème 9"}]},{"id":"10","n":10,"title":"Post-marché et infrastructures de marché","html":"\n<blockquote class=\"note\">\n<p><strong>Poids à l'examen : 3 questions sur 120, catégorie C</strong> : §10.1 (2) · §10.2 (1).\nThème court. Il suffit de ne pas confondre les <strong>trois étages</strong> : <strong>chambre de compensation</strong>, <strong>dépositaire central</strong> et <strong>teneur de compte-conservateur</strong>.</p>\n</blockquote>\n<hr/>\n<h2 id=\"10-1-les-acteurs-du-post-marché\">10.1 Les acteurs du post-marché</h2>\n<h3 id=\"la-chaîne-de-traitement-dune-transaction\">La chaîne de traitement d'une transaction</h3>\n<p><strong>Négociation</strong> (entreprise de marché) → <strong>Compensation</strong> (chambre de compensation) → <strong>Règlement-livraison</strong> (dépositaire central et teneurs de compte).</p>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Acteur</th>\n<th>Rôle</th>\n<th>Moyen de retenir</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Chambre de compensation</strong> (contrepartie centrale)</td>\n<td>Elle <strong>s'interpose</strong> entre l'acheteur et le vendeur par <strong>novation</strong> : elle devient l'<strong>acheteur de chaque vendeur et le vendeur de chaque acheteur</strong>. Elle est la <strong>contrepartie unique</strong>, <strong>garantit la bonne fin</strong> des paiements et livraisons et <strong>protège contre le risque de défaillance</strong>. Elle exige un <strong>dépôt de garantie obligatoire</strong>, fixé par <strong>ses propres règles</strong>, et des <strong>appels de marge</strong>. Elle <strong>publie ses prix et frais</strong> service par service.</td>\n<td><span class=\"tag t-mnemo\">mnémo</span> Le <strong>garant</strong> : « personne ne fait défaut chez moi »</td>\n</tr>\n<tr>\n<td><strong>Dépositaire central</strong> (en France : <strong>Euroclear France</strong>)</td>\n<td>Il fait le <strong>lien entre les émetteurs et les intermédiaires financiers</strong>. Il <strong>enregistre les titres émis en circulation</strong> sur les comptes de ses adhérents et effectue les <strong>virements de compte à compte</strong> entre participants, réalisant ainsi le <strong>transfert de propriété</strong>. Ses <strong>règles de fonctionnement sont approuvées par l'AMF</strong>.</td>\n<td><span class=\"tag t-mnemo\">mnémo</span> Le <strong>grand registre</strong></td>\n</tr>\n<tr>\n<td><strong>Teneur de compte-conservateur (TCC)</strong></td>\n<td>Il <strong>inscrit les titres sur le compte ouvert au nom de l'investisseur</strong> et administre ce compte (opérations sur titres, informations). Il est <strong>habilité par l'ACPR</strong> ; un <strong>établissement de crédit</strong> peut l'être. Il <strong>sépare obligatoirement</strong> ses avoirs propres de ceux de ses clients. Il <strong>pilote le règlement-livraison</strong> pour son client.</td>\n<td><span class=\"tag t-mnemo\">mnémo</span> Le <strong>banquier des titres</strong> de l'investisseur</td>\n</tr>\n<tr>\n<td><strong>TCCP</strong> (teneur de compte-conservateur de parts)</td>\n<td>Il tient les comptes d'<strong>épargne salariale</strong>, depuis 2004</td>\n<td></td>\n</tr>\n<tr>\n<td><strong>Centralisateur</strong></td>\n<td>Il <strong>centralise les ordres de souscription et de rachat</strong> d'un OPC et <strong>contrôle l'heure limite</strong> (late trading, thème 4)</td>\n<td></td>\n</tr>\n<tr>\n<td><strong>Dépositaire d'OPC</strong></td>\n<td><strong>Conservation des actifs + contrôle de la régularité des décisions</strong> de gestion (thème 8.1)</td>\n<td></td>\n</tr>\n<tr>\n<td><strong>SWIFT</strong></td>\n<td>Le <strong>réseau de messagerie</strong> interbancaire, utilisé pour la plupart des paiements internationaux et pour les instructions de règlement-livraison. Ses adhérents sont identifiés par leur <strong>code BIC</strong>.</td>\n<td></td>\n</tr>\n</tbody>\n</table></div>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« La chambre GARANTIT, le dépositaire central ENREGISTRE (et transfère), le teneur de compte INSCRIT chez le client. »</strong></p>\n</aside>\n<h3 id=\"la-tenue-du-passif-dun-opc\">La tenue du passif d'un OPC</h3>\n<p>C'est la <strong>centralisation des ordres de souscription et de rachat</strong> et la <strong>tenue du compte émission</strong> de l'OPC, c'est-à-dire la <strong>réception et l'enregistrement</strong> des ordres. Il ne s'agit ni de la valorisation, ni du contrôle des ratios.</p>\n<h3 id=\"les-modes-de-détention-des-titres\">Les modes de détention des titres</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Mode</th>\n<th>Qui tient le compte ?</th>\n<th>Moyen de retenir</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Au porteur</strong></td>\n<td>L'<strong>intermédiaire financier</strong> (teneur de compte). L'émetteur ne connaît pas nominativement l'actionnaire.</td>\n<td>Le mode le plus courant</td>\n</tr>\n<tr>\n<td><strong>Nominatif pur</strong></td>\n<td><strong>L'émetteur lui-même</strong> (ou son mandataire) tient le compte au nom de l'actionnaire</td>\n<td><span class=\"tag t-mnemo\">mnémo</span> <strong>pur</strong> = directement chez l'émetteur</td>\n</tr>\n<tr>\n<td><strong>Nominatif administré</strong></td>\n<td>Inscription <strong>au registre de l'émetteur</strong>, mais <strong>gestion par l'intermédiaire financier</strong> de l'actionnaire</td>\n<td><span class=\"tag t-mnemo\">mnémo</span> <strong>administré</strong> = l'émetteur connaît l'actionnaire, la banque gère</td>\n</tr>\n</tbody>\n</table></div>\n<p>Le <strong>registre des titres nominatifs</strong> est tenu par <strong>l'émetteur lui-même</strong> (ou un mandataire), jamais par l'AMF.</p>\n<div class=\"ids\" data-sub=\"10.1\"></div>\n<hr/>\n<h2 id=\"10-2-organisation-du-post-marché-règlement-livraison-et-emir\">10.2 Organisation du post-marché, règlement-livraison et EMIR</h2>\n<h3 id=\"le-règlement-livraison\">Le règlement-livraison</h3>\n<ul>\n<li><strong>Délai standard en France et en Europe : J+2</strong> jours ouvrés après la négociation (règlement CSDR).</li>\n<li><strong>Principe de livraison contre paiement</strong> et <strong>délais standard de dénouement</strong>.</li>\n<li><strong>Le transfert de propriété</strong> s'opère <strong>au dénouement du règlement-livraison</strong>, pas au moment de la négociation. C'est aussi le <strong>fait générateur de l'imposition</strong> (thème 12).</li>\n<li>Les règlements en <strong>monnaie banque centrale</strong> sont <strong>irrévocables</strong>.</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« J+2 : je négocie J, je deviens propriétaire J+2. »</strong></p>\n</aside>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p><strong>Passage à J+1</strong> dans l'Union européenne prévu le <strong>11 octobre 2027</strong>. Pour l'instant, la réponse reste J+2.</p>\n</aside>\n<h3 id=\"la-compensation\">La compensation</h3>\n<ul>\n<li>Un <strong>dépôt de garantie est obligatoire</strong>. Sa nature et son étendue sont fixées par les <strong>règles de la chambre</strong>, pas par une autorité européenne.</li>\n<li>Si un client <strong>ne répond pas à un appel de marge</strong>, la chambre peut <strong>clôturer sa position</strong> et <strong>utiliser son dépôt de garantie</strong> pour couvrir la perte.</li>\n</ul>\n<h3 id=\"le-règlement-emir-european-market-infrastructure-regulation\">Le règlement EMIR (<em>European Market Infrastructure Regulation</em>)</h3>\n<ul>\n<li>Il porte sur les <strong>dérivés de gré à gré</strong>, <strong>tous les dérivés OTC</strong>, matières premières comprises.</li>\n<li>Il impose :\n<ol>\n<li>la <strong>compensation obligatoire par une chambre</strong> des dérivés OTC <strong>standardisables</strong> ;</li>\n<li>la <strong>déclaration de toutes les transactions sur dérivés</strong>, <strong>OTC comme sur plateforme</strong>, à des <strong>référentiels centraux</strong> (supervisés par l'ESMA) ;</li>\n<li>des <strong>techniques d'atténuation des risques</strong> pour les dérivés non compensés (échange de garanties).</li>\n</ol>\n</li>\n</ul>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p><strong>EMIR 3</strong> (2024) impose aux acteurs européens de <strong>compenser une partie de leurs dérivés auprès de chambres de l'UE</strong> (« compte actif »).</p>\n</aside>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p><strong>CSDR</strong> : depuis 2022, les <strong>pénalités en cas de retard de règlement</strong> s'appliquent.</p>\n</aside>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p>Le système de paiement <strong>TARGET2</strong> a été remplacé par <strong>T2</strong> (2023).</p>\n</aside>\n<div class=\"ids\" data-sub=\"10.2\"></div>\n<hr/>\n<h2 class=\"flash\" id=\"fiche-flash-du-thème-10\"> Fiche flash du thème 10</h2>\n<ol>\n<li>Chaîne : <strong>négociation → compensation → règlement-livraison</strong>.</li>\n<li><strong>Chambre de compensation</strong> = <strong>novation</strong>, <strong>contrepartie unique</strong>, <strong>garantie de bonne fin</strong>, <strong>dépôt de garantie obligatoire</strong> (ses propres règles), appels de marge, clôture de la position si l'appel n'est pas honoré.</li>\n<li><strong>Dépositaire central</strong> = <strong>Euroclear France</strong> : lien émetteurs ↔ intermédiaires, enregistre les titres en circulation, <strong>virements de compte à compte = transfert de propriété</strong> ; règles <strong>approuvées par l'AMF</strong>.</li>\n<li><strong>TCC</strong> = inscrit les titres <strong>au nom de l'investisseur</strong>, habilité par l'<strong>ACPR</strong>, <strong>ségrégation obligatoire</strong> ; <strong>TCCP</strong> = épargne salariale.</li>\n<li><strong>Nominatif pur</strong> = chez l'émetteur ; <strong>nominatif administré</strong> = registre de l'émetteur, gestion par l'intermédiaire ; registre tenu par l'<strong>émetteur</strong>.</li>\n<li><strong>Passif d'un OPC</strong> = centralisation des souscriptions et rachats et tenue du compte émission.</li>\n<li><strong>J+2</strong> ; <strong>propriété transférée au dénouement</strong> ; livraison contre paiement ; monnaie banque centrale = irrévocable.</li>\n<li><strong>EMIR</strong> = <strong>dérivés OTC</strong> : compensation des dérivés standardisés + <strong>déclaration de tous les dérivés</strong>.</li>\n<li><strong>SWIFT</strong> = messagerie, adhérents identifiés par le <strong>BIC</strong>.</li>\n</ol>\n","toc":[{"id":"10-1-les-acteurs-du-post-marché","t":"10.1 Les acteurs du post-marché"},{"id":"10-2-organisation-du-post-marché-règlement-livraison-et-emir","t":"10.2 Organisation du post-marché, règlement-livraison et EMIR"},{"id":"fiche-flash-du-thème-10","t":"Fiche flash du thème 10"}]},{"id":"11","n":11,"title":"Émissions et opérations sur titres","html":"\n<blockquote class=\"note\">\n<p><strong>Poids à l'examen : 2 questions sur 120, catégorie C</strong> : §11.1 (1) · §11.2 (1).\nPeu de questions, mais des notions simples : marché primaire ou secondaire, prospectus, financement participatif, OPA, OPE, OPR, augmentation de capital, split.</p>\n</blockquote>\n<hr/>\n<h2 id=\"11-1-le-marché-primaire-le-prospectus-et-le-financement-part\">11.1 Le marché primaire, le prospectus et le financement participatif</h2>\n<h3 id=\"marché-primaire-ou-secondaire\">Marché primaire ou secondaire</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Marché</th>\n<th>Ce qui s'y passe</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Primaire</strong> (le « marché du neuf »)</td>\n<td><strong>Émission de titres nouveaux</strong> : <strong>augmentations de capital</strong>, <strong>introductions en bourse</strong>, <strong>émissions d'obligations</strong></td>\n</tr>\n<tr>\n<td><strong>Gris</strong> (<em>grey market</em>)</td>\n<td>Le <strong>trait d'union entre le primaire et le secondaire</strong> : on négocie des titres avant leur règlement définitif</td>\n</tr>\n<tr>\n<td><strong>Secondaire</strong> (la bourse, le « marché de l'occasion »)</td>\n<td><strong>Achat et vente de titres déjà émis</strong></td>\n</tr>\n</tbody>\n</table></div>\n<h3 id=\"les-techniques-démission\">Les techniques d'émission</h3>\n<ul>\n<li><strong>Syndication</strong> : un syndicat de banques place les titres.</li>\n<li><strong>Adjudication</strong> : enchères, utilisées pour les <strong>OAT</strong>. L'adjudication <strong>« au prix demandé »</strong> (chacun paie le prix qu'il a proposé) est dite <strong>« à la hollandaise »</strong>.</li>\n<li><strong>Prise ferme</strong> : le PSI <strong>souscrit ou achète directement à l'émetteur</strong> des titres <strong>pour les revendre</strong>. Il porte le risque de ne pas les placer.</li>\n<li><strong>Placement garanti</strong> : le PSI recherche des souscripteurs et <strong>garantit à l'émetteur un montant minimum</strong> de souscription.</li>\n<li><strong>Placement non garanti</strong> : le PSI <strong>recherche des souscripteurs</strong> pour l'émetteur <strong>sans lui garantir de montant</strong>.</li>\n<li><strong>Sondage de marché</strong> :\n<ul>\n<li>il permet de <strong>tester l'intérêt des investisseurs</strong> (taux, maturité…) avant une émission ;</li>\n<li>il est <strong>autorisé mais très encadré</strong> (règlement MAR) ;</li>\n<li>le PSI peut transmettre des <strong>informations privilégiées</strong> à condition d'<strong>informer les destinataires de leur caractère privilégié</strong> et d'<strong>obtenir leur accord</strong>.</li>\n</ul>\n</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>Prise ferme = j'achète tout et je revends ; garanti = je promets un montant ; non garanti = je fais de mon mieux.</strong></p>\n</aside>\n<h3 id=\"le-prospectus-et-linformation-des-émetteurs\">Le prospectus et l'information des émetteurs</h3>\n<ul>\n<li>Pour une <strong>offre au public</strong> ou une <strong>admission sur un marché réglementé</strong>, l'émetteur publie un <strong>prospectus approuvé par l'AMF</strong> (et non par Euronext). Ce <strong>n'est pas un document confidentiel</strong>.</li>\n<li><strong>Contenu</strong> : les informations qui permettent d'évaluer <strong>le patrimoine, la situation financière, les résultats et les perspectives</strong> de l'émetteur, ainsi que les <strong>droits attachés aux titres</strong> et les <strong>conditions de l'émission</strong>.</li>\n<li>Les <strong>commissaires aux comptes attestent</strong> que les <strong>informations prévisionnelles ou pro forma</strong> ont été correctement établies.</li>\n<li>Les documents officiels sont diffusés par <strong>l'AMF et l'émetteur</strong>.</li>\n<li><strong>Seuil de prospectus</strong> : selon la base, une offre au public <strong>au-delà de 8 M€</strong> exige un prospectus.</li>\n</ul>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p>Le <strong>Listing Act</strong> (2024) a relevé ce seuil à <strong>12 M€</strong> sur 12 mois à partir de <strong>mars 2026</strong>. Il a aussi créé des prospectus allégés (« EU Follow-on », « EU Growth issuance »).\nLe <strong>document d'enregistrement universel (DEU)</strong> est traité au thème 12.2.</p>\n</aside>\n<h3 id=\"le-financement-participatif-crowdfunding\">Le financement participatif (<em>crowdfunding</em>)</h3>\n<ul>\n<li>Il met en relation, <strong>via internet</strong>, des porteurs de projets (souvent <strong>non cotés</strong>) et des investisseurs. Il est <strong>réglementé</strong> et <strong>risqué</strong> : pas de garantie de capital.</li>\n<li><strong>Trois formes</strong> : <strong>actions ou obligations</strong>, <strong>prêts</strong>, <strong>dons</strong>.</li>\n<li>Il <strong>n'est pas géré par un syndicat bancaire</strong> et ne dépasse pas les émissions obligataires en volume.</li>\n<li><strong>Dans la base</strong> : les plateformes de <strong>prêts et de dons</strong> ont le statut d'<strong>IFP</strong> ; les <strong>minibons</strong> sont assimilés à des bons de caisse.</li>\n</ul>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p>Depuis le <strong>10 novembre 2023</strong>, le <strong>règlement européen ECSP</strong> s'applique :</p>\n<ul>\n<li>les plateformes d'<strong>investissement et de prêt aux entreprises</strong> sont des <strong>PSFP agréés par l'AMF</strong>, avec passeport européen ;</li>\n<li>le plafond est de <strong>5 M€ par projet sur 12 mois</strong> ;</li>\n<li>les statuts de <strong>CIP</strong> et les <strong>minibons</strong> ont disparu ;</li>\n<li>l'<strong>IFP</strong> subsiste pour certains prêts et pour les dons.</li>\n</ul>\n</aside>\n<div class=\"ids\" data-sub=\"11.1\"></div>\n<hr/>\n<h2 id=\"11-2-lintroduction-en-bourse-les-offres-publiques-et-les-opé\">11.2 L'introduction en bourse, les offres publiques et les opérations sur titres</h2>\n<h3 id=\"lintroduction-en-bourse\">L'introduction en bourse</h3>\n<ul>\n<li><strong>Diffusion minimale</strong> sur Euronext Paris : <strong>25 % du capital, ou 5 % si cela représente au moins 5 M€</strong>.</li>\n<li>Dans une <strong>offre à prix ouvert (OPO)</strong>, la quasi-totalité des ordres, de particuliers comme de professionnels, sont <strong>révocables</strong> pendant l'offre.</li>\n</ul>\n<h3 id=\"les-offres-publiques\">Les offres publiques</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Offre</th>\n<th>Contrepartie offerte</th>\n<th>Moyen de retenir</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>OPA</strong> (offre publique d'<strong>acquisition</strong>, d'achat)</td>\n<td>Des <strong>espèces</strong> (liquidités)</td>\n<td><span class=\"tag t-mnemo\">mnémo</span> <strong>A = Argent</strong></td>\n</tr>\n<tr>\n<td><strong>OPE</strong> (offre publique d'<strong>échange</strong>)</td>\n<td>D'<strong>autres titres</strong>, cotés, émis ou à émettre</td>\n<td><span class=\"tag t-mnemo\">mnémo</span> <strong>E = Échange de titres</strong></td>\n</tr>\n<tr>\n<td><strong>Offre mixte</strong></td>\n<td><strong>Espèces ET titres</strong></td>\n<td></td>\n</tr>\n<tr>\n<td><strong>OPR</strong> (offre publique de <strong>retrait</strong>)</td>\n<td>Permet aux minoritaires de sortir quand l'actionnaire majoritaire contrôle déjà la société (90 %) ; elle est souvent suivie d'un <strong>retrait obligatoire</strong></td>\n<td><span class=\"tag t-mnemo\">mnémo</span> <strong>R = Retrait de la cote</strong></td>\n</tr>\n</tbody>\n</table></div>\n<ul>\n<li><strong>L'OPA permet de prendre le contrôle</strong> d'une société en rachetant ses actions à ses actionnaires. L'initiateur n'est pas forcément une personne morale.</li>\n<li><strong>Offre obligatoire</strong> : dès le <strong>franchissement de 30 % du capital ou des droits de vote</strong>. Ni 25 %, ni 40 %.</li>\n<li><strong>Offre amicale</strong> : le <strong>conseil d'administration de la cible recommande</strong> d'apporter les titres. Sinon, l'offre est <strong>hostile</strong>.</li>\n<li><strong>Action de concert</strong> : un <strong>accord entre personnes</strong> pour <strong>acquérir, céder ou exercer des droits de vote</strong> afin de mener <strong>une politique commune</strong> ou de <strong>prendre le contrôle</strong>. Les participations des concertistes <strong>s'additionnent</strong> pour le calcul des seuils.</li>\n<li>L'initiateur peut offrir une <strong>option de cession différée</strong>, si elle est <strong>exerçable dans un délai raisonnable</strong>, <strong>subsidiaire</strong> à l'offre principale et <strong>garantie par la banque présentatrice</strong>.</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« 30 % = OPA obligatoire. »</strong></p>\n</aside>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p>Depuis la loi PACTE (2019), le <strong>retrait obligatoire</strong> est possible dès <strong>90 %</strong> du capital et des droits de vote (contre 95 % auparavant).</p>\n</aside>\n<h3 id=\"les-opérations-sur-le-capital\">Les opérations sur le capital</h3>\n<ul>\n<li><strong>Augmentation de capital</strong> :\n<ul>\n<li>décidée par l'<strong>assemblée générale extraordinaire (AGE)</strong> ;</li>\n<li><strong>en numéraire</strong> (apport d'argent) <strong>ou à titre gratuit</strong> (<strong>incorporation de réserves</strong>), ou par apport en nature.</li>\n</ul>\n</li>\n<li><strong>Split (division du nominal)</strong> : on <strong>divise la valeur nominale</strong> d'une action en plusieurs titres. <strong>Ce n'est pas une augmentation de capital</strong> : le capital ne change pas.</li>\n<li><strong>Fusion-absorption</strong> : <strong>une seule société subsiste</strong>, l'autre est <strong>dissoute</strong> ; ses actionnaires <strong>reçoivent des actions nouvelles</strong> de l'absorbante. Une <strong>scission</strong> fait l'inverse : une société se divise.</li>\n<li><strong>Dividende</strong> : les <strong>statuts peuvent prévoir l'option</strong> d'un paiement <strong>en espèces ou en actions</strong> ; ce n'est ni obligatoire, ni interdit.</li>\n<li>Le <strong>paiement d'un dividende</strong> est une <strong>opération sur titres</strong> (OST), contrairement à un simple achat ou à une vente.</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>Split = on coupe la pizza en plus de parts : même pizza (même capital), plus de parts, chacune moins chère.</strong></p>\n</aside>\n<div class=\"ids\" data-sub=\"11.2\"></div>\n<hr/>\n<h2 class=\"flash\" id=\"fiche-flash-du-thème-11\"> Fiche flash du thème 11</h2>\n<ol>\n<li><strong>Primaire</strong> = titres <strong>nouveaux</strong> ; <strong>secondaire</strong> = titres <strong>existants</strong> ; <strong>gris</strong> = entre les deux.</li>\n<li><strong>Prise ferme</strong> = le PSI achète pour revendre ; <strong>placement non garanti</strong> = aucun montant garanti ; <strong>adjudication au prix demandé</strong> = « à la hollandaise ».</li>\n<li><strong>Sondage de marché</strong> = autorisé si les destinataires sont <strong>informés du caractère privilégié et d'accord</strong>.</li>\n<li><strong>Prospectus</strong> : patrimoine, situation financière, résultats, perspectives, droits, conditions ; <strong>approuvé par l'AMF</strong> ; prévisions <strong>attestées par les CAC</strong> ; seuil de <strong>8 M€</strong> dans la base (<strong>12 M€</strong> depuis 2026).</li>\n<li><strong>Crowdfunding</strong> : <strong>actions, prêts, dons</strong>, via internet ; aujourd'hui <strong>ECSP / PSFP</strong> (5 M€ par projet).</li>\n<li>Introduction en bourse : <strong>25 % ou 5 % ≥ 5 M€</strong> ; ordres de l'OPO <strong>révocables</strong>.</li>\n<li><strong>OPA = espèces</strong>, <strong>OPE = titres</strong>, <strong>mixte = les deux</strong> ; <strong>30 % = offre obligatoire</strong> ; <strong>amicale</strong> = recommandée par le CA de la cible ; <strong>concert</strong> = politique commune.</li>\n<li>Augmentation de capital : <strong>AGE</strong>, en <strong>numéraire ou gratuite</strong> ; <strong>split</strong> = division du nominal, <strong>pas</strong> une augmentation ; <strong>fusion</strong> = une société subsiste, nouvelles actions pour les absorbés.</li>\n</ol>\n","toc":[{"id":"11-1-le-marché-primaire-le-prospectus-et-le-financement-part","t":"11.1 Le marché primaire, le prospectus et le financement participatif"},{"id":"11-2-lintroduction-en-bourse-les-offres-publiques-et-les-opé","t":"11.2 L'introduction en bourse, les offres publiques et les opérations sur titres"},{"id":"fiche-flash-du-thème-11","t":"Fiche flash du thème 11"}]},{"id":"12","n":12,"title":"Bases comptables, financières et fiscales","html":"\n<blockquote class=\"note\">\n<p><strong>Poids à l'examen : 6 questions sur 120, catégorie C.</strong>\nRépartition : §12.1 (2) · §12.2 (1) · §12.3 (2) · §12.4 (1).</p>\n<p>La comptabilité se réduit à <strong>« bilan = photo, compte de résultat = film »</strong>. La fiscalité se concentre sur le <strong>PFU</strong>, le <strong>PEA</strong>, l'<strong>assurance-vie</strong> et l'<strong>IFI</strong>.</p>\n</blockquote>\n<hr/>\n<h2 id=\"12-1-bilan-compte-de-résultat-soldes-de-gestion-ratios\">12.1 Bilan, compte de résultat, soldes de gestion, ratios</h2>\n<h3 id=\"les-comptes-annuels\">Les comptes annuels</h3>\n<ul>\n<li><strong>En normes françaises</strong> : <strong>bilan + compte de résultat + annexe</strong>. Les comptes <strong>consolidés</strong> concernent les groupes.</li>\n<li><strong>Principe de prudence</strong>.</li>\n<li><strong>Conservation</strong> des documents comptables et des pièces justificatives : <strong>10 ans</strong> (et non 5 ans comme pour la LCB-FT).</li>\n<li>Le bilan et le compte de résultat sont regroupés dans la <strong>liasse fiscale</strong>.</li>\n<li>Les comptes d'une société cotée sont <strong>certifiés par les commissaires aux comptes</strong>, ni par l'expert-comptable, ni par l'ANC.</li>\n</ul>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th></th>\n<th><strong>Bilan</strong> (la photo à une date donnée)</th>\n<th><strong>Compte de résultat</strong> (le film de l'exercice)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Contenu</td>\n<td><strong>Actif</strong> (ce que l'entreprise possède) et <strong>passif</strong> (ses <strong>ressources</strong> : <strong>capitaux propres + dettes</strong>), avec les capitaux propres <strong>distincts</strong></td>\n<td><strong>Produits</strong> et <strong>charges</strong> de l'exercice, <strong>quelle que soit leur date d'encaissement ou de paiement</strong> (comptabilité d'engagement)</td>\n</tr>\n<tr>\n<td>Exemples</td>\n<td><strong>Actif</strong> : <strong>immobilisations</strong> (dont les <strong>immobilisations financières</strong>, des titres détenus à long terme), <strong>stocks</strong>, <strong>créances clients</strong>, trésorerie. <strong>Passif</strong> : <strong>capital social</strong>, réserves, <strong>provisions</strong>, <strong>dettes fournisseurs</strong>, dettes d'exploitation, dettes financières.</td>\n<td><strong>Produits</strong> : <strong>chiffre d'affaires</strong>, <strong>production stockée</strong>, produits financiers. <strong>Charges</strong> : <strong>frais de personnel</strong>, achats, loyers, <strong>dotations aux amortissements et provisions</strong>, <strong>charges financières</strong>, impôts.</td>\n</tr>\n<tr>\n<td>Usage</td>\n<td>Comparer l'actif et le passif d'une année sur l'autre</td>\n<td>Calculer les <strong>soldes intermédiaires de gestion (SIG)</strong></td>\n</tr>\n</tbody>\n</table></div>\n<ul>\n<li><strong>Classement de l'actif</strong> (plan comptable général) : par <strong>liquidité croissante</strong>, des immobilisations jusqu'à la trésorerie.</li>\n<li><strong>Passif</strong> : une <strong>obligation envers un tiers</strong> qui provoquera une <strong>sortie de ressources sans contrepartie équivalente</strong>.</li>\n<li><strong>Provision</strong> : un <strong>passif</strong> dont l'<strong>échéance ou le montant est incertain</strong>. Elle figure <strong>uniquement au passif</strong> du bilan, et sa dotation est une <strong>charge</strong> du compte de résultat.</li>\n<li><strong>Amortissement</strong> : il <strong>constate l'usure</strong> des immobilisations.</li>\n<li>Le <strong>bénéfice non distribué</strong> <strong>augmente les capitaux propres</strong> (réserves).</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« Le bilan dit CE QUE J'AI et D'OÙ ÇA VIENT ; le compte de résultat dit CE QUE J'AI GAGNÉ cette année. »</strong></p>\n</aside>\n<aside class=\"callout c-warn\"><span class=\"callout-label\">Piège</span>\n<p>Le <strong>capital</strong> est au <strong>passif</strong> du bilan. La <strong>production stockée</strong> est un <strong>produit</strong>, pas une charge.</p>\n</aside>\n<h3 id=\"les-soldes-intermédiaires-de-gestion-calculés-à-partir-du-co\">Les soldes intermédiaires de gestion (calculés à partir du compte de résultat)</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>SIG</th>\n<th>Calcul</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Marge commerciale</strong></td>\n<td><strong>Ventes de marchandises HT − coût d'achat HT</strong> des marchandises vendues</td>\n</tr>\n<tr>\n<td><strong>Valeur ajoutée (VA)</strong></td>\n<td><strong>Production − consommations</strong> (richesse brute créée)</td>\n</tr>\n<tr>\n<td><strong>Excédent brut d'exploitation (EBE)</strong></td>\n<td><strong>VA (+ subventions) − charges de personnel − impôts et taxes</strong></td>\n</tr>\n<tr>\n<td>Résultat d'exploitation → résultat net</td>\n<td></td>\n</tr>\n<tr>\n<td><strong>CAF</strong> (capacité d'autofinancement)</td>\n<td>La <strong>trésorerie potentielle</strong> dégagée par l'activité : les <strong>ressources internes</strong> de l'entreprise</td>\n</tr>\n</tbody>\n</table></div>\n<h3 id=\"les-ratios\">Les ratios</h3>\n<ul>\n<li><strong>Rentabilité financière</strong> des capitaux propres (ROE) = <strong>résultat net / capitaux propres</strong>.</li>\n<li><strong>Autonomie financière</strong> = <strong>capitaux propres / total de l'actif</strong> (ou du passif).</li>\n</ul>\n<div class=\"ids\" data-sub=\"12.1\"></div>\n<hr/>\n<h2 id=\"12-2-linformation-financière-des-sociétés-cotées-et-les-fran\">12.2 L'information financière des sociétés cotées et les franchissements de seuils</h2>\n<h3 id=\"linformation-périodique-sociétés-cotées-sur-un-marché-réglem\">L'information périodique (sociétés cotées sur un marché réglementé)</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Document</th>\n<th>Délai</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Rapport financier annuel</strong> (comptes sociaux et consolidés <strong>en intégralité</strong>)</td>\n<td><strong>4 mois</strong> après la clôture</td>\n</tr>\n<tr>\n<td><strong>Rapport financier semestriel</strong></td>\n<td><strong>3 mois</strong> après la fin du semestre</td>\n</tr>\n</tbody>\n</table></div>\n<ul>\n<li>L'information porte sur l'<strong>activité et la situation financière</strong>, pas sur l'âge des dirigeants ni sur un <strong>plan de développement</strong>, qu'elles n'ont pas à publier.</li>\n<li>Elle est <strong>identique et simultanée en France et à l'étranger</strong>.</li>\n<li>L'AMF <strong>recommande de publier les informations importantes en dehors des heures de bourse</strong>.</li>\n<li>Les <strong>présentations</strong> remises aux analystes sont <strong>mises en ligne au plus tard au début de la réunion</strong>.</li>\n<li><strong>Avertissement sur résultats</strong> (<em>profit warning</em>) : à la <strong>baisse comme à la hausse</strong>.</li>\n<li>Tout <strong>projet de modification des statuts</strong> est communiqué à l'AMF <strong>au plus tard à la convocation</strong> de l'assemblée.</li>\n<li>Un émetteur qui rachète <strong>plus de 10 % d'un emprunt obligataire</strong> en informe le marché <strong>sous 4 jours de négociation</strong>.</li>\n<li><strong>Visa de l'AMF</strong> : il atteste que <strong>les informations nécessaires sont à la disposition du public</strong>. <strong>Ce n'est ni une recommandation d'investir, ni une certification des comptes.</strong></li>\n</ul>\n<h3 id=\"le-document-denregistrement-universel-deu-ex--document-de-ré\">Le document d'enregistrement universel (DEU, ex-« document de référence »)</h3>\n<ul>\n<li>Il est <strong>facultatif</strong> et <strong>annuel</strong>. Il peut être le <strong>rapport financier annuel</strong> s'il contient toutes les informations requises.</li>\n<li>Il peut être <strong>actualisé à tout moment</strong>.</li>\n<li>Il est <strong>approuvé par l'AMF</strong>. Après <strong>deux exercices consécutifs approuvés</strong>, il peut être <strong>déposé sans approbation préalable</strong>.</li>\n<li>L'AMF <strong>notifie le certificat d'approbation à l'ESMA</strong> : il n'y a pas de double approbation.</li>\n</ul>\n<h3 id=\"les-franchissements-de-seuils\">Les franchissements de seuils</h3>\n<ul>\n<li><strong>Seuils légaux</strong> : <strong>5 %, 10 %, 15 %, 20 %, 25 %, 30 %, 1/3, 50 %, 2/3, 90 % et 95 %</strong> du capital ou des droits de vote.</li>\n<li><strong>Déclaration</strong> à la société <strong>et à l'AMF</strong>, <strong>au plus tard le 4e jour de négociation</strong> après le franchissement.</li>\n<li>Elle est due <strong>à la hausse comme à la baisse</strong>, <strong>dans tous les cas</strong>.</li>\n<li>Aux seuils de 10, 15, 20 et 25 %, il faut aussi une <strong>déclaration d'intentions</strong> pour les 6 mois à venir.</li>\n<li><strong>Sanction</strong> : les actions excédentaires sont <strong>privées de droit de vote pendant 2 ans</strong> après la régularisation.</li>\n<li>Rappel : à <strong>30 %</strong>, l'<strong>offre publique est obligatoire</strong> (thème 11).</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« 4 / 3 / 4 »</strong> : rapport annuel sous <strong>4 mois</strong>, semestriel sous <strong>3 mois</strong>, franchissement de seuil déclaré sous <strong>4 jours de bourse</strong>.</p>\n</aside>\n<div class=\"ids\" data-sub=\"12.2\"></div>\n<hr/>\n<h2 id=\"12-3-la-fiscalité-des-particuliers\">12.3 La fiscalité des particuliers</h2>\n<h3 id=\"limpôt-sur-le-revenu-ir\">L'impôt sur le revenu (IR)</h3>\n<ul>\n<li>Il est <strong>progressif</strong>, par tranches : 0 %, 11 %, 30 %, 41 %, <strong>45 %</strong> (taux marginal maximal).</li>\n<li>Il porte sur <strong>tous les revenus</strong> du foyer.</li>\n<li>Il concerne les <strong>résidents fiscaux</strong> (sur leurs revenus mondiaux) <strong>ET les non-résidents</strong> sur leurs <strong>revenus de source française</strong>.</li>\n<li><strong>Quotient familial</strong> = <strong>revenu imposable / nombre de parts</strong>. Il tient compte de la <strong>situation de famille</strong>.\n<ul>\n<li>Exemple : un <strong>couple marié avec 3 enfants</strong> a <strong>4 parts</strong> (2 + 0,5 + 0,5 + 1, le 3e enfant comptant pour une part entière).</li>\n</ul>\n</li>\n<li><strong>Salaires</strong> : abattement forfaitaire de <strong>10 %</strong> pour frais professionnels, sauf option pour les frais réels.</li>\n<li>Les <strong>déductions</strong> diminuent le <strong>revenu imposable</strong>. Les <strong>niches fiscales</strong> sont plafonnées à <strong>10 000 €</strong> par foyer et par an.</li>\n<li><strong>Plafonnement</strong> : le total des impôts ne peut dépasser <strong>75 % des revenus</strong>.</li>\n</ul>\n<h3 id=\"les-prélèvements-sociaux-et-le-pfu-flat-tax-depuis-2018\">Les prélèvements sociaux et le PFU (« flat tax », depuis 2018)</h3>\n<ul>\n<li><strong>PFU = 30 %</strong> : <strong>12,8 % d'IR + 17,2 % de prélèvements sociaux</strong>.</li>\n<li>Il s'applique <strong>par défaut</strong> aux <strong>dividendes</strong>, <strong>intérêts</strong> (compte à terme, <strong>PEL ouverts depuis 2018 dès la 1re année</strong>) et <strong>plus-values mobilières</strong>.</li>\n<li>Option <strong>globale</strong> possible pour le <strong>barème progressif</strong>.</li>\n<li>Les <strong>prélèvements sociaux</strong> (CSG, CRDS…) frappent <strong>tous les revenus du patrimoine et de placement</strong>, <strong>sauf les livrets défiscalisés</strong> : <strong>livret A, LEP, LDD, livret jeune</strong>.\n<ul>\n<li>Ils frappent les revenus du capital <strong>financier et immobilier</strong>.</li>\n<li>La <strong>CSG</strong> porte sur le <strong>brut</strong> des revenus d'activité et financiers, et sur le <strong>net</strong> des revenus fonciers.</li>\n</ul>\n</li>\n</ul>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p><strong>À vérifier</strong> : la loi de financement de la Sécurité sociale pour 2026 a relevé la CSG sur une partie des revenus du capital. Les prélèvements sociaux passeraient à <strong>18,6 %</strong> et la flat tax à <strong>31,4 %</strong>, avec des exceptions (assurance-vie, revenus fonciers…). La base raisonne avec <strong>17,2 % et 30 %</strong>.</p>\n</aside>\n<h3 id=\"les-plus-values\">Les plus-values</h3>\n<ul>\n<li><strong>Mobilières</strong> : soumises au PFU, ou au barème sur option. Les <strong>prélèvements sociaux s'appliquent dès le premier euro</strong>.\n<ul>\n<li>Les <strong>moins-values</strong> s'imputent sur les <strong>plus-values de même nature</strong> pendant <strong>10 ans</strong>, jamais sur des plus-values immobilières.</li>\n<li>Le <strong>fait générateur</strong> de l'impôt est le <strong>transfert de propriété</strong> (J+2 après l'exécution).</li>\n</ul>\n</li>\n<li><strong>Immobilières</strong> : taux forfaitaire de <strong>19 %</strong> + prélèvements sociaux, avec des <strong>abattements pour durée de détention</strong>.</li>\n</ul>\n<h3 id=\"les-enveloppes\">Les enveloppes</h3>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Enveloppe</th>\n<th>Fiscalité</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>PEA</strong></td>\n<td><strong>Avant 5 ans</strong> : retrait = clôture (sauf exceptions), gains imposés selon le <strong>régime des plus-values mobilières</strong> (PFU). <strong>Après 5 ans</strong> : gains <strong>exonérés d'IR</strong>, <strong>mais soumis aux prélèvements sociaux</strong>. La fiscalité <strong>dépend donc de la durée de détention</strong>. Plafond des versements : 150 000 €.</td>\n</tr>\n<tr>\n<td><strong>Assurance-vie</strong> (primes versées depuis le 27 septembre 2017)</td>\n<td><strong>Avant 8 ans</strong> : <strong>PFU de 12,8 %</strong> ou barème. <strong>Après 8 ans</strong> : <strong>abattement annuel de 4 600 €</strong> (personne seule) <strong>ou 9 200 €</strong> (couple), puis taux réduit de 7,5 % (jusqu'à 150 000 € de primes). <strong>Prélèvements sociaux toujours dus</strong>. <strong>Rente viagère</strong> : seule une <strong>fraction</strong>, qui dépend de l'<strong>âge au premier versement</strong>, est imposable. <strong>Décès</strong> : le bénéficiaire est <strong>exonéré de droits de succession dans certaines limites et sous conditions</strong>.</td>\n</tr>\n<tr>\n<td><strong>PEL ouvert depuis 2018</strong></td>\n<td>Imposé au PFU <strong>dès la première année</strong></td>\n</tr>\n</tbody>\n</table></div>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« PEA 5 ans, assurance-vie 8 ans. »</strong></p>\n</aside>\n<h3 id=\"limpôt-sur-la-fortune-immobilière-ifi\">L'impôt sur la fortune immobilière (IFI)</h3>\n<ul>\n<li>Il <strong>remplace l'ISF depuis le 1er janvier 2018</strong> et porte <strong>uniquement sur le patrimoine immobilier</strong>, au <strong>1er janvier</strong>. Il ne touche ni le revenu, ni le portefeuille boursier.</li>\n<li><strong>Redevables</strong> : les <strong>personnes physiques</strong> domiciliées en France, sur leurs <strong>biens immobiliers en France et hors de France</strong>. Les non-résidents ne paient que sur leurs biens situés en France.</li>\n<li><strong>Imposition commune</strong> : couples <strong>mariés</strong> (sauf exception), <strong>pacsés</strong> et <strong>concubins notoires</strong>.</li>\n<li><strong>Exonération</strong> : l'immobilier affecté à l'<strong>activité professionnelle</strong> (y compris via une SCI).</li>\n<li>Seuil de taxation : patrimoine immobilier net <strong>supérieur à 1,3 M€</strong>.</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>IFI = Immobilier, Foyer (mariés, pacsés, concubins), France + étranger pour les résidents.</strong></p>\n</aside>\n<h3 id=\"autres-points\">Autres points</h3>\n<ul>\n<li><strong>Droits de succession et de donation</strong> : calculés sur la <strong>part nette de chaque bénéficiaire, après abattements</strong>.</li>\n<li><strong>TTF</strong> (taxe sur les transactions financières) : <strong>0,3 %</strong> de l'acquisition d'actions françaises cotées de grandes capitalisations, depuis 2017.</li>\n<li><strong>Pinel</strong> : une <strong>réduction d'IR</strong> pour l'<strong>achat d'un logement neuf mis en location</strong>.</li>\n</ul>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p>La <strong>TTF est passée à 0,4 %</strong> au 1er avril 2025. Le <strong>Pinel</strong> a pris fin pour les acquisitions après le <strong>31 décembre 2024</strong>.</p>\n</aside>\n<div class=\"ids\" data-sub=\"12.3\"></div>\n<hr/>\n<h2 id=\"12-4-la-fiscalité-des-sociétés\">12.4 La fiscalité des sociétés</h2>\n<h3 id=\"le-champ-de-limpôt-sur-les-sociétés-is\">Le champ de l'impôt sur les sociétés (IS)</h3>\n<ul>\n<li>L'<strong>IS</strong> porte sur les <strong>bénéfices</strong> (pas sur le chiffre d'affaires). Taux normal <strong>25 %</strong>, taux réduit de 15 % pour les PME sur une première tranche de bénéfice.</li>\n<li><strong>Sociétés de capitaux</strong> (<strong>SA</strong>, SAS…) : soumises <strong>de plein droit</strong> à l'IS.</li>\n<li><strong>Sociétés de personnes</strong> (SNC, sociétés civiles, EURL avec un associé personne physique) : <strong>imposées à l'IR</strong> de leurs associés (transparence), <strong>avec option possible pour l'IS</strong>.</li>\n<li><strong>Territorialité</strong> : sont imposés les bénéfices des <strong>activités exercées en France</strong>.</li>\n<li><strong>Paiement</strong> : <strong>4 acomptes pendant l'année N</strong>, puis le <strong>solde en N+1</strong>.</li>\n<li><strong>Catégories de l'IR</strong> pour les entrepreneurs individuels :\n<ul>\n<li><strong>BIC</strong> (bénéfices industriels et commerciaux) : activités <strong>commerciales, industrielles, artisanales</strong> ;</li>\n<li><strong>BNC</strong> (bénéfices non commerciaux) : <strong>professions libérales</strong>.</li>\n</ul>\n</li>\n</ul>\n<h3 id=\"les-placements-des-entreprises\">Les placements des entreprises</h3>\n<ul>\n<li>Les <strong>revenus financiers</strong> (intérêts, livrets, titres à revenu fixe, placements de trésorerie) sont <strong>intégrés au résultat et imposés à l'IS au taux normal</strong>. Il n'y a ni prélèvement libératoire, ni taux spécial.</li>\n<li>Les <strong>intérêts</strong> sont rattachés à l'exercice <strong>au cours duquel ils ont couru</strong>, même s'ils ne sont pas encore perçus.</li>\n<li>Les <strong>plus-values sur titres de placement et sur OPC</strong> sont imposées <strong>au taux normal de l'IS</strong>.</li>\n<li><strong>Plus-values latentes sur OPC</strong> (CGI art. 209-0 A) :\n<ul>\n<li>les parts d'<strong>OPC français ou étrangers</strong> détenues à la clôture sont <strong>imposées sur leur plus-value latente</strong> (écart de valeur liquidative), sans sursis ;</li>\n<li><strong>exception</strong> : les OPC investis en permanence à <strong>90 % au moins en actions</strong>.</li>\n</ul>\n</li>\n<li>Les <strong>titres cotés</strong> sont <strong>évalués à chaque clôture</strong>, avec une <strong>provision</strong> en cas de dépréciation.</li>\n<li><strong>Régime mère-fille</strong> : les dividendes d'une filiale sont <strong>exonérés</strong>, <strong>sauf une quote-part de frais et charges de 5 %</strong>.</li>\n<li>Les sommes souscrites au capital de <strong>PME innovantes</strong> peuvent être <strong>amorties sur 5 ans</strong>.</li>\n<li>Une entreprise place sa trésorerie de préférence en <strong>supports peu risqués</strong>.</li>\n</ul>\n<aside class=\"callout c-mnemo\"><span class=\"callout-label\">Moyen mnémotechnique</span>\n<p><strong>« Pour une société, tout passe à l'IS au taux normal ; même les plus-values latentes sur OPC (sauf fonds 90 % actions). »</strong></p>\n</aside>\n<div class=\"ids\" data-sub=\"12.4\"></div>\n<hr/>\n<h2 class=\"flash\" id=\"fiche-flash-du-thème-12\"> Fiche flash du thème 12</h2>\n<ol>\n<li><strong>Bilan</strong> = actif (immobilisations, stocks, créances) / passif (capital, réserves, <strong>provisions</strong>, dettes) ; <strong>compte de résultat</strong> = produits (CA, production stockée) / charges (personnel, amortissements, charges financières), <strong>sans tenir compte des dates d'encaissement</strong>.</li>\n<li>Actif classé par <strong>liquidité croissante</strong> ; documents comptables conservés <strong>10 ans</strong> ; principe de <strong>prudence</strong> ; comptes annuels = <strong>bilan + compte de résultat + annexe</strong>.</li>\n<li><strong>Marge commerciale</strong> = ventes − coût d'achat ; <strong>VA</strong> = production − consommations ; <strong>EBE</strong> = VA − personnel − impôts ; <strong>CAF</strong> = ressources internes ; <strong>ROE</strong> = résultat net / capitaux propres.</li>\n<li>Sociétés cotées : <strong>rapport annuel sous 4 mois</strong>, <strong>semestriel sous 3 mois</strong> ; information <strong>identique et simultanée</strong> ; visa AMF ≠ recommandation.</li>\n<li>Seuils : <strong>5 / 10 / 15 / 20 / 25 / 30 / 1/3 / 50 / 2/3 / 90 / 95 %</strong>, déclarés <strong>sous 4 jours de bourse</strong>, à la hausse et à la baisse ; sanction = <strong>privation des droits de vote pendant 2 ans</strong>.</li>\n<li><strong>DEU</strong> facultatif, mis à jour à tout moment, dispense d'approbation après <strong>2 ans</strong>.</li>\n<li>IR <strong>progressif</strong>, taux maximal <strong>45 %</strong> ; <strong>quotient familial</strong> (couple + 3 enfants = <strong>4 parts</strong>) ; abattement <strong>10 %</strong> sur les salaires ; niches plafonnées à <strong>10 000 €</strong>.</li>\n<li><strong>PFU 30 % = 12,8 % + 17,2 %</strong> (option barème) ; prélèvements sociaux sur tout sauf <strong>livret A, LEP, LDD, livret jeune</strong>.</li>\n<li>Moins-values : <strong>10 ans</strong>, sur des plus-values de même nature ; plus-values immobilières : <strong>19 %</strong> + prélèvements sociaux.</li>\n<li><strong>PEA</strong> : exonéré d'IR après <strong>5 ans</strong> (prélèvements sociaux dus) ; <strong>assurance-vie</strong> : abattement de <strong>4 600 / 9 200 €</strong> après <strong>8 ans</strong>.</li>\n<li><strong>IFI</strong> = <strong>immobilier</strong> seulement, au 1er janvier, remplace l'ISF ; mariés, pacsés et concubins imposés ensemble ; immobilier professionnel exonéré.</li>\n<li><strong>IS</strong> sur les <strong>bénéfices</strong> ; SA = IS de plein droit ; sociétés de personnes = IR (option IS) ; revenus et plus-values financiers au <strong>taux normal</strong> ; <strong>mère-fille = 5 %</strong> imposé ; plus-values <strong>latentes</strong> sur OPC imposées (sauf fonds 90 % actions).</li>\n</ol>\n","toc":[{"id":"12-1-bilan-compte-de-résultat-soldes-de-gestion-ratios","t":"12.1 Bilan, compte de résultat, soldes de gestion, ratios"},{"id":"12-2-linformation-financière-des-sociétés-cotées-et-les-fran","t":"12.2 L'information financière des sociétés cotées et les franchissements de seuils"},{"id":"12-3-la-fiscalité-des-particuliers","t":"12.3 La fiscalité des particuliers"},{"id":"12-4-la-fiscalité-des-sociétés","t":"12.4 La fiscalité des sociétés"},{"id":"fiche-flash-du-thème-12","t":"Fiche flash du thème 12"}]}],"annexes":[{"id":"A","title":"Questions de la base à risque","html":"\n<blockquote class=\"note\">\n<p>Ces questions de ta base Excel ont une réponse <strong>fausse</strong>, <strong>absente</strong>, <strong>dépassée</strong> par la réglementation, <strong>discutable</strong> ou <strong>piégeuse</strong>. Elles sont marquées <span class=\"tag t-warn\">piège</span> dans les listes « Questions de la base » de chaque leçon.\n<strong>Règle d'or à l'examen</strong> : si la question tombe <strong>mot pour mot avec les mêmes choix</strong>, la réponse attendue est en principe celle de la base (sauf erreur avérée, signalée <span class=\"tag t-err\">erreur</span>). Si elle a été <strong>reformulée</strong> avec de nouveaux choix, réponds selon le <strong>droit actuel</strong> décrit dans la note.</p>\n</blockquote>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Nombre de questions</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span class=\"tag t-err\">erreur</span> Erreur de la base</td>\n<td>1</td>\n</tr>\n<tr>\n<td><span class=\"tag t-err\">absente</span> Réponse absente</td>\n<td>1</td>\n</tr>\n<tr>\n<td><span class=\"tag t-obs\">dépassée</span> Réponse dépassée par la réglementation</td>\n<td>42</td>\n</tr>\n<tr>\n<td><span class=\"tag t-ver\">à vérifier</span> À vérifier</td>\n<td>1</td>\n</tr>\n<tr>\n<td><span class=\"tag t-ver\">discutable</span> Formulation juridiquement discutable</td>\n<td>1</td>\n</tr>\n<tr>\n<td><span class=\"tag t-warn\">piège</span> Piège</td>\n<td>4</td>\n</tr>\n<tr>\n<td><span class=\"tag t-ctx\">contexte</span> Contexte à connaître</td>\n<td>15</td>\n</tr>\n</tbody>\n</table></div>\n<h2 id=\"erreur-de-la-base\"><span class=\"tag t-err\">erreur</span> Erreur de la base</h2>\n<ul>\n<li><strong><a class=\"qref\" href=\"#\" data-q=\"2670\">Q2670</a></strong> (§1.2.2 — <a href=\"#cours-01\">thème 1</a>) : La base donne « Européen » : c'est FAUX. Le FSB (Conseil de stabilité financière) est un organisme INTERNATIONAL créé par le G20 en 2009. Si la question tombe, réponds « International ».</li>\n</ul>\n<h2 id=\"réponse-absente\"><span class=\"tag t-err\">absente</span> Réponse absente</h2>\n<ul>\n<li><strong><a class=\"qref\" href=\"#\" data-q=\"2578\">Q2578</a></strong> (§7.10 — <a href=\"#cours-07\">thème 7</a>) : La base ne donne AUCUNE réponse. Depuis l'ordonnance de décembre 2020 renforçant la LCB-FT sur les actifs numériques, la monnaie électronique anonyme ne peut JAMAIS être utilisée pour acheter des actifs numériques : choisis « ne peut jamais être utilisée ».</li>\n</ul>\n<h2 id=\"réponse-dépassée-par-la-réglementation\"><span class=\"tag t-obs\">dépassée</span> Réponse dépassée par la réglementation</h2>\n<ul>\n<li><strong><a class=\"qref\" href=\"#\" data-q=\"101\">Q101</a></strong> (§1.3 — <a href=\"#cours-01\">thème 1</a>) : Statut de CIP supprimé le 10/11/2023 (règlement européen ECSP) : les plateformes d'investissement participatif sont devenues des PSFP agréés par l'AMF. Réponse de la base : cumul CIP + IFP.</li>\n<li><strong><a class=\"qref\" href=\"#\" data-q=\"115\">Q115</a></strong> (§1.3 — <a href=\"#cours-01\">thème 1</a>) : Mentionne les CIP, statut supprimé depuis le 10/11/2023 (ECSP). Le CIF reste immatriculé à l'ORIAS : la réponse « ORIAS » reste juste.</li>\n<li><strong><a class=\"qref\" href=\"#\" data-q=\"150\">Q150</a></strong> (§1.5.1 — <a href=\"#cours-01\">thème 1</a>) : Cible d'inflation BCE : « inférieure à, mais proche de 2 % » remplacée en juillet 2021 par une cible de 2 % symétrique à moyen terme. À l'examen, si les choix sont identiques, la réponse attendue reste la seule qui mentionne 2 %.</li>\n<li><strong><a class=\"qref\" href=\"#\" data-q=\"641\">Q641</a>, <a class=\"qref\" href=\"#\" data-q=\"643\">Q643</a>, <a class=\"qref\" href=\"#\" data-q=\"647\">Q647</a>, <a class=\"qref\" href=\"#\" data-q=\"649\">Q649</a>, <a class=\"qref\" href=\"#\" data-q=\"650\">Q650</a>, <a class=\"qref\" href=\"#\" data-q=\"656\">Q656</a>, <a class=\"qref\" href=\"#\" data-q=\"665\">Q665</a>, <a class=\"qref\" href=\"#\" data-q=\"670\">Q670</a>, <a class=\"qref\" href=\"#\" data-q=\"686\">Q686</a>, <a class=\"qref\" href=\"#\" data-q=\"689\">Q689</a>, <a class=\"qref\" href=\"#\" data-q=\"694\">Q694</a>, <a class=\"qref\" href=\"#\" data-q=\"698\">Q698</a>, <a class=\"qref\" href=\"#\" data-q=\"703\">Q703</a>, <a class=\"qref\" href=\"#\" data-q=\"1204\">Q1204</a>, <a class=\"qref\" href=\"#\" data-q=\"2646\">Q2646</a>, <a class=\"qref\" href=\"#\" data-q=\"2647\">Q2647</a>, <a class=\"qref\" href=\"#\" data-q=\"2693\">Q2693</a>, <a class=\"qref\" href=\"#\" data-q=\"2694\">Q2694</a></strong> (§5.2 — <a href=\"#cours-05\">thème 5</a>) : Depuis le 1er janvier 2023, le DICI des OPCVM est remplacé par le DIC PRIIPs pour les investisseurs non professionnels (indicateur de risque SRI de 1 à 7 et 4 scénarios de performance). Les questions sur le DICI restent dans la base : retiens leurs réponses (remise avant souscription, échelle 1 à 7, frais…), qui valent aussi pour le DIC. Confirmé par le sujet du BTS Banque 2026 (épreuve EF2) : l'examen emploie désormais le terme DIC, avec les mêmes réponses (question 692 mise à jour).</li>\n<li><strong><a class=\"qref\" href=\"#\" data-q=\"1188\">Q1188</a></strong> (§6.4 — <a href=\"#cours-06\">thème 6</a>) : La publication annuelle des « 5 premiers lieux d'exécution » (RTS 28) a été supprimée par la révision de MIF 2 (2024) ; l'ESMA a demandé dès 2024 de ne plus la contrôler. La base garde l'ancienne règle : c'est la réponse attendue si la question tombe.</li>\n<li><strong><a class=\"qref\" href=\"#\" data-q=\"1498\">Q1498</a></strong> (§7.6 — <a href=\"#cours-07\">thème 7</a>) : Le PERP n'est plus commercialisé depuis le 1er octobre 2020 : il est remplacé par le PER (loi PACTE). Les cas de sortie anticipée (invalidité, décès du conjoint, surendettement, fin de droits au chômage, cessation d'activité après liquidation judiciaire, et achat de la résidence principale pour l'épargne volontaire du PER) restent proches.</li>\n<li><strong><a class=\"qref\" href=\"#\" data-q=\"1507\">Q1507</a></strong> (§7.6 — <a href=\"#cours-07\">thème 7</a>) : Le taux du livret jeune est libre mais ne peut pas être inférieur au taux du livret A. Les 0,75 % de la base correspondent à l'ancien taux du livret A ; la question figure d'ailleurs aussi dans la liste des questions supprimées.</li>\n<li><strong><a class=\"qref\" href=\"#\" data-q=\"1644\">Q1644</a>, <a class=\"qref\" href=\"#\" data-q=\"1656\">Q1656</a>, <a class=\"qref\" href=\"#\" data-q=\"1665\">Q1665</a>, <a class=\"qref\" href=\"#\" data-q=\"1672\">Q1672</a>, <a class=\"qref\" href=\"#\" data-q=\"1679\">Q1679</a>, <a class=\"qref\" href=\"#\" data-q=\"1683\">Q1683</a>, <a class=\"qref\" href=\"#\" data-q=\"1698\">Q1698</a>, <a class=\"qref\" href=\"#\" data-q=\"1709\">Q1709</a></strong> (§7.10 — <a href=\"#cours-07\">thème 7</a>) : Régime français des ICO (loi PACTE, visa AMF optionnel) remplacé par le règlement européen MiCA (applicable depuis le 30/12/2024) : pour une offre au public de crypto-actifs, un livre blanc est obligatoire et notifié à l'autorité. Réponse de la base : visa optionnel.</li>\n<li><strong><a class=\"qref\" href=\"#\" data-q=\"1648\">Q1648</a>, <a class=\"qref\" href=\"#\" data-q=\"1657\">Q1657</a>, <a class=\"qref\" href=\"#\" data-q=\"1673\">Q1673</a>, <a class=\"qref\" href=\"#\" data-q=\"1676\">Q1676</a>, <a class=\"qref\" href=\"#\" data-q=\"1697\">Q1697</a></strong> (§7.10 — <a href=\"#cours-07\">thème 7</a>) : Le statut de PSAN (enregistrement obligatoire, agrément optionnel auprès de l'AMF) est remplacé par MiCA : les prestataires de services sur crypto-actifs (PSCA/CASP) doivent obtenir un agrément, délivré en France par l'AMF, avec passeport européen ; la période transitoire française a pris fin au plus tard le 1er juillet 2026. Réponses de la base : celles du régime PSAN.</li>\n<li><strong><a class=\"qref\" href=\"#\" data-q=\"2104\">Q2104</a></strong> (§9.5 — <a href=\"#cours-09\">thème 9</a>) : Depuis janvier 2022, la plupart des prestataires de services de communication de données (APA, ARM, CTP) sont agréés et supervisés par l'ESMA, et non plus par l'AMF ou l'ACPR. La base attend « l'AMF ou l'ACPR selon leur statut ».</li>\n<li><strong><a class=\"qref\" href=\"#\" data-q=\"2305\">Q2305</a></strong> (§11.1 — <a href=\"#cours-11\">thème 11</a>) : Les minibons ont été supprimés lors de l'entrée en vigueur du régime européen du financement participatif (ECSP, transition achevée le 10/11/2023). Le reste de la réponse (prêts, actions, obligations) reste juste.</li>\n<li><strong><a class=\"qref\" href=\"#\" data-q=\"2400\">Q2400</a></strong> (§12.3 — <a href=\"#cours-12\">thème 12</a>) : Taux de la TTF : 0,3 % depuis 2017 (réponse de la base), porté à 0,4 % à compter du 1er avril 2025 (loi de finances 2025). Si les choix sont 0,3 / 0,5 / 0,2 %, la base attend 0,3 %.</li>\n<li><strong><a class=\"qref\" href=\"#\" data-q=\"2761\">Q2761</a></strong> (§11.1 — <a href=\"#cours-11\">thème 11</a>) : Seuil français de dispense de prospectus pour une offre au public : 8 M€ dans la base. Le Listing Act européen l'a porté à 12 M€ sur 12 mois à partir de mars 2026. Si la question tombe avec ces choix, la base attend 8 M€.</li>\n<li><strong><a class=\"qref\" href=\"#\" data-q=\"2811\">Q2811</a></strong> (§12.3 — <a href=\"#cours-12\">thème 12</a>) : Le dispositif Pinel a pris fin pour les acquisitions réalisées après le 31 décembre 2024. Sa définition (logement neuf mis en location) reste la bonne réponse.</li>\n</ul>\n<h2 id=\"à-vérifier\"><span class=\"tag t-ver\">à vérifier</span> À vérifier</h2>\n<ul>\n<li><strong><a class=\"qref\" href=\"#\" data-q=\"2429\">Q2429</a></strong> (§12.3 — <a href=\"#cours-12\">thème 12</a>) : PFU de 30 % = 12,8 % d'IR + 17,2 % de prélèvements sociaux : c'est la réponse de la base. À vérifier : la LFSS 2026 a relevé la CSG sur une partie des revenus du capital (prélèvements sociaux portés à 18,6 %, flat tax à 31,4 %, avec des exceptions comme l'assurance-vie et les revenus fonciers).</li>\n</ul>\n<h2 id=\"formulation-juridiquement-discutable\"><span class=\"tag t-ver\">discutable</span> Formulation juridiquement discutable</h2>\n<ul>\n<li><strong><a class=\"qref\" href=\"#\" data-q=\"1296\">Q1296</a></strong> (§7.2 — <a href=\"#cours-07\">thème 7</a>) : Juridiquement, le droit de vote double (art. L225-123) s'attache aux actions ordinaires détenues au nominatif depuis 2 ans, pas aux actions de préférence. Mais les deux autres choix sont faux : la base attend « constituent des actions de préférence ».</li>\n</ul>\n<h2 id=\"piège\"><span class=\"tag t-warn\">piège</span> Piège</h2>\n<ul>\n<li><strong><a class=\"qref\" href=\"#\" data-q=\"23\">Q23</a></strong> (§1.1 — <a href=\"#cours-01\">thème 1</a>) : L'ACPR est juridiquement une autorité administrative indépendante ET adossée à la Banque de France. La base attend « adossée à la Banque de France ».</li>\n<li><strong><a class=\"qref\" href=\"#\" data-q=\"600\">Q600</a></strong> (§5.1 — <a href=\"#cours-05\">thème 5</a>) : La base dit que le démarchage bancaire et financier s'applique « à tous les produits d'épargne (… assurance-vie …) », mais la <a class=\"qref\" href=\"#\" data-q=\"634\">Q634</a> exclut les produits d'assurance du champ des démarcheurs bancaires et financiers. Retiens chaque formulation telle quelle.</li>\n<li><strong><a class=\"qref\" href=\"#\" data-q=\"1050\">Q1050</a></strong> (§6.6 — <a href=\"#cours-06\">thème 6</a>) : La définition donnée (conserve l'exercice de ses droits, actes annulables s'ils lui nuisent) correspond juridiquement à la sauvegarde de justice ; comme elle n'est pas proposée, la base attend « curatelle ».</li>\n<li><strong><a class=\"qref\" href=\"#\" data-q=\"EF26-07\">QEF26-07</a></strong> (§1.3 — <a href=\"#cours-01\">thème 1</a>) : Même énoncé que la question 96 de la base, mais la réponse de la base (démarchage financier en vue d'un conseil) n'est pas proposée ici. Bonne réponse : la réception et la transmission d'ordres sur OPC.</li>\n</ul>\n<h2 id=\"<span class=\"tag t-ctx\">contexte</span>-contexte-à-connaître\"><span class=\"tag t-ctx\">contexte</span> Contexte à connaître</h2>\n<ul>\n<li><strong><a class=\"qref\" href=\"#\" data-q=\"224\">Q224</a></strong> (§1.5.2 — <a href=\"#cours-01\">thème 1</a>) : Le LIBOR a disparu (2021-2023, versions synthétiques jusqu'à fin sept. 2024) ; l'EURIBOR a été réformé (méthode hybride) et existe toujours ; l'EONIA a disparu le 3/01/2022 au profit de l'€STR.</li>\n<li><strong><a class=\"qref\" href=\"#\" data-q=\"227\">Q227</a></strong> (§1.5.2 — <a href=\"#cours-01\">thème 1</a>) : Le nombre de pays de l'indice MSCI Emerging Markets évolue (24 aujourd'hui). Retenir : indice actions des pays émergents.</li>\n<li><strong><a class=\"qref\" href=\"#\" data-q=\"1799\">Q1799</a>, <a class=\"qref\" href=\"#\" data-q=\"1811\">Q1811</a></strong> (§8.4 — <a href=\"#cours-08\">thème 8</a>) : Le DICI (UCITS IV, 2009) a lui-même été remplacé par le DIC PRIIPs pour les investisseurs de détail depuis le 1er janvier 2023.</li>\n<li><strong><a class=\"qref\" href=\"#\" data-q=\"1924\">Q1924</a>, <a class=\"qref\" href=\"#\" data-q=\"1937\">Q1937</a>, <a class=\"qref\" href=\"#\" data-q=\"2481\">Q2481</a>, <a class=\"qref\" href=\"#\" data-q=\"2538\">Q2538</a></strong> (§8.7 — <a href=\"#cours-08\">thème 8</a>) : La DPEF a été remplacée par le « rapport de durabilité » de la directive CSRD (ordonnance de décembre 2023, premiers rapports en 2025 pour les plus grandes entreprises ; le paquet Omnibus de 2025 a reporté et réduit le champ). La définition donnée par la base reste valable.</li>\n<li><strong><a class=\"qref\" href=\"#\" data-q=\"1979\">Q1979</a>, <a class=\"qref\" href=\"#\" data-q=\"1995\">Q1995</a></strong> (§8.5, §8.7 — <a href=\"#cours-08\">thème 8</a>) : Le PERCO n'est plus ouvert depuis le 1er octobre 2020 : il est remplacé par le PER collectif (PERECO, loi PACTE). Le principe (sommes disponibles à la retraite, sauf cas de déblocage anticipé) demeure.</li>\n<li><strong><a class=\"qref\" href=\"#\" data-q=\"2255\">Q2255</a></strong> (§10.2 — <a href=\"#cours-10\">thème 10</a>) : Règlement-livraison à J+2 : toujours vrai aujourd'hui, mais l'UE passera à J+1 le 11 octobre 2027. Réponse attendue : J+2.</li>\n<li><strong><a class=\"qref\" href=\"#\" data-q=\"2266\">Q2266</a></strong> (§11.1 — <a href=\"#cours-11\">thème 11</a>) : Depuis le régime européen ECSP (2023), les plateformes d'investissement et de prêt aux entreprises sont des PSFP agréés par l'AMF ; le statut d'IFP subsiste pour certains prêts et pour les dons. Réponse attendue de la base : statut d'IFP pour les deux.</li>\n<li><strong><a class=\"qref\" href=\"#\" data-q=\"2464\">Q2464</a></strong> (§8.7 — <a href=\"#cours-08\">thème 8</a>) : Seuils de la DPEF (500 salariés, 20 M€ de bilan ou 40 M€ de CA pour les cotées ; 100 M€ pour les non cotées) : régime remplacé par la CSRD (rapport de durabilité). Retiens les seuils de la base pour cette question.</li>\n<li><strong><a class=\"qref\" href=\"#\" data-q=\"2594\">Q2594</a></strong> (§2.2 — <a href=\"#cours-02\">thème 2</a>) : Loi Waserman (2022) : le lanceur d'alerte choisit librement le signalement interne OU externe (autorité). La réponse « directement aux autorités s'il y a urgence » reste la seule juste parmi les choix.</li>\n<li><strong><a class=\"qref\" href=\"#\" data-q=\"692\">Q692</a></strong> (§5.2 — <a href=\"#cours-05\">thème 5</a>) : Formulation mise à jour d'après le sujet du BTS Banque 2026 (épreuve EF2, question 31). L'examen parle désormais du DIC (document d'informations clés PRIIPs), qui a remplacé le DICI ; la réponse reste l'échelle de 1 à 7.</li>\n</ul>\n","toc":[{"id":"erreur-de-la-base","t":"❌ Erreur de la base"},{"id":"réponse-absente","t":"❓ Réponse absente"},{"id":"réponse-dépassée-par-la-réglementation","t":"🕰 Réponse dépassée par la réglementation"},{"id":"à-vérifier","t":"🔎 À vérifier"},{"id":"formulation-juridiquement-discutable","t":"🤔 Formulation juridiquement discutable"},{"id":"piège","t":"⚠ Piège"},{"id":"ℹ-contexte-à-connaître","t":"ℹ Contexte à connaître"}]},{"id":"B","title":"Tous les moyens mnémotechniques du manuel","html":"\n<blockquote class=\"note\">\n<p>Relis cette page en entier la veille et le matin de l'examen. Chaque ligne renvoie à la leçon d'origine.</p>\n</blockquote>\n<h2 id=\"thème-1-cadre-institutionnel-et-réglementaire-france-europe-\">Thème 1 — <a href=\"#cours-01\">Cadre institutionnel et réglementaire (France, Europe, international)</a></h2>\n<ul>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« L'AMF Garde les Marchés et les Gérants ; l'ACPR Agrée les Comptoirs (banques) et les Assureurs, et les Répare (résolution). »</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>SGP → AMF, toujours et seule.</strong> EC ou EI → ACPR, plus l'<strong>approbation du programme d'activité par l'AMF</strong> pour leurs services d'investissement (« l'ACPR signe, l'AMF valide le programme »).</li>\n<li><strong>CCLRF</strong> — Comité consultatif de la <strong>législation</strong> et de la <strong>réglementation</strong> financières — <span class=\"tag t-mnemo\">mnémo</span> le <strong>L</strong> de CCLRF = <strong>L</strong>oi : il relit les textes.</li>\n<li><strong>CCSF</strong> — Comité consultatif du <strong>secteur financier</strong> — <span class=\"tag t-mnemo\">mnémo</span> le <strong>S</strong> de CCSF = <strong>S</strong>ervice au client.</li>\n<li><strong>HCSF</strong> — Haut conseil de stabilité financière (2013) — <span class=\"tag t-mnemo\">mnémo</span> <strong>H</strong>aut conseil = vue <strong>H</strong>élicoptère de tout le système.</li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« La Commission Propose, le Parlement et le Conseil Disposent »</strong> (P-P-C). À la question « qui vote les lois européennes ? », la base attend <strong>le Parlement européen</strong>.</li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>E-B-A = Établissements Bancaires ; E-I-O-PA = Insurance + Occupational PEnsions ; E-S-MA = Securities &amp; MArkets.</strong> « Banque et assurance » = EBA + EIOPA. « Marchés » = ESMA.</li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« Surveiller – Résoudre – Garantir »</strong> = MSU – MRU – SGD.</li>\n<li><strong>FMI</strong> (accords de <strong>Bretton Woods</strong>, 1944) — <span class=\"tag t-mnemo\">mnémo</span> <strong>B</strong>retton <strong>W</strong>oods = <strong>B</strong>anque mondiale + FMI</li>\n<li><strong>Comité de Bâle</strong> (1974, au sein de la <strong>BRI</strong>) — <span class=\"tag t-mnemo\">mnémo</span> <strong>Bâle = Banques</strong></li>\n<li><strong>OICV / IOSCO</strong> (1983) — <span class=\"tag t-mnemo\">mnémo</span> <strong>IOSCO = Securities</strong> (le S de valeurs mobilières)</li>\n<li><strong>FSB / Conseil de stabilité financière</strong> (G20 de Londres, 2009) — <span class=\"tag t-mnemo\">mnémo</span> <strong>FSB = Financial Stability = vue d'ensemble mondiale</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« EI = Ni SGP Ni Banque »</strong> (une entreprise d'investissement est « autre que » les deux).</li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>CIF = « Une Lettre, Une Association, Un registre, Zéro fonds »</strong> :\n<ul>\n<li><strong>Lettre</strong> de mission avant tout conseil ;</li>\n<li><strong>une seule</strong> association agréée AMF ;</li>\n<li><strong>ORIAS</strong> ;</li>\n<li><strong>jamais</strong> de fonds des clients.</li>\n</ul>\n</li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>STAG-flation</strong> = l'économie <strong>stagne</strong> pendant que les prix <strong>flambent</strong>.</li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« RÉ-EX-NÉ-GÉ-CO, 3 P et 2 systèmes »</strong> : RTO – EXécution – NÉgociation – GEstion – COnseil + Prise ferme, Placement garanti, Placement non garanti + MTF et OTF.</li>\n</ul>\n<h2 id=\"thème-2-déontologie-conformité-et-organisation-déontologique\">Thème 2 — <a href=\"#cours-02\">Déontologie, conformité et organisation déontologique des établissements</a></h2>\n<ul>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« H-L-P »</strong> = <strong>H</strong>onnête, <strong>L</strong>oyale, <strong>P</strong>rofessionnelle. Méfie-toi des variantes piégées : « protectrice », « louable ».</li>\n<li><span class=\"tag t-mnemo\">mnémo</span> Le PSI sert <strong>deux maîtres en même temps</strong> : <strong>le client ET le marché</strong>. Une réponse qui sacrifie l'un des deux (« sans avoir à préserver l'intégrité du marché », « la primauté du client est laissée à sa discrétion ») est fausse.</li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« Marché – Primauté – Info CEN – KYC – HLP »</strong> (CEN = Claire, Exacte, Non trompeuse).</li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>RCC<em>I</em> = gestIon</strong> (SGP) ; <strong>RC<em>S</em>I = Services d'investissement</strong> (les autres PSI).\n<ul>\n<li>Un PSI peut avoir <strong>plusieurs RCSI</strong> si l'AMF juge leur nombre adapté à sa taille, à ses activités et à ses risques. Il n'y a pas de limite fixe.</li>\n<li>En <strong>SGP</strong>, le contrôle interne compte <strong>deux niveaux</strong> : le <strong>contrôle permanent</strong>, qui intègre la conformité, et le <strong>contrôle périodique</strong>. Le RCCI couvre <strong>la conformité, le contrôle permanent et le contrôle périodique</strong>.</li>\n<li>Le <strong>dirigeant</strong> d'une petite SGP <strong>peut être RCCI</strong>, mais il doit alors aussi être responsable du <strong>contrôle périodique et du contrôle permanent hors conformité</strong>.</li>\n</ul>\n</li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« Détecter → Prévenir → Gérer → et seulement si ça ne suffit pas : Informer le client »</strong>.</li>\n<li><strong>Liste de surveillance</strong> (<em>watch list</em>, confidentielle, <strong>conservée 5 ans</strong>) — <span class=\"tag t-mnemo\">mnémo</span> on <strong>surveille</strong>, on ne bloque pas</li>\n<li><strong>Liste d'interdiction</strong> (<em>restricted list</em>) — <span class=\"tag t-mnemo\">mnémo</span> on <strong>interdit</strong> certaines activités</li>\n<li><strong>Liste d'initiés</strong> (règlement MAR) — <span class=\"tag t-mnemo\">mnémo</span> elle <strong>vit</strong> avec l'opération</li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« 10 jours pour dire \"bien reçu\", 2 mois pour répondre. »</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« Le médiateur de l'AMF ne parle que de BOURSE et d'ÉPARGNE financière : ni crédit, ni assurance-vie, ni PEL. »</strong></li>\n</ul>\n<h2 id=\"thème-3-sécurité-financière-blanchiment-terrorisme-corruptio\">Thème 3 — <a href=\"#cours-03\">Sécurité financière : blanchiment, terrorisme, corruption, embargos</a></h2>\n<ul>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« P-D-C : Place, Dissimule, Convertit »</strong> ou, en version anglaise, <strong>« P-E-I : Placement, Empilement, Intégration »</strong>. La <strong>phase initiale</strong> est toujours le <strong>placement</strong>.</li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« 5 – 375 / 10 – 750 »</strong> : l'aggravé double tout. Un <strong>collaborateur de banque</strong> qui utilise ses fonctions est dans le cas <strong>aggravé</strong>.</li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« GAFI fait les normes, TRACFIN reçoit les soupçons, ACPR et AMF contrôlent et sanctionnent. »</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« Pas d'identité, pas de relation »</strong> : si le professionnel ne peut pas identifier le client ou connaître l'objet de la relation, il <strong>n'exécute aucune opération</strong> et <strong>n'entame pas</strong> la relation. Si elle existe déjà, <strong>il y met fin</strong>. Il ne peut pas « exécuter puis réclamer les justificatifs ».</li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« 5 ans »</strong> partout en sécurité financière : conservation des documents, et aussi des listes d'initiés (thème 4).</li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« Soupçon = DOIT déclarer, AVANT, en SECRET, à TRACFIN ; et de bonne foi = protégé. »</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« Sapin 500 / 100 »</strong> : 500 salariés, 100 M€ de chiffre d'affaires.</li>\n</ul>\n<h2 id=\"thème-4-la-réglementation-abus-de-marché\">Thème 4 — <a href=\"#cours-04\">La réglementation « Abus de marché »</a></h2>\n<ul>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« I-D-M » = Initié, Divulgation, Manipulation.</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« P-N-E-S » = Précise, Non publique, sur un Émetteur, Sensible pour le cours.</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« 5 ans »</strong>, comme en lutte anti-blanchiment : liste d'initiés, informations sur le site de l'émetteur, documents clients.</li>\n<li><strong>Front running</strong> — <span class=\"tag t-mnemo\">mnémo</span> <strong>front</strong> = passer <strong>devant</strong> le client</li>\n<li><strong>Late trading</strong> — <span class=\"tag t-mnemo\">mnémo</span> <strong>late</strong> = <strong>en retard</strong> sur l'heure limite</li>\n<li><strong>Market timing</strong> — <span class=\"tag t-mnemo\">mnémo</span> <strong>timing</strong> = jouer sur le <strong>décalage</strong> de la VL</li>\n</ul>\n<h2 id=\"thème-5-commercialisation-dinstruments-financiers-démarchage\">Thème 5 — <a href=\"#cours-05\">Commercialisation d'instruments financiers, démarchage, vente à distance et conseil</a></h2>\n<ul>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« Démarcher = SORTIR de l'agence ou ENTRER chez le client sans y être invité. »</strong> Une visite au domicile reste du démarchage même si le client l'a demandée.</li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« Risque inconnu = démarchage interdit »</strong>, même avec une mise en garde écrite.</li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« 14 pour se rétracter, 48 heures pour réfléchir à un ordre, 30 pour rendre l'argent. »</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« On ne se rétracte pas d'un ordre de bourse »</strong> : RTO et exécution n'ont <strong>pas</strong> de délai de rétractation, seulement 48 heures de réflexion.</li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« Le producteur dessine la cible et choisit les canaux, le distributeur l'ajuste à ses clients. »</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« DICI = 2 pages, 1 à 7, AVANT. »</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« PRIIPs = Packagés ; 4 scénarios : Tension, Défavorable, Intermédiaire, Favorable (T-D-I-F) ».</strong></li>\n</ul>\n<h2 id=\"thème-6-relations-avec-les-clients\">Thème 6 — <a href=\"#cours-06\">Relations avec les clients</a></h2>\n<ul>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« 20 – 40 – 2 »</strong> : bilan 20, chiffre d'affaires 40, capitaux propres 2 (en millions d'euros), <strong>2 critères sur 3</strong>.</li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« Descendre est facile, monter se mérite »</strong> : vers plus de protection, une demande acceptée suffit ; vers moins de protection, il faut une demande <strong>et</strong> une évaluation.</li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« Les gendarmes (ACPR, AMF, BdF), les juges au pénal, le fisc et les douanes, le surendettement et le Parlement passent ; les curieux restent dehors. »</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> Consentement <strong>« L-S-E-U »</strong> (Libre, Spécifique, Éclairé, Univoque) ; violation → <strong>72 heures</strong>.</li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« 5 ans, 12 mois pleins, frais inclus, jamais au centre. »</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« Indépendant = Ne garde rien ; Non indépendant = Informe et améliore. »</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« ADÉQUATION = CONSEIL et GESTION (je décide pour toi ou je te recommande : je dois TOUT savoir). APPROPRIÉ = le reste (tu décides seul : je vérifie juste que tu comprends). »</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>Le test d'adéquation compte 4 volets : Connaissances, Expérience, Situation financière, Objectifs.</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« 6 mois pour être certifié. »</strong></li>\n<li><strong>Exécution d'ordres</strong> pour compte de tiers — <span class=\"tag t-mnemo\">mnémo</span> j'<strong>exécute</strong> → je choisis le <strong>lieu</strong></li>\n<li><strong>RTO</strong>, <strong>gestion de portefeuille</strong>, <strong>gestion d'OPC</strong> (le PSI transmet ses ordres à un intermédiaire) — <span class=\"tag t-mnemo\">mnémo</span> je <strong>transmets</strong> → je choisis l'<strong>intermédiaire</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« Entrée = souscription, Sortie = rachat, Garde = conservation, Courtage = exécution. »</strong></li>\n<li><strong>Joint</strong> — <span class=\"tag t-mnemo\">mnémo</span> <strong>Joint = Je peux seul</strong></li>\n<li><strong>Indivis</strong> — <span class=\"tag t-mnemo\">mnémo</span> <strong>Indivis = Indispensable d'être tous d'accord</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>Cessation des paiements = « Dispo &lt; Exigible »</strong> ; déclaration <strong>sous 45 jours</strong>.</li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« 100 pour l'argent, 70 pour les titres, 7 jours pour payer. »</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« Options binaires = INTERDITES (aux particuliers) ; CFD = BRIDÉS (levier plafonné). »</strong></li>\n</ul>\n<h2 id=\"thème-7-instruments-financiers-crypto-actifs-et-leurs-risque\">Thème 7 — <a href=\"#cours-07\">Instruments financiers, crypto-actifs et leurs risques</a></h2>\n<ul>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« Garder une obligation jusqu'au bout = risque de DÉFAUT ; la vendre avant = risque de MARCHÉ (et de liquidité). »</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« PER = Prix / Earnings (le bénéfice) »</strong> : on paie combien d'années de bénéfices ?</li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« Taux et prix font la balançoire »</strong> : l'un monte, l'autre descend.</li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« Euribor = plusieurs maturités (1 semaine-12 mois), EMMI ; €STR = 1 jour, BCE. »</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>Convertible = « obligation + option de devenir actionnaire »</strong> : on paie cette option par un coupon plus faible.</li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« CALL = j'aCHETE ; PUT = je me déPUTe du titre (je vends). »</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>Future = ferme ; option = optionnel pour l'acheteur, qui a payé une prime.</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« SICAV = Société → ActionnAire ; FCP = Fonds Commun → CoPropriétaire. »</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« Bien divers = on te vend du RENDEMENT sur une chose → passage obligé par l'AMF AVANT. »</strong></li>\n</ul>\n<h2 id=\"thème-8-gestion-collective-gestion-pour-compte-de-tiers-et-f\">Thème 8 — <a href=\"#cours-08\">Gestion collective, gestion pour compte de tiers et finance durable</a></h2>\n<ul>\n<li><strong>SGP</strong> (société de gestion de portefeuille) — <span class=\"tag t-mnemo\">mnémo</span> Le <strong>cerveau</strong></li>\n<li><strong>Dépositaire</strong> — <span class=\"tag t-mnemo\">mnémo</span> Le <strong>coffre-fort + le gendarme</strong></li>\n<li><strong>Valorisateur</strong> — <span class=\"tag t-mnemo\">mnémo</span> La <strong>calculatrice</strong></li>\n<li><strong>Commissaire aux comptes</strong> — <span class=\"tag t-mnemo\">mnémo</span> Le <strong>certificateur</strong></li>\n<li><strong>Prime broker</strong> — <span class=\"tag t-mnemo\">mnémo</span> Le <strong>banquier des hedge funds</strong></li>\n<li><strong>Expert externe en évaluation</strong> — <span class=\"tag t-mnemo\">mnémo</span> L'<strong>expert immobilier</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« Mandat = MON portefeuille, mes règles ; OPC = NOTRE portefeuille, ses règles (ratios permanents). »</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« Absolue = seule ; relative = comparée. Sharpe = ce que le gérant gagne en plus, par unité de risque. »</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« FCPR 50, FCPI 70, FIP 70, OPCI 60, nourricier 85. »</strong></li>\n<li><strong>Active</strong> — <span class=\"tag t-mnemo\">mnémo</span> « je <strong>bats</strong> l'indice »</li>\n<li><strong>Passive / indicielle</strong> — <span class=\"tag t-mnemo\">mnémo</span> « je <strong>copie</strong> l'indice »</li>\n<li><strong>Alternative</strong> (hedge funds) — <span class=\"tag t-mnemo\">mnémo</span> « je gagne <strong>dans tous les cas</strong> »</li>\n<li><strong>Style « value »</strong> — <span class=\"tag t-mnemo\">mnémo</span> value = <strong>bonne affaire</strong></li>\n<li><strong>Style « growth »</strong> — <span class=\"tag t-mnemo\">mnémo</span> growth = <strong>croissance</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>E = la planète ; S = les personnes (salariés, fournisseurs, clients, santé) ; G = le pouvoir et l'argent des dirigeants (corruption, rémunérations).</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« CLASS = dans sa CLASSE (son secteur) ; UNIVERSE = dans tout l'UNIVERS ; EFFORT = celui qui PROGRESSE. »</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« ISR = Finances (Bercy) ; GREENfin = Écologie (vert, sans nucléaire ni fossile) ; FINANSOL = SOLidarité (produit d'épargne). »</strong></li>\n</ul>\n<h2 id=\"thème-9-fonctionnement-et-organisation-des-marchés\">Thème 9 — <a href=\"#cours-09\">Fonctionnement et organisation des marchés</a></h2>\n<ul>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« MR et MTF = multilatéraux ; OTF = pas d'actions ; IS = le PSI joue contre son client. »</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>SRD = « Je Règle à la fin du mois » (dernier jour de bourse).</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« AU MARCHÉ = à tout prix, en premier ; LIMITÉ = mon prix ou mieux ; MEILLEURE LIMITE = le prix d'en face à l'arrivée ; STOP = je déclenche à partir d'un seuil. »</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« Prix d'abord, chrono ensuite. »</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« 7 h 15 j'empile, 9 h je fixe, 9 h - 17 h 30 je traite, 17 h 35 je clôture, jusqu'à 17 h 40 je finis au dernier cours. »</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« ISIN = l'instrument ; LEI = l'entité (l'acteur). »</strong></li>\n</ul>\n<h2 id=\"thème-10-post-marché-et-infrastructures-de-marché\">Thème 10 — <a href=\"#cours-10\">Post-marché et infrastructures de marché</a></h2>\n<ul>\n<li><strong>Chambre de compensation</strong> (contrepartie centrale) — <span class=\"tag t-mnemo\">mnémo</span> Le <strong>garant</strong> : « personne ne fait défaut chez moi »</li>\n<li><strong>Dépositaire central</strong> (en France : <strong>Euroclear France</strong>) — <span class=\"tag t-mnemo\">mnémo</span> Le <strong>grand registre</strong></li>\n<li><strong>Teneur de compte-conservateur (TCC)</strong> — <span class=\"tag t-mnemo\">mnémo</span> Le <strong>banquier des titres</strong> de l'investisseur</li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« La chambre GARANTIT, le dépositaire central ENREGISTRE (et transfère), le teneur de compte INSCRIT chez le client. »</strong></li>\n<li><strong>Nominatif pur</strong> — <span class=\"tag t-mnemo\">mnémo</span> <strong>pur</strong> = directement chez l'émetteur</li>\n<li><strong>Nominatif administré</strong> — <span class=\"tag t-mnemo\">mnémo</span> <strong>administré</strong> = l'émetteur connaît l'actionnaire, la banque gère</li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« J+2 : je négocie J, je deviens propriétaire J+2. »</strong></li>\n</ul>\n<h2 id=\"thème-11-émissions-et-opérations-sur-titres\">Thème 11 — <a href=\"#cours-11\">Émissions et opérations sur titres</a></h2>\n<ul>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>Prise ferme = j'achète tout et je revends ; garanti = je promets un montant ; non garanti = je fais de mon mieux.</strong></li>\n<li><strong>OPA</strong> (offre publique d'<strong>acquisition</strong>, d'achat) — <span class=\"tag t-mnemo\">mnémo</span> <strong>A = Argent</strong></li>\n<li><strong>OPE</strong> (offre publique d'<strong>échange</strong>) — <span class=\"tag t-mnemo\">mnémo</span> <strong>E = Échange de titres</strong></li>\n<li><strong>OPR</strong> (offre publique de <strong>retrait</strong>) — <span class=\"tag t-mnemo\">mnémo</span> <strong>R = Retrait de la cote</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« 30 % = OPA obligatoire. »</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>Split = on coupe la pizza en plus de parts : même pizza (même capital), plus de parts, chacune moins chère.</strong></li>\n</ul>\n<h2 id=\"thème-12-bases-comptables-financières-et-fiscales\">Thème 12 — <a href=\"#cours-12\">Bases comptables, financières et fiscales</a></h2>\n<ul>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« Le bilan dit CE QUE J'AI et D'OÙ ÇA VIENT ; le compte de résultat dit CE QUE J'AI GAGNÉ cette année. »</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« 4 / 3 / 4 »</strong> : rapport annuel sous <strong>4 mois</strong>, semestriel sous <strong>3 mois</strong>, franchissement de seuil déclaré sous <strong>4 jours de bourse</strong>.</li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« PEA 5 ans, assurance-vie 8 ans. »</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>IFI = Immobilier, Foyer (mariés, pacsés, concubins), France + étranger pour les résidents.</strong></li>\n<li><span class=\"tag t-mnemo\">mnémo</span> <strong>« Pour une société, tout passe à l'IS au taux normal ; même les plus-values latentes sur OPC (sauf fonds 90 % actions). »</strong></li>\n</ul>\n","toc":[{"id":"thème-1-cadre-institutionnel-et-réglementaire-france-europe-","t":"Thème 1 — Cadre institutionnel et réglementaire (France, Europe, international)"},{"id":"thème-2-déontologie-conformité-et-organisation-déontologique","t":"Thème 2 — Déontologie, conformité et organisation déontologique des établissements"},{"id":"thème-3-sécurité-financière-blanchiment-terrorisme-corruptio","t":"Thème 3 — Sécurité financière : blanchiment, terrorisme, corruption, embargos"},{"id":"thème-4-la-réglementation-abus-de-marché","t":"Thème 4 — La réglementation « Abus de marché »"},{"id":"thème-5-commercialisation-dinstruments-financiers-démarchage","t":"Thème 5 — Commercialisation d'instruments financiers, démarchage, vente à distance et conseil"},{"id":"thème-6-relations-avec-les-clients","t":"Thème 6 — Relations avec les clients"},{"id":"thème-7-instruments-financiers-crypto-actifs-et-leurs-risque","t":"Thème 7 — Instruments financiers, crypto-actifs et leurs risques"},{"id":"thème-8-gestion-collective-gestion-pour-compte-de-tiers-et-f","t":"Thème 8 — Gestion collective, gestion pour compte de tiers et finance durable"},{"id":"thème-9-fonctionnement-et-organisation-des-marchés","t":"Thème 9 — Fonctionnement et organisation des marchés"},{"id":"thème-10-post-marché-et-infrastructures-de-marché","t":"Thème 10 — Post-marché et infrastructures de marché"},{"id":"thème-11-émissions-et-opérations-sur-titres","t":"Thème 11 — Émissions et opérations sur titres"},{"id":"thème-12-bases-comptables-financières-et-fiscales","t":"Thème 12 — Bases comptables, financières et fiscales"}]},{"id":"C","title":"Tous les chiffres clés, thème par thème","html":"\n<blockquote class=\"note\">\n<p>Les nombres sont les questions les plus faciles à réussir… et à rater par confusion. Entraîne-toi à cacher la colonne de droite et à la réciter.</p>\n</blockquote>\n<aside class=\"callout c-new\"><span class=\"callout-label\">Mise à jour</span>\n<p>= valeur qui a changé depuis la base ; voir l'annexe D.</p>\n</aside>\n<h2 id=\"lexamen-lui-même\">L'examen lui-même</h2>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Élément</th>\n<th>Valeur</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Nombre de questions</td>\n<td><strong>120</strong> QCM (3 choix de réponse dans ta base)</td>\n</tr>\n<tr>\n<td>Catégorie A (réglementaire)</td>\n<td><strong>33 questions</strong> → il faut <strong>au moins 27 bonnes</strong> (80 %)</td>\n</tr>\n<tr>\n<td>Catégorie C (culture financière)</td>\n<td><strong>87 questions</strong> → il faut <strong>au moins 70 bonnes</strong> (80 %)</td>\n</tr>\n<tr>\n<td>Compensation entre A et C</td>\n<td><strong>Aucune</strong></td>\n</tr>\n<tr>\n<td>Durée</td>\n<td><strong>2 heures</strong> au maximum (selon les sources publiques, à confirmer à l'inscription)</td>\n</tr>\n</tbody>\n</table></div>\n<h2 id=\"thème-1-cadre-institutionnel\">Thème 1 — Cadre institutionnel</h2>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Élément</th>\n<th>Valeur</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Collège de l'AMF</td>\n<td><strong>16 membres</strong> ; président nommé pour <strong>5 ans non renouvelables</strong></td>\n</tr>\n<tr>\n<td>Commission des sanctions de l'AMF</td>\n<td><strong>12 membres</strong></td>\n</tr>\n<tr>\n<td>HCSF</td>\n<td><strong>8 membres</strong>, présidé par le ministre de l'économie</td>\n</tr>\n<tr>\n<td>Création</td>\n<td>AMF <strong>2003</strong> · ACP <strong>2010</strong> → ACPR <strong>2013</strong> · HCSF <strong>2013</strong> · SESF <strong>2011</strong> · MSU <strong>2014</strong></td>\n</tr>\n<tr>\n<td>International</td>\n<td>Bretton Woods <strong>1944</strong> · Comité de Bâle <strong>1974</strong> · OICV <strong>1983</strong> · FSB <strong>2009</strong> (G20)</td>\n</tr>\n<tr>\n<td>Garantie des dépôts (SGD)</td>\n<td><strong>100 000 €</strong> par déposant et par banque</td>\n</tr>\n<tr>\n<td>Cible d'inflation de la BCE</td>\n<td><strong>2 %</strong> à moyen terme, <strong>symétrique</strong> (depuis 2021)</td>\n</tr>\n<tr>\n<td>Opérations principales de refinancement</td>\n<td>à <strong>7 jours</strong></td>\n</tr>\n<tr>\n<td><span class=\"tag t-new\">nouveau</span> Taux de la facilité de dépôt</td>\n<td><strong>2 %</strong> depuis juin 2025 (à vérifier)</td>\n</tr>\n<tr>\n<td><span class=\"tag t-new\">nouveau</span> Zone euro</td>\n<td><strong>21 pays</strong> (Bulgarie au 01/01/2026)</td>\n</tr>\n<tr>\n<td>Normes de crédit immobilier du HCSF</td>\n<td>taux d'effort <strong>35 %</strong>, durée <strong>25 ans</strong></td>\n</tr>\n<tr>\n<td>Services d'investissement</td>\n<td><strong>10</strong></td>\n</tr>\n</tbody>\n</table></div>\n<h2 id=\"thème-2-déontologie\">Thème 2 — Déontologie</h2>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Élément</th>\n<th>Valeur</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Accusé de réception d'une réclamation</td>\n<td><strong>10 jours ouvrables</strong></td>\n</tr>\n<tr>\n<td>Réponse à une réclamation</td>\n<td><strong>2 mois</strong></td>\n</tr>\n<tr>\n<td>Saisine du médiateur faute de réponse</td>\n<td>au bout de <strong>2 mois</strong></td>\n</tr>\n<tr>\n<td>Mandat du médiateur de l'AMF</td>\n<td><strong>3 ans</strong></td>\n</tr>\n<tr>\n<td>Conservation des enregistrements téléphoniques</td>\n<td><strong>5 ans</strong> (jusqu'à 7 ans si l'autorité le demande)</td>\n</tr>\n<tr>\n<td>Conservation de la liste de surveillance</td>\n<td><strong>5 ans</strong></td>\n</tr>\n<tr>\n<td>Révision de la politique de conflits d'un CIF</td>\n<td><strong>au moins une fois par an</strong></td>\n</tr>\n</tbody>\n</table></div>\n<h2 id=\"thème-3-sécurité-financière\">Thème 3 — Sécurité financière</h2>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Élément</th>\n<th>Valeur</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Blanchiment simple</td>\n<td><strong>5 ans</strong> et <strong>375 000 €</strong></td>\n</tr>\n<tr>\n<td>Blanchiment aggravé</td>\n<td><strong>10 ans</strong> et <strong>750 000 €</strong></td>\n</tr>\n<tr>\n<td>Conservation des documents clients</td>\n<td><strong>5 ans</strong> après la fin de la relation</td>\n</tr>\n<tr>\n<td>Communication systématique d'informations à TRACFIN (espèces)</td>\n<td><strong>10 000 € par mois</strong></td>\n</tr>\n<tr>\n<td>Champ de la déclaration de soupçon</td>\n<td>infraction punie de <strong>plus d'1 an</strong> de prison</td>\n</tr>\n<tr>\n<td>Bénéficiaire effectif</td>\n<td>plus de <strong>25 %</strong> du capital ou des droits de vote</td>\n</tr>\n<tr>\n<td>PPE</td>\n<td>fonction exercée <strong>dans l'année</strong> écoulée</td>\n</tr>\n<tr>\n<td>Loi Sapin 2</td>\n<td><strong>≥ 500 salariés ET CA &gt; 100 M€</strong></td>\n</tr>\n<tr>\n<td>Plafond de paiement en espèces</td>\n<td><strong>1 000 €</strong> (résident en France) ; <span class=\"tag t-new\">nouveau</span> <strong>10 000 €</strong> dans l'UE à partir de 2027</td>\n</tr>\n</tbody>\n</table></div>\n<h2 id=\"thème-4-abus-de-marché\">Thème 4 — Abus de marché</h2>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Élément</th>\n<th>Valeur</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Conservation des listes d'initiés</td>\n<td><strong>5 ans</strong></td>\n</tr>\n<tr>\n<td>Informations privilégiées sur le site de l'émetteur</td>\n<td><strong>5 ans</strong></td>\n</tr>\n<tr>\n<td>Sanction administrative maximale</td>\n<td><strong>100 M€ ou 10 fois le profit</strong></td>\n</tr>\n<tr>\n<td>Sanction pénale (délit d'initié)</td>\n<td><strong>5 ans</strong> et <strong>100 M€</strong></td>\n</tr>\n<tr>\n<td><span class=\"tag t-new\">nouveau</span> Déclaration des transactions des dirigeants</td>\n<td>au-delà de <strong>20 000 € par an</strong> (5 000 € auparavant)</td>\n</tr>\n</tbody>\n</table></div>\n<h2 id=\"thème-5-commercialisation-et-démarchage\">Thème 5 — Commercialisation et démarchage</h2>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Élément</th>\n<th>Valeur</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Rétractation après démarchage</td>\n<td><strong>14 jours calendaires</strong></td>\n</tr>\n<tr>\n<td>Restitution des sommes après rétractation</td>\n<td><strong>30 jours</strong></td>\n</tr>\n<tr>\n<td>Délai de réflexion pour un ordre ou une RTO démarchés</td>\n<td><strong>48 heures</strong></td>\n</tr>\n<tr>\n<td>Vente à distance</td>\n<td><strong>14 jours</strong> (assurance-vie : <strong>30 jours</strong>)</td>\n</tr>\n<tr>\n<td>Démarcheur</td>\n<td>majeur, <strong>baccalauréat ou 2 ans</strong> d'expérience ; carte valable <strong>3 ans</strong></td>\n</tr>\n<tr>\n<td>Démarchage sans carte</td>\n<td><strong>6 mois</strong> et <strong>7 500 €</strong></td>\n</tr>\n<tr>\n<td>Personnes morales exclues du démarchage</td>\n<td><strong>&gt; 5 M€</strong> (bilan, chiffre d'affaires ou actifs gérés)</td>\n</tr>\n<tr>\n<td>Démarchage téléphonique (décret de 2022)</td>\n<td>lundi au vendredi, <strong>10 h-13 h et 14 h-20 h</strong>, <strong>4 appels / 30 jours</strong></td>\n</tr>\n<tr>\n<td>Indicateur de risque du DICI/DIC</td>\n<td>échelle de <strong>1 à 7</strong></td>\n</tr>\n<tr>\n<td>Scénarios de performance PRIIPs</td>\n<td><strong>4</strong></td>\n</tr>\n</tbody>\n</table></div>\n<h2 id=\"thème-6-relations-clients\">Thème 6 — Relations clients</h2>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Élément</th>\n<th>Valeur</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Professionnel par nature (2 critères sur 3)</td>\n<td>bilan <strong>≥ 20 M€</strong>, CA <strong>≥ 40 M€</strong>, capitaux propres <strong>≥ 2 M€</strong></td>\n</tr>\n<tr>\n<td>Passage de non professionnel à professionnel (2 critères sur 3)</td>\n<td>portefeuille <strong>&gt; 500 000 €</strong>, <strong>10 opérations</strong> significatives par trimestre sur 4 trimestres, <strong>1 an</strong> d'expérience</td>\n</tr>\n<tr>\n<td>Violation du secret professionnel</td>\n<td><strong>1 an</strong> et <strong>15 000 €</strong></td>\n</tr>\n<tr>\n<td>Notification d'une violation de données à la CNIL</td>\n<td><strong>72 heures</strong></td>\n</tr>\n<tr>\n<td>Conservation des données et enregistrements</td>\n<td><strong>5 ans</strong></td>\n</tr>\n<tr>\n<td>Performances passées affichées</td>\n<td><strong>5 ans</strong>, périodes complètes de <strong>12 mois</strong></td>\n</tr>\n<tr>\n<td>Avis d'opéré (non professionnel)</td>\n<td>au plus tard le <strong>1er jour ouvrable</strong> suivant</td>\n</tr>\n<tr>\n<td>Vérification des connaissances d'un vendeur</td>\n<td><strong>6 mois</strong></td>\n</tr>\n<tr>\n<td>Révision des politiques d'exécution et de sélection</td>\n<td><strong>chaque année</strong></td>\n</tr>\n<tr>\n<td>FGDR — dépôts</td>\n<td><strong>100 000 €</strong> par déposant et par établissement</td>\n</tr>\n<tr>\n<td>FGDR — titres</td>\n<td><strong>70 000 €</strong> par investisseur et par établissement</td>\n</tr>\n<tr>\n<td>Délai d'indemnisation des dépôts</td>\n<td><strong>7 jours ouvrables</strong></td>\n</tr>\n<tr>\n<td>Déclaration de cessation des paiements</td>\n<td><strong>45 jours</strong></td>\n</tr>\n</tbody>\n</table></div>\n<h2 id=\"thème-7-instruments-financiers\">Thème 7 — Instruments financiers</h2>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Élément</th>\n<th>Valeur</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Actions de préférence sans droit de vote</td>\n<td>au plus <strong>1/2</strong> du capital ; <strong>1/4</strong> si la société est cotée</td>\n</tr>\n<tr>\n<td>Sensibilité d'une obligation</td>\n<td>variation en % pour <strong>1 % (100 points de base)</strong> de taux</td>\n</tr>\n<tr>\n<td>Nominal minimum d'un TCN</td>\n<td><strong>150 000 €</strong></td>\n</tr>\n<tr>\n<td>NEU CP / BTF</td>\n<td><strong>≤ 1 an</strong></td>\n</tr>\n<tr>\n<td>NEU MTN</td>\n<td><strong>&gt; 1 an</strong></td>\n</tr>\n<tr>\n<td>Euribor</td>\n<td><strong>1 semaine à 12 mois</strong>, base <strong>360 jours</strong></td>\n</tr>\n<tr>\n<td>€STR</td>\n<td>transactions de <strong>plus d'1 M€</strong>, au jour le jour</td>\n</tr>\n<tr>\n<td>Compte à terme</td>\n<td><strong>1 mois</strong> minimum</td>\n</tr>\n<tr>\n<td>Livret jeune</td>\n<td>plafond <strong>1 600 €</strong>, taux au moins égal à celui du livret A</td>\n</tr>\n<tr>\n<td>Assurance-vie non réclamée</td>\n<td>versée à la <strong>CDC 10 ans</strong> après le décès</td>\n</tr>\n<tr>\n<td>VL d'un OPC à vocation générale</td>\n<td><strong>au moins 2 fois par mois</strong></td>\n</tr>\n<tr>\n<td>Biens divers</td>\n<td>observations de l'AMF sous <strong>2 mois</strong> ; inventaire sous <strong>3 mois</strong> ; <strong>5 ans et 18 000 €</strong> de sanction</td>\n</tr>\n<tr>\n<td><span class=\"tag t-new\">nouveau</span> MiCA</td>\n<td>stablecoins <strong>30/06/2024</strong> ; reste <strong>30/12/2024</strong> ; fin de la transition PSAN <strong>au plus tard le 01/07/2026</strong></td>\n</tr>\n</tbody>\n</table></div>\n<h2 id=\"thème-8-gestion-collective-et-finance-durable\">Thème 8 — Gestion collective et finance durable</h2>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Élément</th>\n<th>Valeur</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Ratio par émetteur d'un OPCVM</td>\n<td><strong>5 %</strong> (règle 5/10/40)</td>\n</tr>\n<tr>\n<td>Alerte au client sous mandat</td>\n<td>baisse de <strong>10 %</strong> de la valeur du portefeuille</td>\n</tr>\n<tr>\n<td>Horizon moyen terme</td>\n<td><strong>3 à 8 ans</strong></td>\n</tr>\n<tr>\n<td>Application complète d'AIFM</td>\n<td>au-delà de <strong>500 M€</strong></td>\n</tr>\n<tr>\n<td>FCPR</td>\n<td><strong>≥ 50 %</strong> de titres non cotés</td>\n</tr>\n<tr>\n<td>FCPI</td>\n<td><strong>&gt; 70 %</strong> de titres innovants non cotés ; blocage <strong>7 à 10 ans</strong> (5 ans pour l'avantage fiscal)</td>\n</tr>\n<tr>\n<td>FIP</td>\n<td><strong>≥ 70 %</strong> de PME régionales</td>\n</tr>\n<tr>\n<td>OPCI</td>\n<td><strong>≥ 60 %</strong> d'immobilier</td>\n</tr>\n<tr>\n<td>OPCVM nourricier</td>\n<td><strong>≥ 85 %</strong> dans un seul maître</td>\n</tr>\n<tr>\n<td>ELTIF</td>\n<td><strong>≥ 70 %</strong> d'actifs éligibles ; annulation possible pendant <strong>2 semaines</strong></td>\n</tr>\n<tr>\n<td>Société d'épargne forestière</td>\n<td>engagement de <strong>8 ans</strong></td>\n</tr>\n<tr>\n<td>Fonds de partage (Finansol)</td>\n<td><strong>≥ 25 %</strong> des revenus donnés</td>\n</tr>\n<tr>\n<td>Fonds solidaire d'épargne salariale</td>\n<td><strong>5 à 10 %</strong> en entreprises solidaires</td>\n</tr>\n<tr>\n<td>Label ISR</td>\n<td>attribué pour <strong>3 ans renouvelables</strong> ; <span class=\"tag t-new\">nouveau</span> sélectivité <strong>30 %</strong> depuis la réforme de 2024</td>\n</tr>\n<tr>\n<td>DPEF (cotées)</td>\n<td><strong>&gt; 500 salariés</strong> et bilan <strong>&gt; 20 M€</strong> ou CA <strong>&gt; 40 M€</strong></td>\n</tr>\n<tr>\n<td>DPEF (non cotées)</td>\n<td><strong>&gt; 500 salariés</strong> et bilan ou CA <strong>&gt; 100 M€</strong></td>\n</tr>\n<tr>\n<td>Repères</td>\n<td>Kyoto <strong>1997</strong> ; Pacte vert : neutralité carbone en <strong>2050</strong> ; loi PACTE <strong>22 mai 2019</strong></td>\n</tr>\n<tr>\n<td><span class=\"tag t-new\">nouveau</span> Obligation verte européenne (EuGB)</td>\n<td><strong>85 %</strong> alignés sur la taxonomie</td>\n</tr>\n<tr>\n<td><span class=\"tag t-new\">nouveau</span> Noms de fonds ESG (ESMA)</td>\n<td><strong>80 %</strong> d'investissements alignés</td>\n</tr>\n</tbody>\n</table></div>\n<h2 id=\"thème-9-marchés\">Thème 9 — Marchés</h2>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Élément</th>\n<th>Valeur</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Préouverture</td>\n<td><strong>7 h 15 – 9 h</strong></td>\n</tr>\n<tr>\n<td>Fixing d'ouverture</td>\n<td><strong>9 h</strong></td>\n</tr>\n<tr>\n<td>Cotation en continu</td>\n<td><strong>9 h – 17 h 30</strong></td>\n</tr>\n<tr>\n<td>Fixing de clôture</td>\n<td><strong>17 h 35</strong></td>\n</tr>\n<tr>\n<td>Trading at last</td>\n<td><strong>17 h 35 – 17 h 40</strong></td>\n</tr>\n<tr>\n<td>Compartiments d'Euronext Paris</td>\n<td>A <strong>&gt; 1 Md€</strong> · B de <strong>150 M€ à 1 Md€</strong> · C <strong>&lt; 150 M€</strong></td>\n</tr>\n<tr>\n<td>Transparence pré-négociation (MR, MTF)</td>\n<td><strong>5 meilleures limites</strong></td>\n</tr>\n<tr>\n<td>Publication par un APA</td>\n<td><strong>15 minutes</strong></td>\n</tr>\n<tr>\n<td>Trading à haute fréquence</td>\n<td><strong>&gt; 2 messages par seconde</strong></td>\n</tr>\n<tr>\n<td>Reporting des transactions</td>\n<td><strong>J+1</strong></td>\n</tr>\n<tr>\n<td>SRD</td>\n<td><strong>dernier jour de bourse du mois</strong></td>\n</tr>\n<tr>\n<td>Dow Jones</td>\n<td><strong>30</strong> valeurs (CAC 40 : <strong>40</strong>)</td>\n</tr>\n</tbody>\n</table></div>\n<h2 id=\"thème-10-post-marché\">Thème 10 — Post-marché</h2>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Élément</th>\n<th>Valeur</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Règlement-livraison</td>\n<td><strong>J+2</strong> (<span class=\"tag t-new\">nouveau</span> <strong>J+1</strong> au <strong>11/10/2027</strong>)</td>\n</tr>\n<tr>\n<td>TCCP (épargne salariale)</td>\n<td>depuis <strong>2004</strong></td>\n</tr>\n</tbody>\n</table></div>\n<h2 id=\"thème-11-émissions-et-opérations-sur-titres\">Thème 11 — Émissions et opérations sur titres</h2>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Élément</th>\n<th>Valeur</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Offre publique obligatoire</td>\n<td><strong>30 %</strong> du capital ou des droits de vote</td>\n</tr>\n<tr>\n<td>Retrait obligatoire et OPR</td>\n<td><strong>90 %</strong> (depuis la loi PACTE)</td>\n</tr>\n<tr>\n<td>Diffusion minimale à l'introduction</td>\n<td><strong>25 %</strong>, ou <strong>5 %</strong> si cela représente <strong>≥ 5 M€</strong></td>\n</tr>\n<tr>\n<td>Seuil du prospectus</td>\n<td><strong>8 M€</strong> (base) ; <span class=\"tag t-new\">nouveau</span> <strong>12 M€</strong> depuis mars 2026</td>\n</tr>\n<tr>\n<td><span class=\"tag t-new\">nouveau</span> Financement participatif (ECSP)</td>\n<td><strong>5 M€</strong> par projet sur 12 mois</td>\n</tr>\n</tbody>\n</table></div>\n<h2 id=\"thème-12-comptabilité-et-fiscalité\">Thème 12 — Comptabilité et fiscalité</h2>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Élément</th>\n<th>Valeur</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Conservation des documents comptables</td>\n<td><strong>10 ans</strong></td>\n</tr>\n<tr>\n<td>Rapport financier annuel</td>\n<td><strong>4 mois</strong> après la clôture</td>\n</tr>\n<tr>\n<td>Rapport financier semestriel</td>\n<td><strong>3 mois</strong></td>\n</tr>\n<tr>\n<td>Seuils de déclaration</td>\n<td><strong>5, 10, 15, 20, 25, 30, 1/3, 50, 2/3, 90, 95 %</strong></td>\n</tr>\n<tr>\n<td>Délai de déclaration de franchissement</td>\n<td><strong>4 jours de bourse</strong></td>\n</tr>\n<tr>\n<td>Sanction d'une déclaration manquante</td>\n<td>privation des droits de vote pendant <strong>2 ans</strong></td>\n</tr>\n<tr>\n<td>Rachat de plus de 10 % d'un emprunt obligataire</td>\n<td>information sous <strong>4 jours</strong> de négociation</td>\n</tr>\n<tr>\n<td>DEU</td>\n<td>dépôt sans approbation préalable après <strong>2 ans</strong> approuvés</td>\n</tr>\n<tr>\n<td>Taux marginal maximal de l'IR</td>\n<td><strong>45 %</strong></td>\n</tr>\n<tr>\n<td>Abattement sur les salaires</td>\n<td><strong>10 %</strong></td>\n</tr>\n<tr>\n<td>Plafond des niches fiscales</td>\n<td><strong>10 000 €</strong></td>\n</tr>\n<tr>\n<td>Plafonnement global de l'impôt</td>\n<td><strong>75 %</strong> des revenus</td>\n</tr>\n<tr>\n<td>PFU</td>\n<td><strong>30 % = 12,8 % + 17,2 %</strong> (<span class=\"tag t-new\">nouveau</span> 31,4 % à vérifier pour 2026)</td>\n</tr>\n<tr>\n<td>Report des moins-values mobilières</td>\n<td><strong>10 ans</strong></td>\n</tr>\n<tr>\n<td>Plus-values immobilières</td>\n<td><strong>19 %</strong> + prélèvements sociaux</td>\n</tr>\n<tr>\n<td>PEA</td>\n<td>exonération d'IR après <strong>5 ans</strong> ; plafond <strong>150 000 €</strong></td>\n</tr>\n<tr>\n<td>Assurance-vie</td>\n<td><strong>8 ans</strong> ; abattement <strong>4 600 € / 9 200 €</strong> ; <strong>7,5 %</strong> jusqu'à 150 000 € de primes ; <strong>12,8 %</strong> avant 8 ans</td>\n</tr>\n<tr>\n<td>Seuil de l'IFI</td>\n<td><strong>1,3 M€</strong></td>\n</tr>\n<tr>\n<td>TTF</td>\n<td><strong>0,3 %</strong> (base) ; <span class=\"tag t-new\">nouveau</span> <strong>0,4 %</strong> depuis le 01/04/2025</td>\n</tr>\n<tr>\n<td>IS</td>\n<td>taux normal <strong>25 %</strong> ; <strong>4 acomptes</strong></td>\n</tr>\n<tr>\n<td>Régime mère-fille</td>\n<td>quote-part de <strong>5 %</strong> imposée</td>\n</tr>\n<tr>\n<td>Amortissement des souscriptions au capital de PME innovantes</td>\n<td><strong>5 ans</strong></td>\n</tr>\n</tbody>\n</table></div>\n","toc":[{"id":"lexamen-lui-même","t":"L'examen lui-même"},{"id":"thème-1-cadre-institutionnel","t":"Thème 1 — Cadre institutionnel"},{"id":"thème-2-déontologie","t":"Thème 2 — Déontologie"},{"id":"thème-3-sécurité-financière","t":"Thème 3 — Sécurité financière"},{"id":"thème-4-abus-de-marché","t":"Thème 4 — Abus de marché"},{"id":"thème-5-commercialisation-et-démarchage","t":"Thème 5 — Commercialisation et démarchage"},{"id":"thème-6-relations-clients","t":"Thème 6 — Relations clients"},{"id":"thème-7-instruments-financiers","t":"Thème 7 — Instruments financiers"},{"id":"thème-8-gestion-collective-et-finance-durable","t":"Thème 8 — Gestion collective et finance durable"},{"id":"thème-9-marchés","t":"Thème 9 — Marchés"},{"id":"thème-10-post-marché","t":"Thème 10 — Post-marché"},{"id":"thème-11-émissions-et-opérations-sur-titres","t":"Thème 11 — Émissions et opérations sur titres"},{"id":"thème-12-comptabilité-et-fiscalité","t":"Thème 12 — Comptabilité et fiscalité"}]},{"id":"D","title":"Ce qui a changé depuis la base (2021 → 2026)","html":"\n<blockquote class=\"note\">\n<p>Ta base Excel date de la <strong>V4 de février 2021</strong>, complétée par des questions plus récentes (environ 2021-2022). Depuis, de nombreux textes ont évolué. Cette page rassemble toutes les mises à jour signalées <span class=\"tag t-new\">nouveau</span> dans les leçons.</p>\n</blockquote>\n<aside class=\"callout c-warn\"><span class=\"callout-label\">Piège</span>\n<p>Mes connaissances s'arrêtent mi-2026 et je n'ai pas pu consulter le site de l'AMF. Les points marqués « à vérifier » sont à confirmer avec la grille et les documents officiels en vigueur à la date de ton examen.</p>\n</aside>\n<h2 id=\"confirmé-par-un-vrai-sujet-bts-banque-2026-épreuve-ef2-certi\">Confirmé par un vrai sujet : BTS Banque 2026, épreuve EF2 « Certification professionnelle »</h2>\n<p>Ce sujet de 120 questions suit <strong>exactement la grille AMF</strong>, thème par thème et sous-thème par sous-thème (33 questions A, 87 C). <strong>116 de ses questions viennent de ta base</strong>. Il confirme ces mises à jour :</p>\n<ul>\n<li><strong>DIC au lieu de DICI</strong> : la question sur l'affichage du risque est posée avec le DIC, réponse inchangée (<strong>échelle de 1 à 7</strong>). La question 692 a été mise à jour, et les autres questions DICI gardent leurs réponses (<a href=\"#cours-05\">thème 5</a>).</li>\n<li><strong>« Crypto-actifs »</strong> remplace « crypto-monnaies » : toujours <strong>pas de cours légal</strong>, ni en France ni dans l'UE (question 1649, <a href=\"#cours-07\">thème 7</a>).</li>\n<li><strong>Obligations vertes européennes</strong> : elles financent des projets <strong>compatibles avec le règlement Taxonomie</strong> (question 1922, <a href=\"#cours-08\">thème 8</a>).</li>\n<li><strong>Gestion « indicielle »</strong> : la performance s'analyse par rapport à l'indice indiqué dans le <strong>DIC</strong> (question 1964).</li>\n<li><strong>Nouvelle autorité européenne anti-blanchiment</strong> (AMLA, appelée <strong>ALBC</strong> dans le sujet) : elle <strong>harmonise les procédures de contrôle interne et de vigilance</strong> (question EF26-23, <a href=\"#cours-03\">thème 3</a>).</li>\n<li><strong>Questions nouvelles ajoutées à la base</strong> : EF26-07 (CIF et RTO sur OPC), EF26-23 (ALBC), EF26-60 (actionnaires servis en dernier en cas de liquidation), EF26-79 (commission de mouvement), EF26-100 (exemple d'écoblanchiment).</li>\n<li><strong>Classements corrigés d'après la place des questions dans le sujet</strong> : la question 2615 (conflits d'intérêts d'une SGP de FIA) passe au §2.2, la 2745 (« Les OPC sont constitués ») au §8.5, et la 2632a (plafond de garantie des dépôts) au §1.2.1.</li>\n</ul>\n<h2 id=\"thème-1-cadre-institutionnel-et-réglementaire-france-europe-\">Thème 1 — <a href=\"#cours-01\">Cadre institutionnel et réglementaire (France, Europe, international)</a></h2>\n<ul>\n<li><span class=\"tag t-new\">nouveau</span> Exemple concret de mesure du HCSF : depuis 2022, les normes de crédit immobilier sont contraignantes (taux d'effort maximal de 35 %, durée maximale de 25 ans).</li>\n<li><span class=\"tag t-new\">nouveau</span> <strong>Le Royaume-Uni est un pays tiers depuis le 1er janvier 2021</strong> : plus de passeport, seulement des équivalences.</li>\n<li><span class=\"tag t-new\">nouveau</span> L'UE s'est dotée en 2024 d'une <strong>quatrième autorité</strong>, l'<strong>AMLA</strong> (lutte contre le blanchiment, à Francfort), traitée au thème 3.</li>\n<li><span class=\"tag t-new\">nouveau</span> <strong>Financement participatif</strong> : depuis le <strong>10 novembre 2023</strong>, le règlement européen <strong>ECSP</strong> a supprimé le statut de <strong>CIP</strong> (conseiller en investissements participatifs). Les plateformes sont devenues des <strong>PSFP</strong> (prestataires de services de financement participatif), <strong>agréés par l'AMF</strong> et dotés d'un passeport européen. Les questions 101 et 115 de la base reposent encore sur le statut de CIP (voir l'annexe A).</li>\n<li><span class=\"tag t-new\">nouveau</span> <strong>Cible d'inflation</strong> : depuis juillet 2021, la BCE vise <strong>2 % à moyen terme, de façon symétrique</strong>. L'ancienne formule de la base (« inférieure à, mais proche de 2 % », <a class=\"qref\" href=\"#\" data-q=\"150\">Q150</a>) est dépassée, mais c'est la seule réponse qui cite 2 %.</li>\n<li><span class=\"tag t-new\">nouveau</span> Depuis septembre 2024, c'est le <strong>taux de la facilité de dépôt</strong> qui pilote en pratique la politique monétaire. Il est fixé à <strong>2 % depuis juin 2025</strong> (à vérifier à la date de ton examen).</li>\n<li><span class=\"tag t-new\">nouveau</span> La zone euro compte <strong>21 pays depuis l'entrée de la Bulgarie le 1er janvier 2026</strong> (la Croatie l'avait rejointe en 2023).</li>\n<li><span class=\"tag t-new\">nouveau</span> Le <strong>LIBOR a disparu</strong> (2021-2023). L'<strong>EURIBOR a été réformé</strong> et existe toujours (administré par l'<strong>EMMI</strong>). L'<strong>EONIA a disparu le 3 janvier 2022</strong> au profit de l'<strong>€STR</strong>. Le détail des indices de référence est au §7.4.</li>\n</ul>\n<h2 id=\"thème-2-déontologie-conformité-et-organisation-déontologique\">Thème 2 — <a href=\"#cours-02\">Déontologie, conformité et organisation déontologique des établissements</a></h2>\n<ul>\n<li><span class=\"tag t-new\">nouveau</span> <strong>Loi Waserman (2022)</strong> : le lanceur d'alerte <strong>choisit librement</strong> de signaler <strong>en interne ou directement à l'autorité compétente</strong> (AMF, ACPR…). Il n'est plus obligé de passer d'abord par sa hiérarchie. La protection s'étend aux personnes qui l'aident (« facilitateurs »).</li>\n</ul>\n<h2 id=\"thème-3-sécurité-financière-blanchiment-terrorisme-corruptio\">Thème 3 — <a href=\"#cours-03\">Sécurité financière : blanchiment, terrorisme, corruption, embargos</a></h2>\n<ul>\n<li><span class=\"tag t-new\">nouveau</span> <strong>DAC8</strong> : depuis le <strong>1er janvier 2026</strong>, l'échange automatique d'informations s'étend aux <strong>crypto-actifs</strong>.</li>\n<li><strong>Paquet européen anti-blanchiment (2024)</strong> :\n<ul>\n<li>un <strong>règlement unique</strong> (AMLR), d'application directe à partir de <strong>juillet 2027</strong> ;</li>\n<li>une <strong>6e directive</strong> ;</li>\n<li>une nouvelle autorité européenne, l'<strong>AMLA</strong>, installée à <strong>Francfort</strong>. Elle supervisera directement certaines entités financières à haut risque à partir de <strong>2028</strong>.</li>\n<li>L'AMLR prévoit un <strong>plafond européen de paiement en espèces de 10 000 €</strong> (la France applique déjà <strong>1 000 €</strong> pour un résident).</li>\n</ul>\n</li>\n<li><strong>Crypto-actifs</strong> : MiCA remplace progressivement le régime PSAN par celui des <strong>PSCA</strong>. La <strong>« travel rule »</strong> (identification de l'émetteur et du bénéficiaire de chaque transfert de crypto-actifs) s'applique depuis le <strong>30 décembre 2024</strong>.</li>\n<li><strong>Registre des bénéficiaires effectifs</strong> : depuis un arrêt de la Cour de justice de l'UE (novembre 2022), il n'est plus librement ouvert au public. L'accès est réservé aux personnes justifiant d'un <strong>intérêt légitime</strong>.</li>\n<li><strong>Sanctions internationales</strong> : depuis 2022, les mesures de gel visant la Russie ont fortement renforcé la vigilance sur les embargos.</li>\n</ul>\n<h2 id=\"thème-4-la-réglementation-abus-de-marché\">Thème 4 — <a href=\"#cours-04\">La réglementation « Abus de marché »</a></h2>\n<ul>\n<li><span class=\"tag t-new\">nouveau</span> <strong>Listing Act (2024)</strong> :\n<ul>\n<li>les <strong>dirigeants</strong> déclarent leurs transactions au-delà de <strong>20 000 € par an</strong>, au lieu de 5 000 € ;</li>\n<li>depuis <strong>juin 2026</strong>, les <strong>étapes intermédiaires</strong> d'un processus long (une fusion en négociation, par exemple) n'ont plus à être publiées : seul l'événement final l'est.</li>\n</ul>\n</li>\n</ul>\n<h2 id=\"thème-5-commercialisation-dinstruments-financiers-démarchage\">Thème 5 — <a href=\"#cours-05\">Commercialisation d'instruments financiers, démarchage, vente à distance et conseil</a></h2>\n<ul>\n<li><span class=\"tag t-new\">nouveau</span> <strong>À vérifier</strong> : une loi de 2025 a prévu de passer au <strong>consentement préalable (opt-in)</strong> pour le démarchage téléphonique des consommateurs, à partir d'<strong>août 2026</strong>. La base repose sur le système Bloctel (opposition, <em>opt-out</em>).</li>\n<li><span class=\"tag t-new\">nouveau</span> <strong>MIF 2 « quick fix » (2021)</strong> : l'information est désormais fournie <strong>par voie électronique par défaut</strong>.</li>\n<li><span class=\"tag t-new\">nouveau</span> Depuis <strong>2022</strong>, le marché cible intègre aussi les <strong>préférences de durabilité</strong> (ESG) des clients.</li>\n<li><span class=\"tag t-new\">nouveau</span> <strong>Depuis le 1er janvier 2023, le DICI des OPCVM est remplacé par le DIC PRIIPs</strong> pour les clients non professionnels. Les questions « DICI » de la base gardent les mêmes réponses (remise avant souscription, échelle de 1 à 7, frais en %), mais le document s'appelle désormais <strong>DIC</strong>.</li>\n</ul>\n<h2 id=\"thème-6-relations-avec-les-clients\">Thème 6 — <a href=\"#cours-06\">Relations avec les clients</a></h2>\n<ul>\n<li><span class=\"tag t-new\">nouveau</span> <strong>Depuis le 2 août 2022</strong>, le test d'adéquation inclut les <strong>préférences du client en matière de durabilité</strong> (ESG). Voir le thème 8.7.</li>\n<li><span class=\"tag t-new\">nouveau</span> MIF 2 obligeait à publier chaque année les <strong>5 principaux lieux d'exécution</strong> par classe d'instruments (<a class=\"qref\" href=\"#\" data-q=\"1188\">Q1188</a>). La <strong>révision de MIF 2 (2024) a supprimé cette obligation</strong>. Si la question tombe, la réponse attendue reste celle de la base.</li>\n</ul>\n<h2 id=\"thème-7-instruments-financiers-crypto-actifs-et-leurs-risque\">Thème 7 — <a href=\"#cours-07\">Instruments financiers, crypto-actifs et leurs risques</a></h2>\n<ul>\n<li><span class=\"tag t-new\">nouveau</span> <strong>Loi Attractivité (2024)</strong> : les sociétés qui s'introduisent en bourse peuvent émettre des <strong>actions de préférence à droits de vote multiples</strong>.</li>\n<li><span class=\"tag t-new\">nouveau</span> L'<strong>EONIA a disparu le 3 janvier 2022</strong>. L'Euribor existe toujours.</li>\n<li><span class=\"tag t-new\">nouveau</span> Le <strong>PERP</strong> (<a class=\"qref\" href=\"#\" data-q=\"1498\">Q1498</a>) <strong>n'est plus commercialisé depuis le 1er octobre 2020</strong> : il a été remplacé par le <strong>PER</strong> (loi PACTE).</li>\n<li>\n<h3 id=\"ce-qui-a-changé-le-règlement-européen-mica\"><span class=\"tag t-new\">nouveau</span> Ce qui a changé : le règlement européen MiCA</h3>\n</li>\n</ul>\n<h2 id=\"thème-8-gestion-collective-gestion-pour-compte-de-tiers-et-f\">Thème 8 — <a href=\"#cours-08\">Gestion collective, gestion pour compte de tiers et finance durable</a></h2>\n<ul>\n<li><span class=\"tag t-new\">nouveau</span> <strong>AIFM 2</strong> (directive 2024/927, à transposer avant avril 2026) : règles sur les <strong>fonds qui octroient des prêts</strong>, <strong>outils de gestion de la liquidité</strong> obligatoires (au moins deux pour les fonds ouverts, également pour les OPCVM) et encadrement renforcé de la délégation.</li>\n<li><span class=\"tag t-new\">nouveau</span> <strong>ELTIF 2.0</strong> (janvier 2024) : accès des particuliers facilité.</li>\n<li><span class=\"tag t-new\">nouveau</span> <strong>Norme européenne d'obligation verte (EuGB)</strong>, applicable depuis le <strong>21 décembre 2024</strong> : label volontaire qui exige que l'<strong>essentiel des fonds (85 %)</strong> soit aligné sur la <strong>taxonomie</strong> et passe par un <strong>examinateur externe</strong> enregistré auprès de l'ESMA.</li>\n<li><span class=\"tag t-new\">nouveau</span> Le règlement européen sur les <strong>notations ESG</strong> (applicable depuis le <strong>2 juillet 2026</strong>) soumet les agences à l'<strong>agrément et à la surveillance de l'ESMA</strong>. Il impose la <strong>transparence</strong> des méthodes, sans les uniformiser : elles restent différentes d'une agence à l'autre.</li>\n<li><span class=\"tag t-new\">nouveau</span> <strong>La CSRD remplace la DPEF</strong> par un <strong>rapport de durabilité</strong> (standards européens ESRS, vérification par un commissaire aux comptes ou un OTI). Les premiers rapports sont publiés en 2025 pour les plus grandes entreprises. Le <strong>paquet « Omnibus » (2025)</strong> a <strong>reporté</strong> les vagues suivantes et <strong>réduit le champ</strong> des entreprises concernées.</li>\n<li><span class=\"tag t-new\">nouveau</span> Depuis le <strong>2 août 2022</strong>, le conseiller doit recueillir les <strong>préférences de durabilité</strong> du client (MIF 2).</li>\n<li><span class=\"tag t-new\">nouveau</span> Depuis <strong>2024-2025</strong>, les <strong>noms de fonds</strong> utilisant des termes ESG ou « durable » doivent respecter les <strong>orientations de l'ESMA</strong> (au moins <strong>80 %</strong> d'investissements alignés et des exclusions minimales).</li>\n<li><span class=\"tag t-new\">nouveau</span> Le <strong>label ISR a été réformé en 2024</strong> : <strong>exclusion des entreprises qui lancent de nouveaux projets d'énergies fossiles</strong>, <strong>sélectivité renforcée (30 %)</strong> et exigences sur les plans de transition climatique.</li>\n<li><span class=\"tag t-new\">nouveau</span> Une <strong>révision de SFDR</strong> (création de catégories de produits) est en discussion depuis la proposition de la Commission fin 2025.</li>\n</ul>\n<h2 id=\"thème-9-fonctionnement-et-organisation-des-marchés\">Thème 9 — <a href=\"#cours-09\">Fonctionnement et organisation des marchés</a></h2>\n<ul>\n<li><span class=\"tag t-new\">nouveau</span> Depuis <strong>2022</strong>, la plupart des PSCD sont <strong>agréés et supervisés par l'ESMA</strong>. La base (<a class=\"qref\" href=\"#\" data-q=\"2104\">Q2104</a>) répond encore « l'AMF ou l'ACPR selon leur statut ».</li>\n<li><span class=\"tag t-new\">nouveau</span> La révision de MiFIR (2024) organise l'arrivée de <strong>« consolidated tapes » européennes</strong> sélectionnées par l'ESMA (obligations d'abord, puis actions) et <strong>interdit le paiement pour flux d'ordres (PFOF)</strong> au plus tard à mi-2026.</li>\n</ul>\n<h2 id=\"thème-10-post-marché-et-infrastructures-de-marché\">Thème 10 — <a href=\"#cours-10\">Post-marché et infrastructures de marché</a></h2>\n<ul>\n<li><span class=\"tag t-new\">nouveau</span> <strong>Passage à J+1</strong> dans l'Union européenne prévu le <strong>11 octobre 2027</strong>. Pour l'instant, la réponse reste J+2.</li>\n<li><span class=\"tag t-new\">nouveau</span> <strong>EMIR 3</strong> (2024) impose aux acteurs européens de <strong>compenser une partie de leurs dérivés auprès de chambres de l'UE</strong> (« compte actif »).</li>\n<li><span class=\"tag t-new\">nouveau</span> <strong>CSDR</strong> : depuis 2022, les <strong>pénalités en cas de retard de règlement</strong> s'appliquent.</li>\n<li><span class=\"tag t-new\">nouveau</span> Le système de paiement <strong>TARGET2</strong> a été remplacé par <strong>T2</strong> (2023).</li>\n</ul>\n<h2 id=\"thème-11-émissions-et-opérations-sur-titres\">Thème 11 — <a href=\"#cours-11\">Émissions et opérations sur titres</a></h2>\n<ul>\n<li><span class=\"tag t-new\">nouveau</span> Le <strong>Listing Act</strong> (2024) a relevé ce seuil à <strong>12 M€</strong> sur 12 mois à partir de <strong>mars 2026</strong>. Il a aussi créé des prospectus allégés (« EU Follow-on », « EU Growth issuance »).</li>\n<li><span class=\"tag t-new\">nouveau</span> Depuis le <strong>10 novembre 2023</strong>, le <strong>règlement européen ECSP</strong> s'applique :\n<ul>\n<li>les plateformes d'<strong>investissement et de prêt aux entreprises</strong> sont des <strong>PSFP agréés par l'AMF</strong>, avec passeport européen ;</li>\n<li>le plafond est de <strong>5 M€ par projet sur 12 mois</strong> ;</li>\n<li>les statuts de <strong>CIP</strong> et les <strong>minibons</strong> ont disparu ;</li>\n<li>l'<strong>IFP</strong> subsiste pour certains prêts et pour les dons.</li>\n</ul>\n</li>\n<li><span class=\"tag t-new\">nouveau</span> Depuis la loi PACTE (2019), le <strong>retrait obligatoire</strong> est possible dès <strong>90 %</strong> du capital et des droits de vote (contre 95 % auparavant).</li>\n</ul>\n<h2 id=\"thème-12-bases-comptables-financières-et-fiscales\">Thème 12 — <a href=\"#cours-12\">Bases comptables, financières et fiscales</a></h2>\n<ul>\n<li><span class=\"tag t-new\">nouveau</span> <strong>À vérifier</strong> : la loi de financement de la Sécurité sociale pour 2026 a relevé la CSG sur une partie des revenus du capital. Les prélèvements sociaux passeraient à <strong>18,6 %</strong> et la flat tax à <strong>31,4 %</strong>, avec des exceptions (assurance-vie, revenus fonciers…). La base raisonne avec <strong>17,2 % et 30 %</strong>.</li>\n<li><span class=\"tag t-new\">nouveau</span> La <strong>TTF est passée à 0,4 %</strong> au 1er avril 2025. Le <strong>Pinel</strong> a pris fin pour les acquisitions après le <strong>31 décembre 2024</strong>.</li>\n</ul>\n","toc":[{"id":"confirmé-par-un-vrai-sujet-bts-banque-2026-épreuve-ef2-certi","t":"Confirmé par un vrai sujet : BTS Banque 2026, épreuve EF2 « Certification professionnelle »"},{"id":"thème-1-cadre-institutionnel-et-réglementaire-france-europe-","t":"Thème 1 — Cadre institutionnel et réglementaire (France, Europe, international)"},{"id":"thème-2-déontologie-conformité-et-organisation-déontologique","t":"Thème 2 — Déontologie, conformité et organisation déontologique des établissements"},{"id":"thème-3-sécurité-financière-blanchiment-terrorisme-corruptio","t":"Thème 3 — Sécurité financière : blanchiment, terrorisme, corruption, embargos"},{"id":"thème-4-la-réglementation-abus-de-marché","t":"Thème 4 — La réglementation « Abus de marché »"},{"id":"thème-5-commercialisation-dinstruments-financiers-démarchage","t":"Thème 5 — Commercialisation d'instruments financiers, démarchage, vente à distance et conseil"},{"id":"thème-6-relations-avec-les-clients","t":"Thème 6 — Relations avec les clients"},{"id":"thème-7-instruments-financiers-crypto-actifs-et-leurs-risque","t":"Thème 7 — Instruments financiers, crypto-actifs et leurs risques"},{"id":"thème-8-gestion-collective-gestion-pour-compte-de-tiers-et-f","t":"Thème 8 — Gestion collective, gestion pour compte de tiers et finance durable"},{"id":"thème-9-fonctionnement-et-organisation-des-marchés","t":"Thème 9 — Fonctionnement et organisation des marchés"},{"id":"thème-10-post-marché-et-infrastructures-de-marché","t":"Thème 10 — Post-marché et infrastructures de marché"},{"id":"thème-11-émissions-et-opérations-sur-titres","t":"Thème 11 — Émissions et opérations sur titres"},{"id":"thème-12-bases-comptables-financières-et-fiscales","t":"Thème 12 — Bases comptables, financières et fiscales"}]}],"guide":{"html":"\n<h2 id=\"1-lexamen-en-un-coup-dœil\">1. L'examen en un coup d'œil</h2>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th></th>\n<th></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Questions</td>\n<td><strong>120 QCM</strong></td>\n</tr>\n<tr>\n<td>Catégorie <strong>A</strong> (connaissances réglementaires indispensables)</td>\n<td><strong>33 questions</strong>, il faut <strong>au moins 27 bonnes</strong></td>\n</tr>\n<tr>\n<td>Catégorie <strong>C</strong> (culture financière)</td>\n<td><strong>87 questions</strong>, il faut <strong>au moins 70 bonnes</strong></td>\n</tr>\n<tr>\n<td>Règle</td>\n<td><strong>80 % dans CHAQUE catégorie, sans compensation</strong></td>\n</tr>\n<tr>\n<td>Durée</td>\n<td>2 h maximum (sources publiques, à confirmer à l'inscription)</td>\n</tr>\n</tbody>\n</table></div>\n<p> <strong>Où sont les points A ?</strong> Thème 2 (6), thème 3 (3), thème 4 (2), §5.1 (4), thème 6 (16) et §9.2 (2). <strong>Le thème 6 porte à lui seul près de la moitié de la catégorie A.</strong></p>\n<hr/>\n<h2 id=\"3-ce-que-vaut-ce-manuel-honnêtement\">3. Ce que vaut ce manuel, honnêtement</h2>\n<p><strong>Ce qui a été vérifié</strong></p>\n<ul>\n<li>Les deux fichiers ont été <strong>fusionnés et comparés</strong>.\n<ul>\n<li>Pour les 2 045 questions communes, la <strong>cellule jaune</strong> du premier fichier et la <strong>lettre de réponse</strong> du second <strong>concordent à 100 %</strong>.</li>\n<li>Les doublons ont été supprimés.</li>\n<li>Les 199 questions sans thème ont été classées une à une.</li>\n<li>La feuille « questions supprimées » (36 questions retirées en V4) a été écartée.</li>\n</ul>\n</li>\n<li><strong>Toutes les questions</strong> ont été lues, et chaque notion testée est expliquée. Les 2 249 numéros apparaissent chacun dans exactement une leçon.</li>\n<li><strong>Problèmes de la base relevés</strong> :\n<ul>\n<li><strong>1 erreur</strong> : la <a class=\"qref\" href=\"#\" data-q=\"2670\">Q2670</a> donne « européen » pour le FSB, qui est <strong>international</strong> ;</li>\n<li><strong>1 réponse manquante</strong> : la <a class=\"qref\" href=\"#\" data-q=\"2578\">Q2578</a> ;</li>\n<li><strong>42 réponses dépassées</strong> par la réglementation de 2021 à 2026 (DICI → DIC, MiCA, ECSP, TTF…) ;</li>\n<li>des pièges signalés. Tout est dans l'<a href=\"#annexe-A\">annexe A</a>.</li>\n</ul>\n</li>\n<li>Les <strong>calculs</strong> (PER, coupon couru, sensibilité, VL, Sharpe…) ont été vérifiés.</li>\n</ul>\n<p><strong>Ce qui ne peut pas être garanti</strong></p>\n<ul>\n<li><strong>Un score de 100 % ne peut être promis par aucun support.</strong> Les questions de l'examen sont tirées d'une base <strong>officielle mise à jour chaque année</strong> par les organismes certificateurs. Ta base date de 2021-2022 : de nouvelles questions existent forcément. Ce manuel vise donc la <strong>compréhension des notions</strong>, pas seulement la mémorisation des réponses, pour que tu réussisses aussi les questions que tu n'as jamais vues.</li>\n<li><strong>Le droit a changé depuis ta base.</strong> Les mises à jour <span class=\"tag t-new\">nouveau</span> reposent sur mes connaissances (jusqu'à mi-2026), sans accès au site de l'AMF. Les points marqués « à vérifier » doivent être confirmés avec la <strong>grille et les documents officiels en vigueur</strong> à la date de ton examen.</li>\n<li><strong>Règle pratique</strong> : si une question reprend <strong>mot pour mot</strong> une question de ta base, la réponse attendue est en principe celle de la base, sauf erreur <span class=\"tag t-err\">erreur</span>. Si elle est <strong>reformulée</strong> ou porte sur un dispositif récent (MiCA, CSRD, DIC…), réponds selon le <strong>droit actuel</strong>.</li>\n<li><strong>Finance durable</strong> : l'AMF propose aussi un <strong>examen « Finance durable » distinct</strong> (60 questions). Ce manuel prépare à la partie §8.7 de l'examen général.</li>\n</ul>\n<hr/>\n<h2 id=\"4-méthode-de-révision-proposée\">4. Méthode de révision proposée</h2>\n<ol>\n<li><strong>Lis les leçons dans l'ordre</strong> (1 → 12), une ou deux par jour, en t'arrêtant sur les <span class=\"tag t-mnemo\">mnémo</span> et les <span class=\"tag t-warn\">piège</span>.</li>\n<li><strong>Juste après chaque leçon</strong>, fais toutes les questions de ta base listées dans « Questions de la base », sans regarder la réponse. Note les numéros ratés.</li>\n<li><strong>Repasse les questions ratées</strong> deux jours plus tard, puis une semaine plus tard (répétition espacée).</li>\n<li><strong>Priorité en fin de révision</strong> :\n<ul>\n<li>la <strong>catégorie A</strong> (thèmes 2, 3, 4, §5.1, thème 6, §9.2), où l'erreur coûte le plus ;</li>\n<li>les <strong>gros volumes C</strong> : thèmes 7, 8 (dont le §8.7) et 1.</li>\n</ul>\n</li>\n<li><strong>Les trois derniers jours</strong> : les <a href=\"#annexe-C\">chiffres clés</a>, les <a href=\"#annexe-B\">moyens mnémotechniques</a>, les <a href=\"#annexe-A\">questions à risque</a> et les <strong>fiches flash</strong> de chaque thème.</li>\n<li><strong>Examens blancs</strong> : lance-les sur le site (120 questions tirées selon la répartition de la grille) et vise <strong>au moins 90 %</strong> dans chaque catégorie pour garder de la marge.</li>\n</ol>\n<h2 id=\"5-réflexes-de-qcm-à-utiliser-en-dernier-recours\">5. Réflexes de QCM, à utiliser en dernier recours</h2>\n<p>Ces tendances sont mesurées sur les 2 244 questions de ta base. Elles ne remplacent jamais la connaissance.</p>\n<div class=\"table-wrap\"><table>\n<thead>\n<tr>\n<th>Formulation d'une proposition</th>\n<th>Elle est la bonne réponse…</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>« uniquement », « seulement », « exclusivement »</td>\n<td><strong>rarement</strong> (3 à 6 % des cas)</td>\n</tr>\n<tr>\n<td>« toujours », « jamais », « systématiquement », « obligatoirement »</td>\n<td><strong>rarement</strong> (13 à 18 %)</td>\n</tr>\n<tr>\n<td>« sous certaines conditions »</td>\n<td><strong>presque toujours</strong> (6 fois sur 6)</td>\n</tr>\n<tr>\n<td>« dans tous les cas »</td>\n<td>souvent (5 fois sur 7)</td>\n</tr>\n<tr>\n<td>La proposition la plus longue et la plus précise</td>\n<td>dans <strong>47 %</strong> des cas (contre 33 % au hasard)</td>\n</tr>\n<tr>\n<td>« Les deux réponses à la fois »</td>\n<td><strong>8 fois sur 28</strong> seulement : ce n'est pas un bon réflexe</td>\n</tr>\n</tbody>\n</table></div>\n<p>Lis chaque question <strong>deux fois</strong>. Repère les <strong>négations</strong> (« laquelle est fausse ? », « n'est pas… ») et le <strong>sujet exact</strong> (PSI ou SGP ? client professionnel ou non ? démarchage ou vente à distance ?).</p>\n<hr/>\n","toc":[{"id":"1-lexamen-en-un-coup-dœil","t":"1. L'examen en un coup d'œil"},{"id":"3-ce-que-vaut-ce-manuel-honnêtement","t":"3. Ce que vaut ce manuel, honnêtement"},{"id":"4-méthode-de-révision-proposée","t":"4. Méthode de révision proposée"},{"id":"5-réflexes-de-qcm-à-utiliser-en-dernier-recours","t":"5. Réflexes de QCM, à utiliser en dernier recours"}]}};
